window.LANCER_NPC_CLASSES = {"source":"《枪骑兵》核心规则书v3.5","template_intro":"模板可进一步定义 NPC，添加风味或改变他们在战斗中的功能。特别地，超体，精英，低等兵和老兵模板可以用来制造更困难或更容易的敌人。除非有特别的说明（如在班组中），你可以对 NPC 应用任何模板。有些，如老兵，可以应用于其他模板（如超体和精英），以制造非常难对付的敌人。要应用模板，首先要创建一个基础 NPC，然后写下或添加模板被动提供的任何增益（如额外结构）。然后根据模板选择一个或多个可选系统。","roles":["突击","炮击","操纵","卫兵","支援","生物"],"packs":[{"name":"核心规则书","book":"《枪骑兵》核心规则书v3.5","official":true,"note":""},{"name":"尘墓","book":"Foundry 官方数据（尘墓）","official":true,"note":""},{"name":"塞壬之歌","book":"《枪骑兵》模组：塞壬之歌【正式版V1.0】","official":true,"note":"","source":6},{"name":"壁花不容","book":"《枪骑兵》模组：壁花不容【正式版V1.6】","official":true,"note":"幻灵是多层首领，结构与普通职业不同，不在此列。","source":7},{"name":"冬痕行动","book":"《枪骑兵》模组：冬痕行动v1.0","official":true,"note":"","source":5},{"name":"模组资源合集","book":"模组资源合集","official":true,"note":"复仇者只见于合集；合集里的其他职业取自各模组原书，工业机、特种部队、怖物与尘墓模板相同（用 Foundry 官方数据）。","source":3},{"name":"卡斯特与帕勒克","book":"《枪骑兵》第三方域指南：卡斯特与帕勒克2.45【正式版v1.0】","official":false,"note":"","source":11},{"name":"苏丹","book":"《枪骑兵》第三方域指南：苏丹【正式版v1.7】","official":false,"note":"","source":12},{"name":"冷核圆形竞技场","book":"《枪骑兵》第三方扩展：冷核圆形竞技场【正式版v1.0】","official":false,"note":"","source":13},{"name":"强化战斗","book":"《枪骑兵》第三方扩展：强化战斗【正式版v1.0】","official":false,"note":"","source":14},{"name":"午夜伊菲革涅亚","book":"《枪骑兵》第三方模组：午夜伊菲革涅亚","official":false,"note":"伊菲革涅亚本人只有层级 3，是专属首领，不在此列。","source":16},{"name":"天堂末班车","book":"《枪骑兵》第三方模组：天堂末班车","official":false,"note":"","source":17},{"name":"浴金焰","book":"《枪骑兵》第三方模组：浴金焰【正式版V1.1】","official":false,"note":"","source":19},{"name":"军团","book":"《枪骑兵》第三方设定：军团v1.0","official":false,"note":"","source":20}],"classes":[{"id":"npcc_cn_ace","name":"王牌","role":"突击","role_en":"striker","page":278,"pages":[278],"flavor":"首位展现王牌原型机魅力的角色是艾斯琳·詹森（Aisling Jensen），她是维丹娜（Verdana）解放运动期间活跃的一名辅助飞军驾驶员。作为底盘和苍穹之骑士，像艾斯琳这样的王牌以高速扫射、敏捷机动和不顾一切的大胆壮举将他们的机甲投入战斗。他们骄傲自信，热衷于一场精彩的决斗。","tactics":"王牌是高机动快反应的突击，可以使用桶滚来减轻危险或高伤害攻击。桶滚对重型武器尤为有效。他们的引导武器无视掩体，也不需要视线，因此可以持续造成伤害。相对较低的 HP 使得王牌容易受到持续伤害，且他们在对付科技攻击时相对较弱。","stats":{"hull":[-2,-2,-2],"sys":[1,2,3],"agi":[3,4,6],"eng":[0,1,1],"hp":[10,12,14],"armor":[0,0,0],"evasion":[12,15,18],"edef":[8,8,10],"speed":[5,6,7],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"SSC 飞行系统","type":"System","tags":[],"effect":"王牌可以在移动或推进时飞行。","id":"npcf_cn_ace_1","base":true},{"name":"导弹发射器","type":"Weapon","tags":[{"id":"tg_seeking"},{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"","id":"npcf_cn_ace_2","base":true},{"name":"桶滚","type":"Reaction","tags":[{"id":"tg_recharge","val":5}],"trigger":"近战或远程攻击命中王牌。","effect":"王牌执行桶滚，向任意方向飞行 6 空间致使攻击未命中。该移动忽略交战和反应。","id":"npcf_cn_ace_3","base":true}],"optional":[{"name":"轰炸区","type":"System","tags":[{"id":"tg_limited","val":3},{"id":"tg_free_action"},{"id":"tg_round","val":1}],"effect":"若王牌在移动或推进时处于飞行，他们可以向飞行路径下方或邻近的一个角色投掷炸弹。这会造成必须至少与目标占据 1 空间重叠的溅射 1 爆炸。受影响区域内角色必须通过敏捷豁免否则受到 6/8/10 爆炸伤害并伏卧。","id":"npcf_cn_ace_4","base":false},{"name":"低空扫射","type":"Trait","tags":[],"effect":"1/轮，一个快速动作，王牌可向任何方向飞行等同速度空间，向路径下方或邻近一个角色自动造成 3/4/6动能伤害。","id":"npcf_cn_ace_5","base":false},{"name":"导弹群","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_seeking"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Burst","val":5}],"damage":[{"type":"Explosive","val":[3,4,5]}],"effect":"该武器对锁定角色造双倍伤害且不影响盟友角色。","id":"npcf_cn_ace_6","base":false},{"name":"快速响应","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个敌方角色在视线内移动。","effect":"王牌可以推进。","id":"npcf_cn_ace_7","base":false},{"name":"箔条发射器","type":"Trait","tags":[],"effect":"使用桶滚后，王牌将视为处于软性掩护中直到下一回合结束；此外桶滚可用来对抗科技攻击。","id":"npcf_cn_ace_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_aegis","name":"宙斯盾","role":"支援","role_en":"support","page":279,"pages":[279],"flavor":"宙斯盾原型机被用来驻守阵地、支持盟友和压制敌人。在科摩罗（Comorrand）行动中，卡拉金驾驶员麦克伦南（MacLennan）家族的格洛丽亚（Gloria）女士首次使用它并取得显著效果。宙斯盾以其强大防御措施而闻名。其驾驶员可熟练运用传统工具至尖端技术，将最小屏障化为坚固堡垒。","tactics":"宙斯盾是坚固的防御支援单位。覆盖尽可能多盟友的防御网最为有效，因它们很难重新部署。再生护盾也保护宙斯盾免受移动性降低的影响。","stats":{"hull":[0,0,0],"sys":[2,3,4],"agi":[-2,-1,-1],"eng":[2,3,5],"hp":[14,18,18],"armor":[2,2,3],"evasion":[7,8,8],"edef":[10,12,14],"speed":[3,3,3],"size":[1,1,1],"heatcap":[10,10,10],"save":[10,11,12],"sensor":[8,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"轻型雷射炮","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Energy","val":[3,3,3]},{"type":"Burn","val":[2,4,6]}],"effect":"","id":"npcf_cn_aegis_1","base":true},{"name":"防御网","type":"System","tags":[{"id":"tg_recharge","val":4},{"id":"tg_shield"},{"id":"tg_full_action"}],"effect":"宙斯盾会在爆发 3 内散布一面强大辉煌的斥力护盾。激活时，宙斯盾固定，但所有受影响区域内的角色或物品遭到来自区域外的远程、近战和科技攻击则+2难度，且不会被会心一击。受影响区域内的角色可正常攻击该区域内外的角色。受影响区域内盟友角色也获得对受损和缓慢的免疫，当进入该区域且已身负这些状态则立即移除它们。该效果持续到宙斯盾协定结束，或自身晕眩、受扰或被摧毁。非自主移动会导致护盾随宙斯盾一起移动。","id":"npcf_cn_aegis_2","base":true},{"name":"再生护盾","type":"Trait","tags":[],"effect":"宙斯盾对受损和缓慢免疫，且不会被会心一击。","id":"npcf_cn_aegis_3","base":true}],"optional":[{"name":"自适应屏蔽","type":"Trait","tags":[],"effect":"每轮首次在防御网中的盟友受伤害时，防御网内所有盟友获得对该类型伤害抗性。该持续到宙斯盾下一回合结束。","id":"npcf_cn_aegis_4","base":false},{"name":"护法","type":"Trait","tags":[],"effect":"邻近盟友可将该机体充当硬性掩护。","id":"npcf_cn_aegis_5","base":false},{"name":"火山带","type":"Trait","tags":[],"effect":"任意在防御网区域内开始其回合或在轮内首次进入该区域的敌方角色受到 2 热度并且离散直到对方离开该区域。","id":"npcf_cn_aegis_6","base":false},{"name":"硬光覆盖系统","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_recharge","val":5},{"id":"tg_shield"}],"effect":"以快速动作部署线形 3 硬光墙。该墙免疫伤害和效果并赐予硬性掩护。受掩护角色获得线形，溅射，爆发和锥形伤害的抗性。","id":"npcf_cn_aegis_7","base":false},{"name":"HA 黑壁系统","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_full_action"}],"effect":"以完整动作，宙斯盾在射程 5 生成 5 空间高覆盖线形 10 霎间黑墙。所有空间必须是自由空间。墙阻挡视线，影响或攻击，并提供硬性掩护。角色在墙中开始其回合或在自己回合中进入墙则掷 D6。若结果为 4+，将被移出游戏直到对方下一回合结束，当再次出现时自由选择墙体射程 10 以内自由空间。若没有自由空间则会在某个空间自由时返回。该墙持续存在直到宙斯盾以快速动作结束或被摧毁。当它结束时，放逐到霎间中的角色重新出现。","id":"npcf_cn_aegis_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_archer","name":"弓箭手","role":"操纵","role_en":"controller","page":280,"pages":[280],"flavor":"弓箭手原型为大熊座公司（Ursa Major）的护门者之匙二型（Gatekeeper Key-II），因伊卡伯德·卡登（Ichabod Carden）在地震动（Terramoto）战役中的英勇行为而广为人知。弓箭手原型机为强大的瞄准和叠加边界机动系统而牺牲装甲，这让它们深受热爱控制每次射击精确目标的驾驶员青睐。","tactics":"弓箭手擅长于对敌人施加“选择惩罚”——他们让角色在采取某些行动或让弓箭手攻击他们之间做出选择。使用弓箭手锁定高机动或强攻击的 PC，或掩护更脆弱的盟友。记住，当弓箭手能够相当接近他们的目标时最为有效，但他们并不特别坚固。","stats":{"hull":[-1,-1,-1],"sys":[2,3,4],"agi":[2,3,4],"eng":[-1,-1,-1],"hp":[16,20,20],"armor":[0,0,0],"evasion":[8,10,12],"edef":[8,10,12],"speed":[5,5,6],"size":[1,1,1],"heatcap":[8,8,8],"save":[11,13,16],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"轻机枪","type":"Weapon","tags":[{"id":"tg_reliable","val":[3,4,5]}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[5,7,10]}],"effect":"","id":"npcf_cn_archer_1","base":true},{"name":"压制","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"弓箭手在视线射程 10 内选择一个目标：对方受损，而弓箭手获得活靶子反应。该效果持续到弓箭手使用活靶子；目标伤害弓箭手或离开弓箭手视线；弓箭手晕眩、受扰或被摧毁；弓箭手为该动作选择一个新目标；或者弓箭手以一个自由行动结束它。\n【活靶子】（反应）触发：弓箭手的压制目标开始移动。\n效果：用一件武器的攻击进行阻拦。","id":"npcf_cn_archer_2","base":true},{"name":"优秀哨兵","type":"Trait","tags":[],"effect":"弓箭手所有反应攻击+1 准度（例：守望）。","id":"npcf_cn_archer_3","base":true}],"optional":[{"name":"致盲弹","type":"Trait","tags":[{"id":"tg_round","val":1}],"effect":"在弓箭手成功攻击后迫使目标进行工程豁免。若失败目标下一回合结束前只有邻近空间的视线。","id":"npcf_cn_archer_4","base":false},{"name":"威胁迫近","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"距离弓箭手实现射程 10 内一个敌方角色移动或执行动作。","effect":"该角色必须选择：失去触发的动作/移动，或继续执行但让弓箭手以一件武器立即攻击目标。","id":"npcf_cn_archer_5","base":false},{"name":"覆盖火力","type":"Trait","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"弓箭手在视线射程 10 内选择溅射 3 区域，并获得逮住你了反应。\n【逮住你了】（反应）触发：一个角色在该区域进行攻击。\n效果：弓箭手可以攻击该角色。","id":"npcf_cn_archer_6","base":false},{"name":"快速响应","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个敌人角色在视线内移动。","effect":"弓箭手可以推进。","id":"npcf_cn_archer_7","base":false},{"name":"火雹","type":"Trait","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"弓箭手在射程 10 内选择一个敌人：对方固定并受损直到下一回合结束，或直到弓箭手晕眩或受扰，或直到目标允许弓箭手以反应对其进行一件武器的攻击。","id":"npcf_cn_archer_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_assassin","name":"暗杀者","role":"突击","role_en":"striker","page":281,"pages":[281],"flavor":"暗杀者型机甲倾向于敏捷，高伤和速度。这些驾驶员为提高效率而牺牲舒适性，从拆除生命维持到通讯系统，取而代之更强大的处理能力和潜行能力。暗杀者可单打独斗，也可组队作战，驾驶着他们小巧优美的机甲穿过几乎无法穿越的地形，在毫无防备情况下逮住目标。","tactics":"暗杀者是重击落单角色的真正专家。使用暗杀者标记选择一个目标，然后充分利用暗杀者的高速和轻跃来接近距离。有个相当具有威胁的的组合，将暗杀者与会造成机动性降低状态如昏迷或伏卧的 NPC 配对。若没有“魔鬼的咳嗽”霰弹枪这样的可选系统，暗杀者便只能进行近战攻击，且很容易受到持续伤害。","stats":{"hull":[0,1,1],"sys":[1,1,2],"agi":[2,3,4],"eng":[-1,0,0],"hp":[15,15,15],"armor":[0,1,1],"evasion":[12,15,17],"edef":[8,8,8],"speed":[6,6,8],"size":[0.5,0.5,1],"heatcap":[7,7,7],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1"],"base":[{"name":"KAI 生物电镀","type":"Trait","tags":[],"effect":"暗杀者所有敏捷检定+1 准度。此外可以正常速度攀爬和游泳，忽略困难地形，并进行标准移动时可以水平跳跃速度距离，并垂直跳跃速度一半距离（任何组合）。","id":"npcf_cn_assassin_1","base":true},{"name":"热能锋刃","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[2,2,2],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"对伏卧、离散、固定或晕眩目标造成双倍伤害。","id":"npcf_cn_assassin_2","base":true},{"name":"暗杀者标记","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"暗杀者选择视线内一个角色。直到场景结束前使用以下效果：• 对目标伤害有抗性。• 对该目标造成的伤害无法减免。• 在该目标强制的所有豁免中获得+1 准度。暗杀者只有当前目标被摧毁后才能选择新目标。","id":"npcf_cn_assassin_3","base":true},{"name":"轻跃","type":"Trait","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"暗杀者在任意方向飞行 6 空间，但必须降落在一个表面上。降落时，暗杀者邻近的角色必须通过敏捷豁免否则伏卧。","id":"npcf_cn_assassin_4","base":true}],"optional":[{"name":"“魔鬼的咳嗽”霰弹枪","type":"Weapon","tags":[{"id":"tg_knockback","val":2},{"id":"tg_loading"}],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[10,15,20]}],"effect":"","id":"npcf_cn_assassin_5","base":false},{"name":"闷棍","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"tech_type":"Quick","effect":"暗杀者选择邻近的一个角色：对方必须通过工程豁免否则晕眩直到对方下一回合结束。","id":"npcf_cn_assassin_6","base":false},{"name":"回旋踢","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"暗杀者选择邻近的一个角色：对方必须通过机体豁免否则从暗杀者推开 4 空间并伏卧。","id":"npcf_cn_assassin_7","base":false},{"name":"云投射","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"暗杀者引爆炸药制造出一片烟、薄或其他爆发 3 区域遮盖物。暗杀者在受影响区域内获得软性掩护，完全位于区域内或外除暗杀者之外的角色都无法建立视线进入或离开该区域。部分区域内的角色不受影响。该效果会持续到暗杀者下一回合结束，或直到暗杀者再次使用该系统。","id":"npcf_cn_assassin_8","base":false},{"name":"爆裂匕首","type":"System","tags":[{"id":"tg_limited","val":3},{"id":"tg_quick_action"}],"effect":"暗杀者消耗 1 充能向射程 3 内一个角色投掷爆裂匕首，远程攻击目标+2/+4/+6。命中则匕首嵌入目标并在对方下一回合结束时爆炸，爆发 1 内造成 6/8/10 爆炸伤害。","id":"npcf_cn_assassin_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_assault","name":"突击手","role":"突击","role_en":"striker","page":282,"pages":[282],"flavor":"突击手机甲是银河系中最为常见的主要战斗骨架。配备重型步枪、随身武器和一套增强移动、瞄准和防御能力的系统，它们是直接可靠坚韧英勇的战斗单位。突击手机甲驾驶员的训练和装备也是最为价格低廉的，但这并不会妨碍其危险性。","tactics":"突击手是直接了当造成伤害的突击。把他们安置在一个可以有效利用他们韧性和适当射程的位置，使用受身抵抗伤害以最大限度提高他们的生存能力。","stats":{"hull":[1,2,3],"sys":[1,2,3],"agi":[1,2,3],"eng":[1,2,3],"hp":[15,18,21],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,9,10],"speed":[4,4,4],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"重型突击步枪","type":"Weapon","tags":[{"id":"tg_reliable","val":[2,3,4]}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","id":"npcf_cn_assault_1","base":true},{"name":"格斗匕首","type":"Weapon","tags":[],"weapon_size":"副武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[4,6,7]}],"effect":"","id":"npcf_cn_assault_2","base":true},{"name":"受身","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一次攻击命中突击手，但伤害还未掷出。","effect":"获得对所有攻击伤害的抗性。","id":"npcf_cn_assault_3","base":true}],"optional":[{"name":"下挂榴弹发射器","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_arcing"}],"weapon_size":"副武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"","id":"npcf_cn_assault_4","base":false},{"name":"微型导弹弹幕","type":"Trait","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"突击手发射一连串线形 8 的微型导弹。受影响区域内的所有角色必须成功进行机体豁免，否则受到 6/8/10动能伤害。成功豁免伤害减半。","id":"npcf_cn_assault_5","base":false},{"name":"高冲击弹药","type":"System","tags":[{"id":"tg_mod"}],"effect":"这些高口径弹药只能与重型突击步枪一起使用。当使用这些弹药时，突击手攻击变为 AP 和+4 动能伤害，但重型突击步枪再次使用前必须重新上膛（正如其拥有装填）。","id":"npcf_cn_assault_6","base":false},{"name":"自动锁定","type":"Trait","tags":[],"effect":"突击手在攻击时忽略掩护，尽管仍需要视线。","id":"npcf_cn_assault_7","base":false},{"name":"军纪","type":"Trait","tags":[],"effect":"突击手与至少一名带有机甲标签的盟友角色邻近时，其攻击、检定和豁免+1 准度。","id":"npcf_cn_assault_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_barricade","name":"路障","role":"操纵","role_en":"controller","page":283,"pages":[283],"flavor":"维尔德系统公司（Veld Systems）守护者五型（（Keeper Pattern 5）是种常见卫兵机甲，因其在拉玛之歌战役（Sing Rama Sing）中的出色表现而名声大噪。战役中，炽天使连队的奥黛丽·雷默斯（Audrey Reimaus）用守护者 5 型独自保护了拉玛城主天梯塔的安全，从而保证城市居民疏散通道。","tactics":"需封锁高机动目标那么路障是把好手。它们可以使用便携打印机为盟友制造硬性掩护，或阻止近战机甲通过区域。","stats":{"hull":[0,1,2],"sys":[1,1,2],"agi":[-2,-2,-2],"eng":[3,5,6],"hp":[12,16,20],"armor":[1,1,1],"evasion":[6,7,8],"edef":[9,11,13],"speed":[3,3,4],"size":[2,2,2],"heatcap":[10,11,12],"save":[12,15,18],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"重子长矛","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":10}],"damage":[{"type":"Energy","val":[2,2,2]}],"effect":"T2~3 时，该武器可一次攻击两次，击中单独角色两次或攻击两个角色一次。","on_hit":"目标缓慢直到他们下一回合结束。","id":"npcf_cn_barricade_1","base":true},{"name":"便携打印机","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_protocol"}],"effect":"路障打印出一个大小 2 立方体在邻近的自由区域。立方体提供硬性掩护，是具有 20 HP 和闪避 5 的单个物品。","id":"npcf_cn_barricade_2","base":true},{"name":"冲击电镀","type":"System","tags":[],"effect":"路障有对动能攻击有抗性。","id":"npcf_cn_barricade_3","base":true},{"name":"堡垒模块","type":"Trait","tags":[],"effect":"路障忽略困难地形和危险地形。","id":"npcf_cn_barricade_4","base":true}],"optional":[{"name":"拖下水","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"路障对感应中的一个角色进行科技攻击。若成功，目标每主动移动 1 空间就会造成 2AP 能量伤害直到对方下一回合结束。","id":"npcf_cn_barricade_5","base":false},{"name":"地震斥力器","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"所有爆发 3 内的非飞行角色必须通过机体豁免否则从路障击退 3 空格并被伏卧。场景结束前受影响区域变为困难地形。","id":"npcf_cn_barricade_6","base":false},{"name":"挤压出物","type":"Trait","tags":[],"effect":"路障使用便携打印机一次可以打印两个独立立方体而非一个。","id":"npcf_cn_barricade_7","base":false},{"name":"饥饿/竞逐帽贝","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"路障在其邻近大小 4 自由区域迅速打印部署小型移动地雷。受影响区域为困难地形；此外敌对角色在轮内首次进入该区域或在其中开始其回合则必须通过系统豁免否则缓慢直到对方下一回合结束。","id":"npcf_cn_barricade_8","base":false},{"name":"泰坦陷阱无人机","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_limited","val":1},{"id":"tg_quick_action"}],"effect":"陷阱无人机（大小 1/2，HP 5/10/15，回避 10/12/14，电子防御 10/12/14，标签：无人机）该无人机可以打印部署到任何邻近的自由空间。当敌方角色进入无人机射程 3 或在其中开始回合时，无人机会发出一道脉冲固定对方直到无人机被摧毁。","id":"npcf_cn_barricade_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_bastion","name":"棱堡","role":"卫兵","role_en":"defender","page":284,"pages":[284],"flavor":"棱堡以宙斯盾原型机甲的纯粹防御优势换取更大的机动性。它们将区域抗拒进攻能力与坚固防御系统以及先进通信系统相结合。这些机甲是众多强大中队指挥官的最爱。这种搭配效能在德洛梅达星系（Dromeda system）与虚空之间（Space Between）星际海盗公会的交战中得到了最佳展示，当时一名战地晋升的辅助军官赞德·里夫斯（Zander Reeves）就驾驶着这种机甲。","tactics":"棱堡是顽强的防御者，利用自己的机体和大小来保护自己和附近。使用盾墙防御远处的敌人，如炮兵和狙击手。棱堡（和他们的结界）对于击退和强制移动的攻击非常脆弱，因这些效果会破坏他们的许多能力。","stats":{"hull":[2,4,6],"sys":[0,0,0],"agi":[-3,-3,-2],"eng":[2,3,4],"hp":[10,10,10],"armor":[3,3,4],"evasion":[8,10,10],"edef":[8,8,8],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,10,12],"save":[8,10,12],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"轮转榴弹发射器","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_loading"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"","id":"npcf_cn_bastion_1","base":true},{"name":"重型突击盾","type":"Weapon","tags":[{"id":"tg_knockback","val":1}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[3,6,9]}],"effect":"","id":"npcf_cn_bastion_2","base":true},{"name":"无敌意阻截","type":"Trait","tags":[{"id":"tg_protocol"}],"effect":"棱堡及其邻近的一个盟友角色对视线内的一个角色所造成的所有伤害获得抗性。以一个协定，棱堡可选择一个新盟友角色或目标。盟友角色若离开邻近则失去抗性。","id":"npcf_cn_bastion_3","base":true},{"name":"护法","type":"Trait","tags":[],"effect":"邻近盟友可将该机体充当硬性掩护。","id":"npcf_cn_bastion_4","base":true}],"optional":[{"name":"近威胁抗拒系统","type":"System","tags":[],"effect":"当某角色在射程 3 内攻击棱堡时，对方在掷骰前要受到 2/3/4AP 爆炸伤害。","id":"npcf_cn_bastion_5","base":false},{"name":"围困护法","type":"Trait","tags":[],"effect":"邻近棱堡的盟友角色获得对溅射、爆发、线形和锥形攻击所造成伤害的抗性。","id":"npcf_cn_bastion_6","base":false},{"name":"“暂停”引擎","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"棱堡与一个邻近盟友角色暂时被屏蔽到便携式霎间闪烁嵌板中，获得对所有伤害和效果的免疫直到棱堡的下一回合开始。盟友角色若离开邻近则失去免疫。在棱堡下一回合开始，它们会陷入晕眩直到下一回合开始。","id":"npcf_cn_bastion_7","base":false},{"name":"无畏捍卫者","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"棱堡射程 5 内的一个盟友受到伤害，同时棱堡没被固定，缓慢，晕眩或其他不能移动的方式。","effect":"棱堡可以移动到邻近空间并承受伤害。","id":"npcf_cn_bastion_8","base":false},{"name":"死亡抗拒","type":"System","tags":[{"id":"tg_shield"}],"effect":"每轮棱堡第一次被远程或近战攻击成功命中所有伤害降为 0。","id":"npcf_cn_bastion_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_berserker","name":"狂战士","role":"突击","role_en":"striker","page":285,"pages":[285],"flavor":"狂战士型机甲具备先进热循环系统，该系统能将产生的热量转化为纯粹的进攻力量，从而指数级提升其武器输出。该机甲原型最广为人知的便是达尔·梅洛斯将军（Gen’Dal Merlos）那濒毁的骑士们（Knights of Imminent Destruction），它本身也深受专注于纯粹战斗的组织、私人军事公司（PMC）以及已建立国家中可否认资产部队的青睐。","tactics":"狂战士是非常优秀的肉搏决斗者，近距离接触时非常可怕。当他们越是尽可能接近敌军，其潜力越大。鉴于他们差劲的热度上限和电子防御，狂战士很容易遭受科技攻击。聪明的对手会利用好斗为自己建立的优势，让狂战士转而对付盟友，所以最好让他们远离友军。","stats":{"hull":[3,4,6],"sys":[-2,-2,-2],"agi":[2,4,4],"eng":[-1,-1,0],"hp":[12,16,20],"armor":[1,1,1],"evasion":[8,9,10],"edef":[6,6,6],"speed":[5,5,5],"size":[1,1,1],"heatcap":[6,6,6],"save":[10,12,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"链斧","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[7,9,11]}],"effect":"会心一击：目标离散直到对方下一回合结束。","id":"npcf_cn_berserker_1","base":true},{"name":"热潮防御","type":"Trait","tags":[],"effect":"狂战士对所有伤害都具抗性，除非它们被受损、晕眩、固定、离散、缓慢或暴露。","id":"npcf_cn_berserker_2","base":true},{"name":"好斗","type":"Trait","tags":[],"effect":"每轮受到第一次伤害后，狂战士必须立即用链斧攻击邻近的任意角色——无论敌友。","id":"npcf_cn_berserker_3","base":true},{"name":"雪崩冲锋","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"狂战士沿着直线移动与速度相等的空间，忽略反应和交战，然后用链斧攻击随机邻近角色——无论敌友。","id":"npcf_cn_berserker_4","base":true}],"optional":[{"name":"主宰","type":"Trait","tags":[],"effect":"当狂战士使用雪崩冲锋时，所有邻近冲锋路径或最终位置的角色必须通过机体豁免否则伏卧无论敌友。","id":"npcf_cn_berserker_5","base":false},{"name":"捕鲸叉加农炮","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[2,4,6]}],"effect":"","on_hit":"与狂战士大小相等或更小的目标会被拉到其邻近位置或尽可能靠近。若目标更大，则狂战士就会被拉到对方邻近位置。若目标在邻近位置结束移动，则狂战士擒拿对方。","id":"npcf_cn_berserker_6","base":false},{"name":"钉枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"会心一击：目标进行敏捷豁免。若失败，对方固定直到下一回合结束。","id":"npcf_cn_berserker_7","base":false},{"name":"报复","type":"Trait","tags":[],"effect":"每当狂战士受到伤害时，其下次攻击额外造成+2/+3/+4 伤害。该加值最多可叠加+8。该加值在狂战士发动攻击时，或在下一回合结束时丢失。","id":"npcf_cn_berserker_8","base":false},{"name":"燥热","type":"Reaction","tags":[{"id":"tg_shield"},{"id":"tg_round","val":1}],"trigger":"狂战士在近战中受到伤害。","effect":"狂战士获得对攻击伤害的抗性并且攻击者必须通过工程豁免否则受到 2/4/6 燃烧伤害。","id":"npcf_cn_berserker_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_bombard","name":"投弹者","role":"炮击","role_en":"artillery","page":286,"pages":[286],"flavor":"阿尔塔全域弹道公司（Alta All-Theater Ballistics）原型机投弹者底盘及其授权仿品是全银河系中普遍存在的闪光点。建立在长期运行部署持久作战基础，投弹者机甲是为快速部署炮兵至战区的武装部队提供的可行性解决方案。根据此类参数配置的底盘通常位于前线后方数英里设防位置；一种特别非对称部署策略包括在战区上空安置投弹者组——通常是在本地卫星、人工捕获至稳定轨道的天然卫星或专门建造的轨道平台上。从它们的有利位置，炮组可向下方天体倾泻炮弹而远离战斗危险。","tactics":"投弹者是种长距离炮击机甲，其设计目的用来惩戒那些依靠邻近优势紧密阵型的角色他们在近距离时相对脆弱，但在一段距离后对困境有承受力，所以把他们放远一点，以最大化他们的效力。投弹者的撼地炮弹在阻止敌人移动和提供掩护方面效果很好，但也会伤害盟友。","stats":{"hull":[0,1,1],"sys":[1,2,3],"agi":[-1,-1,-1],"eng":[2,3,5],"hp":[10,13,16],"armor":[0,0,0],"evasion":[7,8,8],"edef":[12,14,16],"speed":[2,2,3],"size":[1,1,1],"heatcap":[8,8,8],"save":[11,13,16],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"射石加农炮","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_ordnance"}],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[-1,-1,-1],"range":[{"type":"Range","val":25},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[5,7,8]}],"effect":"","id":"npcf_cn_bombard_1","base":true},{"name":"集束弹药","type":"Trait","tags":[],"effect":"投弹者的攻击对第一个以外所有目标造成+2/+3/+4 伤害。","id":"npcf_cn_bombard_2","base":true},{"name":"撼地炮弹","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_free_action"}],"effect":"用射石加农炮攻击时，投弹者也可以发射一枚特殊的震地炮弹。除了造成伤害外，距离目标空间爆发 3 以内的角色必须通过机体豁免否则伏卧。碎片或破碎的泥土被撞击抛起，在投弹者选择的自由空间内（受影响区域内）制造 2 个大小 1 的硬性掩护。","id":"npcf_cn_bombard_3","base":true},{"name":"攻城甲","type":"Trait","tags":[],"effect":"投弹者对所有来自射程 3 以外攻击造成的伤害都有抗性。","id":"npcf_cn_bombard_4","base":true}],"optional":[{"name":"高冲击炮弹","type":"Trait","tags":[],"effect":"命中时，射石加农炮将目标向外击退 3 空间。","id":"npcf_cn_bombard_5","base":false},{"name":"掩体粉碎机","type":"Trait","tags":[],"effect":"射石加农炮对受影响区域内物品和地形造成10/15/20AP 爆炸伤害，无需掷骰。","id":"npcf_cn_bombard_6","base":false},{"name":"耀斑无人机","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_quick_action"}],"effect":"耀斑无人机（尺寸 1/2，HP10/20/30，闪避 10，电子防御 10，标签：无人机）该无人机可被部署到视线射程 25 空间，在那里盘旋并开始向爆发 2 区域投射强光。受影响区域内所有角色，包括那些移动到该区域或在区域内开始其回合的角色将失去隐形和匿迹，且无法在该区域内躲藏或隐形。此外，投弹者对受影响区域内角色的攻击+1 准度。无人机会承受投弹者攻击的伤害，投弹者一次只能部署一架无人机；若部署新的无人机，则旧的会解体。","id":"npcf_cn_bombard_7","base":false},{"name":"轮转加农炮","type":"Weapon","tags":[{"id":"tg_knockback","val":3},{"id":"tg_loading"},{"id":"tg_ordnance"}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Cone","val":5}],"damage":[{"type":"Explosive","val":[3,4,5]}],"effect":"","id":"npcf_cn_bombard_8","base":false},{"name":"集群引导炸弹","type":"Trait","tags":[],"effect":"射石加农炮在所选目标空间射程 3 内的三个角色受到 2/3/4 爆炸伤害，无论命中与否。","id":"npcf_cn_bombard_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_breacher","name":"破门手","role":"突击","role_en":"striker","page":288,"pages":[288],"flavor":"坎贝尔轨道动力（Campbell Orbital Dynamics）生产的 C-O Mk III 在登舰行动中以高效著称，它经常出现在亚轨道行星防御部队和海盗部队的军火库中。官方的说法是“CO”是“CombatOrbitital”（战斗轨道）的缩写，但民间调侃 CO3 是个“Can Opener”（开罐器），其灵感来自于最著名的 CO3驾驶员之一瓦莱里娅·罗贾斯-萨尼克（Valeria Rojas-Sarnik）的呼号。","tactics":"破门手可造成可观的爆炸伤害，但他们不是特别精准。为了提高他们的能力，使用锁定或与支援 NPC 配合。破门撞击装置可快速完成掩护工作;然而，它缺乏速度和范围，并有引发反应的风险。","stats":{"hull":[2,3,4],"sys":[-1,-1,-1],"agi":[0,1,2],"eng":[1,2,3],"hp":[18,20,22],"armor":[1,1,1],"evasion":[9,11,13],"edef":[7,7,7],"speed":[3,4,5],"size":[1,1,1],"heatcap":[7,7,8],"save":[10,12,14],"sensor":[5,4,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"双管霰弹枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[-2,-2,-2],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"该武器可同时对同一或不同角色进行两次攻击。","id":"npcf_cn_breacher_1","base":true},{"name":"破门撞击装置","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"破门手在一条直线上最多移动 6 空间，忽略交战并穿过但不能停止其他角色占据的空间。破门手路径上的障碍物和物体受到 10/20/30AP 动能伤害。破门手穿过被摧毁的任何障碍物并继续移动，直到移动 6 空间或未能摧毁一个障碍物时停下。任何在破门手路径上的角色必须通过敏捷豁免否则将被尽可能直接地推开并伏卧。","id":"npcf_cn_breacher_2","base":true},{"name":"破甲","type":"Trait","tags":[],"effect":"在一回合内被破门手的双管霰弹枪成功命中超过一次的角色将在剩余场景中离散。","id":"npcf_cn_breacher_3","base":true}],"optional":[{"name":"痛苦制造者","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"破门手在射程 3 以内选择一个角色。他们的下一回合被延迟到目标回合后。破门手回合开始时，若目标仍在射程 3 以内，他们可用自由动作使用双管霰弹枪攻击目标 4 次，而非 2 次。","id":"npcf_cn_breacher_4","base":false},{"name":"高级撞角","type":"Trait","tags":[],"effect":"当使用破门撞击装置时，破门手多移动 4 空间，目标在敏捷豁免上+1 难度。","id":"npcf_cn_breacher_5","base":false},{"name":"跟踪器倒计时","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"破门手对感应内的角色进行科技攻击。成功后，破门手对目标的所有攻击都将获得+1/2/3 准度，且每回合可以一次自由动作进行推进，只要能直接接近目标。这将持续到任意双方角色被摧毁且不能改变新目标。","id":"npcf_cn_breacher_6","base":false},{"name":"高热装药","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_grenade"},{"id":"tg_quick_action"}],"effect":"破门手消耗 1 充能向射程 5 内某空间投掷榴弹。此后溅射 2 爆炸中的角色受到 2/4/6 燃烧伤害，若成功进行敏捷豁免，伤害减半。物品，地形和可展开受到10/20/30 AP 动能伤害。","id":"npcf_cn_breacher_7","base":false},{"name":"射镖霰弹枪","type":"Weapon","tags":[],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[2,3,4]}],"effect":"使用此武器攻击会从目标空间边缘向后形成锥形 3破片。攻击目标空间和受影响区域内所有角色。锥形范围不能改变方向。","id":"npcf_cn_breacher_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_cataphract","name":"甲胄骑兵","role":"突击","role_en":"striker","page":289,"pages":[289],"flavor":"甲胄骑兵中队由强调机动性、冲击力和韧性的快速打击机甲组成；因而，全银河系对拥有瞬间冲破防线能力的甲胄骑兵原型机倍感畏惧。没有什么比一支甲胄骑兵中队冲破静止战线重炮点式防御武器阵地，消灭曾不可撼动的防御者更可怕（或更鼓舞人心）了。甲胄骑兵级底盘中的旗舰机是赛德系统公司（Sine Die Systems）的终焉-44，装载着 SDS 可怖撞锤加农炮，一匹棱角分明的野兽。底盘经久不衰地受欢迎可以归因于凯瑟琳“C- 80”·尼德（Catherine “C- 80” Need）的成功，她驾驶终焉-44在卡琳娜近端防御战（the defense of Carina-Proximal）中大获全胜，一战成名。","tactics":"甲胄骑兵是高机动突击。践踏允许他们越过敌人到达后方，在那里他们使用钉刺迫使脆弱目标进入不利位置。将甲胄骑兵放置更靠近个体敌方角色位置，单点防御盾无法同距离多目标工作。注意甲胄骑兵移动时仍会引起反应，所以要小心使用他们的能力。","stats":{"hull":[1,2,4],"sys":[0,0,0],"agi":[1,3,4],"eng":[0,0,0],"hp":[15,17,20],"armor":[0,0,0],"evasion":[10,10,12],"edef":[8,8,8],"speed":[8,8,8],"size":[1,1,1],"heatcap":[6,7,8],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"撞锤加农炮","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战/大炮","attack_bonus":[0,0,0],"accuracy":[1,2,3],"range":[{"type":"Range","val":5},{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[5,5,5]}],"effect":"这种长矛既可用作远程亦可用作近战武器，但不能在同一回合同时使用。在 T2~3 时，该武器可攻击两次，目标可以是同一个角色，也可以是两个不同角色。","id":"npcf_cn_cataphract_1","base":true},{"name":"践踏","type":"Trait","tags":[],"effect":"甲胄骑兵忽略交战并穿过但不能停止其他角色占据的空间，1/回合对这些角色造成 2/3/4 动能伤害。","id":"npcf_cn_cataphract_2","base":true},{"name":"钉刺","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"甲胄骑兵在直线上移动最多 8 空间，选择一个甲胄骑兵通过或结束邻近的角色；该角色进行+1 难度机体豁免。失败则被甲胄骑兵擒拿并拖拽至移动结束终点。","id":"npcf_cn_cataphract_3","base":true},{"name":"单点防御盾","type":"System","tags":[{"id":"tg_shield"}],"effect":"甲胄骑兵对最近的敌方角色所有伤害具备抗性。若多个角色距离相等，则该效果不适用。","id":"npcf_cn_cataphract_4","base":true}],"optional":[{"name":"导电套索","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_round","val":1}],"effect":"在视线射程 5 内的一个角色必须通过机体豁免。失败则会被拉到尽可能靠近甲胄骑兵的位置；若对方至邻近，则甲胄骑兵自动擒拿对方。","id":"npcf_cn_cataphract_5","base":false},{"name":"长矛射击","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"甲胄骑兵以线形 5 发射一支导电长矛。受影响区域内所有角色必须通过工程豁免否则受扰直到对方下一回合结束。","id":"npcf_cn_cataphract_6","base":false},{"name":"导电投石索","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"射程 10 内的飞行角色必须通过敏捷豁免。若失败则立即降落并固定直到对方下一回合结束。此效果算没有伤害的坠落。","id":"npcf_cn_cataphract_7","base":false},{"name":"电容释放","type":"Trait","tags":[],"effect":"只要甲胄骑兵未被缓慢或固定，就获得对能量伤害和热度的抗性。在甲胄骑兵回合结束时，所有与之相邻近角色受到 2/3/4 热度。","id":"npcf_cn_cataphract_8","base":false},{"name":"冲锋","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"甲胄骑兵以直线移动等同速度的空间，忽略反应和交战，然后用撞锤加农炮攻击射程内的目标。","id":"npcf_cn_cataphract_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_demolisher","name":"粉碎者","role":"卫兵","role_en":"defender","page":290,"pages":[290],"flavor":"对贾迪戈莫拉城（Jadigmora City）漫长的围攻，见证了第一台真正粉碎者骨架的诞生。基于老式狂战士机甲，粉碎者用更持久的系统取代了戏剧性热流系统，改进了液压强度以及超大规模近战武器稳定器。粉碎者驾驶员很快发现了震波武器的一系列新用途。名为海耶斯·罗斯福德（Hayes Rothford）的枪骑兵同他的 NHP 克拉克（Clarke），是第一位真正展示了该平台力量的驾驶员/副驾驶员团队，他们单枪匹马在低轨道击落了一艘攻城护卫舰。","tactics":"粉碎者是缓慢而坚韧的卫兵，当他们与敌人接近时会给予大量伤害并晕眩。在近战中使用他们的大小和力量迫使敌人角色移动离开而不是与他们战斗，然后使用挖壕固守抵御重击。","stats":{"hull":[3,4,6],"sys":[-1,-1,-1],"agi":[-2,-2,-2],"eng":[2,3,4],"hp":[15,20,25],"armor":[2,2,2],"evasion":[6,6,6],"edef":[7,7,7],"speed":[2,2,3],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"毁灭重锤","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[-1,-1,-1],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Explosive","val":[10,14,16]}],"effect":"","on_hit":"目标必须通过机体豁免否则晕眩直到对方下一回合结束。","id":"npcf_cn_demolisher_1","base":true},{"name":"掘壕固守","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一次攻击命中粉碎者，但伤害还未掷出。","effect":"获得对所有攻击伤害的抗性，但缓慢直到自己下一回合结束。","id":"npcf_cn_demolisher_2","base":true},{"name":"冲击装甲","type":"Trait","tags":[],"effect":"粉碎者对近战武器具有抗性。","id":"npcf_cn_demolisher_3","base":true},{"name":"重型骨架","type":"Trait","tags":[],"effect":"粉碎者无法被小于自身的角色推，拉，伏卧或击退。","id":"npcf_cn_demolisher_4","base":true}],"optional":[{"name":"连柄大横扫","type":"System","tags":[{"id":"tg_full_action"}],"attack_bonus":[1,2,3],"effect":"粉碎者以爆发 2 弧度横挥毁灭重锤取代正常攻击。对影响区域内任意角色进行近战攻击。命中则目标受到4/6/8 爆炸伤害并受损直到对方下一回合结束。","id":"npcf_cn_demolisher_5","base":false},{"name":"动能代偿","type":"Trait","tags":[],"effect":"每次粉碎者使用毁灭重锤未命中则所有后续攻击获得+1 准度直到下次命中。该准度可多次叠加。","id":"npcf_cn_demolisher_6","base":false},{"name":"震荡导弹","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"视线射程 5 内粉碎者所选的任意角色必须通过机体豁免否则缓慢和受损直到对方下一回合结束。","id":"npcf_cn_demolisher_7","base":false},{"name":"地震毁灭者","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"除了能飞行的角色，所有在锥形 3 或线形 5 内的角色必须通过敏捷豁免否则晕眩直到对方下一回合结束。","id":"npcf_cn_demolisher_8","base":false},{"name":"当头棒喝","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"tech_type":"Quick","effect":"粉碎者选择其邻近的一个角色：对方必须通过工程豁免否则晕眩直到对方下一回合结束。","id":"npcf_cn_demolisher_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_engineer","name":"工程师","role":"突击","role_en":"striker","page":291,"pages":[291],"flavor":"各种类型的本地化工程师级机甲在全银河系中都颇为常见，专属于它们自身所运作的天体或舞台。工程师作为一种原型早已存在，但直到拉斯·萨姆拉兵工厂公务主管科里达·伊索尔德-诺莱（Corrida Isolde-Nollet）提出了完整的设计原则，它才在很大程度上被定义。在所有情况下，工程师的任务都呈一致性：保卫、维护、安全。工程师在战线中部或后方的最佳作战位置，协调重要阵地的防御，监督所有作战资产的全面部署。记住：若你不能了解敌人，你就会输。","tactics":"工程师的可部署炮塔使他们成为强大的武力倍增器，他们可以每回合部署一个。若敌人不能快速对付工程师炮塔，他们的潜在危害迅速飙升——当他们瞄准带有工程师标记的角色时更是如此。没有工程师标记，炮塔会攻击最近目标，玩家可以借此来控制谁受到伤害。","stats":{"hull":[-1,-1,-1],"sys":[1,2,3],"agi":[-1,-1,-1],"eng":[3,4,6],"hp":[20,20,20],"armor":[0,0,0],"evasion":[7,9,11],"edef":[10,10,12],"speed":[3,3,3],"size":[1,1,1],"heatcap":[10,12,14],"save":[10,12,14],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"高射加农炮","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"该武器对飞行目标攻击有+2 准度。","id":"npcf_cn_engineer_1","base":true},{"name":"可部署炮塔","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_quick_action"}],"effect":"可部署炮塔（大小 1/2，HP5/8/10，回避 10，电子防御 10，标签：无人机）这些自我建构炮塔可部署到任何邻近的自由空间。在工程师回合，部署炮塔会攻击射程 10 内最近的敌方角色。攻击+1/+2/+3，伤害 4/5/6 动能伤害。工程师最多同时拥有 6 台已部署炮塔，若工程师被摧毁，所有炮塔均失效。","id":"npcf_cn_engineer_2","base":true},{"name":"工程师标记","type":"Trait","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"直到工程师下一回合结束，工程师可部署炮塔将攻击它们选择的目标（在射程内），而不是攻击最近的敌方角色。","id":"npcf_cn_engineer_3","base":true}],"optional":[{"name":"强力部署者","type":"Trait","tags":[],"effect":"工程师可使用可部署炮塔一次部署 2 台炮塔。如此行事，该系统视为再充能 4+直到下一次再充能。","id":"npcf_cn_engineer_4","base":false},{"name":"穹盾协议","type":"Trait","tags":[],"effect":"可部署炮塔对飞行目标+2 准度。","id":"npcf_cn_engineer_5","base":false},{"name":"牧羊人领域","type":"Trait","tags":[],"effect":"工程师邻近无人机、物体和掩体获得伤害抗性。","id":"npcf_cn_engineer_6","base":false},{"name":"移动炮塔","type":"Trait","tags":[],"effect":"工程师回合开始时，可向任意方向移动所有可部署炮塔最多 3 空间。","id":"npcf_cn_engineer_7","base":false},{"name":"军火库","type":"Trait","tags":[],"effect":"工程师使用可部署炮塔时，可为其炮塔选择以下一种改造：• 狱火：炮塔攻击变成锥形 3，2/3/4 燃烧伤害。• 地狱风暴：炮塔攻击变成射程 15，溅射 1，2/3/4 爆炸。• 猎人：炮塔攻击获得可靠 1。• 蓄势待发：炮塔或工程师摧毁时，炮塔在爆发 1 爆炸。受影响区域内角色必须通过敏捷豁免否则受到 7/9/11 爆炸伤害。","id":"npcf_cn_engineer_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_goliath","name":"歌利亚","role":"卫兵","role_en":"defender","page":292,"pages":[292,293],"flavor":"在摇篮外八环地区的马德雷山线，檀君（Dangun）骨架是常有之物。由帕克装甲系统（Park Armored Systems）公司研制，由匕首中队（Dagger Squadron）雇佣军连队推广，檀君因其韧性和动能交换能力以及可靠的全战区性能而广受欢迎。檀君是构建突击部队的核心力量——能够搭载强大磁场技术装备的泰坦级机甲，其设计在动能战斗中难以被对手克制。帕克装甲系统公司的投资组合中有诸多小型舰队合同，是家值得关注的制造商；事实上，哈里逊兵工厂已对此给予特别关注，并在万物网上传言表明两家公司可能在不久将来建立合作伙伴关系。","tactics":"歌利亚是机动性相对缓慢卫兵，这会为他们带来敌人。通过挤压目标，歌利亚迫使危险的敌人集中攻击他们；它只需要视线，让歌利亚能够瞄准高机动或难以命中的角色。歌利亚庞大的身躯也为他们的盟友提供了掩护。","stats":{"hull":[4,6,6],"sys":[1,1,1],"agi":[-2,-2,-2],"eng":[0,0,2],"hp":[25,30,35],"armor":[0,0,0],"evasion":[6,6,6],"edef":[6,6,6],"speed":[3,3,3],"size":[3,3,3],"heatcap":[8,10,12],"save":[11,13,15],"sensor":[10,10,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"鼓轮霰弹枪","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[5,5,5]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。","id":"npcf_cn_goliath_1","base":true},{"name":"挤压目标","type":"Tech","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"视线感应内的一个角色攻击歌利亚外其他角色时+3 难度，直到歌利亚下一回合开始。","id":"npcf_cn_goliath_2","base":true},{"name":"重型骨架","type":"Trait","tags":[],"effect":"歌利亚无法被小于自身的角色推，拉，伏卧或击退。","id":"npcf_cn_goliath_3","base":true},{"name":"护法","type":"Trait","tags":[],"effect":"邻近盟友可将歌利亚充当硬性掩护。","id":"npcf_cn_goliath_4","base":true},{"name":"围攻装甲","type":"Trait","tags":[],"effect":"歌利亚对射程 3 以外的所有攻击伤害具有抗性。","id":"npcf_cn_goliath_5","base":true}],"optional":[{"name":"斥力肘击","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"歌利亚射程 2 内的角色必须通过机体豁免否则受到 4/5/6 动能伤害，从歌利亚推离 5 空格并伏卧。","id":"npcf_cn_goliath_6","base":false},{"name":"钉栓","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"歌利亚射程 2 内的一个角色固定和受损，直到对方对歌利亚造成伤害，歌利亚陷入晕眩或被摧毁，或当歌利亚以其他角色为目标结束。此效果持续期间，歌利亚被固定。","id":"npcf_cn_goliath_7","base":false},{"name":"粉碎性拥抱","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"邻近歌利亚的角色必须通过敏捷豁免否则自动被歌利亚擒拿并受扰，直到不再擒拿为止。歌利亚一次只能以该方式擒拿一个角色。","id":"npcf_cn_goliath_8","base":false},{"name":"警惕性护法","type":"Trait","tags":[],"effect":"从歌利亚提供的掩护中受益的盟友角色获得所有伤害抗性。","id":"npcf_cn_goliath_9","base":false},{"name":"报复","type":"Trait","tags":[],"effect":"每当歌利亚受到伤害时，其下次攻击额外造成+2/+3/+4 伤害。该加值最多可叠加+8。该加值在歌利亚发动攻击时，或在下一回合结束时丢失。","id":"npcf_cn_goliath_10","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_hive","name":"蜂巢","role":"操纵","role_en":"controller","page":294,"pages":[294],"flavor":"理论上，火卫二事件后发展起来的无人机和无人机群与其老前辈没有太大区别：它们会建立本地万物网；制造并部署一个或半个世纪的无人机；协调它们以实现各自目标。尽管如此，复杂的处理员-训练员关系允许驾驶员在直接控制和自主操作之间切换，这会在连续操作无人机一个月后造成心理创伤。因此，建议他们每两周轮换一次配对的蜂巢枢纽。","tactics":"蜂巢使用剃刀蜂群控制战场，为盟友提供软性掩护，并排斥区域内他们的敌人。部署峰群并使用雄蜂攻势来锁定敌人，或者将他们移动到蜂群和盟友范围内。","stats":{"hull":[-1,-1,1],"sys":[2,4,5],"agi":[0,0,0],"eng":[1,1,1],"hp":[20,20,20],"armor":[0,1,1],"evasion":[8,8,10],"edef":[10,13,16],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,8],"save":[12,14,17],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"猎杀者虫巢","type":"Weapon","tags":[{"id":"tg_smart"},{"id":"tg_seeking"}],"weapon_size":"主武器","weapon_kind":"巢房","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Burn","val":[3,3,3]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。","id":"npcf_cn_hive_1","base":true},{"name":"雄蜂攻势","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"蜂巢对感应内一个角色进行科技攻击。成功则目标将选择其一：对方固定并受损直到下一回合结束，或立即朝蜂巢所选方向移动 5 空间。该移动忽略交战和反应。","id":"npcf_cn_hive_2","base":true},{"name":"剃刀蜂群","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"蜂巢在感应内某自由空间部署一个溅射 1 剃刀蜂群。盟友角色只要部分处于受影响区域内便获得软性掩护。敌对角色至少在该区域内开始其回合或在轮内首次进入该区域则受到 2/4/6 燃烧伤害。蜂巢可部署任意数量剃刀蜂群，每剃刀蜂群会持续至场景结束，或直到蜂巢被摧毁。","id":"npcf_cn_hive_3","base":true}],"optional":[{"name":"电镀纳米云","type":"System","tags":[],"effect":"蜂巢射程3 内敌方角色在其回合开始时受到2 燃烧伤害；此外直到对方离开射程 3，否则进行所有系统检定和豁免以及所有科技攻击+1/2/3 难度。","id":"npcf_cn_hive_4","base":false},{"name":"机动蜂群","type":"Trait","tags":[],"effect":"蜂巢回合开始可移动所有剃刀蜂群任何方向最多 2空间，包括进入其他角色占据的空间。","id":"npcf_cn_hive_5","base":false},{"name":"倾泻蜂群","type":"Trait","tags":[],"effect":"角色受到剃刀蜂群燃烧伤害时必须通过系统豁免，否则在受到伤害后立即向蜂巢所选方向移动 4 空间。该移动忽略交战和反应。","id":"npcf_cn_hive_6","base":false},{"name":"研磨小队战术","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"accuracy":[1,1,1],"tech_type":"Quick","effect":"蜂巢释放难以击中的微型无人机，对视线感知内一个敌方角色使用科技攻击。命中则无人机紧紧抓住目标，对方每次执行任意动作或反应受到 2 燃烧伤害直到对方下一回合结束。","id":"npcf_cn_hive_7","base":false},{"name":"寻索云","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"巢房","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Cone","val":5}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"受到该武器伤害的角色被锁定。","id":"npcf_cn_hive_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_hornet","name":"马蜂","role":"操纵","role_en":"controller","page":295,"pages":[295],"flavor":"勇士巴龙公司（SatriaBarong）的击剑手（Espada）系列半身骨架机甲长期以来是底盘赛道的热门选择；尤其是击剑手机甲是备受尊敬的勇士巴龙–岛野奢华（ShimanoLUX）底盘赛车队的首选。近来，勇士巴龙在 SSC 授权下开始研制一款去岛野奢华品牌化的击剑手军用规格变体，由此诞生了马蜂原型机，为其他公司提供了一个适配和改进的平台。这些竞争者中最著名的是钱德拉塞卡与赫歇尔公司（Chandrasekhar & Herschel），他们是新蓝移大奖赛领域的主要赞助商。","tactics":"马蜂是小巧而迅速的操控者，很难击中，且非常恼人。他们造成的伤害有限，但他们的能力造成移动减少状态是非常适合锁定敌人的突击。对他们敌人来说幸运的是，马蜂差劲的电子防御使他们容易受到智慧武器和科技攻击。","stats":{"hull":[-2,-2,-2],"sys":[2,3,4],"agi":[2,4,6],"eng":[0,0,0],"hp":[8,8,8],"armor":[0,0,0],"evasion":[16,18,20],"edef":[6,7,8],"speed":[6,8,10],"size":[0.5,0.5,0.5],"heatcap":[5,6,7],"save":[12,14,16],"sensor":[5,5,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"针刺手枪","type":"Weapon","tags":[],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Energy","val":[1,2,3]}],"effect":"","on_hit":"目标受损直到对方下一回合结束。","id":"npcf_cn_hornet_1","base":true},{"name":"SCC 总套组","type":"System","tags":[],"effect":"马蜂可以在移动或推进时悬浮。","id":"npcf_cn_hornet_2","base":true},{"name":"迂回","type":"Trait","tags":[],"effect":"每轮以一个反应可对马蜂的第一次攻击自动失败。","id":"npcf_cn_hornet_3","base":true},{"name":"钉刺系统","type":"Tech","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"马蜂对感应内角色进行科技攻击。命中则对方会受到 3/4/5 热度并受扰直到对方下一回合结束。","id":"npcf_cn_hornet_4","base":true}],"optional":[{"name":"适应/规避/脱离","type":"Trait","tags":[],"effect":"马蜂获得对擒拿的免疫且始终忽视交战。","id":"npcf_cn_hornet_5","base":false},{"name":"本影封锁","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"某角色在视线感应范围内试图攻击。","effect":"目标必须通过系统检定否则攻击自动失败。","id":"npcf_cn_hornet_6","base":false},{"name":"超音速","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"马蜂以不可思议的速度飞至视线射程 50 内的空间视为瞬间移动。","id":"npcf_cn_hornet_7","base":false},{"name":"巫术导弹","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"副武器","weapon_kind":"发射器","attack_bonus":[0,0,0],"accuracy":[1,2,3],"range":[{"type":"Range","val":5},{"type":"Blast","val":1}],"damage":[{"type":"Heat","val":[3,4,5]}],"effect":"","id":"npcf_cn_hornet_8","base":false},{"name":"锁定/维持标枪","type":"System","tags":[{"id":"tg_full_action"}],"effect":"马蜂向视线射程 5 内的目标射出标枪。目标必须通过机体豁免否则被刺穿，此时标枪将受害者顶死在地面（或其他表面）上使对方固定和离散。对方自身或任何邻近角色可尝试用一个完整动作进行机体豁免来移除标枪；否则，该效果持续到场景结束或直到马蜂再次使用该动作。","id":"npcf_cn_hornet_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_mirage","name":"蜃楼","role":"支援","role_en":"support","page":296,"pages":[296,297],"flavor":"蜃楼级机甲机甲通常被受雇于与地平线结盟的武装团体所使用。由于没有原始制造商，它们是少数几个可供知情组织使用的非荷鲁斯开源模式组之一。蜃楼使用先进礼拜编码，用幻术和误导的面纱把自己和盟友包裹起来。虽然围绕这些机甲的扭曲效应是显而易见地由传感器扭曲引起，但它们的力量甚至足以影响到有机系统——在接触时需谨慎。","tactics":"蜃城是强大的支援机甲，能够随意传送他们的盟友，并用扭曲探头关闭远程攻击者。他们可让盟友角色隐形，但同时也会变得脆弱。这些优势是有代价的：忽略掩护的武器和系统——如“引导”武器——可以绕过扭曲探头，蜃城本身不会造成任何伤害。","stats":{"hull":[-2,-2,-2],"sys":[2,3,4],"agi":[1,2,3],"eng":[1,2,3],"hp":[10,12,14],"armor":[0,0,0],"evasion":[10,12,14],"edef":[12,15,18],"speed":[5,6,7],"size":[0.5,0.5,0.5],"heatcap":[6,6,6],"save":[11,14,17],"sensor":[15,15,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"扭曲探头","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"accuracy":[1,1,1],"tech_type":"Quick","effect":"蜃楼对感应内一个目标进行科技攻击。成功则对方受到 2/3/4 热度且下一回合结束前所有攻击目标视为拥有软性掩护。","id":"npcf_cn_mirage_1","base":true},{"name":"现实闪烁","type":"Trait","tags":[],"effect":"蜃楼在执行一次标准移动时瞬间移动。","id":"npcf_cn_mirage_2","base":true},{"name":"数据面纱","type":"System","tags":[],"effect":"默认蜃楼处于隐形并可用快速动作将此状况转移视线内另一角色。蜃楼不再隐形，只有以快速动作将其转移回或转移至另一角色蜃楼才恢复状况；否则此效果将持续到蜃楼被摧毁。","id":"npcf_cn_mirage_3","base":true},{"name":"漏洞扫描器","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"蜃楼先进电子对抗系统对敌人系统造成严重破坏，致使它们在战场上误报。它们可在感应内瞬间移动最多2 个盟友角色，向任何方向移动 5 空间，揭示其“真实”位置。该移动忽略交战和反应。蜃楼同时获得信标光点反应。\n【信标光点】（反应，1/轮）触发：一个敌对角色在视线内执行动作。\n效果：蜃楼可让一个盟友角色向任意方向瞬间移动 5 空间。","id":"npcf_cn_mirage_4","base":true}],"optional":[{"name":"幻术子程序","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"蜃楼对感应内一个目标进行科技攻击。成功则目标视所有蜃楼的盟友角色为隐形直到对方下一回合开始。","id":"npcf_cn_mirage_5","base":false},{"name":"扭曲目标","type":"Trait","tags":[],"effect":"蜃楼射程 50 内所有盟友角色获得软性掩护。若蜃楼受伤害，此效果直到对方下一回合开始时结束。","id":"npcf_cn_mirage_6","base":false},{"name":"超折叠挤压","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[1,2,3],"tech_type":"Quick","effect":"蜃楼对射程 5 的一个敌方角色进行科技攻击。成功则目标与蜃楼视线内的某盟友角色交换位置，由蜃楼选择同时进行瞬间移动。飞行角色无法与不飞行角色交换，反之亦然。","id":"npcf_cn_mirage_7","base":false},{"name":"虚伪神像显化","type":"Tech","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_tech"}],"tech_type":"Full","effect":"蜃楼视线射程5 内自由空间创造三个大小1 数据构念。这些构念提供软性掩护但可通过。当有敌方角色经过构念时该构念会消失，而对方必须通过系统豁免否则受到 2 热度并固定直到下一回合结束。蜃楼回合中任意时点，只要有足够空间就可以将视线内某盟友瞬间移动到数据构念位置，让其消失。","id":"npcf_cn_mirage_8","base":false},{"name":"多重性","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"视线内一个盟友角色被命中。","effect":"攻击者必须通过系统豁免。失败则蜃楼的盟友将获得对攻击伤害和效果的免疫，并可向自选方向瞬间移动最多 5 空间。","id":"npcf_cn_mirage_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_operator","name":"操作员","role":"炮击","role_en":"artillery","page":298,"pages":[298],"flavor":"操作员是已知的未知，极少能在前线遭遇，但这不该被误认其脆弱性。操作员在任何方面都相当危险而致命。和他们机甲一样，操作员身体中也装载着最先进的技术。当他们在战斗中死去，他们的身体以及他们的机甲会一同自焚，将任何技术和数据化为灰烬。","tactics":"操作员是极具机动能力的精英炮击机甲。他们不是特别硬，但可以使用回溯驱动在战场周围瞬间移动，使自己处于有利位置：在障碍物或地形上，或在掩体——任何他们可以使用高度精确的猛禽等离子步枪狙击敌人的地方。","stats":{"hull":[2,3,4],"sys":[2,3,4],"agi":[2,3,4],"eng":[2,3,4],"hp":[10,12,15],"armor":[0,0,0],"evasion":[10,12,14],"edef":[10,12,14],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"猛禽等离子步枪","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[2,2,2],"range":[{"type":"Range","val":20}],"damage":[{"type":"Energy","val":[7,7,7]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。","id":"npcf_cn_operator_1","base":true},{"name":"回溯驱动","type":"System","tags":[],"effect":"操作员在执行标准移动时瞬间移动。","id":"npcf_cn_operator_2","base":true},{"name":"瞬步","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"操作员可瞬间移动到视线射程 50 内的自由空间。","id":"npcf_cn_operator_3","base":true},{"name":"自我消除","type":"Trait","tags":[],"effect":"操作员机体被摧毁时会立即释放一波过热等离子体自焚。当次此动作执行时，邻近操作员的所有角色必须通过敏捷豁免否则受到 4/6/8 能量伤害。成功则伤害减半。随后该机甲从战场上移除——它被彻底消灭了。","id":"npcf_cn_operator_4","base":true}],"optional":[{"name":"褪色生成器","type":"System","tags":[],"effect":"操作员回合结束时会隐形直到下一回合开始。若受到伤害或进行反应，该状况立即停止。","id":"npcf_cn_operator_5","base":false},{"name":"瞬动破片","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"操作员瞬间移动到视线射程 15 内另一角色所占据的空间。目标必须通过敏捷豁免否则受到 4/8/12AP 能量伤害并受扰直到对方下一回合结束。成功则伤害减半。无论成功与否，操作员受到 1d6AP 能量伤害，并被放置在目标邻近自由空间中。","id":"npcf_cn_operator_6","base":false},{"name":"要塞","type":"Trait","tags":[],"effect":"操作员系统豁免+3 准度，针对它们的科技攻击+3难度。","id":"npcf_cn_operator_7","base":false},{"name":"散兵","type":"Trait","tags":[{"id":"tg_round","val":1}],"effect":"每回合一次，操作员回合中任意时点，可用一个自由动作进行推进。","id":"npcf_cn_operator_8","base":false},{"name":"超新星导弹","type":"Weapon","tags":[{"id":"tg_seeking"}],"weapon_size":"副武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15},{"type":"Blast","val":1}],"damage":[{"type":"Energy","val":[4,6,8]}],"effect":"","id":"npcf_cn_operator_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_priest","name":"司铎","role":"支援","role_en":"support","page":299,"pages":[299],"flavor":"司铎原型机甲可在科技狂热者邪教、超人类主义运动以及优先考虑技术霸权的国家或公司中找到。这些骨架被配置为将其敏感核心系统与共感机体互相连接，创造数字超结构以建立和保持全战区控制。司铎原型底盘和策略的使用先驱是由一支被称为玛雅信使（Messengers of MAIA）的神秘小团体。表面上信使们是个情报集团，他们推动所有系统（合成体和有机体）达到他们的理论极限。他们甚至在相互联系的驾驶员之间分享感官输入——一种已知会导致超感知逃逸和其他升格精神状态的体验。","tactics":"司铎是强大的支援机甲，使用他们的授权可以高效地配合其他角色。使用他们的散列护盾保护脆弱目标，并授权给盟友突进或卫兵。敌人可以通过将司铎与他们的同伴分开来解除授权，此时双方都对状态效果变得脆弱。","stats":{"hull":[-1,-1,-1],"sys":[2,4,6],"agi":[-1,-1,-1],"eng":[2,3,4],"hp":[10,13,16],"armor":[0,0,0],"evasion":[10,10,10],"edef":[12,15,18],"speed":[5,5,6],"size":[1,1,1],"heatcap":[10,10,10],"save":[11,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"誓绝","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"司铎对感应内一个目标进行科技攻击。成功则对方每次攻击都受到 2/3/4 热度直到对方下一回合结束。","id":"npcf_cn_priest_1","base":true},{"name":"坚定目标","type":"Trait","tags":[],"effect":"司铎系统豁免+1 准度，针对它们的科技攻击+1难度。","id":"npcf_cn_priest_2","base":true},{"name":"授权","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"司铎将射程 5 内一个盟友机甲或载具的系统连接起来。只要对方保持连接并在射程 5 内，目标所有攻击就能获得+1/2/3 准度且可使用司铎系统代替自身。然而若二者之一受扰、受损或晕眩，另一个角色也会在相同持续时间内接受该状态或直到连接被切断。若其中一个角色被摧毁或彼此移动超过 5 空间，则连接被切断。司铎一次只能与一个角色连接。","id":"npcf_cn_priest_3","base":true},{"name":"散列护盾","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"司铎释放微型无人机聚集在附近机甲周围提供保护。司铎或处于感应内一个盟友将从之后的 1d3 次攻击中获得对伤害和热度的抗性。该效果不会叠加。","id":"npcf_cn_priest_4","base":true}],"optional":[{"name":"伟大授权","type":"Trait","tags":[],"effect":"授权使目标对所有伤害获得抗性，但司铎在连接时固定。","id":"npcf_cn_priest_5","base":false},{"name":"附魔盾","type":"Trait","tags":[],"effect":"散列护盾同时给予护盾 5/6/8。","id":"npcf_cn_priest_6","base":false},{"name":"圣所","type":"Tech","tags":[{"id":"tg_full_tech"}],"tech_type":"Full","effect":"司铎感应内选择一个盟友角色。在目标受到攻击之前，攻击者必须先通过系统豁免。攻击者失败则无法再次攻击目标，直到该角色的下一回合开始。","id":"npcf_cn_priest_7","base":false},{"name":"要塞","type":"Trait","tags":[],"effect":"坚定目标的所有值从+1 提升为+3。","id":"npcf_cn_priest_8","base":false},{"name":"分形攻势","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":5}],"trigger":"被授权连接的一个角色受到伤害。","effect":"攻击者进行系统豁免。若失败则晕眩直到对方下一回合结束。","id":"npcf_cn_priest_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_pyro","name":"纵火狂","role":"卫兵","role_en":"defender","page":300,"pages":[300],"flavor":"海西危机后，由枪骑兵弗拉马（Flama）和他名副其实的魔鬼军团第一次普及，纵火狂在全银河系被斥为军事国和企业国拥有的纯粹破坏性力量的化身。它们的使用在为达到目的不择手段的组织中颇为常见。纵火狂拥有良好装甲，隔热性能比大多数同等重量的底盘都要好，其设计用来控制难以置信的内部热量，同时向敌人投射挥发性化学物质和火焰。纵火狂通常用于城市和丛林战，在那里他们得以用来铲除固守的防御者。","tactics":"纵火狂是缓慢而坚韧的机甲，对已遭受烧伤的角色尤为有效。若玩家不保持他们的距离，纵火狂便可向他们使用爆炸性通风倾倒大量的热量。放置纵火狂，让他们使用防火带盾保护盟友免受火力。然而请注意，玩家可以移动盾牌将其效力降低到零，或者他们可以通过使用晕眩或击退武器攻击纵火狂使其失效。","stats":{"hull":[1,2,3],"sys":[-1,-1,0],"agi":[-1,0,0],"eng":[3,4,5],"hp":[10,13,15],"armor":[3,3,4],"evasion":[8,8,8],"edef":[8,8,8],"speed":[2,2,2],"size":[1,1,1],"heatcap":[12,12,16],"save":[10,12,14],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"火焰喷射器","type":"Weapon","tags":[{"id":"tg_heat_self","val":4}],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Cone","val":5}],"damage":[{"type":"Burn","val":[3,4,5]}],"effect":"该武器对已燃烧的角色造成双倍燃烧。","id":"npcf_cn_pyro_1","base":true},{"name":"爆炸性通风","type":"System","tags":[{"id":"tg_full_action"}],"effect":"纵火狂清除所有热量。爆发 1 内的角色必须通过敏捷豁免否则受到等同纵火狂清除量一半的热度并伏卧。","id":"npcf_cn_pyro_2","base":true},{"name":"隔热","type":"Trait","tags":[],"effect":"纵火狂对燃烧免疫。","id":"npcf_cn_pyro_3","base":true},{"name":"防火带盾","type":"System","tags":[{"id":"tg_shield"}],"effect":"纵火狂回合结束时，视线内其中末端 1 空间与纵火狂邻近的自由空间创造出高 4 空间的线形 4 能量护盾。它不会阻挡视线，但提供软性掩护；当攻击一个受益于掩体的角色时，掷骰 1d6 出 4+视为未命中。这将持续到纵火狂下一回合开始，或纵火狂移动或晕眩。它无法和隐形叠用。","id":"npcf_cn_pyro_4","base":true}],"optional":[{"name":"无屏蔽反应堆","type":"Trait","tags":[],"effect":"角色开始回合中与纵火狂邻近，或在轮内首次与纵火狂邻近，则受到 2/3/4 热度。","id":"npcf_cn_pyro_5","base":false},{"name":"围攻装甲","type":"Trait","tags":[],"effect":"纵火狂对射程 3 以外的所有攻击伤害具有抗性。","id":"npcf_cn_pyro_6","base":false},{"name":"凝固汽油弹","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_loading"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Blast","val":1}],"damage":[{"type":"Burn","val":[3,4,5]},{"type":"Heat","val":[2,4,6]}],"effect":"","id":"npcf_cn_pyro_7","base":false},{"name":"超热","type":"Reaction","tags":[{"id":"tg_shield"}],"trigger":"纵火狂受到近战攻击的伤害。","effect":"纵火狂对所有攻击伤害获得抗性。攻击者必须通过工程豁免否则受到 2/4/6 燃烧伤害。","id":"npcf_cn_pyro_8","base":false},{"name":"爆炸性喷口","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"爆发 2 以内的敌人必须通过机体豁免否则击退至区域外并伏卧。然后纵火狂向任意方向飞行 5 空间，但必须在完成该动作后着陆。","id":"npcf_cn_pyro_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_rainmaker","name":"祈雨师","role":"炮击","role_en":"artillery","page":301,"pages":[301],"flavor":"这带有戏谑意味的“祈雨师”，是对专门使用火箭和导弹的机甲和驾驶员的绰号。祈雨师被灵活作战单位所青睐，它装载了武器移动平台，能够在任何范围内对付任何目标。","tactics":"祈雨师既是炮兵又是指挥者。他们的标枪火箭弹迫使角色避开某些区域或承受一定的伤害。他们还可以通过猎犬导弹和阿特拉斯导弹等可选系统造成延迟伤害。和其他炮击机甲一样，祈雨师自身相对来说比较脆弱。","stats":{"hull":[0,0,0],"sys":[2,3,3],"agi":[0,1,1],"eng":[0,0,1],"hp":[10,12,14],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,10,12],"speed":[3,3,3],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"导弹舱","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_reliable","val":[2,3,3]},{"id":"tg_knockback","val":1}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":20}],"damage":[{"type":"Explosive","val":[4,5,6]}],"effect":"该武器一次可以攻击 1~3 个角色。","id":"npcf_cn_rainmaker_1","base":true},{"name":"标枪火箭弹","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"祈雨师会在视线射程 20 内选择互相不邻近的 3 自由空间。所有角色都知悉选择了哪些空间。祈雨师向空中发射一连串自动瞄准火箭：下次当一个敌对角色在选定空间移动穿越，或在其上开始其回合，或从上方不超过 10 空间的位置经过——会被火箭击中造成 5/6/7 动能伤害。每空格只能触发一次。该效果持续到祈雨师下一回合开始。","id":"npcf_cn_rainmaker_2","base":true},{"name":"狩猎者","type":"Trait","tags":[],"effect":"对锁定的敌方角色，祈雨师武器获得智慧，引导和AP。","id":"npcf_cn_rainmaker_3","base":true}],"optional":[{"name":"地狱导弹","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"祈雨师射程 20 某起点向外锥形 3 内所有角色受到4/6/8 能量伤害和 2 热度，通过敏捷豁免伤害减半。该系统无需视线，只需到达目标可能路线。","id":"npcf_cn_rainmaker_4","base":false},{"name":"猎犬导弹","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"猎犬导弹（大小 1/2，HP10/15/20，回避 10，电子防御 10，标签：无人机）祈雨师邻近空间部署猎犬导弹，选择视线射程 20内一个目标。祈雨师开始回合时导弹向目标飞行 3 空间，若目标被锁定飞行 6 空间。它直线移动，若需要可绕过掩体和地形机动。当它与角色碰撞或到达目标时会产生爆发 1 的爆炸。受影响区域内角色受到 16/20/24 能量伤害，通过敏捷豁免则伤害减半。","id":"npcf_cn_rainmaker_5","base":false},{"name":"无尽之雨","type":"Trait","tags":[],"effect":"祈雨师为标枪火箭弹选择 6 空间，而非 3。","id":"npcf_cn_rainmaker_6","base":false},{"name":"齐射","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"选择视线射程 20 内所有角色受到 4/6/8 爆炸伤害，成功进行敏捷豁免伤害减半。","id":"npcf_cn_rainmaker_7","base":false},{"name":"阿特拉斯导弹","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"祈雨师选择视线射程 30 内一个地面空间，所有角色都知悉选择了哪些空间。祈雨师发射一枚导弹，在下一轮结束时该地点造成溅射 2 的爆炸；受影响角色受到16/20/24 爆炸伤害，成功进行敏捷豁免伤害减半。","id":"npcf_cn_rainmaker_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_ronin","name":"浪人","role":"突击","role_en":"striker","page":302,"pages":[302],"flavor":"浪人骨架不同于狂战士和粉碎者所青睐的机甲，它们并非为创造性战术应用而改造或临时制作——它们是精品制造者专为近身格斗而精心设计。尽管在多数评论家看来有些过时，但静滞和磁力防御技术的兴起使得浪人在现代战斗中更具活力。浪人在武术文化和表演格斗厂商中都很常见，高超的肉搏能力使它们在竞争中脱颖而出。在偏爱远程战斗的文化中，浪人型机甲的使用较少，但那些使用了古典武器并幸存下来的驾驶员却享有某种荣誉。传奇枪骑兵须佐之男（Susanoo）将这一原型机抬升至神话版的地位，在新塞莱斯廷之殇（Neo-Celestine Disappointment）期间，她驾驶着代言的 GRAM 科技公司（GRAMtech ）的打击者一型底盘，与无数信天翁机队伴飞作战。","tactics":"浪人是简单直接的高伤害近战突击者。弹反使敌人用远程武器攻击浪人变得非常危险，但他们往往会在装甲敌人手中遭重，并严重依赖准度。","stats":{"hull":[1,2,4],"sys":[-1,-1,-1],"agi":[2,4,5],"eng":[-1,-1,-1],"hp":[18,20,22],"armor":[0,0,0],"evasion":[10,13,16],"edef":[7,7,7],"speed":[5,5,6],"size":[1,1,1],"heatcap":[7,7,7],"save":[10,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"碳纤维剑","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[1,1,1],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[6,6,6]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。\n会心一击：造成+1d6 动能伤害。","id":"npcf_cn_ronin_1","base":true},{"name":"弹反","type":"Reaction","tags":[{"id":"tg_shield"},{"id":"tg_round","val":1}],"trigger":"浪人受到远程攻击的伤害。","effect":"掷骰 1d6：4+，浪人获得该攻击的伤害抗性，并且攻击者必须对自己重复此次攻击。","id":"npcf_cn_ronin_2","base":true}],"optional":[{"name":"充能斩","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"所有与浪人邻近的角色受到 6/9/12 动能伤害，若通过敏捷豁免则减半。","id":"npcf_cn_ronin_3","base":false},{"name":"箔条发射器","type":"Trait","tags":[],"effect":"浪人推进后获得软性掩护直到下一个回合开始。","id":"npcf_cn_ronin_4","base":false},{"name":"共鸣锋刃","type":"Trait","tags":[],"effect":"被浪人伤害的角色将获得一个浪人标记。浪人回合开始时可用一个自由动作清除所有浪人标记，自动对所有浪人标记角色造成 1d6AP 动能伤害并清除标记。","id":"npcf_cn_ronin_5","base":false},{"name":"直觉模式","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"直到浪人下一个回合结束，每回合首次被选为攻击目标时，浪人可率先以反应使用碳纤维剑攻击射程内的角色。","id":"npcf_cn_ronin_6","base":false},{"name":"加长刀刃","type":"System","tags":[],"effect":"浪人的碳纤维剑变为威胁 3。当浪人每回合首次用它进行会心一击时，威胁内的所有角色都将受到 2/3/4动能伤害——包括目标。","id":"npcf_cn_ronin_7","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_scourer","name":"清扫器","role":"突击","role_en":"striker","page":304,"pages":[304],"flavor":"清扫器级机甲的特点是通过大规模输出递归能量平台携带致命的能量武器。这些机甲遍布银河系，扮演着专业角色，用强大的光束攻击支援常规地面部队，既能够轻松阻止电子威胁，也能够有效打击敌方士兵。","tactics":"清扫器专注于单目标施行多次攻击造成大量伤害。它们可以很容易地用来对付移动缓慢或强硬的难敌。然而，当被迫转换目标时，他们的效率会降低许多，他们需要保持不动才能充分利用自己的武器。","stats":{"hull":[1,2,3],"sys":[0,0,1],"agi":[0,1,1],"eng":[1,2,4],"hp":[10,13,15],"armor":[2,2,2],"evasion":[8,9,10],"edef":[8,8,8],"speed":[4,4,4],"size":[1,1,1],"heatcap":[8,8,12],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"热能喷枪","type":"Weapon","tags":[{"id":"tg_heat_self","val":4}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":8}],"damage":[{"type":"Energy","val":[6,8,10]}],"effect":"","id":"npcf_cn_scourer_1","base":true},{"name":"倾泻聚焦","type":"Trait","tags":[],"effect":"当清扫器使用热能喷枪命中时，若目标在上一轮中也被热能喷枪成功命中，则目标受到 5/7/8 燃烧伤害。","id":"npcf_cn_scourer_2","base":true},{"name":"冷却模块","type":"System","tags":[],"effect":"在清扫器回合开始时，若它们在上一回合结束后没有移动包括强制移动，则清扫器清除所有热度。","id":"npcf_cn_scourer_3","base":true},{"name":"烧蚀保护层","type":"System","tags":[],"effect":"清扫器对能量伤害具有抗性。","id":"npcf_cn_scourer_4","base":true}],"optional":[{"name":"超压","type":"Trait","tags":[],"effect":"受倾泻聚焦影响的角色会离散和缓慢直到对方下一回合结束。","id":"npcf_cn_scourer_5","base":false},{"name":"紧急通风口","type":"Trait","tags":[],"effect":"当清扫器超过其热度上限或被晕眩时，它们隐形直到下一回合开始。","id":"npcf_cn_scourer_6","base":false},{"name":"脉冲镭射","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Line","val":10}],"damage":[{"type":"Energy","val":[4,4,4]}],"effect":"T2~3 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。","id":"npcf_cn_scourer_7","base":false},{"name":"闪光镜头","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"以清扫器为原点的锥形 5 内所有角色必须通过系统豁免否则受扰直到清扫器下一回合开始。","id":"npcf_cn_scourer_8","base":false},{"name":"熔化","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"清扫器对射程 10 内的可展开或无人机进行远程攻击，成功则造成 20AP 能量伤害。","id":"npcf_cn_scourer_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_scout","name":"斥候","role":"支援","role_en":"support","page":305,"pages":[305],"flavor":"最具破坏性的机械化战争战略需要主动、近距离、积极地应用轨道、大气和地面火力支援。于是斥候机甲与它们的驾驶员应运而生。使用先进的目标定位系统，侦察兵既是战术协调者也是炮兵指挥官，它们与盟军一起绘制战场地图，并精确地定位直接目标和自主开火。","tactics":"斥候是被设计用来提升他们盟友伤害的支援机甲。他们自身不会造成伤害，但标记步枪和隐形场都可保证他们的盟友角色的存活并防止敌人隐匿。他们尤其擅长揭示隐形角色，但需要接近目标才能充分利用这种能力。如同大多数支援机，斥候机甲自身的承受力并不足。","stats":{"hull":[-1,-2,-2],"sys":[3,4,5],"agi":[2,4,5],"eng":[-1,-1,0],"hp":[8,8,8],"armor":[0,0,0],"evasion":[12,15,18],"edef":[10,13,16],"speed":[6,7,8],"size":[0.5,0.5,0.5],"heatcap":[6,6,6],"save":[11,13,15],"sensor":[20,20,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1/2 或 1"],"base":[{"name":"标记步枪","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[2,2,2],"range":[{"type":"Range","val":15}],"damage":[],"effect":"","on_hit":"目标受到锁定。只要他们锁定，则同时离散并不能躲藏或隐形。","id":"npcf_cn_scout_1","base":true},{"name":"视野","type":"Trait","tags":[],"effect":"斥候忽略躲藏和隐形，它们知悉感知内所有角色精确位置。","id":"npcf_cn_scout_2","base":true},{"name":"回升扫描","type":"System","tags":[{"id":"tg_full_action"}],"effect":"斥候选择射程 5 内所有角色进行系统豁免。失败则立即失去匿迹和隐形，且无法从任何掩护中重新获得该状况或增益直到斥候下一回合开始。","id":"npcf_cn_scout_3","base":true},{"name":"隐形场","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"斥候生成爆发 3 的隐形场持续到下一回合结束。受影响区域内的斥候和盟友角色隐形，但斥候在系统激活时固定。","id":"npcf_cn_scout_4","base":true}],"optional":[{"name":"系统掠劫者","type":"Trait","tags":[],"effect":"在回升扫描中豁免失败的角色会被锁定并受到2/3/4 热度。","id":"npcf_cn_scout_5","base":false},{"name":"测位仪","type":"Trait","tags":[],"effect":"与斥候邻近时，盟友角色所有攻击掷骰+1 准度。","id":"npcf_cn_scout_6","base":false},{"name":"暴露弱点","type":"Trait","tags":[],"effect":"成功被标记步枪攻击的角色下次成功被远程或近战攻击时受到+4/+6/+8 额外伤害。若它没被触发，则持续到场景结束。","id":"npcf_cn_scout_7","base":false},{"name":"数据面纱","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"默认斥候处于隐形并可用快速动作将此状态转移视线内另一角色。斥候不再隐形，只有以快速动作将其转移回或转移至另一角色斥候才恢复状态；否则此效果将持续到斥候被摧毁。","id":"npcf_cn_scout_8","base":false},{"name":"轨道炮打击","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"斥候视线射程 20 地面上选择一个空间；所有角色都知悉选择了哪个空间。斥候呼叫施行轨道轰炸，在下一轮结束时击中目标，造成爆发 2 的爆炸。受影响区域角色必须通过敏捷豁免。失败则受到 12/16/20 能量伤害并伏卧。若成功，伤害减半并仍保持站立。","id":"npcf_cn_scout_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_seeder","name":"播种机","role":"操纵","role_en":"controller","page":306,"pages":[306],"flavor":"作为工兵的播种机原型机擅长部署由地雷陷阱组成的防御网。它们装载传感器套组炸药，以小队形式运作：它们共同在战场上铺设陷阱和圈套，布设地雷和其他区域拒止系统以引导敌人进入杀伤区。","tactics":"播种机擅长封锁区域，用地雷控制敌人行动。播种机可在每个回合放置一枚地雷，正因如此若不加以干涉随，它们便可迅速将战场的一部分变成一片混乱。盟友角色不会触发播种机地雷，但若它们被波及爆炸中会受到地雷影响。播种机可以获取可选系统迫使角色分散或承受额外伤害。","stats":{"hull":[0,1,2],"sys":[2,3,4],"agi":[0,0,0],"eng":[0,0,0],"hp":[12,14,16],"armor":[2,2,2],"evasion":[7,8,9],"edef":[10,10,11],"speed":[4,4,4],"size":[1,1,1],"heatcap":[10,10,10],"save":[12,15,18],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"布雷","type":"System","tags":[{"id":"tg_mine"},{"id":"tg_quick_action"},{"id":"tg_round","val":1}],"effect":"播种机在射程 3 内自由空间部署一枚地雷。一旦部署完毕，当敌人移动到它上方则就会产生溅射 1 爆炸，同时影响盟友和敌人。• 晕眩地雷：该区域角色若未能通过工程豁免则晕眩直到对方下一回合结束。• 炸药地雷：该区域角色受到 8/12/16 爆炸伤害，通过敏捷豁免伤害减半。• 密封地雷：该区域内机体豁免失败的角色固定直到对方下一回合结束，然后缓慢再到下一回合结束。• 电震地雷：该区域内系统豁免失败的角色受扰直到一份下一回合结束，然后受损再到下一回合结束。播种机地雷是隐形且无法被瞄准的，但在感应内的敌方角色可通过成功的系统检定来发现它们。角色可在同一空间通过快速动作进行系统检定除它们；然而，这一检定的失败将引爆地雷。","id":"npcf_cn_seeder_1","base":true},{"name":"重力榴弹发射器","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_knockback","val":1}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[2,3,4]}],"effect":"","id":"npcf_cn_seeder_2","base":true}],"optional":[{"name":"弹跳地雷","type":"Trait","tags":[],"effect":"当敌对角色飞行或移动到布雷上方 10 空间时也会激活，地雷跳跃到 10 空间高度，在其上升撞到的第一个角色旁引爆。","id":"npcf_cn_seeder_3","base":false},{"name":"绊索","type":"Trait","tags":[],"effect":"布雷获得再充能 5+。地雷现在占据线形 3 区域，当敌人移动进入或穿越该区域时，地雷会从最近的空间引爆。","id":"npcf_cn_seeder_4","base":false},{"name":"快速部署者","type":"Trait","tags":[],"effect":"布雷一次埋设两枚地雷而非一枚。","id":"npcf_cn_seeder_5","base":false},{"name":"重力钉刺","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"视线射程 5 内的一个角色必须通过系统豁免否则一枚重力钉刺将附加在其身上。播种机用协定引爆所有重力钉刺，使目标自动受到 4/6/8AP 爆炸伤害，并被拉向播种机选择的方向 3 空间。一个快速动作并通过系统豁免可剔除一枚重力钉刺。","id":"npcf_cn_seeder_6","base":false},{"name":"引爆钉刺","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"视线射程 5 内最多 3 个角色必须通过系统豁免否则一枚引爆钉刺将附加在其身上。播种机下一回合开始，所有引爆钉刺都将引爆，产生爆发 1 爆炸，对所有受影响角色造成 3/5/7 爆炸伤害。若受影响区域重叠，角色将从多个钉刺来源受到多个伤害。","id":"npcf_cn_seeder_7","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_sentinel","name":"哨兵","role":"卫兵","role_en":"defender","page":307,"pages":[307],"flavor":"哨兵原型机常被用作守卫和护送，也常是指挥官随从或炮兵阵地的驻守。这些机甲及其驾驶员采用了先进技术套件以确保其护卫对象能存活和运转，即使这要付出自身底盘或生命的代价。与较为重型的棱堡原型不同，哨兵迅捷而灵敏：它们常用采用主动防御策略，使用先进技术、系统和直接武器进行先发制人的攻击以保护对象其目标。","tactics":"哨兵是高机动卫兵，专注于通过守望来保护他们的盟友。他们是直接近距离攻击者，依靠定位来充分利用他们的装备，他们并不具备等同于其他卫兵的承受力。","stats":{"hull":[2,3,4],"sys":[1,2,3],"agi":[1,2,3],"eng":[1,2,3],"hp":[16,20,24],"armor":[1,1,1],"evasion":[8,11,13],"edef":[8,11,13],"speed":[5,5,6],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"战斗霰弹枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","id":"npcf_cn_sentinel_1","base":true},{"name":"伸缩剑","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"","id":"npcf_cn_sentinel_2","base":true},{"name":"子夜之眼","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"哨兵缓慢，但守望的 1/回合取代 1/轮。一旦激活，该效果将一直持续到以快速动作终止。","id":"npcf_cn_sentinel_3","base":true},{"name":"护法","type":"Trait","tags":[],"effect":"邻近盟友可将哨兵充当硬性掩护。","id":"npcf_cn_sentinel_4","base":true}],"optional":[{"name":"制裁者弹药","type":"Trait","tags":[],"effect":"被哨兵守望攻击伤害的角色同时缓慢直到对方下一回合结束。","id":"npcf_cn_sentinel_5","base":false},{"name":"盛怒喉缩","type":"System","tags":[{"id":"tg_full_action"}],"effect":"哨兵为该系统提供武器。一旦装备好，哨兵就会在下一次使用战斗霰弹枪进行两次而非一次攻击。","id":"npcf_cn_sentinel_6","base":false},{"name":"穿刺者","type":"System","tags":[{"id":"tg_round","val":1}],"effect":"当哨兵用守望攻击时，其目标必须通过机体豁免否则固定并受扰直到对方下一回合结束。","id":"npcf_cn_sentinel_7","base":false},{"name":"快速响应","type":"Reaction","tags":[],"trigger":"一个敌人角色在视线内移动。","effect":"哨兵可以推进。","id":"npcf_cn_sentinel_8","base":false},{"name":"保镖","type":"Trait","tags":[{"id":"tg_protocol"}],"effect":"哨兵选择射程 5 内的盟友角色作为其守护目标并获得自反式打击反应。\n【自反式打击】（反应）触发：某角色攻击哨兵的守护目标。\n效果：哨兵率先用守望攻击该角色。","id":"npcf_cn_sentinel_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_sniper","name":"狙击手","role":"炮击","role_en":"artillery","page":308,"pages":[308,309],"flavor":"某些驾驶员没能在战场上目睹狙击手的原因是那些驾驶员已经死了。这些机甲是为了稳定性，绝对精度和以牺牲机动性为代价的远程动能武器而建造，它们往往以小规模自给团队运作，远离直接战斗。狙击手驾驶员是个骄傲的兵种，更强调经济性和优雅性，而非破坏力。","tactics":"对狙击手破坏力的恐惧理所当然，尤其是当他们制造集中伤害时。使用狙击手标记，他们可以直接造成结构伤害，使几乎任何角色运作时间缩短。对手可以通过巧妙地使用掩体或伏卧来避免这种情况。狙击手主要缺点是他们需要固定位置才能进行最好的工作，他们的步枪需要完整动作才能射击。","stats":{"hull":[-2,-2,-2],"sys":[1,3,4],"agi":[1,2,3],"eng":[1,1,2],"hp":[10,12,14],"armor":[0,0,0],"evasion":[10,13,16],"edef":[8,9,10],"speed":[4,4,4],"size":[1,1,1],"heatcap":[6,6,6],"save":[11,13,15],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"反器材步枪","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_ordnance"},{"id":"tg_loading"}],"weapon_size":"超重型","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[2,2,2],"range":[{"type":"Range","val":25}],"damage":[{"type":"Kinetic","val":[10,15,20]}],"effect":"","id":"npcf_cn_sniper_1","base":true},{"name":"狙击手标记","type":"System","tags":[{"id":"tg_full_action"}],"effect":"视线射程 25 内一个角色获得狙击手标记。对具有狙击手标记的目标，反器材步枪造成 1 结构伤害取代正常伤害。角色知悉自己身上的狙击手标记。若处于掩护或伏卧则忽略该效果并正常承受伤害。在该角色回合中，具有狙击手标记的角色可以用自由动作伏卧。狙击手一次只能标记一个角色，但可以将狙击手标记以一个完整动作转移到另一个角色。","id":"npcf_cn_sniper_2","base":true},{"name":"登山者","type":"Trait","tags":[],"effect":"狙击手可以在任何表面（包括悬垂和垂直表面）攀爬并且保持静止不动不受惩罚。","id":"npcf_cn_sniper_3","base":true}],"optional":[{"name":"甄选装弹","type":"System","tags":[],"effect":"狙击手在使用反器材步枪攻击之前可以选择一种特殊弹药类型。使用此弹药功能进行攻击如常并在成功攻击时产生额外效果。狙击手可从以下选项中选择：• 电磁：目标必须通过系统豁免否则受扰直到对方下一回合结束。• 耀斑：目标失去匿迹或隐形直到对方下一回合结束才能重新获得。• 冲击：目标必须通过机体豁免否则伏卧。• 熔化：目标必须通过工程豁免否则离散直到对方下一回合结束。","id":"npcf_cn_sniper_4","base":false},{"name":"防御性抓钩","type":"System","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"狙击手可以用抓钩将自己拉到射程 5 以内的任何地点，如同飞行。狙击手同时获得重新定位反应。\n【重新定位】（反应）触发：一个敌人角色在视线内移动。\n效果：狙击手可适用防御性抓钩。","id":"npcf_cn_sniper_5","base":false},{"name":"遮蔽炸弹","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"狙击手引爆一枚炸弹，制造出爆发 3 的烟、雾或其他隐藏物。狙击手在受影响区域内获得软性掩护，除了狙击手以外角色无法画出视线进入或离开该区域。部分在区域内的角色对区域外角色有视线。这该效果持续到狙击手下一回合结束，或者直到狙击手再次使用该系统。","id":"npcf_cn_sniper_6","base":false},{"name":"移动靶子","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个敌人角色在视线射程 20 内移动。","effect":"狙击手打断对方移动。该角色必须要么放弃引发的动作/移动，要么立即被狙击手使用反器材步枪攻击。若步枪尚未装填，则狙击手可以放弃该动作进行装填。","id":"npcf_cn_sniper_7","base":false},{"name":"死亡金属轮","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"狙击手为反器材步枪填装一种特殊的过穿透力子弹：下一次攻击变为线形 20。","id":"npcf_cn_sniper_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_specter","name":"幽鬼","role":"突击","role_en":"striker","page":310,"pages":[310],"flavor":"开发幽鬼原型机的原则很简单：不被击中胜过最强盔甲。幽鬼利用尖端光电伪装从战场和敌人扫描中消失。它们忽隐忽现，混淆视觉与雷达。这是它们如此致命的原因，尽管武器确实也起到关键作用。","tactics":"幽灵是高机动突击，对那些失误落单的敌人表现出众。使用潜行连同他们的高威胁和速度让他们越过前线去寻找脆弱个体目标，如狙击手和炮击机。幽灵永久隐形，这是他们生存的关键；他们的承受力不强，但可以随时躲藏。","stats":{"hull":[-3,-2,-2],"sys":[1,2,3],"agi":[3,5,6],"eng":[0,1,1],"hp":[10,10,10],"armor":[0,0,0],"evasion":[10,15,18],"edef":[8,9,12],"speed":[4,5,7],"size":[1,1,1],"heatcap":[7,7,7],"save":[10,13,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"单丝剑","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[5,5,5]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。","id":"npcf_cn_specter_1","base":true},{"name":"潜行","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"幽鬼移动等于速度的空间，然后躲藏。该移动忽略交火和反应。","id":"npcf_cn_specter_2","base":true},{"name":"战术斗篷","type":"Trait","tags":[],"effect":"幽鬼永久隐形。","id":"npcf_cn_specter_3","base":true},{"name":"追猎","type":"Trait","tags":[],"effect":"当目标邻近没有其他角色时，幽鬼近战攻击造成+5 伤害。","id":"npcf_cn_specter_4","base":true}],"optional":[{"name":"要塞","type":"Trait","tags":[],"effect":"幽鬼系统豁免+3 准度，针对它们的科技攻击+3难度。","id":"npcf_cn_specter_5","base":false},{"name":"枯竭系统","type":"Tech","tags":[{"id":"tg_full_tech"}],"attack_bonus":[2,4,6],"tech_type":"Full","effect":"幽鬼对邻近角色进行科技攻击。成功则目标晕眩。此效果持续到除幽鬼外其他角色开始回合与目标邻近或移动到目标邻近。","id":"npcf_cn_specter_6","base":false},{"name":"瞬步","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"幽鬼可瞬间移动到视线射程 50 内的自由空间。","id":"npcf_cn_specter_7","base":false},{"name":"冲锋手枪","type":"Weapon","tags":[],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[2,2,2]}],"effect":"T2 时，该武器可一次攻击两次，目标可以是同一个角色，也可以是两个不同角色。T3 时，它可以一次攻击三次。","id":"npcf_cn_specter_8","base":false},{"name":"弱点分析仪","type":"System","tags":[],"effect":"幽鬼开始躲藏的回合时，其下一次攻击（当匿迹时）获得+1/+2/+3 准度，且会心一击时+1d6 动能伤害。","id":"npcf_cn_specter_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_support","name":"支援者","role":"支援","role_en":"support","page":311,"pages":[311],"flavor":"支援者原型机甲通过大量即时分诊系统库，从基本闪印电镀到浅介质结构加固包和白浴纳米浆，来维持其盟友的生产和行动。从边界花园战场前线的“庄严之神的微笑”（Laughter of a Solemn God）到外太阳系收购股份有限公司（ExtraSolar Acquisitions, Inc.）离群天体猎人执行的精确行动，当机甲团队需要比部署更长的生存时间时，支援者原型机甲的效用将无与伦比。","tactics":"支援者是无法造成任何伤害的笨重机甲，但有强大的治疗和状态清除效果。尽管他们有一定的承受力，但无法保护自己，需要接近他们的盟友才能起效。聪明的玩家会在补给无人机被激活前射击并摧毁它们，扑灭任何治疗的机会。","stats":{"hull":[1,1,1],"sys":[0,1,2],"agi":[-2,-1,-1],"eng":[2,4,6],"hp":[15,18,22],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,10,12],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,12,16],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"密封枪","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"支援者选择视线射程 5 内一个角色，盟友或敌人：• 盟友：目标清除所有燃烧但会缓慢直到对方下一回合结束。• 敌人：目标必须通过敏捷豁免否则缓慢直到对方下一回合结束。无论成功与否，围绕其爆发 1 区域变为困难地形，持续到场景结束。","id":"npcf_cn_support_1","base":true},{"name":"补给无人机","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"补给无人机（大小 1/2，HP 5/8/10，回避 10/12/14，电子防御 10/12/14，标签：无人机）该无人机可在射程 5 内空间悬停。下一次盟友角色移动到无人机旁边时，它会钳制释放其储备，恢复5/10/15HP。","id":"npcf_cn_support_2","base":true},{"name":"单子修补云","type":"Trait","tags":[],"effect":"盟友角色靠近支援者时，所有豁免和机甲技能检定中掷骰两次并选择更高的结果。","id":"npcf_cn_support_3","base":true}],"optional":[{"name":"远程重启","type":"Trait","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"支援者清除射程 5 内的盟友角色以下任意两种状态：受损，受扰，晕眩和缓慢。","id":"npcf_cn_support_4","base":false},{"name":"附魔云","type":"Trait","tags":[],"effect":"盟友角色开始其回合时与支援者邻近，他们可以清除一个状态。","id":"npcf_cn_support_5","base":false},{"name":"遥控云","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"支援者在射程 5 内释放溅射 2 纳米云。盟友角色在该区域开始其回合或在轮内首次进入该区域，将恢复2/4/6HP。云在支援者下一回合开始时消散。","id":"npcf_cn_support_6","base":false},{"name":"防御性脉冲","type":"System","tags":[{"id":"tg_full_action"}],"effect":"射程 3 内的所有盟友角色清除受扰与锁定。","id":"npcf_cn_support_7","base":false},{"name":"碰锁无人机","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"碰锁无人机（大小 1/2，HP 5/10/15，回避 10，电子防御 10，标签：无人机）该自动部署无人机可在射程 3 内钳住一个角色，占据相同空间并与其一起移动。当无人机附着目标身上时，目标每回合开始获得 5/8/10HP 并在所有检定、豁免和攻击上+1 准度。敌人可瞄准无人机攻击。","id":"npcf_cn_support_8","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_witch","name":"女巫","role":"操纵","role_en":"controller","page":312,"pages":[312,314],"flavor":"女巫原型底盘总能在体系风暴的中心找到位置，它们擅长制造现实空间和军团空间怖物来覆盖战场。在任何时候，它们都有可能在物理战场和万物网的骚乱中同时作战。为了处理由此产生的输入输出混乱漩涡，女巫通常会与人格克隆的 NHP 配对，通过并行处理任务来提高战斗效率。","tactics":"女巫是务实的控制者，使用拆毁术来施加热度，使用盲目术来关闭远程攻击者。掠夺性逻辑给了他们对付重武器角色的工具，这也可以帮助他们的盟友。在女巫们释放大部分热度后，目标一般在下一个回合都有机会释放自己的热度。","stats":{"hull":[-2,-1,-2],"sys":[3,5,6],"agi":[1,2,3],"eng":[0,0,0],"hp":[12,14,14],"armor":[0,0,0],"evasion":[10,12,14],"edef":[13,16,20],"speed":[6,6,6],"size":[0.5,0.5,0.5],"heatcap":[8,8,8],"save":[12,15,18],"sensor":[15,15,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1/2 或 1"],"base":[{"name":"拆毁术","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"accuracy":[1,1,1],"tech_type":"Quick","effect":"女巫对感应内一个角色进行科技攻击。成功则目标会立即受到 1/2/3 热度，然后在女巫下一回合开始时受到 4 热度。","id":"npcf_cn_witch_1","base":true},{"name":"盲目术","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":4}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"女巫对感应内一个角色进行科技攻击。成功则目标在下一回合结束前只对邻近空间有视线。","id":"npcf_cn_witch_2","base":true},{"name":"掠夺性逻辑","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":6}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"女巫对感应内一个角色进行科技攻击。成功则目标立即使用女巫选择的武器攻击女巫选择射程内的角色。","id":"npcf_cn_witch_3","base":true},{"name":"模糊术","type":"Trait","tags":[],"effect":"女巫自身回合中，它们隐形。","id":"npcf_cn_witch_4","base":true}],"optional":[{"name":"扩散苦难","type":"Trait","tags":[{"id":"tg_round","val":1},{"id":"tg_free_action"}],"effect":"1/轮，当女巫使用快速科技或完整科技时，可用自由动作针对主要目标邻近的任意角色重复其选择。","id":"npcf_cn_witch_5","base":false},{"name":"暗云","type":"Trait","tags":[],"effect":"如果目标在超温危域，则拆毁术的额外热度伤害在女巫下一回合开始时增加到 7 热度。","id":"npcf_cn_witch_6","base":false},{"name":"束缚术","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"女巫对感应内一个角色进行科技攻击。命中则女巫将目标束缚在射程 3 内位置。若目标从该点移动超过 3空间（无论自主或强制），将受到 2/3/4 热度并受扰直到对方下一回合结束，然后该效果结束。否则对方会被持续束缚直到女巫被摧毁或晕眩，或场景结束。","id":"npcf_cn_witch_7","base":false},{"name":"石化术","type":"Tech","tags":[{"id":"tg_full_tech"},{"id":"tg_recharge","val":6}],"attack_bonus":[2,4,6],"tech_type":"Full","effect":"女巫对感应内的一个角色进行科技攻击。成功则目标缓慢。在对方下一回合会固定。再下一回合会晕眩。所有状态在回合结束时结束。","id":"npcf_cn_witch_8","base":false},{"name":"痛苦转移","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"女巫对感应内的一个角色进行科技攻击。若成功，在女巫的下一回合结束前，每当该目标受到热度，其射程 5 内所有盟友角色收到相同数量的热度。有时，你可能需要非机甲类的 NPC。以下特殊职业——人类，步兵班组和怪形——适用于这些情况。","id":"npcf_cn_witch_9","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_human","name":"人类","role":"生物","role_en":"biological","page":314,"pages":[314],"flavor":"会有各式人类最终都走上战场，包括驾驶员、VIP 和旁观者。当有人在战斗中爬出他们的机甲时，你将主要使用人类 NPC；若你想要一组完整的步兵班，使用班组职业代替。人类永远不能附加其他模板，也不能获得结构。","tactics":"","custom_note":"选择其一： 选择任意：","stats":{"hull":[1,2,3],"sys":[1,2,3],"agi":[1,2,3],"eng":[1,2,3],"hp":[6,6,6],"armor":[0,0,0],"evasion":[10,10,10],"edef":[10,10,10],"speed":[4,4,4],"size":[0.5,0.5,0.5],"save":[10,10,10],"sensor":[5,5,5],"heatcap":[0,0,0],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[],"optional":[{"name":"远程武器","type":"Weapon","tags":[],"weapon_size":"","weapon_kind":"","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Kinetic","val":[1,2,3]}],"effect":"","id":"npcf_cn_human_1","base":false},{"name":"近战武器","type":"Weapon","tags":[],"weapon_size":"","weapon_kind":"","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[1,2,3]}],"effect":"","id":"npcf_cn_human_2","base":false},{"name":"反装甲武器","type":"Weapon","tags":[],"weapon_size":"","weapon_kind":"","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Variable","val":[3,4,5],"note":"爆炸或能量"}],"effect":"","id":"npcf_cn_human_3","base":false},{"name":"老兵","type":"Trait","tags":[],"effect":"+2/+4/+6 HP","id":"npcf_cn_human_4","base":false,"bonus":{"hp":[2,4,6]}},{"name":"披甲","type":"Trait","tags":[],"effect":"+1~2 装甲","id":"npcf_cn_human_5","base":false,"bonus":{"armor":1}}],"pack":"核心规则书","source":1},{"id":"npcc_cn_squad","name":"班组","role":"生物","role_en":"biological","page":315,"pages":[315],"flavor":"虽然驾驶员个体和其他非机甲士兵可能不会对大多数机甲构成太大威胁，但一支装备精良训练有素的步兵班组本身就是危险。","tactics":"班组就是他们理所当然的样子：由五到十名全副武装的士兵组成的小队在战场上作为一个角色。","stats":{"hull":[2,4,6],"sys":[2,4,6],"agi":[2,4,6],"eng":[2,4,6],"hp":[10,15,20],"armor":[0,0,0],"evasion":[8,8,8],"edef":[8,8,8],"speed":[4,4,4],"size":[4,4,4],"save":[10,12,14],"sensor":[15,15,15],"heatcap":[0,0,0],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["4（1/2 个体）","4（1/2 个体）","4（1/2 个体）"],"base":[{"name":"士兵","type":"Trait","tags":[],"effect":"班组是一个角色，但它代表着一群士兵行动。当小队受到一定伤害就会导致一名或多名士兵死亡。最终，这将减少班组每回合的攻击次数，如相关武器所列。在默认情况下，班组由 10 成员组成，每位成员拥有 1HP。","id":"npcf_cn_squad_1","base":true},{"name":"普通军士","type":"Trait","tags":[],"effect":"班组无法使用低等兵，老兵，或超体模板，且永远不能获得结构。","id":"npcf_cn_squad_2","base":true},{"name":"人多力量大","type":"Trait","tags":[],"effect":"班组对所有非线形，锥形，溅射或爆发的攻击伤害有抗性，并且对擒拿，冲撞，击退和晕眩免疫。","id":"npcf_cn_squad_3","base":true},{"name":"散开","type":"Trait","tags":[],"effect":"不追踪士兵个体位置，该班组成员被假定它所占据的空间内自由移动。其他角色可在班组占据的空间中自由移动并结束他们回合，只要班组占据至少 2 自由空间，它就可以重叠障碍物、掩护或其他角色结束其回合。","id":"npcf_cn_squad_4","base":true},{"name":"尺寸不足","type":"Trait","tags":[],"effect":"单独士兵可轻松躲到掩体后，但机甲规模级别武器的强大力量限制了他们被掩护的效率。班组总是处于软性掩护，即使在开阔地带，但无法从硬性掩护中获益。","id":"npcf_cn_squad_5","base":true},{"name":"主要武器","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Variable","val":[2,3,4],"note":"动能，能量或爆炸（制作时选择）"}],"effect":"该武器可一次攻击 2 次；若班组损失超过一半 HP则只能攻击 1 次。","id":"npcf_cn_squad_6","base":true},{"name":"反装甲武器","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Variable","val":[5,6,7],"note":"动能，能量或爆炸（制作时选择）"}],"effect":"","id":"npcf_cn_squad_7","base":true}],"optional":[{"name":"披甲","type":"Trait","tags":[],"effect":"班组+1 装甲。","id":"npcf_cn_squad_8","base":false,"bonus":{"armor":1}},{"name":"伏击者","type":"Trait","tags":[],"effect":"班组在首轮战斗中所有攻击、豁免和检定+2 准度。","id":"npcf_cn_squad_9","base":false},{"name":"卧倒藏好","type":"Reaction","tags":[],"trigger":"班组被攻击命中。","effect":"班组获得伤害抗性，但固定直到下一回合结束。","id":"npcf_cn_squad_10","base":false},{"name":"快速突入装置","type":"Trait","tags":[],"effect":"班组可以在移动或推进时飞行。","id":"npcf_cn_squad_11","base":false},{"name":"纪律","type":"Trait","tags":[],"effect":"失去 HP 不会影响班组每回合的攻击次数。","id":"npcf_cn_squad_12","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_cn_monstrosity","name":"怪形","role":"生物","role_en":"biological","page":316,"pages":[316,317],"flavor":"怪形，作为特别庞大或令人恐惧的自然捕食者。它们通常生活在野外，但其中一些却能被驯化并训练用于战斗。在银河系遥远的角落，对这些生物的需求很高。","tactics":"","stats":{"hull":[3,4,6],"sys":[-2,-2,-2],"agi":[2,3,4],"eng":[-2,-2,-2],"hp":[14,16,18],"armor":[1,1,1],"evasion":[10,12,15],"edef":[10,10,10],"speed":[6,7,8],"size":[1,1,1],"save":[10,12,15],"sensor":[10,10,10],"heatcap":[0,0,0],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1 或 2","1 或 2","1~3"],"base":[{"name":"独特生理机能","type":"Trait","tags":[],"effect":"若怪形有结构（例如，它拥有精英或超体模板），当它受到结构伤害时，参照怪形结构伤害表掷骰。\n怪形结构伤害表 掷骰[结构伤害]D6\n5~6 擦身而过 怪形痛苦地畏缩；它会受损直到它下一回合结束。\n3~4 强力一击 怪形被重击的力量击倒伏卧。\n2 肢解 攻击卸下怪形四肢或大块组织；它受到 1d6 动能伤害，并在场景结束前缓慢。\n1 直接命中\n结果取决于怪形的剩余结构：\n• 3+结构：怪形被重击头部并昏迷直到它下一回合结束。\n• 2 结构：怪形必须成功进行机体豁免，否则将被摧毁。\n• 1 结构：怪形被摧毁。\n多数 1 致命一击 怪形被摧毁。","id":"npcf_cn_monstrosity_1","base":true},{"name":"致命游戏","type":"Trait","tags":[],"effect":"怪形至少有一个可选突变。","id":"npcf_cn_monstrosity_2","base":true},{"name":"爪击","type":"Weapon","tags":[],"weapon_size":"","weapon_kind":"","attack_bonus":[2,4,6],"accuracy":[1,1,1],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[6,8,12]}],"effect":"","id":"npcf_cn_monstrosity_3","base":true}],"optional":[{"name":"酸液喷吐","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Energy","val":[3,4,5]}],"effect":"","on_hit":"目标离散直到对方下一回合结束。","id":"npcf_cn_monstrosity_4","base":false},{"name":"黏着分泌物","type":"Trait","tags":[],"effect":"每回合首个被怪形伤害的角色必须通过工程豁免否则缓慢。该效果会持续到目标恢复 HP 或场景结束。","id":"npcf_cn_monstrosity_5","base":false},{"name":"掘穴动物","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"只要地表有足够延展性，怪形就会在地下挖洞。挖洞时它被视为隐形，可自由穿过角色和其他障碍物所占据的空间；但它只能移动、推进或出现在一个自由空间（作为一个快速动作）。当怪形出现时，它附近的所有角色必须成功进行机体豁免，否则将被伏卧。","id":"npcf_cn_monstrosity_6","base":false},{"name":"腐蚀啮咬","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"与怪形邻近的角色必须通过机体豁免否则将受到4/5/6 燃烧伤害。成功与否都会离散直到对方恢复任意HP。","id":"npcf_cn_monstrosity_7","base":false},{"name":"纠缠之爪","type":"Trait","tags":[],"effect":"怪物在擒拿中+1 准度，在攻击被它擒拿的目标时+1 准度，且获得在擒拿中推进和使用反应的能力。","id":"npcf_cn_monstrosity_8","base":false},{"name":"自然伪装","type":"Trait","tags":[],"effect":"怪形在邻近任何地形或掩体时隐形，且将软性掩护视为硬性掩护。","id":"npcf_cn_monstrosity_9","base":false},{"name":"横冲直撞","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"怪形以直线移动等同速度空间，无视反应和交火，在其他角色占据的空间中自由移动。经过或邻近路径的角色必须通过敏捷豁免否则受到 4/6/8 动能伤害。","id":"npcf_cn_monstrosity_10","base":false},{"name":"再生器","type":"Trait","tags":[],"effect":"在怪形回合结束时，恢复其总 HP1/4。若它在同一回合中受到能量伤害，则不会恢复任何 HP。","id":"npcf_cn_monstrosity_11","base":false},{"name":"逆刺","type":"Trait","tags":[],"effect":"怪形受到近战武器的伤害后，会自动对攻击者造成1/2/3AP 动能伤害。","id":"npcf_cn_monstrosity_12","base":false},{"name":"迅捷","type":"Trait","tags":[{"id":"tg_free_action"},{"id":"tg_round","val":1}],"effect":"每轮一次，怪形可以在其回合中以一个自由动作进行推进。","id":"npcf_cn_monstrosity_13","base":false},{"name":"调节隐匿","type":"Trait","tags":[],"effect":"怪形获得以下两种伤害抗性：动能，能量，爆炸。若其降低到总 HP 一半或更少，则失去抗性。若它有任意结构，则当 HP 恢复到完全时将重新获得抗性。","id":"npcf_cn_monstrosity_14","base":false},{"name":"有翼","type":"Trait","tags":[],"effect":"怪形在移动时可飞行，在移动结束时无需落地。","id":"npcf_cn_monstrosity_15","base":false}],"pack":"核心规则书","source":1},{"id":"npcc_x_ss_1","name":"水蛭","role":"操纵/支援","page":82,"pages":[82,83],"flavor":"圆滑，强壮而迅捷，这些水蛭（通常也称之为亚斯安伯沙（Asanbosam，一种吸血鬼））最初被农场的异质躯体部所雇。其生态位为支援那些通过保护或消灭某一作战人员就能确保结果的特种作战。作为质躯体部最灵活的作战支援平台，亚斯安伯沙经常被部署在农场资产收回任务中。其独特设计可重塑盟友底盘，或吸附敌人并将战斗拖入它们最擅长的领域。","tactics":"水蛭在战场上同时担任控制和支援角色。它们最适合在各种目标清除任务中与快速且致命的底盘配合使用。使用它们来支援那些需要增添防御性能的 NPC，或针对单个 PC 并破坏其计划。","stats":{"hull":[2,4,6],"sys":[1,2,2],"agi":[3,3,3],"eng":[0,0,0],"hp":[8,8,8],"armor":[0,0,0],"evasion":[12,15,18],"edef":[8,8,8],"speed":[6,8,10],"size":[0.5,0.5,0.5],"heatcap":[4,6,8],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"水蛭","type":"Trait","tags":[],"effect":"水蛭获得增强擒拿能力。这给予它们以下增益：• 水蛭可擒拿射程 3 以内的角色。当它擒拿一个角色，从战场上移除水蛭。它视为和目标占据同一空间。这不会引起反应和交战。• 1/轮，水蛭可用一个自由动作使用擒拿。对盟友擒拿时自动成功。• 水蛭可在擒拿时执行反应。盟友角色被水蛭擒拿时可进行反应和推进。• 水蛭擒拿一个角色时获得软性掩护。被水蛭擒拿的盟友角色同样具有软性掩护。• 水蛭可在战斗开始时已擒拿一个盟友角色。","id":"npcf_x_ss_1_1","base":true},{"name":"双重利爪 MKII","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_thrown","val":5}],"weapon_size":"副武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[2,3,3]}],"effect":"该武器在攻击被水蛭擒拿的角色时+1 准度。","on_hit":"以一个自由动作，水蛭可承受 2 热度进行一次额外攻击，并且可继续对命中目标进行一次额外攻击，直到它承受的热度超过其热度上限。","id":"npcf_x_ss_1_2","base":true},{"name":"虫草学说升级 I","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"水蛭从以下效果中选择其二：• 被擒拿角色结束一个非自身系统，武器，特征或天赋造成的状态影响。• 被擒拿目标失去所有护盾。• 对擒拿角色或水蛭获得 5/6/7 护盾。","id":"npcf_x_ss_1_3","base":true},{"name":"净化","type":"System","tags":[{"id":"tg_heat_self","val":2},{"id":"tg_quick_action"}],"effect":"擒拿时，水蛭选择选项其二：• 将擒拿角色向任意方向推动 4 空间。• 使擒拿角色或射程 3 内另一角色受损。• 对擒拿角色或射程 3 内另一角色造成 3/4/5AP 能量伤害。","id":"npcf_x_ss_1_4","base":true}],"optional":[{"name":"EMP 脉冲","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":4}],"trigger":"水蛭擒拿时受到外部来源的伤害或热度。","effect":"爆发 2 内敌对角色必须通过系统豁免，否则受扰直到他们下一回合结束。","id":"npcf_x_ss_1_5","base":false},{"name":"褪色炉","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_heat_self","val":2}],"effect":"选择一个被水蛭擒拿的角色：水蛭和目标隐形直到水蛭下一回合开始。","id":"npcf_x_ss_1_6","base":false},{"name":"泽蛭学说升级 II","type":"Trait","tags":[],"effect":"被水蛭擒拿的敌对角色每次攻击时受到 1/2/3 热度。","id":"npcf_x_ss_1_7","base":false},{"name":"孤独底盘","type":"Trait","tags":[],"effect":"水蛭未擒拿时，当邻近盟友角色在自身回合移动或推进时，则水蛭可与其一同移动，只要该移动从水蛭邻近未知开始即可。","id":"npcf_x_ss_1_8","base":false},{"name":"超新星","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":4}],"trigger":"一个敌对角色致使水蛭结束擒拿。","effect":"在擒拿结束前，被擒拿角色受到 4/5/6 燃烧。","id":"npcf_x_ss_1_9","base":false},{"name":"共生学说升级 III","type":"Trait","tags":[],"effect":"水蛭速度减半。当擒拿盟友角色时，水蛭可在被擒拿盟友回合激活。每轮水蛭不能以此法执行回合超过一次，除非通过其装备系统和特征给予其额外激活。","id":"npcf_x_ss_1_10","base":false},{"name":"邪恶扰乱","type":"Trait","tags":[],"effect":"水蛭擒拿一个敌对角色时，每当水蛭受到伤害，该角色受到 2AP 能量伤害和 2 热度。","id":"npcf_x_ss_1_11","base":false}],"pack":"塞壬之歌","source":6},{"id":"npcc_x_ss_2","name":"暴风雨","role":"操纵","role_en":"controller","page":84,"pages":[84,85,86],"flavor":"征服山峰的过程中总会遇到一些考验，轻则打碎骨头，重则摧毁心灵。源自基马文塞山脉迷雾峰峦与被遗忘在第二委员会战争思维体，暴风雨，也被称为伊博盖恩——在首次被发现时就刻在其巨大底盘上的头衔——将其投射笼罩在下方所有身上的阴影。伊博盖恩是巨大的飞行平台，满载纳米灰浴，为改变一片局部区域的天气状况而设计。伊博盖恩是种古老的机甲模式，甚至早于联盟机械化底盘作战理论。它在战场上空盘旋，制造完全的天气异常，意图击溃敌军所有软硬目标。","tactics":"本次任务第一场战斗使用了这全新的控制 NPC，暴风雨。该敌人是为这场任务专门平衡的独特 NPC。在本任务外使用暴风雨时，请记住它是对军情报告强有力的补充，应被视为比超体 NPC 更具威胁性。若需要在战斗中引入暴风雨，可通过添加与玩家数量成比例的气候节点这种可破坏物品的形式来调整军情报告。在任何时候，由于其大小和能力，战斗中都不应有超过一个的暴风雨，最好把它作为带有开放空间较大地图上的任务目标来部署。暴风雨比大多数 NPC 更坚固，但没有可削减的结构，因此只要该机甲维持运作，它的所有系统和武器就会持续威胁 PC。暴风雨在敌后方盘旋，使用改变天气的系统来消耗逼近的敌对力量。它使用其气象灰浴系统操纵盟友和敌人影响状态区。PC 和 NPC 可通过破坏气候节点或在其稳定影响区内寻求庇护来躲避压倒性的天气影响。尽管如此，玩家应保持警惕。暴风雨能够结束气象灰浴以部署纳米体陨石，该陨石可以重定向至节点以造成高伤害。暴风雨最适合在主要目标是阻止敌人推进或地图区域拒止的情况下使用。其纳米台风加农炮可用来威胁敌对控制区，或将敌人推进陨石溅射区。暴风雨配备了一系列可选系统，在与气候节点交互时增加了许多功能性。当部署暴风雨时，一定要与能转移 PC 注意力或拥有强制移动和削弱效果的 NPC 一同部署。","stats":{"hull":[3,3,3],"sys":[1,1,1],"agi":[-1,-1,-1],"eng":[2,2,2],"hp":[30,35,40],"armor":[1,1,1],"evasion":[8,8,8],"edef":[10,10,10],"speed":[2,2,3],"size":[3,4,4],"heatcap":[12,12,16],"save":[10,13,16],"sensor":[20,20,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"中心装饰品","type":"Trait","tags":[],"effect":"每场战斗最多只能部署一台暴风雨，且无法使用NPC 模板。","id":"npcf_x_ss_2_1","base":true},{"name":"飞行平台","type":"Trait","tags":[],"effect":"暴风雨在零重力环境下可正常移动。在大气中，它总是在 4 空间高度悬浮。暴风雨获得对固定的免疫，并且不会因晕眩而坠落。由于其大小，暴风雨无法躲藏，也无法从掩体中获得硬性掩护。","id":"npcf_x_ss_2_2","base":true},{"name":"气象灰浴","type":"System","tags":[{"id":"tg_protocol"}],"effect":"战斗开始时，暴风雨可从以下每个类别中选择一个灰浴效果，为战斗期间做好准备。暴风雨回合开始时，它可激活三种灰浴效果中的一种，从类别 I 开始，然后是类别 II，再到类别 III，然后从类别 I 再次开始。同一类别的多个效果在任意时刻都不能同时激活。在暴风雨每回合结束时，每激活一个效果会对暴风雨造成 2 热度。它可在回合结束时以一个自由动作结束效果。若这会导致暴风雨超过热度上限，则暴风雨可以不承受来自该系统造成的热度。灰浴效果只能影响在暴风雨感应内的角色。• 零度浴：任意在自己回合中未执行标准移动或推进的角色将在回合结束时固定，并维持固定直到他们以一个快速动作清除该状态。• 太阳浴：所有角色在受到自身造成的热度，超限，杀绝和外部来源的热度时+1 热度。• 旋涡浴：所有飞行角色视为在困难地形中移动，所有地面单位自动缓慢。• 狂风浴：在每个角色的回合结束时，他们向暴风雨选择的方向移动 2/3/4 空间。\n【类别 I】\n• 拦截浴：激活后，暴风雨选择一个角色，在该效果持续时间内，从任意远程攻击或近战攻击中获得对以下一种伤害类型的抗性——爆炸、动能或能量。• 虚幻浴：所有与暴风雨邻近的盟友角色和暴风雨选择的另一盟友角色隐形。• 静电浴：激活后，暴风雨选择一个角色，在一轮中首次与其临近的角色自动受到 2 热度。• 分裂浴：激活后，暴风雨选择一个盟友角色，敌对角色对其发动的科技攻击+2 难度。\n【类别 II】\n• 腐蚀浴：暴风雨选择一个角色：目标必须通过机体豁免，否则在他们下次受到任何远程攻击或近战攻击时受到+3/4/5AP 伤害，无论命中与否。该效果持续到暴风雨回合终止该影响或一个气候节点被破坏。• 对流浴：暴风雨选择一个角色：目标必须通过敏捷豁免否则离散直到暴风雨回合终止该影响或一个气候节点被破坏。• 沙暴浴：暴风雨选择一个角色：目标必须通过系统豁免，否则只能对邻近空间绘制视线，该效果持续到暴风雨回合终止该影响或一个气候节点被破坏。• 天火浴：暴风雨选择一个角色：目标必须通过工程豁免否则被光束击中而承受 1/2/3 热度和 1/2/3燃烧，该效果持续到暴风雨回合终止该影响或一个气候节点被破坏。\n【类别 III】","id":"npcf_x_ss_2_3","base":true},{"name":"暴风眼","type":"Trait","tags":[],"effect":"暴风雨可选择对其气象灰浴的任何效果具有免疫。此外，当它被摧毁或暴露时，它可摧毁一个气候节点作为替代来清除暴露和所有热度，并恢复到一半 HP。","id":"npcf_x_ss_2_4","base":true},{"name":"气候节点","type":"Trait","tags":[],"effect":"气候节点（大小 2，HP 10/15/20，电子防御 10，回避 10，标签：可展开在战斗开始时和 PC 部署后，部署与 PC 数量相等的气候节点。它们与玩家部署区或其他气候节点的间距不得超过 10 空间。一旦部署，这些节点就相当于硬性掩护，并对任何来源的移动具有免疫。位于气候节点射程 3 内的角色可选择获得对来自气象灰浴任意效果的免疫，只要他们维持在射程 3 内。此外，在每轮结束但纳米体陨石还未迫使敌人或盟友进行豁免前，暴风雨可将一个纳米体陨石溅射区域的中心重定向到气候节点射程 3 内的一个空间。一旦所有气候节点都被摧毁，所有来自气象灰浴的持续影响立即结束。","id":"npcf_x_ss_2_5","base":true},{"name":"季风灰浴分撒器","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_smart"},{"id":"tg_seeking"}],"weapon_size":"超重型","weapon_kind":"发射器","attack_bonus":[2,3,4],"accuracy":[0,0,0],"range":[{"type":"Range","val":15},{"type":"Blast","val":2}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","on_hit":"目标受损并缓慢直到他们下一回合结束。","id":"npcf_x_ss_2_6","base":true},{"name":"纳米体陨石","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"暴风雨可结束任意激活的气象灰浴效果，并创建与以此法结束的气象灰浴效果数量相等的溅射 2 区域。暴风雨在地图上只能同时存在 3 个溅射区，这些区域不能重叠并持续到下一轮结束。在下一轮结束时，任何部分或完全位于受影响区域内的角色必须通过敏捷豁免，否则受到 14/16/18 动能伤害，成功则伤害减半。激活该系统时，暴风雨清除所有热度。","id":"npcf_x_ss_2_7","base":true},{"name":"灰浴台风加农炮","type":"Weapon","tags":[{"id":"tg_knockback","val":5}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[2,3,4],"accuracy":[-1,-1,-1],"range":[{"type":"Range","val":15},{"type":"Blast","val":1}],"damage":[{"type":"Heat","val":[2,3,4]},{"type":"Kinetic","val":[3,4,5]}],"effect":"","on_hit":"若该武器的击退致使目标与足够大的障碍物上相撞，使其停止移动且必须通过机体豁免否则受到 4动能伤害。","id":"npcf_x_ss_2_8","base":true}],"optional":[{"name":"空白空间翘曲转移","type":"System","tags":[{"id":"tg_heat_self","val":3},{"id":"tg_quick_action"}],"effect":"暴风雨可将气候节点射程 3 内的任何盟友角色瞬间移动到另一节点射程 3 内的自由空间。","id":"npcf_x_ss_2_9","base":false},{"name":"扩散器","type":"Reaction","tags":[{"id":"tg_recharge","val":6},{"id":"tg_round","val":1}],"trigger":"一个敌对角色在暴风雨射程 3 内开始回合，或在其回合中首次与暴风雨邻近。","effect":"目标必须通过系统豁免，否则无法以任何方式恢复 HP，直到它们承受结构或压力伤害。","id":"npcf_x_ss_2_10","base":false},{"name":"虚幻节点","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_heat_self","val":3},{"id":"tg_quick_action"}],"effect":"暴风雨视线感应内所有气候节点下一轮结束前隐形。","id":"npcf_x_ss_2_11","base":false},{"name":"归位节点","type":"System","tags":[{"id":"tg_heat_self","val":2},{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"归位节点（大小 1，HP1，电子防御 10，回避 10，标签：可展开）一旦部署，这些节点就被视为气候节点；然而它们仅向邻近角色提供免疫，而非射程 3 内。","id":"npcf_x_ss_2_12","base":false},{"name":"雷电发生器","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"暴风雨在射程 5 内选择最多两个敌对角色：他们必须成功通过系统豁免，否则受到 2/3/4 热度并受扰直到他们下一回合结束。","id":"npcf_x_ss_2_13","base":false},{"name":"灰浴控制","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"暴风雨可激活另一种来自气象灰浴的灰浴效果。它持续到一个气候节点被破坏或暴风雨主动结束。它不必从现有灰浴效果列表中进行选择，也不必遵循类别顺序，但仍必须承受维持效果所需的热度。","id":"npcf_x_ss_2_14","base":false},{"name":"点防御炮塔","type":"Weapon","tags":[{"id":"tg_accurate"}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"1/轮，以一个反应，暴风雨可使用该武器攻击进入气候节点射程 3 的角色，从节点绘制视线。它也能如同从一个气候节点上绘制视线一般使用该武器进行攻击和守望。","id":"npcf_x_ss_2_15","base":false},{"name":"重定向","type":"Reaction","tags":[{"id":"tg_recharge","val":4}],"trigger":"暴风雨视线感应内一个气候节点受到一次远程攻击命中。","effect":"伤害结算后，暴风雨可迫使节点射程 3 内的一个敌对角色进行敏捷豁免，失败则承受该攻击一半伤害。","id":"npcf_x_ss_2_16","base":false},{"name":"反射灰墙","type":"Reaction","tags":[{"id":"tg_recharge","val":6}],"trigger":"暴风雨视线感应内一个气候节点受到攻击命中。","effect":"伤害结算后，暴风雨可将该伤害降低至 0。","id":"npcf_x_ss_2_17","base":false}],"pack":"塞壬之歌","source":6},{"id":"npcc_x_wf_1","name":"潜伏者","role":"突击","role_en":"striker","page":180,"pages":[180],"flavor":"潜伏者级的敌人在战场上罕见却可怖。它们通常利用灰浴模拟纳米云和物质压缩器，在虫群之间来回跳跃，猛烈挥舞着纳米鞭，并利用虫群如水般轻而易举地躲避攻击。","tactics":"潜伏者是迟缓但强大的敌人，他们的护罩区域尤其骇人。精明的玩家会使用骇入或智能武器来分散这些区域，使潜伏者更容易受到攻击。潜伏者可以使用彼此的区域，所以在战场上有多个潜伏者可以极大地倍增他们的力量。","stats":{"hull":[2,3,4],"sys":[0,0,0],"agi":[2,3,4],"eng":[-1,-1,-1],"hp":[10,14,18],"armor":[1,1,1],"evasion":[10,12,14],"edef":[6,6,6],"speed":[3,3,4],"size":[1,1,1],"heatcap":[5,5,8],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"本影护罩","type":"Trait","tags":[{"id":"tg_protocol"}],"effect":"任何战斗开始时，当他们作为增援部队抵达，或 1/轮以协议可让潜伏者在射程 5 内爆发 1 区域制造一波纳米体涟漪风暴——护罩区域。护罩提供软性掩护。此外，在护罩区域内：• 潜伏者们（包括自身）化为隐形，并获得所有伤害和热度的抗性。• 敌对角色离散和受损。护罩区域只能被科技攻击和瞄准电子防御的武器（例如智能武器）所攻击。它们拥有 10/13/16 电子防御，一旦攻击成功便会消散。潜伏者不能同时激活超过三个护罩区域。护罩区域可以互相重叠，但它们的效果不叠加。","id":"npcf_x_wf_1_1","base":true},{"name":"精练鞭","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[8,10,12]}],"effect":"在护罩区域内使用该武器获得威胁 3 和+1 准度。\n会心一击：如上所述，目标立即被擒拿。","on_hit":"目标被拉到潜伏者邻近，或尽可能靠近。","id":"npcf_x_wf_1_2","base":true},{"name":"本影转移","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"潜伏者瞬间移动到视线内的护罩区域。","id":"npcf_x_wf_1_3","base":true}],"optional":[{"name":"烧竭护罩","type":"Trait","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"潜伏者消耗一个他们所在或邻近的护罩区域，清除所有状况，获得护盾 4/6/8，然后移动与速度相等的空间。他们无法消耗他们在同一回合中创建的护罩区域。","id":"npcf_x_wf_1_4","base":false},{"name":"防御护罩","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"潜伏者受到伤害或热度。","effect":"它会创建一个以它所在位置为中心的护罩区域，即使它已有三个激活区域。","id":"npcf_x_wf_1_5","base":false},{"name":"吞噬碎片","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"在护罩区域内，潜伏者可用快速动作以雷霆之势喷出锥形 3剃刀般锋利的纳米体洪流。受影响区域内的角色必须通过工程豁免否则受到 4/5/6AP 能量伤害。成功则伤害减半。","id":"npcf_x_wf_1_6","base":false},{"name":"天命护罩","type":"Trait","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"潜伏者将他们目前占据的某护罩区域扩展到爆发 2。这可能致使它囊括其他角色。从现在起需两次成功攻击才能驱散效果。","id":"npcf_x_wf_1_7","base":false},{"name":"开膛利爪","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[5,7,8]}],"effect":"该武器在护罩区域内使用造成双倍伤害。","id":"npcf_x_wf_1_8","base":false}],"pack":"壁花不容","source":7},{"id":"npcc_x_wf_2","name":"神行客","role":"炮击/突击","page":181,"pages":[181,182],"flavor":"神行客由侦察兵、孤狼和独行侠驾驶——通常是那种习惯于在敌后花费大量时间工作的驾驶员。这些精英驾驶员所携带的大量装备使他们有能力适应几乎任何环境。","tactics":"神行客千变万化，但其变化只在特定范围生效。使用其能力重新定位其职能，以便它最大限度地利用其套件。玩家们会意识到进退自如是对付神行客的高效策略，其有效攻击需要既定距离，靠近或远离能使其失效。","stats":{"hull":[-2,0,0],"sys":[-1,0,2],"agi":[2,4,4],"eng":[1,2,3],"hp":[10,12,14],"armor":[0,0,0],"evasion":[10,13,16],"edef":[8,8,10],"speed":[4,4,4],"size":[0.5,0.5,0.5],"heatcap":[5,5,5],"save":[10,12,14],"sensor":[20,20,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1/2 或 1"],"base":[{"name":"切换套件","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"神行客切换至一个可用套件，获得新的攻击选项。它还获得只能在这一轮使用的额外效果。默认情况下，它拥有两个套件，射手套件和散兵套件，并可获得更多可选系统。在任意既定回合中，他们只能使用一个套件中的武器和系统。当神行客的一个武器或系统被摧毁时，它必须从已激活的套件中选择。神行客可以选择任意套件开始战斗，但在它切换到不同套件前不会获得切换加成。","id":"npcf_x_wf_2_1","base":true}],"optional":[{"name":"CQB 特训","type":"Trait","tags":[],"effect":"神行客免疫缓慢且不能被擒拿。","id":"npcf_x_wf_2_2","base":false},{"name":"奔忙","type":"Trait","tags":[],"effect":"当神行客切换套件时，他们可自由动作移动等同速度的空间。","id":"npcf_x_wf_2_3","base":false},{"name":"进攻武器性切换","type":"Trait","tags":[],"effect":"当神行客使用切换套件时，他们可对邻近敌方角色造成 2 动能伤害。受影响角色必须成功通过敏捷豁免否则被击退 3 空间并伏臥。","id":"npcf_x_wf_2_4","base":false},{"name":"基础套件","type":"Trait","tags":[],"effect":"射手套件切换增益：仅在本回合，游骑兵长步枪的伤害不能以任何方式减少，并且它忽略重火器标签。","id":"npcf_x_wf_2_5","base":false},{"name":"游骑兵长步枪","type":"Weapon","tags":[{"id":"tg_ordnance"}],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[0,0,0],"accuracy":[1,1,1],"range":[{"type":"Range","val":20}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"若目标距离超过射程 8，则该武器造成 9/10/12 动能伤害而非标准伤害。","id":"npcf_x_wf_2_6","base":false},{"name":"闪避","type":"Reaction","tags":[{"id":"tg_recharge","val":4}],"trigger":"超过射程 8 的远程攻击将击中神行客。","effect":"该攻击失败，且神行客获得对所有伤害抗性直到回合结束。","id":"npcf_x_wf_2_7","base":false},{"name":"散兵套件","type":"Trait","tags":[],"effect":"切换增益：仅在本回合，神行客会变为隐形，并且它的移动会忽略困难地形，忽略交战，且不会引起反应。","id":"npcf_x_wf_2_8","base":false},{"name":"爆破步枪","type":"Weapon","tags":[{"id":"tg_knockback","val":3}],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[1,1,1],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Explosive","val":[6,7,8]}],"effect":"","id":"npcf_x_wf_2_9","base":false},{"name":"复位","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"任意角色开始他们的回合。","effect":"神行客可移动与其速度相等的空间。","id":"npcf_x_wf_2_10","base":false},{"name":"可选套件","type":"Trait","tags":[],"effect":"攻城套件切换增益：神行客在射程 5 内溅射 1 区域散布菱角，在场景结束前将其视为困难地形。随后，他们在任何邻近的自由空间部署一块大小 1 的硬性掩护，该掩护维持至场景结束。","id":"npcf_x_wf_2_11","base":false},{"name":"肩部迫击炮","type":"Weapon","tags":[{"id":"tg_arcing"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[0,0,0],"accuracy":[1,1,1],"range":[{"type":"Range","val":10},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[4,5,6]}],"effect":"","id":"npcf_x_wf_2_12","base":false},{"name":"防爆屏蔽","type":"Trait","tags":[],"effect":"神行客对所有来自线形，锥形，爆发和溅射效果的伤害和热度具有抗性，并且在避免这些效果的所有豁免上+1 准度。","id":"npcf_x_wf_2_13","base":false},{"name":"盘踞","type":"Trait","tags":[],"effect":"神行客免疫敌对角色强迫的非自主移动。","id":"npcf_x_wf_2_14","base":false},{"name":"工兵套件","type":"Trait","tags":[],"effect":"神行客向视线射程 5 内的角色发射一枚闪光榴弹。目标必须通过敏捷豁免，否则受扰直到他们下一回合结束。","id":"npcf_x_wf_2_15","base":false},{"name":"电磁霰弹枪","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[1,1,1],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[2,3,4]}],"effect":"","on_hit":"目标受到锁定。","id":"npcf_x_wf_2_16","base":false},{"name":"烟雾弹","type":"System","tags":[{"id":"tg_limited","val":2},{"id":"tg_quick_action"}],"effect":"神行客向视线射程 5 内发射一枚烟雾弹，创造一片溅射 1 的烟雾区域。该区域提供软性掩护，直到场景结束。","id":"npcf_x_wf_2_17","base":false},{"name":"干扰桥塔","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_limited","val":2},{"id":"tg_quick_action"}],"effect":"干扰桥塔（大小 1，5/6/8HP，标签：可展开）一旦安置，该桥塔会创建爆发 2 的静滞区域。在受影响区域内的敌对角色将受扰，直到他们离开。即使神行客切换套件，桥塔依然存在。","id":"npcf_x_wf_2_18","base":false}],"pack":"壁花不容","source":7},{"id":"npcc_x_wf_3","name":"怨恨者","role":"卫兵","role_en":"defender","page":183,"pages":[183],"flavor":"怨恨者是种侵略性技术防御底盘，常被荷鲁斯技术邪教、海盗和叛乱派系使用。通过使用反应堆覆盖的礼拜编码，这些机甲能够撬开机甲反应堆核心并维持这种状态——每次武器开火给予失效反馈。那些初出茅庐或粗心大意的驾驶员在战场上对抗经验丰富的怨恨者驾驶员，往往会发现自己最后料理了自己。","tactics":"怨恨利用那些依赖热度管理或精心产热来最大化伤害输出的角色。使用监禁来锁住危险的伤害输出者，并将其置于某处登基以保护盟友，但要小心——它机动性相对较弱，并且不能自己成事。","stats":{"hull":[0,0,0],"sys":[2,3,4],"agi":[-2,-2,-2],"eng":[2,3,4],"hp":[18,20,22],"armor":[2,3,4],"evasion":[6,6,6],"edef":[10,14,16],"speed":[2,2,2],"size":[2,2,2],"heatcap":[5,6,7],"save":[13,15,17],"sensor":[20,20,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"登基","type":"System","tags":[{"id":"tg_recharge","val":4},{"id":"tg_shield"},{"id":"tg_quick_action"}],"effect":"怨恨者被固定并激活爆裂防御盾。任何对怨恨者或其邻近盟友进行远程或近战攻击的角色在掷骰前受到 3AP 能量伤害。该效果持续怨恨者下一回合结束，或以快速动作结束该效果。","id":"npcf_x_wf_3_1","base":true},{"name":"护法","type":"Trait","tags":[],"effect":"邻近盟友可将怨恨者充当硬性掩护。","id":"npcf_x_wf_3_2","base":true},{"name":"监禁","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"视线感应内某角色必须通过系统豁免，否则受到 4/5/6能量伤害并被催化病毒感染。受该种病毒影响的角色无法通过任意方法清除热度（除过热）。该效果持续至场景结束，直至怨恨者被毁，或受影响角色移到怨恨者旁。当至少一个角色受到病毒影响时，怨恨者被固定。已感染病毒目标若再次遭到监禁则伤害翻倍。","id":"npcf_x_wf_3_3","base":true},{"name":"扣押","type":"Tech","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"视线感应内的敌方角色需通过系统豁免否则受到 2/3/4 热度并固定到他们下一回合结束。成功则不受热度影响，但会缓慢直到他们下一回合结束。","id":"npcf_x_wf_3_4","base":true}],"optional":[{"name":"碾压目标","type":"Tech","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"怨恨者视线感应内选择一个角色：他们攻击怨恨者外的所有角色+3 难度，直到怨恨者下一回合开始。","id":"npcf_x_wf_3_5","base":false},{"name":"反馈护盾","type":"Tech","tags":[{"id":"tg_round","val":1},{"id":"tg_shield"},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"怨恨者视线射程 5 内选择一个盟友角色。任何成功伤害该角色的角色会立即受扰直到他们下一回合结束。该效果持续到被触发，或场景结束。","id":"npcf_x_wf_3_6","base":false},{"name":"阴险牢笼","type":"Trait","tags":[],"effect":"受监禁影响的角色在超限后立即受到 5/7/9AP 能量伤害。受影响角色会知晓这种影响，且该伤害无法以任何方式减免。","id":"npcf_x_wf_3_7","base":false},{"name":"卡瑟利","type":"Tech","tags":[{"id":"tg_recharge","val":6},{"id":"tg_full_tech"}],"tech_type":"Full","effect":"怨恨者在视线感应内对其选择的所有角色使用监禁。","id":"npcf_x_wf_3_8","base":false},{"name":"盘踞","type":"Trait","tags":[],"effect":"怨恨者免疫敌对角色强迫的非自主移动。","id":"npcf_x_wf_3_9","base":false}],"pack":"壁花不容","source":7},{"id":"npcc_x_ws_1","name":"主战坦克","role":"炮击/突击","page":59,"pages":[59,60,61],"flavor":"即便在机械化底盘时代，坦克仍是现代装甲理论的核心组成部分，其历史可追溯到前大崩溃装甲战的最早期。尽管自那时以来技术不断进步，但现代主战坦克的总体设计仍然一目了然：一辆装备着巨大主武器炮塔的装甲载具，配备有辅助武器，融合了火力、防护对策和机动性为一体的多功能进攻防御型单位。虽然底盘往往是更加灵活和可塑性更强的打击平台，但坦克不仅能安装更厚重的装甲，还能在行进中使用大口径武器。在全银河系中可以找到的坦克配置种类可能比底盘变种还要多样，不同国家、军方甚至私人军队都能找到最适合他们作战策略的设计。","tactics":"主战坦克是一种重装甲重武器的“定点”单位，能够凭借其速度和火力迅速压倒敌人。它可以使用主炮和副武器展开弹幕以及使用坦克冲击来碾压其他角色，能够迅速造成大量伤害，复合装甲则使其极具抗打击力。这些优势因其移动受限和过于明显的装甲面朝向而得到平衡，因此很容易受到侧击。选择在什么位置射击，什么时候发动突击是充分利用该单位的关键。","stats":{"hull":[4,5,6],"sys":[0,0,0],"agi":[-2,-2,-2],"eng":[2,3,4],"hp":[20,25,30],"armor":[2,2,2],"evasion":[6,7,8],"edef":[8,10,12],"speed":[5,5,5],"size":[2,2,2],"heatcap":[10,10,10],"save":[11,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"雷霆万钧","type":"Trait","tags":[],"effect":"主战坦克无法获得低等兵模板, 且每场景只能出现一辆主战坦克。","id":"npcf_x_ws_1_1","base":true},{"name":"全履带","type":"Trait","tags":[],"effect":"主战坦克必须沿直线移动，尽管它可以在不同的方向上分别移动和推进。此外, 主战坦克不能攀爬，游泳，操作物品，或进行除了冲撞以外的近战攻击，但它忽略困难地形并免疫伏卧。","id":"npcf_x_ws_1_2","base":true},{"name":"武装配备","type":"Trait","tags":[],"effect":"主战坦克必须选择一门主炮和一件辅助武器。","id":"npcf_x_ws_1_3","base":true},{"name":"复合装甲","type":"Trait","tags":[],"effect":"主战坦克一侧是装甲面（选择其指示物/图标/微缩模型一侧，参考右侧图示）。所有角色均可辨明其朝向。任何攻击和效果，若其效果线直接对准装甲面，则视主战坦克拥有 6 装甲，且对溅射、爆发、线形和锥形的伤害及效果获得抗性。自装甲面受到的 AP 伤害、燃烧和以及主战坦克在离散状态下承受的任何伤害仍会减少2。地雷和其他基于邻近的系统不受此特征影响。每当主战坦克标准移动或推进时，可改变其装甲面的朝向。","id":"npcf_x_ws_1_4","base":true},{"name":"坦克冲击","type":"Trait","tags":[],"effect":"主战坦克忽略交战并可以穿过其他小于大小 3 的角色和障碍物所占据的空间，但不能停留在其中。以此法穿过的物品会被摧毁，而穿过的角色会被直接推出其行进路线，若以推进来穿过其他角色，1/回合，该角色必须通过机体豁免否则受到 4/5/6 动能伤害并伏卧。","id":"npcf_x_ws_1_5","base":true},{"name":"稳定车身","type":"Trait","tags":[],"effect":"主战坦克无法被小于自身的角色推拉或击退。若敌对效果会使主战坦克移动 2 或更多空间，或使其伏卧（即使主战坦克因免疫或较小角色的移动而忽略该效果），该角色在效果结算后可改变其装甲面朝向。角色无论自身大小都可冲撞主战坦克，以改变其装甲面朝向。","id":"npcf_x_ws_1_6","base":true}],"optional":[{"name":"主炮：滑膛炮","type":"Weapon","tags":[{"id":"tg_knockback","val":3}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Explosive","val":[8,10,12]}],"effect":"该武器对地形、掩体、物品造成 10/20/30 AP 爆炸伤害。未命中：任何邻近目标的物品大小 1 部分（如掩体，可展开物品，建筑或地形）受到 10/20/30 爆炸伤害。","id":"npcf_x_ws_1_7","base":false},{"name":"轨道炮","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Line","val":10}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"该武器忽略硬性掩护。","id":"npcf_x_ws_1_8","base":false},{"name":"“安塔瑞斯”型镭射炮","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Energy","val":[6,7,8]},{"type":"Heat","val":[3,4,5]}],"effect":"","id":"npcf_x_ws_1_9","base":false},{"name":"反坦克炮","type":"Weapon","tags":[{"id":"tg_ordnance"}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[0,1,2],"accuracy":[1,1,1],"range":[{"type":"Range","val":15}],"damage":[{"type":"Kinetic","val":[8,10,12]}],"effect":"会心一击：目标离散直到其下一回合结束。","id":"npcf_x_ws_1_10","base":false},{"name":"“扫街者”榴霰弹发射器","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[0,0,0],"accuracy":[1,1,1],"range":[{"type":"Range","val":3},{"type":"Cone","val":5}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"此攻击的锥形区域在开火时无法改变方向。","id":"npcf_x_ws_1_11","base":false},{"name":"辅助武器：同轴机枪","type":"Weapon","tags":[{"id":"tg_knockback","val":1}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"该武器可以同时攻击两个目标。","id":"npcf_x_ws_1_12","base":false},{"name":"反装甲导弹","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_arcing"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Explosive","val":[3,4,5]}],"effect":"","id":"npcf_x_ws_1_13","base":false},{"name":"标记巢房","type":"Weapon","tags":[{"id":"tg_smart"},{"id":"tg_seeking"}],"weapon_size":"主武器","weapon_kind":"巢房","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Burn","val":[2,3,4]}],"effect":"","on_hit":"目标必须通过系统豁免否则被锁定并受损直到对方下一回合结束。","id":"npcf_x_ws_1_14","base":false},{"name":"“天窗”防空镭射炮","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Energy","val":[2,3,4]}],"effect":"","on_hit":"若目标正在飞行，对方必须通过敏捷豁免否则选择以下结果之一：受到 1d6 额外伤害，或立即着陆（视为不受伤害的坠落）且直到下一回合结束都无法飞行。","id":"npcf_x_ws_1_15","base":false},{"name":"全向炸药","type":"Weapon","tags":[{"id":"tg_knockback","val":2}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Burst","val":2}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"原文攻击加值为「+1/2/33」，按 +1/2/3 录入。\n该武器忽略交战造成的远程攻击惩罚。","id":"npcf_x_ws_1_16","base":false},{"name":"悬浮坦克","type":"Trait","tags":[],"effect":"主战坦克忽略危险地形，并且移动不再受到直线移动限制影响。","id":"npcf_x_ws_1_17","base":false},{"name":"攻城模式","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"主战坦克展开（或收起）稳定器，只要该系统激活，它就始终固定。在该模式下，坦克主炮会获得抛射和+5射程（或线形+5），但主战坦克不能使用主炮对射程 3内的角色、物品和空间进行以它们为中心的远程攻击。","id":"npcf_x_ws_1_18","base":false},{"name":"副炮手","type":"System","tags":[],"effect":"即使受扰或晕眩，主战坦克仍可使用辅助武器进行攻击。","id":"npcf_x_ws_1_19","base":false},{"name":"移动碉堡","type":"Trait","tags":[],"effect":"邻近主战坦克的盟友角色可使用主战坦克作为硬性掩护。当受益于上述掩护时，该角色获得对来自爆发、溅射、线形和锥形伤害的抗性。","id":"npcf_x_ws_1_20","base":false},{"name":"烟幕","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"主战坦克可在射程 5 内创造溅射 2 的浓厚烟幕，阻绝传感器，且可以立刻用自由动作进行推进入烟幕。该区域持续到主战坦克下一回合结束，所有烟幕中的角色和物品获得软性掩护。主战坦克和任何盟友角色首次进入烟幕时清除自身锁定。","id":"npcf_x_ws_1_21","base":false}],"special":"载具","pack":"冬痕行动","source":5},{"id":"npcc_x_mc_1","name":"复仇者","role":"突击/卫兵","page":51,"pages":[51],"flavor":"复仇者级机甲的驾驶员往往是狂热者、职业战士，以及来自高度重视禁卫军或战士种姓文化的民族。战斗中，这些驾驶员扮演着力量倍增者和班组领导者的角色，但比起他们的机甲，他们作为个人更引人注目。复仇者驾驶员与他们的盟友紧密维系着——这份牵绊强大到当形势转向对敌人有利时，对战斗、失败和斗争的强烈情绪足以促使他们做出令人难以置信的英雄壮举。","tactics":"复仇者最初并不是特别危险，但当他们的盟友们集结在他周围时，便是他们极具危险之时。将它们安置在其他高优先级目标附近，以利用它们的复仇能力，迫使角色在首先消灭它们或因摧毁盟友而遭受更多痛苦之间做出选择。","stats":{"hull":[1,2,3],"sys":[0,0,0],"agi":[1,3,5],"eng":[0,0,0],"hp":[15,18,21],"armor":[0,0,0],"evasion":[10,12,15],"edef":[8,10,12],"speed":[5,5,5],"size":[1,1,1],"heatcap":[6,6,8],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"决斗手枪","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[2,3,4],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"","id":"npcf_x_mc_1_1","base":true},{"name":"迸发簇弹","type":"Trait","tags":[{"id":"tg_round","val":1}],"effect":"当复仇者的攻击伤害到另一角色时，他们可以迫使该角色通过工程豁免，否则将被爆破簇弹覆盖直到他们下一回合结束。在该效果解除前，他们每次进行近战或远程攻击时都会受到3/4/5AP 爆炸伤害。受影响角色会意识到这种效果。","id":"npcf_x_mc_1_2","base":true},{"name":"复仇","type":"Trait","tags":[],"keywords":["1/场景"],"effect":"若某非低等兵的盟友角色在射程 5 内被摧毁，在场景结束前，复仇者获得护盾 8/12/16，攻击时+5 基础伤害，所有攻击、检定和豁免+1 准度。","id":"npcf_x_mc_1_3","base":true},{"name":"突击装甲","type":"Trait","tags":[],"effect":"复仇者对射程 3 以内的所有伤害有抗性。","id":"npcf_x_mc_1_4","base":true}],"optional":[{"name":"致命","type":"Trait","tags":[],"effect":"复仇者会心一击+1d6 动能伤害。","id":"npcf_x_mc_1_5","base":false},{"name":"无尽复仇","type":"Trait","tags":[],"effect":"复仇在每场景中可被触发任意次数，但在第一次触发后，它就不能获得额外伤害提升。取而代之的是它给予+4/5/6 护盾。这不会取代原先的护盾，而是增加相同的量。","id":"npcf_x_mc_1_6","base":false},{"name":"仇恨锁链","type":"Trait","tags":[],"effect":"当复仇触发时，所有射程 5 内的盟友角色——不包括复仇者——获得护盾 4/6/8。","id":"npcf_x_mc_1_7","base":false},{"name":"审判霰弹枪","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_seeking"}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[0,0,0],"accuracy":[-1,-1,-1],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Energy","val":[10,12,14]}],"effect":"","on_hit":"目标必须通过敏捷豁免否则被击倒伏臥。当射程 3 内盟友色被摧毁时，该武器会自动装填。","id":"npcf_x_mc_1_8","base":false},{"name":"拟态陷阱","type":"Reaction","tags":[],"keywords":["每轮不限次"],"trigger":"复仇者射程 5 内的盟友角色豁免失败，或复仇者视线内的盟友角色被敌对角色攻击。","effect":"复仇者可直线向攻击者移动 3 空间。","id":"npcf_x_mc_1_9","base":false}],"pack":"模组资源合集","source":3},{"id":"npcc_x_cp_1","name":"架构师","role":"卫兵","role_en":"defender","page":78,"pages":[78,79],"flavor":"架构师们是机械化战斗中久经考验的主力——将民用底盘积极转化为军用标准。架构师主要从地形改造或构建模式中进行升级换代，将殖民地建设和修复工具转向战斗防御工事和堑壕，在该部署堡垒的地方部署它们。","tactics":"架构师可使用他们的城堡战斗地球化改造动态重塑战场——用它来创建一个固守点好让盟友撤退，同时以自身据守玩家。它们缺乏破坏性系统，这意味着玩家突破其防御就能轻易威胁到它们。","stats":{"hull":[2,4,6],"sys":[0,0,0],"agi":[-2,-2,-2],"eng":[1,2,3],"hp":[15,19,24],"armor":[1,1,2],"evasion":[6,6,6],"edef":[10,10,10],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,10,10],"save":[10,12,14],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"防御者","type":"Trait","tags":[],"effect":"邻近的盟友角色可将架构师视为硬性掩护。架构师忽略困难和危险地形。","id":"npcf_x_cp_1_1","base":true},{"name":"泥浆加农炮","type":"Weapon","tags":[{"id":"tg_knockback","val":5}],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Cone","val":5}],"damage":[],"effect":"攻击时：在该区域自由空间安置大小 1 的硬性掩护。直到架构师下一回合开始前与它邻近的空间变为困难地形。","id":"npcf_x_cp_1_2","base":true},{"name":"城堡战斗地球化改造","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"架构师可使用以下动作：打印（再充能 4+）：在射程 3 内安置最多 3 块大小 1硬性掩护，或 1 块大小 2 硬性掩护。裂痕：架构师在射程 5 内选择线形 5 区域。在它下一回合开始时，该区域崩溃。该地区的物品和地形被摧毁。角色必须通过敏捷检定否则固定并获得软性掩护直到他们用快速动作通过机体豁免。锐化：感应内溅射 1 变为困难地形直到场景结束或你再次使用该动作。该区域伏卧角色受到 3/5/7 动能伤害。震颤：感应内溅射 1 所有角色必须通过机体豁免否则伏卧。该区域内物品和地形受到 10AP 动能伤害。","id":"npcf_x_cp_1_3","base":true}],"optional":[{"name":"“冈格尼尔”镭射炮位","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_limited","val":1}],"effect":"冈格尼尔镭射炮（大小 1，,20HP，5 回避/ED，标签：可展开，对所有伤害有抗性）架构师可用完整动作将冈格尼尔镭射炮安置在邻近的自由空间中，并划出线形 20 区域。当邻近镭射炮时可用快速动作选择新的线形区域。它在轮结束时准备就绪并充能。架构师或任何邻近冈格尼尔镭射炮的盟友角色可承受4 热度以快速动作来发射它。冈格尼尔必须充能才能发射。开火时，镭射记录的线形内或邻近的所有角色必须通过机体豁免否则受到 16/20/24AP 能量伤害。然后它失去充能。它会在下一轮结束时再次充能。","id":"npcf_x_cp_1_4","base":false},{"name":"民用地形打印机","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"架构师在视线射程 5 内标记 2 个自由空间。至少有一个必须在它的射程 3 内。在其中一个空间中的盟友角色可用移动 1 空间以直线方式立即移动到另一个空间，忽略交战和反应，以及其他角色的阻挡和地雷。若障碍物或地形挡住了他们去路，就会提前停止移动。","id":"npcf_x_cp_1_5","base":false},{"name":"嵌入式弹射器","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_quick_action"}],"effect":"架构师固定直到下一回合开始。以一个快速动作，它可以将一个与它大小相同或更小的邻近盟友角色扔到射程 10内的任意空间。该移动忽略交战和反应，若碰到障碍物或角色就会提前结束移动。若命中一个角色，该角色必须通过机体豁免否则伏卧。","id":"npcf_x_cp_1_6","base":false},{"name":"密封胶混合","type":"Trait","tags":[],"effect":"泥浆加农炮获得，命中：目标必须通过机体豁免否则固定直到他们用一个快速动作来挣脱。","id":"npcf_x_cp_1_7","base":false},{"name":"堑壕武士","type":"Trait","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"当架构师有掩护时，他们获得+2 装甲。以一个快速动作，它可以挖一个 2 空间宽的线形 4 战壕，至少有一个空间与之邻近。角色全部在战壕内则获得软性掩护。该战壕一直持续到架构师再次使用该动作，或邻近角色用完整动作通过机体检定摧毁它。","id":"npcf_x_cp_1_8","base":false},{"name":"喷砂器","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"架构师在视线感应内的溅射 2 自由空间创建一个微粒爆发，持续到他们下一回合结束。角色至少部分在该区域有软性掩护，并将所有角色视为隐形。若他们在该区域结束回合，将受到 3AP 动能伤害。","id":"npcf_x_cp_1_9","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_cp_2","name":"掷弹兵","role":"突击","role_en":"striker","page":80,"pages":[80],"flavor":"在播种机制造阻塞点和防御边界的位置上，掷弹兵冲入敌军队形，积极破坏对方推进。他们通过绕开置信武器防御并利用多功能爆炸工具箱来迫使敌方消耗资源，从而构成实质性威胁。","tactics":"掷弹兵的目的是骚扰和破坏——“太鼓”GL-16 可分散或聚集玩家，而投掷榴弹则为他们提供了定制选项来干扰玩家的计划。清扫者装甲也可让他们避开更多的永久防御。它们的近程要求它们待在近处——远程防御可阻止它们推进。","stats":{"hull":[2,2,3],"sys":[1,1,1],"agi":[0,0,0],"eng":[1,3,5],"hp":[14,16,20],"armor":[1,1,1],"evasion":[8,8,10],"edef":[10,12,14],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,10,12],"save":[12,15,18],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"“太鼓”GL-16","type":"Weapon","tags":[{"id":"tg_arcing"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Explosive","val":[5,5,5]}],"effect":"该武器在 T2 攻击两次，在 T3 攻击三次。","on_hit":"目标向掷弹兵选择的方向击退 1 空间。","id":"npcf_x_cp_2_1","base":true},{"name":"清扫者装甲","type":"Trait","tags":[],"effect":"掷弹兵对爆炸伤害具有抗性，对无人机、可展开、榴弹和地雷的伤害免疫。该特性不影响带有无人机标签的武器。","id":"npcf_x_cp_2_2","base":true},{"name":"掷弹","type":"System","tags":[{"id":"tg_grenade"},{"id":"tg_quick_action"},{"id":"tg_turn","val":1}],"effect":"掷弹兵向射程 5 内空间投掷以下榴弹之一，在溅射 1爆炸。震荡：该区域内角色必须通过机体豁免否则击退 3 空间，若他们撞到障碍则受损直到他们下一回合结束并伏卧。燃烧：该区域内角色必须通过敏捷豁免否则受到 1/2/3燃烧，并在他们下一回合结束前清除热度时只能清除一半。电击：该区域内角色必须通过工程豁免否则受到 2/3/4热度，并且在科技攻击和智能与引导武器攻击时+2 难度直到下一回合结束。烟雾：产生溅射 2 区域。直到掷弹兵下一回合结束前，溅射区域中的角色和物品具有软性掩护。","id":"npcf_x_cp_2_3","base":true}],"optional":[{"name":"丧钟","type":"Trait","tags":[],"effect":"当掷弹兵被摧毁时，它可立即投掷一枚榴弹。","id":"npcf_x_cp_2_4","base":false},{"name":"家庭烹饪","type":"Trait","tags":[{"id":"tg_recharge","val":4}],"effect":"当掷弹兵使用掷弹时，它可以激活该特征，使榴弹的溅射半径增加 1。","id":"npcf_x_cp_2_5","base":false},{"name":"木履尖刺","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"掷弹兵在邻近的无人机、物品或地形身上扎入一枚爆炸钉。以协定它能引爆所有的爆炸钉。所有受影响的无人机或物品向任意方向推动 3 空间，然后产生爆发 1 范围。该区域内的角色必须通过敏捷豁免否则受到 8/12/16 爆炸伤害，成功则伤害减半。","id":"npcf_x_cp_2_6","base":false},{"name":"游击遮蔽","type":"Trait","tags":[],"effect":"当角色在掷弹兵的强制豁免中失败时，他们将掷弹兵视为隐形直到下一回合开始。","id":"npcf_x_cp_2_7","base":false},{"name":"截短保险丝","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"掷弹兵对感应内的角色进行科技攻击。成功则对方所有武器失去装填，带有榴弹或地雷标签的系统会立即失去 1 充能。若武器失去装填，对方将受到 2/3/4 AP 爆炸伤害，若失去 1 充能，则受到 2/3/4 AP 爆炸伤害。","id":"npcf_x_cp_2_8","base":false},{"name":"智能弹药","type":"System","tags":[],"effect":"掷弹兵的榴弹无需视线，只要追踪到目标路径即可，盟友角色自动通过豁免来避免其影响。","id":"npcf_x_cp_2_9","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_cp_3","name":"拦截机","role":"卫兵","role_en":"defender","page":81,"pages":[81],"flavor":"拦截机是将传统狗斗/空中战术转换为底盘级交互。它们尺寸较小，但卓越的速度和响应时间可打断、干扰和惩罚笨重的骨架。置信套件和高 G 机动的结合需要大量训练才能在不造成严重伤害情况下处理，这使得拦截机成为任何部队罕见而宝贵的资产。","tactics":"拦截机的存在是为否认选择并迫使玩家专注于他们。拦截标记让他们始终跟随和骚扰高速目标，拦截式 SMG 的高威胁使对方难以逃脱。虽然拦截机的机动性非常强，但很容易被缓慢甩在后面，也很容易被干掉或忽略。","stats":{"hull":[2,2,2],"sys":[1,2,3],"agi":[3,4,5],"eng":[0,0,0],"hp":[12,14,16],"armor":[1,1,1],"evasion":[11,14,16],"edef":[8,8,10],"speed":[6,6,6],"size":[0.5,0.5,0.5],"heatcap":[8,8,8],"save":[12,13,15],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"SCC 总套组","type":"System","tags":[],"effect":"拦截机可以在移动或推进时悬浮。","id":"npcf_x_cp_3_1","base":true},{"name":"拦截式 SMG","type":"Weapon","tags":[{"id":"tg_reliable","val":[1,2,3]}],"weapon_size":"副武器","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[3,5,7]}],"effect":"当有拦截标记的角色对一个盟友角色发起攻击时，该武器可用一种反应开火，目标是攻击者。","id":"npcf_x_cp_3_2","base":true},{"name":"拦截标记","type":"Trait","tags":[{"id":"tg_protocol"},{"id":"tg_recharge","val":5}],"effect":"拦截机在视线内选择一个敌对角色施以拦截标记。他们的武器伤害忽略该角色的装甲，并且每当该角色移动时，他们都可以移动相同数量的空间。同时只能标记一个角色；施以新标记会移除前一个标记。","id":"npcf_x_cp_3_3","base":true}],"optional":[{"name":"点防屏","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":5}],"trigger":"射程 3 内的一个角色发起一次攻击。","effect":"拦截机进行一次对抗的攻击掷骰。若他们赢得对抗则此次攻击自动失败。","id":"npcf_x_cp_3_4","base":false},{"name":"手痒难耐","type":"Trait","tags":[],"effect":"使用拦截式 SMG 的反应攻击在触发动作前结算。它获得命中：目标在本回合进行的下次攻击+1 难度。","id":"npcf_x_cp_3_5","base":false},{"name":"碎片投掷器","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_recharge","val":4}],"effect":"在拦截机下一回合结束前，敌对角色将拦截机射程 3内的空间视为困难地形。他们可以忽略该效果，但在该区域每移动 1 空间就会受到 1AP 动能伤害。","id":"npcf_x_cp_3_6","base":false},{"name":"反射/下潜","type":"Trait","tags":[],"effect":"拦截机的移动忽略交战和反应。","id":"npcf_x_cp_3_7","base":false},{"name":"超音速乱入","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"拦截机开局并不在战场上部署。相反，在敌对角色回合开始时，你可以将拦截机安置在他们射程 3 内。以一个完整动作，它可以将自己从战场上移除，在下一回合开始时返回射程 50 内的任何位置。若多个角色具备此特征，则每回合只有一个角色可激活它。","id":"npcf_x_cp_3_8","base":false},{"name":"晕眩冠冕","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":1}],"effect":"拦截机创造爆发 3 闪光。受影响区域角色必须通过系统豁免否则受扰直到下一回合结束，成功则受损。","id":"npcf_x_cp_3_9","base":false},{"name":"箔条投掷包","type":"System","tags":[{"id":"tg_limited","val":2}],"effect":"拦截机推进时可在它开始移动的空间中制造爆发 2。该区域角色必须通过系统豁免否则在其下一回合结束前无法进行反应或将视线划出邻近空间外。","id":"npcf_x_cp_3_10","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_cp_4","name":"群主","role":"卫兵","role_en":"defender","page":82,"pages":[82,83],"flavor":"不同于蜂巢的大军团构想，群主骨架与单独的强大无人机思维体建立了强韧且独一的维系。群主从远处引导它，可维持一个安全距离，同时仍然通过神经主观体连接体验战斗的情绪迸发——它们将战争重塑为捕食者和猎物之间原始的兽性关系。","tactics":"群主与其巨兽无人机协同工作——远处引导无人机冲入近战范围攻击和固定目标。使用示踪步枪来标记更多正在躲避的目标。然而，群主本身颇为脆弱，而且没有它的指挥，巨兽之躯也会失去能力。","stats":{"hull":[3,3,3],"sys":[1,2,3],"agi":[3,3,5],"eng":[-2,-2,-2],"hp":[10,10,10],"armor":[0,0,0],"evasion":[14,15,16],"edef":[12,13,14],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,8],"save":[12,14,17],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"巨兽无人机","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_turn","val":1}],"effect":"巨兽无人机（大小 2，15/20/25 HP，8 回避/ED，4 速度，2 装甲，标签：无人机）每场景开始时，群主可部署一个强大可自主移动的同伴无人机在射程 3。它可用快速动作命令无人机采取以下动作之一：• 猛扑：对邻近角色+2/+4/+6 近战攻击。命中则受到 6/9/12 动能伤害并被无人机擒拿，无人机机体+2/层级。• 致残：被无人机擒拿的角色受到 4/6/8 AP 动能伤害，并受扰与受损直到他们脱离擒拿。","id":"npcf_x_cp_4_1","base":true},{"name":"原始反射","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个角色开始在巨兽无人机邻近开始移动。","effect":"他们必须通过敏捷检定否则伏卧。","id":"npcf_x_cp_4_2","base":true},{"name":"示踪步枪","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Energy","val":[2,3,5]},{"type":"Heat","val":[1,1,1]}],"effect":"","on_hit":"巨兽无人机可直接向群主的目标移动 3 空间。在群主下一回合结束前，任何角色对目标的下次攻击+1 准度。","id":"npcf_x_cp_4_3","base":true},{"name":"潜行者斗篷","type":"Trait","tags":[],"effect":"距离 5 之外的角色将其视为隐形。","id":"npcf_x_cp_4_4","base":true},{"name":"超载链接","type":"Trait","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":5}],"effect":"巨兽无人机恢复所有 HP（即使它被摧毁）并移动等同其速度的空间。群主晕眩直到他们下一回合开始。","id":"npcf_x_cp_4_5","base":true}],"optional":[{"name":"巫术无人机","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"群主对感应内角色进行一次科技攻击。命中则对方所有检定和豁免+1 难度，并在每回合结束时受到 2AP 动能伤害。他们可以在回合结束时通过系统豁免来移除无人机，或者邻近盟友角色可以尝试用快速动作豁免。","id":"npcf_x_cp_4_6","base":false},{"name":"霸主密令","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"群主对感应内每个无人机在任意方向上移动最多 4 空间。","id":"npcf_x_cp_4_7","base":false},{"name":"野兽契约","type":"Trait","tags":[],"effect":"只要巨兽无人机在群主视线感应内，它们在所有检定和豁免中+1 准度。","id":"npcf_x_cp_4_8","base":false},{"name":"熟练猎手","type":"Trait","tags":[],"effect":"该场景开始时群主标记一个角色。群主和巨兽无人机对该角色的攻击+1 准度，对其会心一击+2/3/4 额外伤害。","id":"npcf_x_cp_4_9","base":false},{"name":"生物组件","type":"Trait","tags":[],"effect":"巨兽无人机+1 速度并且在敏捷检定和豁免+1 准度。群主回合结束时它隐形直到下一回合开始或受到伤害。","id":"npcf_x_cp_4_10","base":false},{"name":"圈套无人机","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":2}],"effect":"圈套无人机（大小 2，5/10/15 HP，10 回避/ED，标签：无人机）群主将一架圈套无人机部署到视线感应内的自由空间。当角色在回合开始时邻近圈套无人机或在回合中首次移动到它邻近位置时，他们必须通过机体豁免否则固定和伏卧直到无人机被摧毁。","id":"npcf_x_cp_4_11","base":false},{"name":"“致命一击”","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_reliable","val":[2,3,4]}],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[10,15,20]}],"effect":"若该武器不致使目标被摧毁或失去结构，则只造成可靠伤害。","id":"npcf_x_cp_4_12","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_cp_5","name":"矢量","role":"炮击","role_en":"artillery","page":84,"pages":[84,85],"flavor":"矢量是种非典型设计——由卡斯特为其初期战争开发，但从未及时部署——如今被发现在废弃筒仓中，重新唤醒。矢量被用于零重力战斗，其目标是用一堆哑火长矛刺穿对手。他们成为卡斯特孤儿的最佳骨架；简单，致命，而且擅长小队作战。","tactics":"矢量的大部分伤害来自他们的微型喷流长矛。使用该武器迫使玩家改变位置，即使未能命中，并使用矢量的机动性来创造一个无处不在的威胁，让长矛刺穿他们的阵地。长矛的拖沓意味着矢量在面对更多机动对手或更开放空间时可能会吃亏——若有足够空间让他们的目标机动，他们可能会失去大部分潜在输出。","stats":{"hull":[2,2,2],"sys":[-1,-1,-1],"agi":[4,5,6],"eng":[2,2,2],"hp":[10,14,18],"armor":[1,1,1],"evasion":[12,14,16],"edef":[8,8,8],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,10],"save":[12,14,16],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"“黑寡妇”长步枪","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_knockback","val":1}],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"","on_hit":"矢量的目标必须通过机体豁免否则立即着陆（计算为坠落而不受伤害），直到下一回合结束才能再次飞行。","id":"npcf_x_cp_5_1","base":true},{"name":"改良 SCC 套组","type":"System","tags":[],"effect":"矢量可在移动或推进时飞行。","id":"npcf_x_cp_5_2","base":true},{"name":"微型喷流长矛","type":"Trait","tags":[{"id":"tg_free_action"},{"id":"tg_quick_action"}],"effect":"以一个自由动作，矢量标记一条对所有角色可见的线形20 区域，它将微型喷流长矛准备就绪。当一个敌对角色主动进入该区域时，它就会开火。受影响区域内所有角色必须通过敏捷豁免否则受到 12 动能伤害，成功豁免伤害减半并且被击退 2 空间。一个角色可通过对长矛起始位置进行远程或科技攻击，对抗矢量的回避或 ED，让它提前开火。若一个角色将同时受到多支长矛的影响，则进行一次豁免，每额外一支长矛则受到+2/3/4 伤害和+2 击退。若击中地形或物品，长矛会提前停止，摧毁该物品。该线形上的飞行角色也必须进行豁免。多支长矛不能从同一空间发射。矢量可花费一个快速动作在本回合额外进行 1/2/3 次该自由动作。","id":"npcf_x_cp_5_3","base":true}],"optional":[{"name":"爆裂筒仓","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[3,3,3]}],"effect":"受影响区域内的物品和地形受到 10AP 爆炸伤害。T2 时，该武器一次可攻击两个目标，T3 时可攻击三个目标。目标区域不能重叠。","id":"npcf_x_cp_5_4","base":false},{"name":"亡魂钉","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"矢量选择一个带有锁定的角色。当矢量进行该动作，并且在该角色每回合结束时，只要该角色从任何来源受到过锁定，就放置一个将他们包括在区域内的微型喷流长矛。角色可用快速动作通过系统豁免来终止该效果。矢量在同一时间只能标记一个角色。","id":"npcf_x_cp_5_5","base":false},{"name":"雷达猎犬","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个在射程 20 内的角色对矢量用科技动作。","effect":"矢量在该动作结算前推进，并在角色完成移动前或后将微型喷流长矛瞄准触发角色的位置。","id":"npcf_x_cp_5_6","base":false},{"name":"魔爪/狂怒瞄准矩阵","type":"System","tags":[{"id":"tg_quick_action"}],"keywords":["???热度（自身）"],"effect":"矢量选择任意数量已激活的微型喷流长矛。每个被选长矛都可瞄准一个新区域，使用相同的起始位置，并且矢量受到等同所选长矛数量的热度。","id":"npcf_x_cp_5_7","base":false},{"name":"自主部署","type":"Trait","tags":[],"effect":"当矢量安置一个微型喷流长矛时，线形可从射程 3 内任何空间起始。","id":"npcf_x_cp_5_8","base":false},{"name":"巨像箭囊","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"矢量掷骰 1d3+1/2/3。它可在本回合额外使用等同掷骰结果次数的微型喷流长矛动作，并受到同值的热度。","id":"npcf_x_cp_5_9","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_cp_6","name":"美德","role":"支援","role_en":"support","page":86,"pages":[86,87],"flavor":"美德型骨架处于能量屏蔽部署的前沿——曾被降级为不可移动防御工事的技术重新诠释其便携式设计。这些盾牌的极端功率消耗限制了它们的进攻潜力，但作为交换，美德可通过远距离盾牌投射和高回收率确保对中班组的保护。美德骨架具有内在自我牺牲精神，往往会让驾驶员对团队的忠诚度极高，或自我价值感极低。","tactics":"美德的粒子屏障是个令人难以置信的强大防御工具，允许它的目标忽略所有伤害——使用它来保护有被集火风险的近距突击者，或有可能承受稳定伤害的脆弱骨架。美德一次只能保护一个目标。他们的低热度上限使他们非常容易暴露，若其盾牌不堪重负，美德就会很快被摧毁。","stats":{"hull":[0,0,0],"sys":[4,4,6],"agi":[1,2,3],"eng":[2,2,4],"hp":[10,10,10],"armor":[0,0,0],"evasion":[10,12,14],"edef":[10,12,14],"speed":[3,3,3],"size":[2,2,2],"heatcap":[6,6,6],"save":[12,14,16],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"粒子屏障","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"美德开局获得 10/15/20 护盾。它在每回合开始时获得1/2，将其添加到该护盾上，直到满额。以一个快速动作，它可以将盾牌延伸到视线感应内的一个盟友军角色。每当该角色受到伤害时，美德在减少该伤害减免之前受到同等伤害，而该角色不会受到伤害。该连接效果持续到美德选择一个新目标，被减少到 0 护盾，被受扰或晕眩，或者二者在他们回合结束时不在彼此视线内。","id":"npcf_x_cp_6_1","base":true},{"name":"祝福术","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"美德受到 4AP 能量伤害，并在视线感应内选择一个盟友角色。然后，该角色可选择以下选项之一：• 重新装填一把武器。• 清除 3/4/5 热度。• 立即掷骰再充能。","id":"npcf_x_cp_6_2","base":true},{"name":"奉献术","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"tech_type":"Quick","effect":"在视线感应内选择一个溅射 2 的自由空间。敌对角色不能自愿进入该区域，直到美德下一回合开始。","id":"npcf_x_cp_6_3","base":true},{"name":"纯净组件","type":"Trait","tags":[],"effect":"美德不能选择低等兵模板。","id":"npcf_x_cp_6_4","base":true}],"optional":[{"name":"脉冲屏障","type":"Trait","tags":[],"effect":"只要美德有护盾，美德与其连接的粒子屏障目标就不会被击退、推或拉。","id":"npcf_x_cp_6_5","base":false},{"name":"炫目之盾","type":"Reaction","tags":[{"id":"tg_turn","val":1}],"trigger":"一个敌对角色攻击命中美德。","effect":"该角色视所有其他角色为隐形直到他们下一回合结束。","id":"npcf_x_cp_6_6","base":false},{"name":"数据香炉节点","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_heat_self","val":1},{"id":"tg_recharge","val":5}],"tech_type":"Quick","effect":"美德在感应内自由空间创建一个香炉构造（大小 1，5HP，10 回避/ED）。盟友角色可使用该构造作为硬性掩护，邻近的盟友角色可用快速动作消耗它，以清除一个非自己造成的状况，并获得 4/6/8 护盾。","id":"npcf_x_cp_6_7","base":false},{"name":"逐出教会","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"美德对感应内的目标进行科技攻击。命中则目标会被推离 3 空间，并受到 1/2/3 热度。若目标具有护盾，则击退和热度获得+3。","id":"npcf_x_cp_6_8","base":false},{"name":"交感超钩","type":"Trait","tags":[],"effect":"美德或它的粒子屏障目标都可以用自由动作终结它们的链接。如此行事时，目标身上所有非自身造成的状况都会转移到美德身上。","id":"npcf_x_cp_6_9","base":false},{"name":"活力屏障","type":"Trait","tags":[],"effect":"当粒子屏障的目标移动或推进时可飞行。当链接终止时，它的目标可用反应移动等同其速度一半的距离。","id":"npcf_x_cp_6_10","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npcc_x_sultan_1","name":"搬运工","role":"支援","role_en":"support","page":150,"pages":[150,151],"flavor":"搬运工是几千年前装甲步兵战术的当代翻版。作为一种跨 APC 和 IFV 的协同平台，搬运工原则强调部队资产和底盘之间的协调，相互支援以弥补各自的战术弱点。在战场上，即使是一架搬运工也能起到大幅力量倍增器的作用，步兵需承担高优先级的任务，而步兵班与经常陪同他们进入危险区域的驾驶员建立亲密的个人关系并不罕见。","tactics":"搬运工是种独特的支援单位，可与班组和小型机甲协同工作。这些部队可以使用搬运工来提供掩护，但更重要的是快速部署能力，这给他们意想不到的机动量，使他们能够迅速在战场周围重新部署。没有任何这样的单位来配合，该机甲诸多系统很快就失去价值。","stats":{"hull":[1,2,3],"sys":[0,0,0],"agi":[1,2,3],"eng":[0,0,1],"hp":[14,17,20],"armor":[0,0,0],"evasion":[10,12,14],"edef":[8,9,10],"speed":[5,5,5],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"远程机炮","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"","on_hit":"目标受损直到他们下一回合结束。在此期间，若你的目标移动超过 1 空间，他们清除受损但受到 2/3/4 动能伤害。搬运工被摧毁时，此效果立即结束。","id":"npcf_x_sultan_1_1","base":true},{"name":"机械化步兵学说","type":"Trait","tags":[],"effect":"搬运工可以运转一支班组或一些大小相加比自己小的角色。盟友人类和大小 1/2 的机甲可使用搬运工作为硬性掩护，它可以从各个方向为所有邻近班组提供硬性掩护。","id":"npcf_x_sultan_1_2","base":true},{"name":"快速部署","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"选择邻近的一支班组或一些大小相加比自己小的角色，将他们装载到该机甲上。它们和搬运工占据相同空间，且免疫伤害，在机载时不会被攻击或被攻击影响。随后搬运工移动 10空间，忽略交战、反应和困难地形。在该移动结束时，装载的角色自动重新部署到搬运工邻近的空间。","id":"npcf_x_sultan_1_3","base":true}],"optional":[{"name":"烟雾发射器","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_free_action"}],"effect":"射程 5 内创造 1 或 2 个溅射 2 区域。这些区域会持续到搬运工下一回合结束，且该区域所有角色和物品都获得软性掩护。","id":"npcf_x_sultan_1_4","base":false},{"name":"万能钥匙","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"搬运工发射特制突破弹，为盟友角色的移动创造机会。将此视为 5 射程内锥形 3 区域，且不能改变方向。该区域的物品、掩体和地形受到 10/20/30AP 爆炸伤害，该区域的所有角色必须通过机体豁免否则将被击退 2 空间并伏卧。","id":"npcf_x_sultan_1_5","base":false},{"name":"分诊无人机","type":"Reaction","tags":[{"id":"tg_recharge","val":5}],"trigger":"搬运工感应内的生物角色受到攻击命中","effect":"他们在攻击中受到的所有伤害、热度和燃烧获得抗性。然后他们可以在下次攻击时获得重骰，必须接受第二结果。","id":"npcf_x_sultan_1_6","base":false},{"name":"自动榴弹发射器","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"","on_hit":"目标受损直到他们下一回合结束。搬运工自身无法使用该武器。邻近的班组、人类或大小 1/2机甲可使用此武器进行交火。","id":"npcf_x_sultan_1_7","base":false},{"name":"火控交联","type":"Trait","tags":[],"effect":"1/轮，当搬运工攻击命中时，其感应内盟友下次攻击同一目标时+1 准度。1/轮，当搬运工感应内盟友攻击命中时，搬运工对同一目标下次攻击+1 准度。","id":"npcf_x_sultan_1_8","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_2","name":"动员兵","role":"卫兵","role_en":"defender","page":152,"pages":[152],"flavor":"动员兵代表着战场上驾驶员的技能下限。无论是出于爱国主义的期望还是由于专制压迫而被迫服役，他们接受了最低限度的训练，并配备了低质量大规模生产的底盘和武器以节省成本。应征入伍的士兵没有特定的角色或战术专长。他们的存在主要是为了扩充指挥官队伍，通常作为第一波吸收火力，而更熟练更纪律的部队在他们后面推进。","tactics":"动员兵就像“焦油坑”部队，他们投入战斗通过消耗、激怒和以绝对数量优势来困住敌人。炮灰特性允许你让动员兵为更有价值的单位承受打击，而即抛式 PDW，虽然力量不足，但可同时打击多个敌人，散布伤害。惊慌开火还提供了另一种吸引玩家注意力的方法，即通过罚值骚扰他们。别忘了动员兵也可以通过在盟友和敌人之间插入自己打断对手移动，从而牵制减缓向更重要后方单位（如炮兵）前进的对手。","stats":{"hull":[-1,-1,0],"sys":[-1,-1,0],"agi":[-1,-1,0],"eng":[-1,-1,0],"hp":[8,8,8],"armor":[0,0,0],"evasion":[8,9,10],"edef":[8,9,10],"speed":[4,4,4],"size":[0.5,0.5,0.5],"heatcap":[5,5,5],"save":[8,10,12],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1/2 或 1"],"base":[{"name":"即抛式 PDW","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,1,1],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"攻击时：动员兵可选择清空弹匣，射程视为锥形 5，随后必须重新装填才能再次使用。","id":"npcf_x_sultan_2_1","base":true},{"name":"量变产生质变","type":"Trait","tags":[],"effect":"动员兵成对部署。它们都拥有相同的属性和系统，并且当在战斗中被激活时，它们都会在同一个回合中一起行动。动员兵无法使用低等兵，精英，超体或老兵模板，且永远无法获得结构。","id":"npcf_x_sultan_2_2","base":true},{"name":"炮灰","type":"Trait","tags":[],"effect":"当动员兵邻近的盟友角色受到远程或近战攻击时，以一个反应，他们可以被迫承受该攻击。","id":"npcf_x_sultan_2_3","base":true},{"name":"惊慌开火","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"动员兵不顾技术精度疯狂开火，不熟练地为盟友提供火力掩护。选择视线射程 5 内一个敌对角色。该角色在动员兵下一回合结束前所有攻击+1 难度。若动员兵被毁则效果结束。","id":"npcf_x_sultan_2_4","base":true}],"optional":[{"name":"装甲浮士德","type":"System","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"动员兵在射程 10 内发射一枚溅射 1 爆炸弹头引爆。受影响区域内角色必须通过机体豁免否则受到 4/6/8 爆炸伤害并伏卧。","id":"npcf_x_sultan_2_5","base":false},{"name":"生存本能","type":"Trait","tags":[],"effect":"当一对动员兵中任何一个被摧毁时，剩下一个将获得对所有伤害的抗性，直到他们下一回合结束，且可以一个反应进行推进，该移动忽略交战和反应。","id":"npcf_x_sultan_2_6","base":false},{"name":"民兵步枪","type":"Weapon","tags":[{"id":"tg_reliable","val":[1,1,2]}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"该武器系统取代即抛式 PDW。动员兵现在可以对射程 10 内的目标使用恐慌开火了。","id":"npcf_x_sultan_2_7","base":false},{"name":"战斗盾","type":"System","tags":[{"id":"tg_shield"}],"effect":"动员兵开始 HP+2，交战时大小被视为大 1","id":"npcf_x_sultan_2_8","base":false,"bonus":{"hp":2}},{"name":"反装甲高爆炸弹","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_limited","val":1},{"id":"tg_inaccurate"}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Explosive","val":[6,8,10]}],"effect":"","on_hit":"目标缓慢和离散直到他们下一回合结束。动员兵可选择+2 准度代替不准进行攻击，一旦命中自身就会立即被摧毁。","id":"npcf_x_sultan_2_9","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_3","name":"角斗士","role":"卫兵","role_en":"defender","page":154,"pages":[154],"flavor":"角斗士不存在某种标准，他们来自各个天体和竞技场。尽管来源不同，但依然存在一些共同点：底盘坚固耐用，经常从工业和劳作底盘改造而来，添加额外装甲镀层，配备了各种增强近距离作战系统。若被迫服役，角斗士可在前线执行突击/冲击部队的任务，只需进行少量改造和驾驶员再训练，尽管装备可能仍然不太标准化——这些机甲驾驶员往往倾向于特定武器配置而不考虑后勤方面的问题。","tactics":"角斗士是种富有侵略性和破坏性，喜好近距离战和个人战的近战坦克。它的槌拳和液压爪组合能让它在击倒之敌人前将其拖出位置，而它的铁山靠能则能缩小距离并打断玩家移动，若玩家试图绕过它时可作拦截。可选系统中如活塞式压缩长矛和突破钻头让你能够切换角斗士武器，并以各种削弱状态威胁玩家。角斗士以攻为守，并不存在直接保护盟友免受伤害的方法，无论如何拥有远程火力和控制能力的玩家能够自由选择目标。","stats":{"hull":[2,3,4],"sys":[-2,-2,-2],"agi":[-1,-1,-1],"eng":[1,2,3],"hp":[18,20,22],"armor":[2,2,2],"evasion":[8,10,12],"edef":[8,9,10],"speed":[3,3,3],"size":[2,2,2],"heatcap":[8,8,8],"save":[11,13,15],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"槌拳","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"","on_hit":"目标必须通过机体豁免否则伏卧并受损直到他们下一回合结束。","id":"npcf_x_sultan_3_1","base":true},{"name":"液压爪","type":"Trait","tags":[],"effect":"当角斗士擒拿一个角色时，他们可以立即将该角色移动到与其邻近的自由空间。擒拿时，角斗士如常进行反应。","id":"npcf_x_sultan_3_2","base":true},{"name":"铁山靠","type":"Reaction","tags":[{"id":"tg_recharge","val":5}],"trigger":"角斗士视线内一个敌对角色开始移动","effect":"角斗士可迎面移动忽略交战和反应的 6 空间。角斗士必须尽可能在对方邻近位置结束该移动，若是如此触发该反应的角色必须通过机体豁免否则伏卧。","id":"npcf_x_sultan_3_3","base":true}],"optional":[{"name":"地面格斗术","type":"Trait","tags":[],"effect":"当角斗士邻近的角色从伏卧站起来时，可以一个反应立即用槌拳发起攻击。角斗士在每轮中可使用任意次数的该反应。","id":"npcf_x_sultan_3_4","base":false},{"name":"转矩连枷","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"","on_hit":"目标必须通过敏捷豁免否则缓慢直到下一回合结束。","id":"npcf_x_sultan_3_5","base":false},{"name":"突破钻","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_inaccurate"}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[8,10,12]}],"effect":"","on_hit":"目标必须通过机体豁免否则固定和离散直到下一回合结束。该武器对物品、掩体、地形和环境造成 10/15/20 AP 动能伤害。","id":"npcf_x_sultan_3_6","base":false},{"name":"活塞式压缩长矛","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_knockback","val":2},{"id":"tg_accurate"}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[2,3,4]}],"effect":"1/轮，当角斗士或邻近盟友被近战攻击命中时，角斗士或该盟友可获得该攻击所有伤害的抗性。攻击者随后受到 2/3/4AP动能伤害。","id":"npcf_x_sultan_3_7","base":false},{"name":"虽败犹荣","type":"Trait","tags":[],"effect":"当角斗士被摧毁时，他们可以先立即移动速度，然后用自己选择的武器进行攻击。","id":"npcf_x_sultan_3_8","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_4","name":"梦魇","role":"操纵","role_en":"controller","page":156,"pages":[156],"flavor":"当代战术理论中有个更令人不安的发展乃是反认知/神经危险武器的兴起，即所谓本体论战争。该种武器使用即使不完全禁止也常受到严格管制，它对生物和无机大脑产生典型非人道影响，但对于愿无视这些公约的指挥官来说，应用于恐怖分子的战略利益可轻松凌驾任何道德担忧。这些梦魇骨架的驾驶员将定期接受心理异常以及超分形神经诱发的枕叶硬化和慢性模因脑病的发作迹象筛查。","tactics":"梦魇是善于摆布他人的控制手，迫使玩家做出艰难决定。神游状态以及可选的解放和厄菲阿尔特应变系统让玩家陷入选择承受何种削弱后果的两难境地，而麻痹印迹的削弱效果即使被盟友迅速治疗也会持续存在。虽然最显而易见的解决方案是直接摧毁梦魇，但它的内置蛇怪会折磨那些过于关注它的玩家。","stats":{"hull":[0,0,0],"sys":[2,4,6],"agi":[1,2,3],"eng":[-1,-1,-1],"hp":[14,16,16],"armor":[0,0,0],"evasion":[8,9,10],"edef":[12,14,16],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,8],"save":[12,15,18],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"神游状态","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"目标受到 3/4/5 热度，梦魇可立即使目标朝自己选择的方向移动速度空间。目标可选择忽略该移动，若如此他们会缓慢且无法进行反应直到他们下一回合结束。","id":"npcf_x_sultan_4_1","base":true},{"name":"麻痹印迹","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"目标固定直到下一回合结束。一旦目标不再固定，他们必须通过系统豁免否则受损和缓慢直到他们下一回合结束。","id":"npcf_x_sultan_4_2","base":true},{"name":"内置蛇怪","type":"Trait","tags":[],"effect":"若角色在他们回合中对梦魇进行的第一次攻击骰失败，他们将自动受损直到他们下一回合结束。","id":"npcf_x_sultan_4_3","base":true}],"optional":[{"name":"杏仁体荆棘","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":6}],"tech_type":"Quick","effect":"所有爆发 2 内的敌对角色必须通过系统豁免否则立即使用他们的反应在本回合移动等同速度的距离，尽可能远离梦魇。","id":"npcf_x_sultan_4_4","base":false},{"name":"解放","type":"Tech","tags":[{"id":"tg_full_tech"},{"id":"tg_limited","val":1}],"tech_type":"Full","effect":"梦魇在感应内选择一个敌对角色并迫使其立即使用其反应移动等同他们速度的距离并使用最多两件武器去攻击射程内的角色。梦魇选择移动的方向，使用的武器和所有目标。若目标装备了任何 AI 系统，这些攻击会获得+1 准度。角色可以选择晕眩直至下一回合结束而忽略该效果。","id":"npcf_x_sultan_4_5","base":false},{"name":"厄菲阿尔特应变","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"目标感染本体论病毒，该病毒持续到场景结束。他们在所有攻击骰上+1 难度，每次失败的攻击都会受到 2/3/4 热度。他们可以通过快速动作进行+1 难度的系统豁免，或者使用权宜攻击或自己选择的武器攻击盟友角色来清除感染。此攻击+1 准度取代+1 难度。同一时间只有一个目标可被此病毒感染。","id":"npcf_x_sultan_4_6","base":false},{"name":"磁感魔爪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","on_hit":"梦魇在邻近该目标使用科技攻击时+1 准度和+2 热度。","id":"npcf_x_sultan_4_7","base":false},{"name":"辐射萨诺塔编码","type":"Trait","tags":[],"effect":"当梦魇被摧毁时，它将创造一个持续到场景结束的爆发 2 区域。敌方角色在他们回合中第一次进入该区域或者在该地区开始其回合，则必须通过系统豁免否则受到 3/4/5 热度。","id":"npcf_x_sultan_4_8","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_5","name":"食人魔","role":"突击","role_en":"striker","page":158,"pages":[158,159],"flavor":"即便在近战专家中，食人魔学说底盘也是种极为罕见的设计，它完全舍弃武器，而选择了一种更基本更残酷的战争形式——利用强化控制器和动力手甲赤手空拳地击打对手。虽然其军备看似简单，但许多食人魔驾驶员使用的却是精密老练的技术，从传统非武装武术到街头格斗和角斗运动，他们的底盘也同样通过各种系统和改造来加强这些非传统战术，如反射/反应模块，强化四肢和关节，增强骨架力量套件。与其他近战核心理论相比，食人魔在当代军事部队构成中占据着尴尬的位置，因此更倾向于在特殊任务中使用，如在高度不稳定的环境中战斗或其他不允许或不可能使用武器的战场中，尽管其同意频繁出现在某些军事文化中，在战斗竞技场中，以及在非标准部队如海盗或雇佣兵的行列中。","tactics":"食人魔是重视连击的前锋，使用其冲击手甲和其他近战攻击组合在一起。其流星冲拳能力可迅速冲到对手脸上，随后进行一串可选的连击反应动作如上勾拳或反手猛击来加强其打击。食人魔最大缺点是需要与敌人面对面接触，并且依赖于能够使用的反应。缓慢或固定等状态可阻止它拉近距离，而远程攻击可以在它逼近前消耗它一番。","stats":{"hull":[4,5,6],"sys":[-2,-2,-2],"agi":[1,2,3],"eng":[0,0,0],"hp":[18,21,24],"armor":[2,2,2],"evasion":[10,12,14],"edef":[7,8,9],"speed":[4,4,4],"size":[1,1,1],"heatcap":[6,6,6],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"冲击手甲","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"该武器可在受扰下使用，当它被摧毁时食人魔立即受损直到他下一回合结束。","id":"npcf_x_sultan_5_1","base":true},{"name":"流星拳","type":"Trait","tags":[],"effect":"当食人魔进行近战攻击时，可以在攻击前直线向目标角色飞行 3 空间。该移动忽略交战与反应。","id":"npcf_x_sultan_5_2","base":true},{"name":"上勾拳","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"食人魔用近战攻击命中。","effect":"目标必须通过机体豁免否则被击退 3 空间并伏卧。成功则被击退 1 空间且保持站立。随后食人魔通过直接路线向目标移动相同数量的空间。","id":"npcf_x_sultan_5_3","base":true},{"name":"反手猛击","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"食人魔用近战攻击命中。","effect":"与食人魔邻近的不同目标受到 3/4/5 动能伤害，必须通过敏捷豁免否则受损直到他们下一回合结束。","id":"npcf_x_sultan_5_4","base":true},{"name":"混战","type":"Trait","tags":[],"effect":"在擒拿中，食人魔可推进并且进行反应。","id":"npcf_x_sultan_5_5","base":true}],"optional":[{"name":"报复","type":"Trait","tags":[],"effect":"每当食人魔受到伤害时，其下次攻击造成+2/+3/+4 额外伤害。该额外伤害最多可叠加至+8。当食人魔攻击或在下一回合结束时，该额外伤害将会丢失。","id":"npcf_x_sultan_5_6","base":false},{"name":"机枪肘击","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"食人魔用近战攻击命中。","effect":"食人魔可移动最多 3 空间，忽略交战与反应，然后对爆发 1 区域内的所有角色进行一次+1/+2/+3 掷骰的近战攻击。命中则目标受到 3/4/5 动能伤害。","id":"npcf_x_sultan_5_7","base":false},{"name":"反击架势","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"食人魔用近战攻击命中。","effect":"在食人魔下一回合开始前，他们将获得对近战攻击伤害的抗性，或攻击者可选择在掷骰前受到 4/6/8 动能伤害。","id":"npcf_x_sultan_5_8","base":false},{"name":"打桩机震荡波","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"食人魔飞行 5 空间，它必须在该移动结束时落地否则坠落。随后他们在落地时制造一个爆发 2 区域。该区域除了飞行角色之外的所有角色必须通过敏捷豁免，否则受到 4/6/8 动能伤害并伏卧。","id":"npcf_x_sultan_5_9","base":false},{"name":"灾厄投掷","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"食人魔选择一个邻近角色并强迫他们通过机体豁免。若豁免成功，则他们会被食人魔擒拿并受到 4/5/6 动能伤害。若他们豁免失败，食人魔就会抓起他们，以令人难以置信的狂放将他们丢出去。目标在食人魔选择的方向击退 5 空间，受到8/10/12 动能伤害并伏卧。若他们与另一个角色碰撞，该角色必须通过机体豁免否则受到一半伤害同时也被伏卧；若他们与一个物品，可展开，或一块地形碰撞，则这些被碰撞的物品会受到 10/20/30 AP 动能伤害。","id":"npcf_x_sultan_5_10","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_6","name":"幻影","role":"突击","role_en":"striker","page":160,"pages":[160,161],"flavor":"幻影学说底盘基于在战斗中使用的非因果律技术，采用了特殊系统让驾驶员能够让他们的机甲与本地现实·异步，在研究人员称之为“天穹”所在上下浮动。这让幻影获得了种能从不可能的途径穿过固体物品跟踪对手然后重新显现施以进攻的无敌能力。该平台的驾驶员通常会因其精神坚韧和战斗技能而被选中，经常使用战术相位驱动技术会对心理造成很大负担。","tactics":"幻影是拥有双重形态的暗杀者，其独特的相位发生器使其能够穿过障碍物甚至是其他机甲，从意想不到的角度接近目标，为它们的攻击做好准备。相位状态的幻影能够将受到的伤害降低为零，而当它返回现世时，其相位利刃就会变超负荷运转，让玩家陷入两难境地——他们是花时间和精力试图让幻影过热并让它尽早脱离相位状态好呢，还是冒着让它先发制人的风险等待它自己出现好？","stats":{"hull":[-1,-1,-1],"sys":[0,0,0],"agi":[2,3,4],"eng":[1,2,3],"hp":[14,14,14],"armor":[0,0,0],"evasion":[10,12,14],"edef":[7,8,9],"speed":[6,6,6],"size":[0.5,0.5,0.5],"heatcap":[7,7,7],"save":[10,12,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1/2 或 1","1/2 或 1","1/2 或 1"],"base":[{"name":"相位利刃","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_accurate"}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Energy","val":[4,6,8]}],"effect":"当幻影激活其相位发生器时，该武器将充满破坏性能量并在下次攻击时对命中目标造成 8/12/16 能量伤害。该攻击伤害无法以任意方式降低。","id":"npcf_x_sultan_6_1","base":true},{"name":"相位发生器","type":"System","tags":[{"id":"tg_protocol"}],"effect":"当该系统被激活时，幻影会转变相位化为无形，但其不完善的相位技术意味着他们仍然可成为科技攻击的目标。幻影可以协定结束该效果。若幻影过热，该系统将被关闭直到他们下一回合结束，其效果立即结束。","id":"npcf_x_sultan_6_2","base":true},{"name":"滑行迂回","type":"Trait","tags":[],"effect":"幻影以一个反应能够对所有攻击获得抗性。","id":"npcf_x_sultan_6_3","base":true},{"name":"畸变脉冲","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"该能力只在幻影无形时可用。幻影在感应围内制造一个爆发 1的空间畸变，将其同时视为对无形和有形角色的困难地形。当幻影以协定关闭相位发生器时，畸变会剧烈内爆，区域内所有其他角色，无论无形还是有形，都必须通过系统豁免否则受到2/3/4 热度并伏卧。同一时间只能有一个畸变被激活，若另一个被激活则代替旧的那个。","id":"npcf_x_sultan_6_4","base":true}],"optional":[{"name":"壳中幽灵","type":"Trait","tags":[],"effect":"1/轮，当相位发生器激活时，幻影可选择一个移动穿过的有形角色。该角色必须通过工程豁免否则受到 2/3/4 热度并缓慢直到他们下一回合结束。","id":"npcf_x_sultan_6_5","base":false},{"name":"空间分离","type":"Trait","tags":[],"effect":"当幻影以协定关闭相位发生器时，可瞬间移动 3 空间。","id":"npcf_x_sultan_6_6","base":false},{"name":"零向量驱动","type":"System","tags":[],"effect":"当相位发生器激活时，幻影在标准移动或推进时获得悬浮飞行。若幻影在半空中时相位发生器失效，则会立即坠落。","id":"npcf_x_sultan_6_7","base":false},{"name":"幽影刀","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":3}],"effect":"消耗 1 充能向射程 3 内角色投掷相动刀，进行+2/+4/+6 的远程攻击。命中的目标受到 4/6/8AP 动能伤害并变为无形直到他们下一回合结束。","id":"npcf_x_sultan_6_8","base":false},{"name":"相位开膛手","type":"Trait","tags":[],"effect":"当充能的相位利刃成功命中目标时，目标会根据幻影选择方向瞬间移动 3 空间。若该空间被另一角色占据，该角色必须通过工程豁免否则受到 4/5/6 动能伤害并且离散直至他们下一回合结束。然后将目标放置在与该角色最近邻近的的自由空间中。","id":"npcf_x_sultan_6_9","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_7","name":"收割者","role":"卫兵","role_en":"defender","page":162,"pages":[162,163],"flavor":"收割者底盘即使是那些与并肩作战者也常被怀疑和不信任，许多驾驶员都听说过猖獗的灰浴虫群会毫不犹豫吞食天地的可怖故事。尽管纳米武器当之无愧地有着令人恐惧的名声，但这些骨架常会对嵌入其中的纳米虫巢保持严格操作保障，将它们转向局部区域防御应用，以及增强的耐用性和自我修复功能，但不止一个驾驶员发现这“驯服”的纳米体可能和它们更具侵略性的武器化同类一样危险。","tactics":"收割者是款具有控制能力的坚韧坦克，无论它去往哪里，都会在周围创造一个伤害和致残尾随其后之敌的区域。虽然移动缓慢，但它的位移鞭可以用来将敌人拖进军团之躯区域，逐渐侵蚀他们的生命值并阻碍他们的逃跑能力。虽然收割者没有装甲，但它的高血量和再生意味着若不集火它会措施良机，但一旦它受到足量的伤害时就会触发它的遏制缺口特征，它周围的区域会越发危险，而迅速摧毁它的优先级将会变得很高。","stats":{"hull":[2,3,4],"sys":[1,2,3],"agi":[-1,-1,-1],"eng":[-1,-1,-1],"hp":[20,24,28],"armor":[0,0,0],"evasion":[6,7,8],"edef":[10,12,14],"speed":[3,3,3],"size":[2,2,2],"heatcap":[6,6,6],"save":[11,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"位移鞭","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":3}],"damage":[{"type":"Energy","val":[4,4,4]}],"effect":"收割者使用该武器时可攻击视线威胁内一个或两个目标。命中的目标必须通过系统豁免否则被拉到收割者邻近的自由空间或尽可能靠近的位置。","id":"npcf_x_sultan_7_1","base":true},{"name":"重型骨架","type":"Trait","tags":[],"effect":"比收割者小的角色无法将其推动、拉动、伏卧或击退。","id":"npcf_x_sultan_7_2","base":true},{"name":"军团之躯","type":"Trait","tags":[],"effect":"收割者回合结束时恢复 1/4 总 HP。若其在同一轮中受到燃烧伤害则无法恢复任何 HP。收割者被爆发 2 的成群纳米体包围，它们会跟随收割者的一举一动。此区域开始其回合的敌对角色会受到 3/4/5AP 动能伤害，并必须通过工程豁免否则缓慢直到他们下一回合结束。当一个收割者在一个场景中第一次被减少到其结构一半以下（若其只有单个结构，则改为减少到其最大 HP 一半以下），该特征就会被永久关闭。","id":"npcf_x_sultan_7_3","base":true},{"name":"遏制缺口","type":"Trait","tags":[],"effect":"该特征只有在军团之躯被永久关闭时才会被激活。战斗伤害致使收割者纳米虫群开始在不可控制的疯狂中吞噬周边一切，创造出一个新的爆发 2 区域。此区域开始其回合的敌对角色会受到 3/4/5 燃烧伤害，并且必须通过工程豁免否则缓慢并且他们获得所有 HP 或护盾的增益降低一半直到他们下一回合结束。豁免成功则不会缓慢。","id":"npcf_x_sultan_7_4","base":true}],"optional":[{"name":"面纱虫巢","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"收割者的军团之躯和/或遏制缺口特征所创造的区域也可作为盟友角色的软性掩护。","id":"npcf_x_sultan_7_5","base":false},{"name":"同类相食","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":6}],"effect":"收割者的军团之躯和/或遏制缺口区域内选择一个至少有 1 维修上限的角色。该角色失去 1 维修，收割者恢复 5/7/9HP，并清除其选择的一个状态。","id":"npcf_x_sultan_7_6","base":false},{"name":"灰浴涂层","type":"Trait","tags":[],"effect":"1/轮，当收割者被远程或近战攻击命中时，射程 3 内的单个角色受到 2/3/4 燃烧伤害。","id":"npcf_x_sultan_7_7","base":false},{"name":"集中散布","type":"System","tags":[{"id":"tg_full_action"}],"effect":"收割者在下一回合结束前会被固定，但其军团之躯和/或遏制缺口区域会变成任何方向的锥形 5 区域。","id":"npcf_x_sultan_7_8","base":false},{"name":"残存虫群","type":"Trait","tags":[],"effect":"被摧毁的收割者熔毁成一团翻涌的灰浴。将收割者从游戏中移除，并在最近的自由空间中替换为溅射 1 区域，该区域持续到场景结束。该区域可与其他单位重叠，被视为困难地形，任何角色在其回合中首次进入该区域或开始其回合则受到2/3/4 AP 动能伤害。在每轮开始时，该区域可向任何方向移动最多 3 空间。","id":"npcf_x_sultan_7_9","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_8","name":"军士","role":"支援","role_en":"support","page":164,"pages":[164],"flavor":"班级战术指挥官是战区战略行动指挥链的重要一环。一名熟练班长通常从士兵军衔中通过领导能力和战场能力晋升，能够通过激励手段大幅提高既定单位的作战操作指标。相关底盘通常基于前线突击型，增强在战术交战期间不间断实时协调的通信和 ECM 能力。","tactics":"军士是直接严肃的支援单位，它增强感应内盟友，作为战术阵型的核心。玩家可能会想集火军士，让其尽早退出战斗，所以用防御单位来遮蔽他们，让他们处于可安全地执行班组领袖和协同机动，以建立攻击的进攻是关键。协同机动也可以用于防御，让盟友单位有机会撤退或搬离危险区域。就其本身而言，军士并非是特别强大的战斗人员，若被迫进入直接战斗其选择非常有限。","stats":{"hull":[1,2,3],"sys":[2,3,4],"agi":[0,0,0],"eng":[0,0,0],"hp":[15,17,19],"armor":[1,1,1],"evasion":[8,9,10],"edef":[10,12,14],"speed":[4,4,4],"size":[1,1,1],"heatcap":[10,10,10],"save":[10,12,14],"sensor":[10,10,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"突击卡宾枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"在使用该武器攻击前或后（包括作为反应），军士可移动 2空间。该移动忽略交战与反应。","id":"npcf_x_sultan_8_1","base":true},{"name":"班组领袖","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"1/轮，若军士未受扰则可在感应内选择一或两个盟友角色。在他们下一回合结束前，这些盟友下一次攻击+1 准度，或者他们下一次造成的豁免+1 难度。在任何既定场景中，不能超过一个军士。","id":"npcf_x_sultan_8_2","base":true},{"name":"协同机动","type":"Trait","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"在军士感应内选择一或两个盟友角色。这些盟友可向任意方向移动 3 空间，忽略交战与反应。","id":"npcf_x_sultan_8_3","base":true}],"optional":[{"name":"五轮急速","type":"Trait","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":6}],"effect":"在军士感应内选择一或两个本轮尚未行动的盟友角色。以一个反应，军士和那些盟友可立即按任意顺序发起交火。随后这些盟友单位被视为在该轮中已经进行过回合。","id":"npcf_x_sultan_8_4","base":false},{"name":"伏击战术","type":"Trait","tags":[{"id":"tg_full_action"},{"id":"tg_limited","val":1}],"effect":"你可以立即在军士感应内任意自由空间放置最多 4 个低等兵到战场。这些低等兵可立即发挥作用，在他们该轮中进行动作，但只有在所有其他回合进行后进行。","id":"npcf_x_sultan_8_5","base":false},{"name":"大肆吹捧","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"在军士感应内选择一个盟友角色。该单位在下一次远程或近战攻击中造成+1d6 额外伤害。","id":"npcf_x_sultan_8_6","base":false},{"name":"大地惊雷","type":"Reaction","tags":[{"id":"tg_recharge","val":6}],"trigger":"在军事感应内一个盟友角色降低到 0HP。","effect":"改为降低到 1HP。","id":"npcf_x_sultan_8_7","base":false},{"name":"地狱之爪","type":"Trait","tags":[],"effect":"1/轮，每当一个盟友角色被摧毁，军士和军士感应内所有其他盟友角色的下次攻击+1 准度。","id":"npcf_x_sultan_8_8","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_9","name":"白蚁","role":"操纵","role_en":"controller","page":166,"pages":[166,167],"flavor":"所谓的白蚁学说底盘便是充当前线作战的工程师，白蚁常在主要突击部队前有序移动，清除障碍，并为盟军部队开辟临时通道。白蚁常被组织成“老鼠洞”小队，其紧凑耐用的结构非常适合在密集建造城市战区作战，利用一套强大的拆除工具来突破甚至是极为坚固的建筑，摧毁固定炮台，扰乱敌人在战场上的机动。尽管白蚁驾驶员在这些任务中表现出色，但众所周知，他们在操作时往往会公然无视可接受的附带伤害限制，其部署也往往会相应地分配。","tactics":"白蚁是爆炸物控制者，能够轻松地在战场上开辟道路，创造自己的侧翼路线和阻塞点。它的镭射钻和弹坑炸药能它在短时间内完成建筑任务，它还能创造出一些地形复杂区域来减缓玩家速度或迫使他们选择另一条道路。白蚁最适合在有大量建筑和地形的地图上工作，他们的系统在更开放的环境中可能不太有用。许多白蚁系统距离相对较短，这迫使他们为了部署炸药包，震荡榴弹，或者用粘滞分离枪创造危险区域而不得不靠近行动，但若玩家允许他们靠近就会造成惊人伤害。","stats":{"hull":[1,2,3],"sys":[-2,-2,-2],"agi":[-1,-1,-1],"eng":[2,3,4],"hp":[8,10,12],"armor":[2,2,3],"evasion":[7,8,9],"edef":[8,10,12],"speed":[5,5,5],"size":[0.5,0.5,0.5],"heatcap":[7,7,7],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"镭射钻","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Line","val":5}],"damage":[{"type":"Energy","val":[3,3,3]},{"type":"Burn","val":[2,3,4]}],"effect":"攻击时：该武器自动对其区域内所有掩体、地形、物品和可展开物品造成 10/20/30 AP 能量伤害。","id":"npcf_x_sultan_9_1","base":true},{"name":"弹坑炸药","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"射程 5 内制造溅射 1 区域。该区域内所有掩体、地形、物品和可展开物品受到 10/20/30AP 爆炸伤害，该区域内所有角色必须通过敏捷豁免否则受到 4/6/8 爆炸伤害并且伏伏卧，成功则伤害减半并且保持站立。该区域变为 1 空间深的坑，直至场景结束前该区域为困难地形。","id":"npcf_x_sultan_9_2","base":true},{"name":"堡垒模块","type":"Trait","tags":[],"effect":"白蚁忽略困难和危险地形。","id":"npcf_x_sultan_9_3","base":true},{"name":"爆破镀层","type":"Trait","tags":[],"effect":"白蚁具有对爆炸伤害的抗性。","id":"npcf_x_sultan_9_4","base":true}],"optional":[{"name":"震荡榴弹","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"在射程 5 内制造溅射 1 区域。该区域内所有角色必须通过机体豁免否则会被从爆炸中心击退 2 空间并受损直到下一回合结束。","id":"npcf_x_sultan_9_5","base":false},{"name":"粘滞分离枪","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"在射程 5 内制造溅射 1 区域。场景结束前该区域为困难地形。以一个快速动作，白蚁可引爆该区域，使其地形恢复正常并且该区域所有角色必须通过敏捷豁免否则受到 3/4/5 燃烧伤害。","id":"npcf_x_sultan_9_6","base":false},{"name":"热烟","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"在射程 5 内制造溅射 2 区域。除白蚁外所有角色无法进入或离开该区域的视线。部分在该区域的角色对区域内外的角色仍有视线。除白蚁外任意角色在其回合中第一次进入该区域或开始其回合将受到 2/3/4 热度。该效果持续到白蚁下一回合结束，或者直到白蚁再次使用该系统。","id":"npcf_x_sultan_9_7","base":false},{"name":"反应装甲","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"白蚁被近战攻击命中","effect":"白蚁对该攻击所有伤害获得抗性，然后攻击者必须通过机体豁免否则直接远离白蚁击退 2 空间并伏卧。","id":"npcf_x_sultan_9_8","base":false},{"name":"炸药包","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"白蚁可在射程 3 内自由空间部署该炸药，或他们可针对射程3 内的角色进行+1/+2/+3 远程攻击将炸药附着在该角色身上。当被部署到一个自由空间时，白蚁可以协定引爆这该炸药，对一个爆发 1 区域内的掩体、地形、物品和可展开物品造成 10/20/30 AP 爆炸伤害，并迫使该区域内所有角色通过敏捷豁免否则受到 8/10/12 爆炸伤害。豁免成功则伤害减半。当附着在角色身上时，该炸药会在他们下一回合结束时自动引爆，取代所列伤害效果的爆发 1 区域。任何被炸药附着的角色豁免自动失败同时离散直到他们下一回合结束。","id":"npcf_x_sultan_9_9","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_10","name":"泰坦","role":"炮击","role_en":"artillery","page":168,"pages":[168,169],"flavor":"与其说泰坦是实际军事学说的一个例子，不如说它是一种象征，它的设计目的是在敌人心中制造恐惧，并在战场上缓慢推进时激励盟友。即使是专用的攻城底盘，通常（虽然不总是）都是四足或六足设计，遍布重型武器和坚固装甲，泰坦的巨大尺寸本身就是一种武器，但它笨重性质和高昂成本致使众多指挥官认为它不过是种不切实际的“奇迹武器”，用来给将军们留下深刻印象和满足政客们的自负。尽管如此，泰坦级平台部署时的战斗数据记录显示，敌方在所有战区的兵力消耗比例异常高。","tactics":"泰坦是种高耸的超重型火炮步行者，其庞大和无情使其成为戏剧性定位遭遇战的理想选择。火控连接电池在泰坦周围设置了一圈玩家可加以利用的死角，但这样做的风险是，泰坦可能会以不可阻挡的力量从他们身上碾过。关于泰坦需要注意的重要一点是它的二次伤害特性，它与其众多武器和系统相互作用，以多种方式改变战场或影响它的功能。因此，与其他 NPC 相比，该型运行需要更多的心思，而且它可能比其他 NPC 更强大。当你建造以泰坦为特色的遭遇时，你应注意不要让自己背上太多移动部件的负担。","stats":{"hull":[3,4,6],"sys":[0,0,0],"agi":[-3,-3,-3],"eng":[2,3,4],"hp":[25,30,35],"armor":[2,3,4],"evasion":[6,6,6],"edef":[8,11,14],"speed":[2,2,2],"size":[4,4,4],"heatcap":[12,12,12],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"火控连接电池","type":"Weapon","tags":[],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":20}],"damage":[{"type":"Explosive","val":[8,10,12]}],"effect":"该武器攻击时可以一或两个目标。该武器无法对泰坦射程 3内或更近的目标开火。该武器第一次被摧毁时，将它可攻击的目标数量减少到一个。","id":"npcf_x_sultan_10_1","base":true},{"name":"超级武器","type":"Trait","tags":[],"effect":"泰坦无法使用低等兵模板，在任意场景中只能出现一个泰坦。","id":"npcf_x_sultan_10_2","base":true},{"name":"无坚不摧之力","type":"Trait","tags":[],"effect":"泰坦忽略困难地形，比泰坦小的角色无法将其推动、拉动、伏卧或击退，并且可以自由占据包含其他角色的空间。当泰坦在回合中第一次移动到敌方角色所占据的空间时，该角色必须通过敏捷豁免否则受到 4/6/8 动能伤害并伏卧。","id":"npcf_x_sultan_10_3","base":true},{"name":"二次伤害","type":"Trait","tags":[],"effect":"泰坦不会一开始就激活该特征。当泰坦在一个场景中第一次被减少到其结构一半以下（若其只有单个结构，则改为减少到其最大 HP 一半以下），该特征就会激活并变得明显不稳定致使二次爆炸和伤害警报。在泰坦下一回合开始时，所有爆发 3内角色必须通过敏捷豁免否则受到 6/8/10 爆炸伤害并被击退 3 空间。豁免成功则伤害减半并击退 1 空间。","id":"npcf_x_sultan_10_4","base":true},{"name":"天命护盾","type":"Reaction","tags":[{"id":"tg_recharge","val":6}],"trigger":"泰坦受到射程 3 以外的攻击命中","effect":"泰坦对此次攻击造成的所有伤害获得抗性。当二次伤害特征第一次被激活时，该系统会自动再充能。","id":"npcf_x_sultan_10_5","base":true}],"optional":[{"name":"脊柱光矛","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_loading"},{"id":"tg_ordnance"}],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Line","val":20}],"damage":[{"type":"Energy","val":[10,15,20]}],"effect":"该武器取代火控连接电池，并且无法对泰坦射程 3 内或更近的目标开火。该武器所在区域的任何物品、掩体或地形都会立即被摧毁，受到该攻击的任何角色都必须通过工程豁免否则受损与离散直到他们下一回合结束。当二级伤害激活时，该武器会失去装填，但泰坦每次开火都会受到 1d6+1 热度。","id":"npcf_x_sultan_10_6","base":false},{"name":"弹射平台","type":"Trait","tags":[],"effect":"泰坦可作为众多机甲的载体平台，只需这些机甲大小总和比泰坦小。盟友机甲可在泰坦上开始战斗，也可以在靠近泰坦时通过快速动作与之对接。当他们对接在泰坦上时获得软性掩护，与泰坦占据相同空间并随泰坦移动，忽略交战与反应。泰坦携带的机甲可以标准移动的方式离开载具，或者他们可以协定弹射自己，移动等同其速度的距离并且其下一次远程或近战攻击+1 准度。当第一次激活二次伤害特征时，泰坦身上的所有机甲都会受到 5AP 爆炸伤害，并可用一个反应立即从它身上弹射。","id":"npcf_x_sultan_10_7","base":false},{"name":"无畏级","type":"Trait","tags":[],"effect":"泰坦获得缓慢免疫，无论何时移动或推进，他们都可穿过环境中的建筑、物品和其他障碍物，无论其大小。任何以该方式移动通过的障碍都将被摧毁，并成为困难地形。当二次伤害特征激活时，泰坦速度变为 4，但每当他们以该种方式通过障碍物时就会受损直到他们下一回合结束。","id":"npcf_x_sultan_10_8","base":false},{"name":"点式防御阵列","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,4,4]}],"effect":"层级 2：该武器可一次进行两次攻击，目标可以是同一角色，也可以是两个不同角色。层级 3：它可以同时发起三次攻击。当二次伤害特征激活，泰坦回合结束时，他们必须以自由动作使用该武器攻击距离最近角色，不管敌友。","id":"npcf_x_sultan_10_9","base":false},{"name":"围护构型","type":"Trait","tags":[],"effect":"盟友角色可以泰坦为硬性掩护。二次伤害特征激活时，禁用该特征，并在泰坦射程 3 范选择两个自由空间，然后选择一名玩家在泰坦射程 3 内选择两个自由空间。从泰坦底盘上炸落的大块装甲和碎片坠落在那里，成为大小 1 的障碍物，到场景结束前提供硬性掩护。","id":"npcf_x_sultan_10_10","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_sultan_11","name":"女武神","role":"突击","role_en":"striker","page":170,"pages":[170],"flavor":"女武神学说不寻常地混合了几种现有底盘设计，以实现这独特的战场职责，这是台快速机动的空中近距离作战平台，它能够绕过坚固前线防御，寻找高价值的目标如炮兵部队，野战指挥官和电子战平台，以快速游击模式使敌人迷失方向和压力倍增。其设计适合高级飞行和近战骨架的苛刻工程要求使得女武神没有得到量产，经常带领被指派的驾驶员在更传统的军事等级体系内形成紧密而排外的圈子。","tactics":"女武神是种高机动性的突击手，非常适合游击战术。悬浮飞行和纳米碳戟的巨大威胁让它可以绕过前线防御者而不与交战或反应发生冲突，然后通过空袭，它可以同时攻击和变换阵地，为此后攻击做好准备，并将玩家的注意力引向多个方向。若女武神降落，那么其战斗力就会大打折扣。","stats":{"hull":[-1,-1,-1],"sys":[0,0,0],"agi":[3,4,6],"eng":[2,3,4],"hp":[14,14,14],"armor":[0,0,0],"evasion":[12,14,16],"edef":[7,8,9],"speed":[6,6,8],"size":[1,1,1],"heatcap":[7,7,7],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"纳米碳戟","type":"Weapon","tags":[{"id":"tg_accurate"},{"id":"tg_knockback","val":1}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[7,7,7]}],"effect":"层级 2：该武器可一次进行两次攻击，目标可以是同一角色，也可以是两个不同角色。层级 3：它可以同时发起三次攻击。","id":"npcf_x_sultan_11_1","base":true},{"name":"SSC 总套组","type":"Trait","tags":[],"effect":"女武神可在移动或推进时悬浮。","id":"npcf_x_sultan_11_2","base":true},{"name":"空袭","type":"Trait","tags":[],"effect":"1/轮，当女武神在推进过程中攻击目标时，该角色必须通过机体豁免否则伏卧。当女武神在推进并且分裂其移动中使用纳米碳戟攻击，则可以在该移动过程中的任何时点自由地在目标之间分配攻击。女武神必须在飞行才能使用特征。","id":"npcf_x_sultan_11_3","base":true}],"optional":[{"name":"烧竭推进装置","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":1}],"effect":"女武神可推进 20 空间。该移动忽略交战，不会引起反应攻击。女武神必须在飞行才能使用该系统。","id":"npcf_x_sultan_11_4","base":false},{"name":"萤火虫微型导弹","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"爆发 2 内的所有角色必须通过敏捷豁免否则受到 4/6/8 爆炸伤害，+2/3/4 热度并缓慢直到他们下一回合结束。豁免成功则伤害和热度减半，且不会缓慢。","id":"npcf_x_sultan_11_5","base":false},{"name":"闪盲光环","type":"Reaction","tags":[{"id":"tg_recharge","val":6}],"trigger":"一个敌对角色移动到女武神邻近位置","effect":"其必须通过系统豁免否则受扰直到他们下一回合结束。","id":"npcf_x_sultan_11_6","base":false},{"name":"箔条发射器","type":"Trait","tags":[],"effect":"女武神推进后将视为处于软性掩护中直到下一回合结束。","id":"npcf_x_sultan_11_7","base":false},{"name":"机动推进器","type":"System","tags":[{"id":"tg_free_action"}],"effect":"1/轮，作为一个自由动作，女武神可向任意方向移动 2 空间。该移动忽略交战，并不会引起反应攻击。女武神必须在飞行才能使用特征。","id":"npcf_x_sultan_11_8","base":false}],"pack":"苏丹","source":12},{"id":"npcc_x_cca_1","name":"武库","role":"突击","role_en":"striker","page":42,"pages":[42,43],"flavor":"战争是在安静紧张的房间里，通过无线电收发和数据广播进行。它们被写在干巴巴的纸上，是战战兢兢、得意洋洋、心惊胆战，口耳相传。它们是由钢铁、碳纤维和陶瓷板以及机械手中高口径死亡利器进行战斗并取得胜利——多么诚惶诚恐，多么骇人听闻——它把灵魂从肉体中切分，将士兵度为冠予火药王冠的神明。机器有千般面容，未来只会有更多，每张面容都有不同，每张面容都毛骨悚然地，不无不同。这样一来，战争便也迷失了方向。","tactics":"武库是个坚韧且自给自足的对手，随玩家击落其设备，它会变得更快更具侵略性，也更脆弱。它有一系列非常宽泛的系统可供使用，但一次只能访问数个，玩家可从战术上选择要降级的装置系统，以防止危险效果重叠。","stats":{"hull":[2,4,6],"sys":[0,0,0],"agi":[1,2,3],"eng":[0,0,0],"hp":[15,20,25],"armor":[0,0,0],"evasion":[8,9,10],"edef":[8,9,10],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"特殊规则","type":"Trait","tags":[],"effect":"武库核心由多层模块化系统和即抛式装甲保护，以带有装置X 标签的系统和武器为代表。可减少对核心造成的伤害，等同武库装置总量，最小为 1。该减免无法忽略，武库也无法获取将其装置总值提高到 25 以上的系统。当一个角色对武库造成伤害时，该角色可选择直击装置而非核心骨架（其实际 HP）。它的装置，无论总值如何，均为 4HP。当该 HP 减少至 0 时，攻击者选择一件装置武器或系统降级到其下一级别，降低其整体装置值并改变其效果。任何过量伤害都会溢出到核心，并如常减免，然后装置 HP 重置为 4，若装置武器或系统被摧毁，然后进行修复，它只能修复至被摧毁时的级别，无法修复到更高级别。被摧毁的装置武器和系统并非有效降级目标。玩家知晓所有装置系统当前级别的数据。","id":"npcf_x_cca_1_1","base":true},{"name":"标志性","type":"Trait","tags":[],"effect":"一个场景中只能出现一个具有此特征的 NPC。武库必须始终采用精英或超体模板。若它采用超体模板，它还获得了无畏级基础系统。","id":"npcf_x_cca_1_2","base":true},{"name":"超压材料覆层","type":"System","tags":[],"keywords":["装置 5"],"effect":"1. 反应镀层（装置 5）：武库无法被被小于自身的角色推、拉、击退或伏卧。当它被射程 3 内角色攻击命中时，对方受到 2/3/4 爆炸伤害且必须通过机体豁免否则伏卧。2. 陶瓷调节（装置 3）：武库获得+1 速度，若成功检定或豁免会造成一半伤害，则不会造成任何伤害。3. 聚合织物（装置 0）：武库获得+2 速度，在使用武器攻击前或后可滑步 2 空间。","id":"npcf_x_cca_1_3","base":true},{"name":"维稳","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"武库做好准备支架进行下一次射击。该效果一直持续到它用火神卡宾枪开火或以自由动作解除该姿态。当它支架时固定，使用火神卡宾枪攻击+1 准度，每回合第一次攻击未命中时，它可重新瞄准射程内另一目标。","id":"npcf_x_cca_1_4","base":true},{"name":"火神卡宾枪","type":"Weapon","tags":[{"id":"tg_ordnance"},{"id":"tg_accurate"}],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":12}],"damage":[{"type":"Kinetic","val":[7,9,11]}],"effect":"（1. 远镜：装置 5）\n2. 满磁：装置 3，可靠 1/2/3，不准，+1/+2/+3，[锥形 5][10/13/15 动能伤害]3. 刺刀：重武器近战，装置 0，+1/+2/+3，[威胁 1][4/6/8 动能伤害]该武器以远镜数据开始每场景。当每个装置级别被摧毁时，它会推进到满磁，再然后是刺刀。","id":"npcf_x_cca_1_5","base":true}],"optional":[{"name":"构建不同","type":"Trait","tags":[],"effect":"武库成功攻击造成的伤害不能降低到 1/1/2 以下。","id":"npcf_x_cca_1_6","base":false},{"name":"飞行准备电枢","type":"System","tags":[],"keywords":["装置 5"],"effect":"1. 西风套件（装置 5）：武库在移动或推进时可飞行，当它使用维稳时以缓慢代替固定，维稳会使火神卡宾枪+2击退。2. 推进器组件（装置 3）：武库可在推进时飞行。当它使用维稳时可承受 1 热度加速旋转推进器组件；在下一回合开始时，它可用协定进行推进。该移动视为滑步。3. 自动陀螺仪（装置 0）：武库可用一个协定使用维稳。","id":"npcf_x_cca_1_7","base":false},{"name":"“心灵探索者”脉冲导弹","type":"Weapon","tags":[{"id":"tg_seeking"},{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":12}],"damage":[{"type":"Energy","val":[5,5,5]}],"effect":"该武器只能以最近的敌对角色为目标（如果多个角色等距，则任选其一）。该武器可以在 T2 攻击 2 次，或在 T3 攻击 3 次。","id":"npcf_x_cca_1_8","base":false},{"name":"巫术腰带","type":"System","tags":[],"keywords":["装置 5"],"effect":"1. 榴弹索（装置 5）：以一个快速动作，武库可投掷一枚榴弹在射程 8 的溅射 1 内爆炸。至少部分位于受影响区内角色必须通过敏捷豁免否则受到 4/6/8 爆炸伤害并伏卧，成功则伤害减半。2. 布雷艇（装置 3）：武库可每单独移动开始或结束时在一个邻近自由空间埋设地雷。当一个敌对角色进入地雷空间时，它就会引爆；受到 3/4/5 爆炸伤害并在武库选择的方向上击退 2 空位。3. 撒粉器（装置 0）：武库在一次会心一击中+1d6 额外伤害。它的所有近战攻击都获得+1/+2/+3 额外爆炸伤害和击退 1。","id":"npcf_x_cca_1_9","base":false},{"name":"冗余炉心管道","type":"System","tags":[],"keywords":["装置 5"],"effect":"1. 零点散热器（装置 5）：若武库在超温危域结束回合，它会冷却热度直到它低于超温危域。2. 冷却液循环（装置 3）：武库在每轮结束时为冷却 1/2/3热度。超温危域时可用一个快速动作，将废冷却剂从锥形 5 中排射。受影响区域角色必须通过工程豁免否则受到 3 燃烧+2/3/4 热度，成功则减半。3. 打破限制器（装置 0）：武库可超限，每次承受 1d6 热度。超限只能用于推进、冲撞或擒拿。若武库被毁，它会以自爆规则立即爆炸。","id":"npcf_x_cca_1_10","base":false},{"name":"“米达斯”数据库","type":"System","tags":[],"keywords":["装置 5"],"effect":"1. 加固天线（装置 5）：对武库的科技攻击+2 难度并且若命中则攻击者承受 2/3/4 热度。2. 开源储库（装置 3）：对武库的科技攻击+1 难度，并获得“米达斯”入侵快速科技动作。3. 暴露节点（装置 0）：对武库的科技攻击+1 准度，在回合开始时与之邻近或在回合中首次移动至邻近的角色受到 2/3/4 热度。","id":"npcf_x_cca_1_11","base":false},{"name":"“米达斯”入侵","type":"System","tags":[{"id":"tg_heat_self","val":2}],"attack_bonus":[2,4,6],"effect":"武库对实现感应内的一个角色进行科技攻击。命中则对方受扰直到下一回合结束，并且必须通过系统豁免。若豁免失败，则对方必须在晕眩，承受 3/4/5 AP 能量伤害，和选择感应内一个盟友重复次豁免好似他也受到攻击命中般，这三者中选择。只要新角色在范围内，该效果就可以连锁，但同一角色不能在同一动作中选择两次。","id":"npcf_x_cca_1_12","base":false},{"name":"蓝宝石//顶点能量神盾","type":"System","tags":[{"id":"tg_shield"}],"keywords":["装置 5"],"effect":"1. 粒子投射（装置 5）：武库可用一个快速动作激活该系统投射一个爆发 2 盾牌。来自区域外的攻击对至少部分位于区域内的角色+2 难度，并且区域内角色对离散免疫。2. 充能外层（装置 3）：武库及其邻接盟友不受会心一击。当另一个装置系统被摧毁时，武库获得 5/6/7 护盾。3. 破碎屏障（装置 0）：武库获得脉冲神盾武器。","id":"npcf_x_cca_1_13","base":false},{"name":"脉冲神盾","type":"Weapon","tags":[{"id":"tg_knockback","val":3}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Energy","val":[4,5,6]}],"effect":"","on_hit":"武库获得 3/4/5 护盾。目标必须通过机体豁免否则伏卧。","id":"npcf_x_cca_1_14","base":false},{"name":"围攻增强","type":"Trait","tags":[],"effect":"维稳将抛射赋予火神卡宾枪。在刺刀数据中获得投掷 8。当它以此法投掷时，会在武库下一回合结束时返还。","id":"npcf_x_cca_1_15","base":false},{"name":"回火铁","type":"Trait","tags":[],"effect":"武库在受到攻击后获得+1 装甲（这可打破装甲上限）。它在每轮开始时失去额外装甲。","id":"npcf_x_cca_1_16","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npcc_x_cca_2","name":"虹膜","role":"炮击","role_en":"artillery","page":45,"pages":[45,46],"flavor":"虹膜式部署是现代围攻战术中一种，有其严酷而尖端的新颖之处。轨道火炮平台如今成为了此类交战的支柱，单平台可与数十架底盘同步，提供实时目标数据和武装增幅。这种物理穿透传感挡板与瞄准屏幕的能力在标准防御程序中制造了一个缺口，而这个缺口尚未得到充分解决。","tactics":"虹膜大量伤害会非常明显，并且对速度较慢体型较大的角色的惩罚大于速度较快的角色。“北极星”轨道阵列需要大量工作才能达到其最终轮廓，而虹膜得益于盟友在近距离骚扰玩家并将他们拖入其视线，同时阻碍他们对防御力较弱的虹膜缩小差距。","stats":{"hull":[-1,-1,-1],"sys":[1,2,3],"agi":[0,0,0],"eng":[1,2,3],"hp":[14,18,22],"armor":[0,1,1],"evasion":[8,8,8],"edef":[10,12,14],"speed":[3,3,4],"size":[1,1,1],"heatcap":[10,10,10],"save":[11,12,13],"sensor":[20,20,20],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"标志性","type":"Trait","tags":[],"effect":"一个场景中只能出现一个具有此特征的 NPC。虹膜必须始终采用精英或超体模板。若它采用超体模板，它还获得了流星基础系统。","id":"npcf_x_cca_2_1","base":true},{"name":"掠食者群","type":"Weapon","tags":[{"id":"tg_seeking"},{"id":"tg_ap"},{"id":"tg_accurate"}],"weapon_size":"重型","weapon_kind":"巢房","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15},{"type":"Line","val":5}],"damage":[{"type":"Energy","val":[6,6,6]}],"effect":"该武器可以在 T2 攻击 2 次，或在 T3 攻击 3 次。攻击时：标记目标区域但不要进行攻击掷骰。所有标记区域在每轮虹膜第一回合开始时结算攻击。若多个区域与一个角色重叠，则只会受到一次攻击。","id":"npcf_x_cca_2_2","base":true},{"name":"轨道上行链路","type":"Trait","tags":[],"effect":"虹膜与轨道火炮平台相连，充当其在地面上的眼。每当一个非匿迹、非隐形或对虹膜不具有掩护的角色在视线内结束其回合时，对方就会获得一个目标标记（以一个 d6 追踪，从1 开始），或者若该角色已拥有标记，则将其标记增加 1。1/回合，若虹膜对其会心一击，该角色也会获得标记。标记无法超过 4 以上。若角色开始其回合处于匿迹，或者若他们稳住阵脚并通过系统豁免代替清除状态或重新装填，则他们的标记将减少 1。","id":"npcf_x_cca_2_3","base":true},{"name":"“北极星”轨道阵列","type":"Trait","tags":[],"effect":"超重型大炮，引导，+2/+4/+6该武器无法被摧毁。虹膜必须消耗 1 目标标记才能发射该武器，并将其以该角色为中心。只要对方没有匿迹，无论距离如何，都可将其作为目标。根据标记值该武器具有不同数据。若标记增加到 5，则虹膜可用一个反应来使目标标记 4 数据发射“北极星”轨道阵列。该武器造成的可靠伤害为能量伤害。1. 溅射 3，2/2/3 能量伤害2. 溅射 2，4/5/6 能量伤害3. 溅射 1，5/7/9 能量伤害+3 燃烧，可靠 3 4. 单目标，8/12/16 能量伤害+5 燃烧，精准，AP，可靠 4/6/8。","id":"npcf_x_cca_2_4","base":true}],"optional":[{"name":"眼花缭乱","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"射程 10 锥形 5 内所有角色都必须通过系统豁免，否则将丢失匿迹和隐形，并在下一回合结束之前无法匿迹或隐形。此外，对他们的下一次攻击+1 准度。","id":"npcf_x_cca_2_5","base":false},{"name":"洪水无人机","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_drone"},{"id":"tg_recharge","val":4}],"effect":"洪水无人机（大小 1/2，8 回避/ED，5 HP）虹膜在视线感应内自由空间部署一架洪水无人机。1/回合，当虹膜用远程武器命中洪水无人机射程 2 内的角色时，它会释放一道能量脉冲，对爆发 2 内所有角色造成 2/3/4 能量伤害。","id":"npcf_x_cca_2_6","base":false},{"name":"融核电箭","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"虹膜对射程 15 内的物品或地形造成 10AP 能量伤害。若这破坏了它，邻近的角色必须通过机体豁免否则伏卧。","id":"npcf_x_cca_2_7","base":false},{"name":"饥饿羊群","type":"Trait","tags":[],"effect":"被捕掠食者群造成会心一击的角色每次受到伤害时都会受到+1 伤害，直到对方下一回合结束。","id":"npcf_x_cca_2_8","base":false},{"name":"阻断虫群","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_heat_self","val":1},{"id":"tg_recharge","val":5}],"effect":"直到虹膜下一回合开始，当它被远程武器攻击时，掷骰1d6。结果为 5+则攻击未命中，并且攻击者受到 2AP 能量伤害并直到下一回合结束前受损。","id":"npcf_x_cca_2_9","base":false},{"name":"依托","type":"Trait","tags":[],"effect":"虹膜将与任意盟友机甲角色邻近的敌对角色视为比实际目标标记高 1（例如：目标标记 2 视为目标标记 3）。这无法将标记推进到 5，并且若邻近不再，则标记恢复正常。","id":"npcf_x_cca_2_10","base":false},{"name":"昴宿式镭射群","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Energy","val":[6,8,10]},{"type":"Burn","val":[2,2,2]}],"effect":"该武器只能以拥有目标标记的角色为目标，并在开火时将标记降低 1。","id":"npcf_x_cca_2_11","base":false},{"name":"太阳之怒","type":"Trait","tags":[],"effect":"当“北极星”轨道阵列以目标标记 2 或更低的目标开火时，目标空间将化为困难地形直到场景结束，若角色在受影响区域结束回合则将受到 1/2/3 能量伤害+1 热度。","id":"npcf_x_cca_2_12","base":false},{"name":"观测员闪烁","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":5}],"tech_type":"Quick","effect":"虹膜消耗感应内任意数量角色的锁定。这些角色都会获得 1 目标标记，或将标记增加 1。","id":"npcf_x_cca_2_13","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npcc_x_cca_3","name":"蚊","role":"卫兵","role_en":"defender","page":47,"pages":[47,48],"flavor":"蚊底盘学说最初是在渗透到伊斯帕萨拉尔的联合会（Amalgate）暗杀小组手中首次遭遇。该设计中心特征是一套翘曲空间储存库位移结构与侵略性编码库的组合；数字入侵维系在机械部件的物理分离。这些被切割的碎片在外部空间附着到蚊自身的处理器上，使其大大超过通常功率/重量比限制。","tactics":"鲜血与汲取的结合极大激励了针对蚊而非其盟友的行动。它射程很短，没有直伤或热度，这意味着它无法独自终结一场遭遇战，集火会以比恢复更快的速度摧毁其防御。","stats":{"hull":[-2,-2,-2],"sys":[2,4,6],"agi":[1,2,3],"eng":[0,0,0],"hp":[10,12,14],"armor":[0,0,0],"evasion":[10,12,14],"edef":[10,12,14],"speed":[5,5,5],"size":[1,1,1],"heatcap":[6,7,8],"save":[11,13,15],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"size_note":["1 或 1","1 或 1","1 或 1"],"base":[{"name":"特殊规则","type":"Trait","tags":[],"effect":"蚊有两个可贴给角色的特殊标记：鲜血与汲取。一个角色最多可以有 6 个。角色在每回合开始时获得等同鲜血的装甲（最多 6），并获得等同鲜血的护盾。1/回合，每当角色成为攻击目标时，在攻击结算后，他们失去 1 鲜血。部分系统只有在使用者拥有 X+鲜血时才可激活，但除非另有说明，否则使用它们不会消耗鲜血。角色每拥有 1 汲取标记，所有攻击掷骰、检定和豁免都会-1。角色在对蚊进行一次攻击时可移除 1 汲取，在稳住阵脚时移除 3汲取。","id":"npcf_x_cca_3_1","base":true},{"name":"标志性","type":"Trait","tags":[],"effect":"一个场景中只能出现一个具有此特征的 NPC。蚊必须始终采用精英或超体模板。若它采用超体模板，它还获得了吸血鬼基础系统。","id":"npcf_x_cca_3_2","base":true},{"name":"放血","type":"Trait","tags":[],"effect":"当蚊用科技攻击命中一个敌对角色，或使其豁免失败时，对方会获得 1 汲取，蚊获得 1 鲜血。","id":"npcf_x_cca_3_3","base":true},{"name":"鲜血//银行","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"蚊对感应内的一个角色进行科技攻击。命中则对方受到 2热度，若蚊有 1+/4+/6 鲜血，则使对方缓慢/固定/晕眩。一个角色每场景只能以此法晕眩一次。若对方已晕眩，则受到4/6/8 能量伤害。","id":"npcf_x_cca_3_4","base":true},{"name":"灵魂陷阱","type":"Tech","tags":[{"id":"tg_quick_tech"}],"keywords":["鲜血 3+"],"tech_type":"Quick","effect":"蚊在感应内选择一个敌对角色进行系统豁免。失败则它选择一个特征、武器、系统或核心系统。这不能将已激活的核心系统作为目标。在蚊被摧毁前，或在对方用一个快速动作选择一个邻近盟友使其获得 2/3/4 汲取前，他们无法在场景结束前以任何方式使用、激活或受益于该系统。","id":"npcf_x_cca_3_5","base":true}],"optional":[{"name":"黑纱光束","type":"Weapon","tags":[{"id":"tg_smart"}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Line","val":5}],"damage":[{"type":"Energy","val":[3,4,5]}],"effect":"受影响区域盟友角色不会受到攻击；相反，他们在下一个回合结束前隐形。受影响区域作为软性掩护持续存在，直到蚊下一回合结束。","on_hit":"目标必须通过系统豁免，否则在下一回合结束前，除邻近空间外无法绘制视线。","id":"npcf_x_cca_3_6","base":false},{"name":"泡罩","type":"Tech","tags":[{"id":"tg_quick_tech"}],"keywords":["鲜血 2+"],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"蚊对感应内的一个角色进行科技攻击。命中则对方反应堆安全装置开始失灵。若他们推进，超限，弹幕，或自身获得4+总热度，则安全性会完全失效。对方受到 6/8/10 AP 能量伤害，并在下一回合结束前受损。该效果持续到下一回合结束。","id":"npcf_x_cca_3_7","base":false},{"name":"支配术","type":"Tech","tags":[{"id":"tg_full_tech"}],"keywords":["鲜血 5+"],"attack_bonus":[2,4,6],"accuracy":[1,1,1],"tech_type":"Full","effect":"蚊对感应内的一个角色进行科技攻击。命中则夺取对其主要操作系统的控制权。目标无法进行任意动作，除了移动、推进、擒拿、冲撞、权宜攻击或技能检定，直到对方以一个完整动作通过系统豁免。","id":"npcf_x_cca_3_8","base":false},{"name":"吸血动物","type":"Trait","tags":[],"effect":"蚊可获得使用灵魂陷阱所窃取的所有系统、武器或特征。若所窃物具有受限效果则代替其原始值获得 1/2/3 充能；否则效果将完全复制对方拥有的数据，直到灵魂陷阱被使用。","id":"npcf_x_cca_3_9","base":false},{"name":"失血","type":"Trait","tags":[],"effect":"若场景中的一个角色获得超过 6 汲取，他们会清除所有汲取，失去 1 维修并受扰与缓慢直到下一回合结束。","id":"npcf_x_cca_3_10","base":false},{"name":"动力虹吸","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[2,4,6],"tech_type":"Quick","effect":"蚊对感应内的一个角色进行科技攻击。命中则对方缓慢直到下一回合结束，目标射程 2 内的蚊或所有盟友角色可用一个反应移动等同其速度的距离。心理静态","id":"npcf_x_cca_3_11","base":false},{"name":"系统相喰","type":"Reaction","tags":[],"trigger":"在射程 X 内的蚊或盟友遭到一个角色攻击。","effect":"蚊制造一个尖叫静电和火花箔条的爆发 X。对该区域盟友的攻击获得+1 难度并将蚊自身视为隐形直到蚊下一回合结束。蚊的鲜血减少 X。这适用于触发的攻击。反应，1/轮，鲜血 X+\n当蚊视线感应内的盟友角色失去结构或压力，或被摧毁时，它将获得 2 鲜血。","id":"npcf_x_cca_3_12","base":false},{"name":"输血集群","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"蚊将所有鲜血从自己身上转移到射程 3 的一个盟友上。","id":"npcf_x_cca_3_13","base":false},{"name":"湿件脑脊","type":"System","tags":[],"effect":"对蚊及其邻近盟友的科技攻击+1 难度。它还获得接驳脑脊科技动作。","id":"npcf_x_cca_3_14","base":false},{"name":"接驳脑脊","type":"Tech","tags":[{"id":"tg_limited","val":1},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"蚊在射程 3 内选择了一个敌对机甲角色，并同时对机甲及其驾驶员进行本体论打击。对方缓慢，无法从天赋，会心一击，或采取科技动作中受益。在每对方回合结束时可尝试一次毅力检定来结束该效果。1/回合，对方可以通过承受 4/5/6不可减少 AP 动能伤害重新掷骰一次结果，并为每个邻近的盟友机甲在此豁免中+1 准度。若蚊被摧毁，或如果对方愿意失去 1 结构而非重新掷骰，则该效果立即结束。","id":"npcf_x_cca_3_15","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npcc_x_cca_4","name":"地球化","role":"操纵","role_en":"controller","page":50,"pages":[50,51,52],"flavor":"改装或调整民用机甲在闪点内战或长期围攻中相对常见——但鲜少能达到这种规模。地球化认证军用底盘是对殖民地建造机械进行彻底重新设计和武器化的大规模工程结果，其本身通常已有数百年历史。结果与狗头人模式组礼拜编码产品的某些方面具有令人担忧的对称性，将古代生物群系设计工具和巍峨反应堆化作狂野的元素之怒。","tactics":"地球化的存在重塑着它周边的整个地图，它能够部署的发电器系统越多，规模就越大。它依赖于强大自由动作的能源效果，但能源骰是并不可靠，而且仅限于自己的领域。玩家必须在直接攻击地球化和破坏其基础设施间取得平衡以免其失控。","stats":{"hull":[0,0,0],"sys":[2,2,2],"agi":[-2,-2,-2],"eng":[2,4,6],"hp":[10,14,16],"armor":[2,2,2],"evasion":[6,6,6],"edef":[8,10,12],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,10,12],"save":[12,14,16],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"特殊规则","type":"Trait","tags":[],"effect":"地球化部分特征、武器和系统具有能源 X 标签，其可展开具有发电器和领域标签。在地球化每回合开始时掷骰一个能源骰（d6），每激活一个带有发电器标签的系统就+1d6。将每个骰子分配给发电器系统或地球化。地球化及其系统每次只能容纳一枚骰子。这些骰子持续到地球化下一回合开始。X 能源的效果和动作需要能源骰激活；当执行动作时，将骰子减少 X，并且若骰子小于 X，则无法执行。X 能源效果默认情况下以自由动作，因此可重复执行，除非另有说明。地球化的独特可展开有一个领域；这是根据其数据块中描述的持久施加影响的领域。默认情况下，爆发 1 中所有空间在部署时都在其领域内。领域空间总是在源自可展开的效果范围内，即使所列范围更窄。若一个可展开在地球化回合开始时剩余 4+能源，那么在场景结束前，它将获得领域大小+1。该效果可以叠加到最大尺寸爆发 3。领域效果持续到可展开被摧毁。","id":"npcf_x_cca_4_1","base":true},{"name":"标志性","type":"Trait","tags":[],"effect":"一个场景中只能出现一个具有此特征的 NPC。地球化必须始终采用精英或超体模板。若它采用超体模板，它还获得了暴风基础系统。","id":"npcf_x_cca_4_2","base":true},{"name":"工业中心超大杯","type":"Trait","tags":[],"effect":"地球化具有爆发 X 光环，继承所有被激活的发电器可展开设备的领域效果，其中 X 是激活发电器可展开设备总数的二分之一（最多 3）。它还可以获取使用其他能源动作。它和它的盟友对所有领域效果免疫，除非它另有选择。","id":"npcf_x_cca_4_3","base":true},{"name":"气旋轮叶","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"气旋轮叶（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：此区域忽略垂直距离。这是个困难地形，在该区域开始回合或在回合中首次进入该区域的敌对角色必须通过机体豁免，否则飞行必须被迫降落，并且在下一回合结束前无法飞行。• 阵风（2 能源）：射程 3 内的角色必须通过一次机体豁免否则将被向任意方向推离 3 空间。飞行角色在该豁免中+1 难度。• 气旋（5 能源）：领域中所有敌对角色必须通过一次机体豁免否则伏卧。","id":"npcf_x_cca_4_4","base":true},{"name":"水蛭光束","type":"Weapon","tags":[{"id":"tg_heat_self","val":1}],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":12}],"damage":[{"type":"Energy","val":[3,3,3]},{"type":"Heat","val":[2,2,2]}],"effect":"该武器对超温危浴的目标+1 准度。该武器可以在 T2 攻击 2 次，或在 T3 攻击 3 次。","on_hit":"地球化可为任意能源骰加 1。世界熔炉特征，快速动作，能源 X地球化为一个再充能 X 或更低的无人机或可展开系统再充能。","id":"npcf_x_cca_4_5","base":true},{"name":"岩浆引擎","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"岩浆引擎（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：该区域内的角色只能清除一半热度，并且在所有工程检定和保存中+1 难度。若一个角色在该区域结束回合则受到 1/2/3 热度。• 熔岩流（3 能源）：创建一个起源于领域的线形 5 区域，该区域持续到场景结束或该部署被摧毁。这是个困难地形，在该区域开始回合或在回合内首次进入该区域的角色必须通过敏捷豁免否则受到 3/4/5 燃烧。若处于超温危域则燃烧翻倍。• 火山屑（6 能源）：领域中的角色受到 2 热度和 3/4/5燃烧。","id":"npcf_x_cca_4_6","base":true}],"optional":[{"name":"燃尽引擎","type":"Trait","tags":[],"effect":"地球化所有发电器可展开设备都会获得以下能源动作：燃尽（5 能源，快速动作）：该可展开爆炸，摧毁它和它所创造的所有效果，除了它的领域。在领域中的所有角色都必须通过敏捷豁免否则承受 6/8/10 爆炸伤害，成功则伤害减半。领域将一直持续到场景结束。","id":"npcf_x_cca_4_7","base":false},{"name":"浓缩燃料","type":"Trait","tags":[],"effect":"每当地球化在能源骰上掷出 1 时，它可承受 1 热度并重新掷骰。","id":"npcf_x_cca_4_8","base":false},{"name":"拒绝网格","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"选择两个在彼此之间视线射程 5 内的发电器可展开，并绘制一条连接它们的线形。该区域对两个可展开视为领域，每回合首次进入该区域的一个敌对角色受到 2/3/4 能量伤害。该线形一直持续到场景结束或任意一个可展开被摧毁。地球化可以消耗自身能源来提高改线形的射程 2/所消耗能源。","id":"npcf_x_cca_4_9","base":false},{"name":"地下水层喷口","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"地下水层喷口（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：该区域视为困难地形。在该区域结束其回合的角色冷却 1 热度，然后将其存储在该可展开中。最多可储存 4热度，但可以冷却更多热度。• 热传递（3 能源）：在领域中选择一个角色。该区域内所有其他角色失去 1 热度。所选角色必须通过工程豁免否则承受等同其他角色流失的总热度与该系统中存储的所有热度相加结果的热度，成功则热度减半。• 洪水/水流（5 能源）：领域射程 2 内的所有角色必须通过机体豁免否则被拉到区域中心或尽可能靠近区域中心的位置。","id":"npcf_x_cca_4_10","base":false},{"name":"避雷针","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"避雷针（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：该区域内的敌对角色无论何时执行或成为科技动作的成功目标，都会获得 1 电荷。若一个角色获得第 5 次电荷，则清除所有电荷，受到 4/6/8 能量伤害，并在下一回合结束前受扰。一个角色可以通过稳住阵脚移除所有电荷，若该可展开被摧毁，则所有电荷都会被清除。• 静电（2 能源）：射程 3 内的一个角色通电。对其他角色而言，与该角色邻近的空格均视为领域，他们在回合结束时获得 1 电荷。该效果持续到对方以一个快速动作进行工程豁免，或者稳住阵脚。• 电箭瘫痪（5 能源）：选择一个领域中的角色。该角色必须通过工程豁免否则受到 2 热度+3/4/5 能量伤害，并在下一回合结束前受扰，豁免成功则伤害与热度减半并且受损。一个角色只能被该效果受扰 1/场景。然后，在首个受到次效果的角色射程 3 内对另一个角色重复此效果。受静电影响的角色始终被视为在射程内。若一个角色有任意电荷，清除所有电荷，该角色在豁免失败时承受该数值的额外热度，成功则热度减半。","id":"npcf_x_cca_4_11","base":false},{"name":"地震捣杵","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"地震捣杵（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：只有在地球化允许的情况下，该区域的物品和地形才会受到破坏。该区域并非是敌对无人机或可展开移动进入或放置的有效空间。• 建设者/破坏者（2 能源）：对领域内的物品、无人机或地形造成 10 AP 动能伤害，或创建 1 块大小 1，10HP的地形，以提供硬性掩护。• 渗穴（6 能源）：在领域中的单个空间中创造一个坑。一个因任何原因完全进入坑中的非飞行角色深陷其中。该角色会伏卧，无法离开该空间（除非进入另一个坑），直到他们使用标准移动并通过敏捷豁免爬出，进入邻近坑的自由空间。该空间可在角色下创造，迫使对方通过敏捷豁免否则立即坠入其中，成功则移动到邻近自由空间。","id":"npcf_x_cca_4_12","base":false},{"name":"冰川虹吸","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"地震捣杵（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：角色在该区域开始除标准移动外的任何移动时，必须通过敏捷豁免否则摔倒伏卧。伏卧角色必须通过敏捷豁免才能站起来。• 零下（3 能源）：在地球化下一回合结束前，任意在领域中结束回合的敌对角色若不在超温危域则在下一回合结束前缓慢。若已经缓慢，则改为固定。• 冻结（4 能源）：选择一个领域中的角色。该角色冷却热度直到不再处于超温危域，然后必须通过机体豁免否则承受等同热度流失两倍的 AP 动能伤害，成功则减半。","id":"npcf_x_cca_4_13","base":false},{"name":"接近抑制","type":"Tech","tags":[{"id":"tg_quick_tech"}],"attack_bonus":[1,2,3],"accuracy":[1,1,1],"tech_type":"Quick","effect":"命中后目标会被一种催化病毒感染。若对方在下一回合结束时邻近与他们相同大小或更大的物品或地形，它就会引爆。承受 4/5/6 AP 爆炸伤害，并且场景结束前他们邻近的所有空间都化为困难地形。","id":"npcf_x_cca_4_14","base":false},{"name":"超原胞播种机","type":"Weapon","tags":[{"id":"tg_seeking"}],"weapon_size":"超重型","weapon_kind":"巢房","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15},{"type":"Blast","val":2}],"damage":[],"effect":"原文伤害：[3/5/7 ???伤害]，伤害类型缺失。\n（能源 6）\n攻击时：选择以下数据之一：• 雷霆（能量）：攻击获得智慧，在下一轮结束前，受影响区域角色在所有科技攻击和系统检定与豁免方面+2难度。• 飓风（爆炸）：攻击获得击退 2，在下一轮结束前，地球化可将任意在该区域结束其回合的角色向任何方向推动 2 空间。• 暴雪（动能）：攻击获得可靠 1/2/3，在下一轮结束前，受影响区域角色无法绘制视线到射程 3 外。","id":"npcf_x_cca_4_15","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npcc_x_cca_5","name":"幻人","role":"支援","role_en":"support","page":54,"pages":[54,55],"flavor":"在地面交战环境中，军团现象的显化虽然罕见却也并非不可能。借助于放大节点与神经数字桥接支撑，这些实体甚至可以表现出准物理遭遇体，尽管它们仍依赖于周边物理架构来维持其内聚性。由此诞生的幻人具有与舰队军团相同的后量化计算力，以及独具的非因果显现，通常以自发式纳米体生成、异常热力学变化以及临时性完全性心理模因升华来实现。","tactics":"幻人是其盟友的力量倍增器；它没有任何直接伤害或数据效果，但直接控制允许它将任何正常 NPC 超限至更大威胁。但此刻也是它最脆弱的时候——它无法使用电子精魂来规避与他们共享的伤害。由于其感应距离较短，它需要盟友保持近距，而可破坏其编队的玩家战术将干扰其更强大的召集能力。","stats":{"hull":[0,0,0],"sys":[2,4,6],"agi":[2,2,2],"eng":[-2,-2,-2],"hp":[16,18,20],"armor":[0,0,0],"evasion":[10,10,10],"edef":[12,14,16],"speed":[4,5,6],"size":[1,1,1],"heatcap":[8,8,10],"save":[11,12,13],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"特殊规则","type":"Trait","tags":[],"effect":"带有召集标签的系统在使用后变为未充能并且无法再次使用。幻人回合开始时，掷骰 1d6；若小于或等于感应内盟友角色的数量，则为所有召集系统充能。低等兵与无人机算 1/4 个角色。","id":"npcf_x_cca_5_1","base":true},{"name":"标志性","type":"Trait","tags":[],"effect":"一个场景中只能出现一个具有此特征的 NPC。幻人必须始终采用精英或超体模板。若它采用超体模板，它还获得了技术症候群基础系统。","id":"npcf_x_cca_5_2","base":true},{"name":"电子精魂","type":"Trait","tags":[],"effect":"幻人具有 AI 标签，无法拥有人类驾驶员。它可以悬浮，移动或推进时视为瞬间移动，并被所有以回避为目标的攻击视为隐形。若在轮结束时感应内不存在盟友角色，它将受到 5不可减免能量伤害。","id":"npcf_x_cca_5_3","base":true},{"name":"直接控制","type":"Trait","tags":[{"id":"tg_protocol"},{"id":"tg_round","val":1}],"effect":"幻人选择感应内一个盟友角色。幻人回合立即结束，该角色立即激活，即便对方已在本轮激活过。直到幻人下一回合开始，对方：• 可激活幻人拥有任意系统或武器好似该角色自己拥有。• 可使用幻人 HASE 四项属性来代替其自身属性。• 在所有攻击中+1 准度，并 1/回合在命中时+2/3/4 额外能量伤害。• 具有所有伤害和热度的抗性。• 幻人对所有伤害和效果免疫，但会受到目标在减免前所受一半的伤害和热度。","id":"npcf_x_cca_5_4","base":true},{"name":"电镀","type":"Tech","tags":[{"id":"tg_quick_tech"}],"keywords":["召集"],"tech_type":"Quick","effect":"一个感应盟友角色获充能量。对方恢复 4/6/8HP，获得+1 装甲（最多 4），所有攻击造成+1 点能量伤害。这种效果","id":"npcf_x_cca_5_5","base":true},{"name":"激励","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"一个感应内盟友角色清除除晕眩外一个非自身造成的状态，并在下一次攻击的最终掷骰时不会遭受难度。","id":"npcf_x_cca_5_6","base":true}],"optional":[{"name":"极乐世界","type":"Trait","tags":[],"effect":"盟友角色在幻人邻近结束其回合则冷却 1/2/3 热度，并且免疫敌对角色所有科技动作直到下一回合开始。","id":"npcf_x_cca_5_7","base":false},{"name":"电子喷雾","type":"Tech","tags":[{"id":"tg_heat_self","val":1},{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"一个感应内盟友角色获得电子充能。此后直到该角色下一回合结束，当一个敌对角色进入射程 3 内空间时必须通过工程豁免否则受到 5 能量伤害并且伏卧，成功则伤害减半。若幻人目标 HP 为其最大值一半或更低，这将提升到 6/8/10 能量伤害，并且该触发敌人无论豁免成功还是失败都将受损。","id":"npcf_x_cca_5_8","base":false},{"name":"强制复苏","type":"System","tags":[],"keywords":["召集"],"effect":"直接控制可用来以盟友角色残骸为目标。这使该角色恢复最大 HP1/2、0 热度和 1 结构和 1 压力。当该角色被摧毁时不会再留下残骸，它在彻底的撕裂中分解。","id":"npcf_x_cca_5_9","base":false},{"name":"预兆","type":"Trait","tags":[],"effect":"由直接控制指定的角色清除所有燃烧和所有非自身造成的状态，并可以在其自己回合中悬浮移动。","id":"npcf_x_cca_5_10","base":false},{"name":"链路壁障","type":"System","tags":[],"effect":"在每轮开始时，幻人获得等同感应内盟友角色数量2/3/4 倍（最高 8/10/12）护盾。每当感应内盟友角色受到伤害时，它会首先作用于该护盾如同该护盾时盟友角色自己拥有一般。","id":"npcf_x_cca_5_11","base":false},{"name":"救援","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"一个感应内盟友角色被瞬间移动到幻人邻近或尽可能靠近的一个自由空间。若该角色剩余最大 HP 只有一半或更少，则获得对所有伤害和热度的抗性直到下一回合开始。","id":"npcf_x_cca_5_12","base":false},{"name":"同调","type":"Reaction","tags":[{"id":"tg_round","val":1}],"keywords":["召集"],"trigger":"一个感应内盟友角色攻击命中一个目标。","effect":"感应内另一盟友可用单一武器对同一目标进行攻击，对其造成一半伤害、热度和燃烧。","id":"npcf_x_cca_5_13","base":false},{"name":"思维之矛","type":"Tech","tags":[{"id":"tg_full_tech"}],"keywords":["召集"],"tech_type":"Full","effect":"从幻人或感应内一个盟友角色为起点绘制线形 8。受影响区域敌对角色获得锁定并受到 4 能量伤害。若已锁定则受到6/8/10 伤害作为替代消耗锁定。该区域中的盟军角色获得软性掩护直到下一回合开始，并可以滑步 2 空间。若该线形与最大 HP 只有一半或更低时与盟友重叠时，则可提前停止。然后，从该盟友角色位置开始重新绘制一条新线形。一个角色不能被新线形影响两次。","id":"npcf_x_cca_5_14","base":false},{"name":"电离","type":"Tech","tags":[{"id":"tg_full_tech"}],"tech_type":"Full","effect":"在感应内创造一个至少有 1 空间与盟友角色邻近的溅射2 区域。对该区域内敌对角色的攻击+1 精度，并且 1/回合获得命中：该区域内所有敌对角色均受到 1 能量伤害。该区域一直持续到场景结束，或幻人使用该系统来创造一个新区域。","id":"npcf_x_cca_5_15","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npcc_x_rc_1","name":"比蒙巨兽","role":"炮击","role_en":"artillery","page":51,"pages":[51,52,53],"flavor":"环环相扣的钛板堆积如山，如雷鸣般的脚步撼动大地，向四面八方喷射烈焰与死亡。比蒙巨兽是战场上所能遭遇的最大自行式陆地部队之一，也是极其罕见的，如此一个骨架的建造成本便是天文数字。这一机甲，硕大无朋，拔地倚天，通常由多人操作，这是对其无数放大系统进行监控的必要条件。比蒙巨兽武装精良，通常配备安装在机体上的辅助节点，以指数级方式增强比蒙巨兽的有效性，使用重叠火力覆盖盲点或提供有价值的支援系统。虽然真正的超大型机甲可以有各种形式，但只有最辉煌的，才配得上“比蒙巨兽”的称号。","tactics":"比蒙巨兽被设计为整个场景都围绕它构筑的高威胁单一NPC。比蒙巨兽提供了一种强有力的“BOSS”级敌人，这可能会给全枪骑兵小队带来挑战。比蒙巨兽只能在“巨兽之战”军情报告中使用。","stats":{"hull":[4,5,6],"sys":[1,2,3],"agi":[-3,-3,-3],"eng":[5,5,5],"hp":[25,30,35],"armor":[1,1,1],"evasion":[6,6,6],"edef":[10,12,14],"speed":[3,5,5],"size":[5,5,5],"heatcap":[10,10,10],"save":[11,13,15],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"内置多管发射器","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_knockback","val":1}],"weapon_size":"超重型","weapon_kind":"发射器","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"该武器攻击射程内的每个敌对角色。","id":"npcf_x_rc_1_1","base":true},{"name":"泰坦践踏","type":"Weapon","tags":[],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[-1,-1,-1],"range":[{"type":"Burst","val":1}],"damage":[{"type":"Explosive","val":[8,10,12]}],"effect":"该武器只影响敌方角色。无论命中与否，在攻击结算后，所有敌方角色都会被推出攻击的爆发范围，即使是穿过承重点空间也会被推出去。","id":"npcf_x_rc_1_2","base":true},{"name":"超体","type":"Trait","tags":[],"effect":"比蒙巨兽必须配备超体模板（数据变化已包含在上述列表中），但不得使用任何超体选项。","id":"npcf_x_rc_1_3","base":true},{"name":"比蒙巨兽","type":"Trait","tags":[],"effect":"以下规则适用于比蒙巨兽：• 它的大小 5，占据溅射 2 为模板，高度 5 的空间。• 它无法推进。• 它具有对伏卧、无形和所有非自主移动的免疫。• 它忽略困难地形，并自动摧毁它移动经过或进入的所有地形。• 它永远无法匿迹或隐形。• 它不会致使或影响交战。• 角色可占据与比蒙巨兽相同的空间。• 每层级必须获得 1 比蒙巨兽可选。","id":"npcf_x_rc_1_4","base":true},{"name":"承重点","type":"Trait","tags":[],"effect":"比蒙巨兽拥有与 PC 数量相等的承重点。承重点是比蒙巨兽上的固定单个空间节点。它们垂直覆盖整个比蒙巨兽的高度。角色无法占据承重点的空间。若比蒙巨兽移动并且一个角色占据了承重点的空间，则该角色将被推离直到他们不再占据承重点位置。","id":"npcf_x_rc_1_5","base":true},{"name":"辅助节点","type":"Trait","tags":[],"effect":"比蒙巨兽上每个承重点都有一个永久占据它的辅助节点。辅助节点可从辅助节点部分中选择。辅助节点：• 作为独立角色，每轮获得一次独立于比蒙巨兽的单独回合。• 与比蒙巨兽共享数据，除了它们拥有 15/18/21 HP 以及没有热度上限。• 影响多目标的攻击和效果对辅助节点造成一半伤害。• 与比蒙巨兽一起移动，并对所有其他形式的移动和伏卧具有免疫。• 不会致使或影响交战。• 无法从任何使用于比蒙巨兽的任何 NPC 模板中获益。• 具有单一结构且无压力。• 可使用超重型武器进行守望。• 当比蒙巨兽被摧毁时一起摧毁。• 在其回合结束时自动清除无形。每个辅助节点都配备了一个确定其类型的辅助节点特征。","id":"npcf_x_rc_1_6","base":true},{"name":"内置自动维修","type":"System","tags":[{"id":"tg_limited","val":1}],"effect":"比蒙巨兽稳住阵脚时，它可消耗任何数量的充能以满 HP修复相应数量被摧毁的辅助节点。若先前被摧毁的辅助节点本轮未进行过回合，它可正常进行回合。每个被摧毁的辅助节点在每场景中只能修复一次。每当比蒙巨兽受到结构或压力伤害时，该系统获得 1 充能。","id":"npcf_x_rc_1_7","base":true},{"name":"冗余系统","type":"Trait","tags":[],"effect":"比蒙巨兽以等同其所拥有的辅助节点数量的护盾开始每个场景。在它自身每回合开始时，它获得等同其所拥有的完好辅助节点数量的护盾。比蒙巨兽的结构或压力永远无法减少到其拥有的完好辅助节点数量以下。若它受到的伤害或热度会使其结构或压力低于其完好辅助节点数量，那么它将保留在1HP 或最大热度上限。若比蒙巨兽重新获得任意节点，它不会重新获得结构或压力，但依然会在适当数量节点被破坏前，不会再失去更多结构或压力。","id":"npcf_x_rc_1_8","base":true}],"optional":[{"name":"辅助节点：机枪阵列","type":"Weapon","tags":[{"id":"tg_reliable","val":[3,4,5]}],"weapon_size":"超重型","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"该节点配备了机枪。","id":"npcf_x_rc_1_9","base":false},{"name":"辅助节点：点防","type":"Weapon","tags":[],"weapon_size":"超重型","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"该节点配备了点防武器。该节点每轮可无限守望。","id":"npcf_x_rc_1_10","base":false},{"name":"辅助节点：猎潜导弹发射器","type":"Weapon","tags":[{"id":"tg_smart"},{"id":"tg_seeking"}],"weapon_size":"超重型","weapon_kind":"发射器","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Energy","val":[8,10,12]}],"effect":"该节点配备了猎潜导弹发射器。该武器的伤害无法以任何方式减免——通过装甲、抗性或其他方式。","id":"npcf_x_rc_1_11","base":false},{"name":"辅助节点：炮击阵列","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_inaccurate"}],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":20},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[6,8,10]}],"effect":"该节点配备了炮击阵列。","id":"npcf_x_rc_1_12","base":false},{"name":"辅助节点：骇客节点","type":"Trait","tags":[],"effect":"该节点配备了骇客模块。该节点使科技攻击+1 准度。当它使用完整科技动作时，可进行两次入侵。","id":"npcf_x_rc_1_13","base":false},{"name":"辅助节点：飞行甲板","type":"Trait","tags":[],"effect":"以一个完整动作，该节点必须在一个邻近的自由空间中部署一台带有低等兵模板的王牌 NPC。该节点无法执行任何其他动作。它只能有一个低等兵发挥作用。低等兵立即执行它的回合，并在该节点回合中继续进行接下来的回合。若该节点被毁，低等兵将开始进行独立回合（若低等兵已在本轮激活过，那么从下一轮开始）。","id":"npcf_x_rc_1_14","base":false},{"name":"辅助节点：护盾发生器","type":"Trait","tags":[],"effect":"该节点配备了护盾发生器。该节点完好时，比蒙巨兽和所有非护盾生成器节点都具有对所有伤害的抗性。以一个完整动作，该节点可清除比蒙巨兽和所有节点（包括其自身）中的所有燃烧标记。","id":"npcf_x_rc_1_15","base":false},{"name":"末日导弹","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_limited","val":1}],"effect":"消耗 1 充能，瞄准射程 20 内的溅射 3 区域。该区域中角色受到的爆炸伤害等同比蒙巨兽在场景中参与的轮次2/3/4 倍。成功的敏捷豁免使伤害减半。该地区地形自动被摧毁。","id":"npcf_x_rc_1_16","base":false},{"name":"牵引粉碎机","type":"System","tags":[{"id":"tg_full_action"}],"effect":"选择视线内距离超过 7 空间的角色。对方固定。在比蒙巨兽回合结束时，该角色被拉向比蒙巨兽 3 空间。若它接触到地形，地形会被摧毁。若它接触到一个角色，该角色会以最直线的方式被推开。当它邻近比蒙巨兽时，它会受到1 结构伤害，该效果结束。若目标或比蒙巨兽移动，包括非自主移动，该效果也会立即结束，由该系统牵引的移动除外。怪系统一次只能影响一个角色。受影响角色可用一个完整动作进行机体豁免，成功则立即结束该效果。固定状态只能通过本系统列出的方式清除。","id":"npcf_x_rc_1_17","base":false},{"name":"舰船级投射屏障","type":"System","tags":[{"id":"tg_full_action"}],"effect":"将 2 个线形 4 屏障完整安置在射程 3 内的任何位置。它们有 6 空间高。屏障会摧毁所有贯穿的地形，但可不与角色重叠。比蒙巨兽对所有穿过屏障的非抛射或引导的攻击伤害具有抗性。角色可自由通过屏障，但当他们进入屏障或在一轮中首次在屏障内开始回合时，受到 4/6/8 燃烧。屏障持续到比蒙巨兽移动或再次执行该动作。","id":"npcf_x_rc_1_18","base":false},{"name":"多重扫描仪","type":"System","tags":[{"id":"tg_full_action"}],"effect":"所有敌对角色被锁定，即使对方处于匿迹。当对方锁定时，失去隐形和匿迹，且无法受益于此。","id":"npcf_x_rc_1_19","base":false},{"name":"至高无上的战争领主","type":"Trait","tags":[],"effect":"比蒙巨兽首次被摧毁时以 1 结构和压力代替，恢复所有HP，清除所有热度。","id":"npcf_x_rc_1_20","base":false}],"special":"军情报告特殊","pack":"强化战斗","source":14},{"id":"npcc_x_rc_2","name":"列车","role":"卫兵","role_en":"defender","page":54,"pages":[54],"flavor":"列车是列车大盗军情报告的一部分。","tactics":"","stats":{"hull":[4,5,6],"sys":[1,1,1],"agi":[-2,-2,-2],"eng":[0,1,2],"hp":[25,30,30],"armor":[0,0,0],"evasion":[6,6,6],"edef":[6,6,6],"speed":[0,0,0],"size":[3,3,3],"heatcap":[10,10,10],"save":[10,12,14],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"轨道列车加农炮","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_reliable","val":[3,4,5]}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[5,7,10]}],"effect":"","id":"npcf_x_rc_2_1","base":true},{"name":"应急护盾发生器","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"该系统维持激活直到列车下一回合开始。激活时，列车获得对所有伤害抗性的能力。","id":"npcf_x_rc_2_2","base":true},{"name":"死亡引擎","type":"Trait","tags":[],"effect":"火车每转执行两个互相分隔的回合。它具有+3 结构和压力。列车在结构伤害和过热检定时掷骰两次，并选择其中一个结果。列车无法使用模板进一步改造。在其回合开始时，列车清除一个状态，并修复一件被摧毁的武器或系统。只要列车未被摧毁，列车邻近的空间就被视为 NPC 的进入区（IZ）。","id":"npcf_x_rc_2_3","base":true,"bonus":{"structure":3,"stress":3,"activations":1}},{"name":"列轨","type":"Trait","tags":[],"effect":"除了通过碾压之速特征，列车无法移动。列车不受其他角色的非自主移动影响。永远不能强迫它离开自己的路线。无论何时，列车的移动都不受交战和反应影响。它的移动无论如何都无法阻止。","id":"npcf_x_rc_2_4","base":true},{"name":"碾压之速","type":"Trait","tags":[],"effect":"在一轮结束时，列车沿着其预定路线移动一定数量的空间，在第 6 轮结束时离开战场。在每轮结束的移动过程时，列车将碾过其路径中的角色和物品。物品自动摧毁，而角色（无论敌友）必须进行敏捷豁免否则受到 10/15/20AP 动能，并被推离与伏卧。成功则伤害减半并维持站立，但仍被推离。","id":"npcf_x_rc_2_5","base":true}],"optional":[],"special":"军情报告特殊","pack":"强化战斗","source":14},{"id":"npcc_x_rc_3","name":"合约杀手","role":"突击","role_en":"striker","page":56,"pages":[56],"flavor":"合约杀手是合约杀手奖励目标的一部分。","tactics":"","stats":{"hull":[1,2,2],"sys":[1,2,2],"agi":[1,2,2],"eng":[1,2,2],"hp":[15,18,21],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,10,12],"speed":[5,5,5],"size":[1,1,1],"heatcap":[8,8,8],"save":[11,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"“重锤”卡宾枪","type":"Weapon","tags":[{"id":"tg_reliable","val":[2,3,4]}],"weapon_size":"重型","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"该武器的伤害无法以任何方式减免——通过装甲、抗性或其他方式。","id":"npcf_x_rc_3_1","base":true},{"name":"狩猎匕首","type":"Weapon","tags":[{"id":"tg_thrown","val":5}],"weapon_size":"副武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[5,6,7]}],"effect":"该武器的伤害无法以任何方式减免——通过装甲、抗性或其他方式。","id":"npcf_x_rc_3_2","base":true},{"name":"赚外快的","type":"Trait","tags":[],"effect":"合约杀手只能通过“合约杀手”奖励目标加入。目标随机确定一个 PC 作为杀手目标。合约杀手对其目标所有攻击，豁免和检定+1 准度。合约杀手忽略目标的隐形和匿迹状况。","id":"npcf_x_rc_3_3","base":true},{"name":"顶级掠食者","type":"Trait","tags":[],"effect":"合约杀手每轮执行两个互相分隔的回合。它具有+2 结构和压力。合约杀手无法使用模板进一步改造。","id":"npcf_x_rc_3_4","base":true,"bonus":{"structure":2,"stress":2,"activations":1}},{"name":"耸肩","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"合约杀手受到任意来源的伤害。","effect":"合约杀手获得对伤害的抗性。","id":"npcf_x_rc_3_5","base":true},{"name":"德瓦娜级 NHP","type":"System","tags":[{"id":"tg_limited","val":1}],"keywords":["AI"],"effect":"合约杀手可在任意时刻消耗 1 充能来激活该系统，并获得以下效果之一：• 在攻击前，它可直接声明攻击自动命中。• 在豁免或检定前，它可直接声明自动成功。• 它可立即清除影响它的状态或状况。","id":"npcf_x_rc_3_6","base":true},{"name":"阴影者炸药","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":1}],"effect":"合约杀手向射程 5 内的空间投掷魔影炸药，产生一个溅射 1 的隐藏烟雾区；它一直持续到合约杀手下一回合结束。若合约杀手在烟雾中结束回合，它会立即隐形和匿迹，直到它发起攻击或离开该区域。","id":"npcf_x_rc_3_7","base":true},{"name":"干扰者榴弹","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":1}],"effect":"合约杀手向射程 5 内的空间投掷干扰榴弹，产生一个溅射 2 的静滞区。该区域中的角色缓慢，并且必须通过系统豁免否则受扰。该两种状态都会持续到角色下一回合结束。","id":"npcf_x_rc_3_8","base":true},{"name":"毁灭者导弹","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_limited","val":1}],"effect":"合约杀手发射线形 8 的杀伤导弹。所有受影响角色必须通过敏捷豁免否则受到 6/8/10 燃烧。成功则伤害减半。","id":"npcf_x_rc_3_9","base":true}],"optional":[],"special":"奖励目标特殊","pack":"强化战斗","source":14},{"id":"npcc_x_rc_4","name":"最高领袖","role":"支援","role_en":"support","page":57,"pages":[57],"flavor":"最高领袖是斩首行动奖励目标的一部分。","tactics":"","stats":{"hull":[1,2,2],"sys":[1,2,2],"agi":[1,2,2],"eng":[1,2,2],"hp":[50,55,60],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,10,12],"speed":[4,4,4],"size":[1,1,1],"heatcap":[8,8,8],"save":[10,13,15],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"最高领袖","type":"Trait","tags":[],"effect":"最高领袖只能通过“斩首行动”奖励目标加入。最高领袖不是得分角色。","id":"npcf_x_rc_4_1","base":true},{"name":"耸肩","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"最高领袖受到任意来源的伤害。","effect":"最高领袖获得对伤害的抗性。","id":"npcf_x_rc_4_2","base":true},{"name":"我简单说两句","type":"Trait","tags":[],"effect":"最高领袖唯一能进行的攻击就是冲撞。最高领袖无法进行躲藏动作。","id":"npcf_x_rc_4_3","base":true},{"name":"前进！","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"选择视线感应内一个盟友角色，对方可立即推进。","id":"npcf_x_rc_4_4","base":true},{"name":"走向胜利！","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"选择视线感应内一个盟友角色，对方在所有攻击中+1 准度直到对方下一回合结束。","id":"npcf_x_rc_4_5","base":true}],"optional":[],"special":"奖励目标特殊","pack":"强化战斗","source":14},{"id":"npcc_x_rc_5","name":"炮兵阵地","role":"炮击","role_en":"artillery","page":59,"pages":[59],"flavor":"炮兵阵地是无尽轰炸奖励目标的一部分。","tactics":"","stats":{"hull":[0,0,0],"sys":[0,0,0],"agi":[0,0,0],"eng":[0,0,0],"hp":[40,50,60],"armor":[0,0,0],"evasion":[5,5,5],"edef":[5,5,5],"speed":[0,0,0],"size":[3,3,3],"heatcap":[0,0,0],"save":[0,0,0],"sensor":[0,0,0],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"惰性","type":"Trait","tags":[],"effect":"炮兵阵地是角色，但不会参与轮流进行的回合，也不会交战。它们不受除锁定外的所有移动、状态和状况的影响。炮兵阵地不是得分角色。","id":"npcf_x_rc_5_1","base":true},{"name":"阻燃","type":"Trait","tags":[],"effect":"炮兵阵地在受到初始燃烧伤害后立即清除所有燃烧标记。","id":"npcf_x_rc_5_2","base":true},{"name":"开炮！","type":"Trait","tags":[],"effect":"在每轮结束时，炮兵阵地向战场上随机确定的 PC 角色开炮。它无需视线，且具有无限的射程。在目标上安置溅射 2。然后，该溅射会偏离，并在随机确定的方向上挪动 1d6 空间，从而确定其最终位置。该区域内的角色受到 6/8/10 爆炸伤害。该区域内的所有地形都会自动摧毁，若溅射包括了炮兵阵地自身，它不会开炮。","id":"npcf_x_rc_5_3","base":true}],"optional":[],"special":"奖励目标特殊","pack":"强化战斗","source":14},{"id":"npcc_x_rc_6","name":"增幅器","role":"支援","role_en":"support","page":60,"pages":[60],"flavor":"微型增幅器以其惊人之速在战场上飞驰。它配备了一台专门的能量虹吸器，且目的明确：从敌人那里收集能量，分配给盟友增加其力量。一旦浸没在窃取能量中，增幅器就会变得极其危险，它能够分解其动力附件并与盟友永久结合，赋予它们更强大的能量以及其标志性的能量虹吸能力。","tactics":"增幅器以两种模式作用。若它失去护盾，就必须冒险使用其近距离汲取光束来参与战斗并收集能量。一旦它收集护盾，它就会成为玩家的主要目标，他们会试图在它它传递护盾之前移除它。","stats":{"hull":[-3,-3,-3],"sys":[2,2,4],"agi":[3,4,5],"eng":[1,1,1],"hp":[8,8,8],"armor":[0,0,0],"evasion":[14,16,18],"edef":[10,12,14],"speed":[6,6,6],"size":[0.5,0.5,0.5],"heatcap":[5,5,5],"save":[10,12,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"汲取光束","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[1,1,1],"range":[{"type":"Range","val":5}],"damage":[{"type":"Energy","val":[1,2,3]}],"effect":"成功攻击敌方角色后，该角色获得 4/5/6 护盾。","id":"npcf_x_rc_6_1","base":true},{"name":"增幅","type":"System","tags":[{"id":"tg_full_action"}],"effect":"增幅器只有在当前具有护盾情况下才能执行此动作。以感应内的一个盟友角色为目标。增幅器从战场上移除，在场景结束前与目标永久结合。目标获得等同增幅器上的护盾，在拥有任意护盾期间所有攻击、豁免和检定+1 准度。此外，该角色还获得汲取光束武器。一个角色只能被增幅 1/场景。","id":"npcf_x_rc_6_2","base":true},{"name":"SCC 半身套组","type":"System","tags":[],"effect":"增幅器可悬浮，但在任意表面上方不得超过 3 空间。","id":"npcf_x_rc_6_3","base":true},{"name":"促进","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"感应内的一个盟友角色获得等同增幅器上的护盾。增幅器失去所有护盾。","id":"npcf_x_rc_6_4","base":true}],"optional":[{"name":"改良促进","type":"Trait","tags":[],"effect":"增幅器可同时促进 2 个盟友而非 1 个。","id":"npcf_x_rc_6_5","base":false},{"name":"焕然增幅","type":"Trait","tags":[],"effect":"当增幅器使用增幅时，目标角色可立即在该轮中额外进行一个回合。","id":"npcf_x_rc_6_6","base":false},{"name":"CQB 专家","type":"Trait","tags":[],"effect":"汲取光束变为威胁 3。","id":"npcf_x_rc_6_7","base":false},{"name":"指挥中心","type":"Trait","tags":[],"effect":"此拆除目标射程 3 内盟友角色可重新进行豁免和检定。","id":"npcf_x_rc_6_8","base":false},{"name":"增加输出","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"增幅器将其当前护盾翻倍。它不可超过 8/10/12 护盾。","id":"npcf_x_rc_6_9","base":false},{"name":"回避措施","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"增幅器失去所有护盾。","effect":"增幅器可立即移动等同其速度，忽略交战和反应。","id":"npcf_x_rc_6_10","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_7","name":"蛮兽","role":"生物","role_en":"biological","page":61,"pages":[61],"flavor":"蛮兽是笨重的生物兵器，通常由改良巨型动物制成，但有时甚至可以是人类。这些奴隶兽因生长刺激和类固醇而膨胀到惊人比例，通常出现在竞技场上为大众娱乐，其侵略性会在那里展现得淋漓尽致。通过植入其小脑的抑制剂芯片，蛮兽萎缩的大脑得以控制，有效地将其化为顺从的肌肉构造。","tactics":"鉴于蛮兽的猛摔能力，它可轻松将任何计划搞得一团糟，并这样做的同时造成一定伤害。虽然蛮兽有大量 HP，但它们没有装甲，很容易倒在集火攻击中。若蛮兽失效，玩家可接管它并派它去对付敌人，让敌人尝到自己的苦果。","stats":{"hull":[4,5,6],"sys":[-2,-1,0],"agi":[-1,-1,-1],"eng":[0,0,0],"hp":[25,30,35],"armor":[0,0,0],"evasion":[6,8,8],"edef":[8,8,8],"speed":[3,3,3],"size":[2,2,2],"heatcap":[0,0,0],"save":[11,13,15],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"肉肉拳","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","on_hit":"目标被擒拿。","id":"npcf_x_rc_7_1","base":true},{"name":"猛摔","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"只有当蛮兽擒拿一个比自己大小相等或更小的角色时才能执行该动作。角色被推离蛮兽 5 空间。若它与另一角色或地形发生碰撞，它将击倒伏卧。","id":"npcf_x_rc_7_2","base":true},{"name":"痛苦反射","type":"Trait","tags":[],"effect":"当每轮蛮兽首次受到不足以摧毁它的伤害时，它可立即执行任何快速动作，即使还不是它的回合，并且忽略对重复执行动作的限制。","id":"npcf_x_rc_7_3","base":true},{"name":"抑制芯片","type":"Trait","tags":[],"effect":"尽管蛮兽是生物，但它并不免疫科技动作和科技攻击。当蛮兽被摧毁时，它首先移动 5 空间，并使用肉肉拳进行单次攻击。在此期间它对伤害免疫并且所有影响它的擒拿立即结束。其移动方向和目标由最接近的玩家角色来选择。","id":"npcf_x_rc_7_4","base":true}],"optional":[{"name":"泰山压顶","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":5}],"effect":"邻近的角色必须进行机体豁免否则受到 10/14/18 动能伤害并击倒伏卧。检定成功则伤害减半并保持站立。","id":"npcf_x_rc_7_5","base":false},{"name":"殖装武器","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"在非蛮兽回合时，该武器+1 准度。","id":"npcf_x_rc_7_6","base":false},{"name":"激素泵","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_recharge","val":4}],"effect":"以一个协定，蛮兽可选择以下增益之一，这些增益将持续到它下一回合开始。• 侵略：蛮兽可用肉肉拳进行弹幕攻击，进行两次攻击而非一次。• 坦克：每当蛮兽到攻击时，掷一个 d6。结果为 5+则蛮兽获得对所有造成伤害的抗性。• 野性：蛮兽速度翻倍。","id":"npcf_x_rc_7_7","base":false},{"name":"报复","type":"Trait","tags":[],"effect":"每当蛮兽受到伤害时其下次攻击额外造成+2/+3/+4 伤害。该加值最多可叠加 8。该加值在蛮兽发动攻击时丢失，或在他们下一回合结束时。","id":"npcf_x_rc_7_8","base":false},{"name":"野蛮","type":"Trait","tags":[],"effect":"当蛮兽被摧毁时，它可进行系统检定。成功则蛮兽在抑制芯片中自行移动选择目标，代替玩家的选择。","id":"npcf_x_rc_7_9","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_8","name":"十字军","role":"支援","role_en":"support","page":62,"pages":[62],"flavor":"十字军机甲常作为正面攻击的重心，是长矛尖端最前沿的行进者，是保持盟友高昂士气的提振者。那些驾驶十字军的人往往极富魅力、是本地英雄或精神领袖。它们的存在可激励周边人，去克服他们机械构造的物理限制。这种效果通常以释放净化和重置盟友系统的网状系统洗涤器的激增来强化，使其即使在最激烈的战斗中也能以峰值容量运行。","tactics":"十字军机甲是种有能力帮助其他机甲维持 100%运转的支援机甲。在其他支援职业机甲无法积极参战的情况下，十字军的长剑不应被低估，尤其是对聚集的敌人而言。十字军可成为一支小部队的强大核心，制止敌人可能向他们投掷的大量肮脏伎俩。","stats":{"hull":[2,3,4],"sys":[-2,-2,-2],"agi":[0,0,0],"eng":[0,0,0],"hp":[20,22,24],"armor":[2,2,2],"evasion":[8,10,12],"edef":[8,10,12],"speed":[4,4,4],"size":[2,2,2],"heatcap":[5,6,7],"save":[11,13,15],"sensor":[3,3,3],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"长剑","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[5,6,7]}],"effect":"每当使用该武器进行攻击时，它可对威胁内不同角色进行第二次攻击。","id":"npcf_x_rc_8_1","base":true},{"name":"激励光环","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"十字军可用一个快速动作激活激励光环。十字军感应内的盟军角色免疫俯卧、缓慢、固定、受损、受扰和眩晕，并立即清除这些影响，只要它们非自主造成。激励光环持续到十字军下一回合结束。","id":"npcf_x_rc_8_2","base":true},{"name":"战斗口号","type":"Trait","tags":[{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"这一快速动作只有在激励光环激活时可执行，在受到激励光环影响的盟友角色会获得对所有伤害的抗性。","id":"npcf_x_rc_8_3","base":true}],"optional":[{"name":"英雄冲锋","type":"Trait","tags":[{"id":"tg_recharge","val":6}],"effect":"当十字军激活激励光环时，它和受影响盟友角色可立即向离它们最近的敌方角色推进。","id":"npcf_x_rc_8_4","base":false},{"name":"震慑之吼","type":"Trait","tags":[{"id":"tg_recharge","val":6}],"effect":"当十字军激活激励光环时，十字军感应内的敌方角色必须进行机体豁免否则伏卧。","id":"npcf_x_rc_8_5","base":false},{"name":"根深蒂固","type":"Trait","tags":[],"effect":"十字军免疫来自敌方角色强迫的非自主移动。","id":"npcf_x_rc_8_6","base":false},{"name":"死亡抗拒","type":"System","tags":[{"id":"tg_shield"}],"effect":"每轮十字军首次被远程或近战攻击成功命中的所有伤害降为 0。","id":"npcf_x_rc_8_7","base":false},{"name":"塔盾","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"只要该武器未被摧毁，十字军就获得+1 装甲，邻近的盟军角色可使用十字军作为硬性掩护。","id":"npcf_x_rc_8_8","base":false,"bonus":{"armor":1}}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_9","name":"刽子手","role":"操纵","role_en":"controller","page":63,"pages":[63],"flavor":"刽子手原型机常在需要做出重大声明时发挥作用。这些可畏的机甲在设计上古老而威严，无情地向目标行进。一旦受害者被刽子手锋利的爪子抓住，它就会开始用超巨型刀刃来犹如烤鸡般慢慢转动。刽子手式机甲所做的一切都充满残忍暴力，它是种心理武器而不单单是物理武器，任何目睹其可怕表现的人都会感到恐惧。","tactics":"刽子手擅长孤立单独目标并终结受伤的敌人。其恐惧的氛围意味着敌人很难获得盟友帮助，而刽子手的威严使他们难以逃脱。在与某人擒拿后，在范围内集火刽子手将是最高优先级，以免被擒拿者在下一轮遭到处决。","stats":{"hull":[4,5,6],"sys":[-2,-2,-2],"agi":[0,0,0],"eng":[1,2,3],"hp":[15,18,21],"armor":[2,2,2],"evasion":[8,10,12],"edef":[8,8,8],"speed":[4,4,4],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"处刑之刃","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[],"effect":"该武器只能攻击被刽子手擒拿的角色，且只有在刽子手擒拿控制情况下。它造成等同于目标最大 HP 一半的伤害。","id":"npcf_x_rc_9_1","base":true},{"name":"机甲捕手","type":"Trait","tags":[],"effect":"刽子手擒拿获得+1 准度，在攻击被其擒拿的目标时+1准度。刽子手在擒拿时视为大小 3。","id":"npcf_x_rc_9_2","base":true},{"name":"请到断头台","type":"Trait","tags":[],"effect":"当刽子手擒拿控制时：• 它获得硬性掩护。• 在刽子手感应内的敌方角色会缓慢。• 被擒拿角色不受所有由刽子手外引起的非自主移动的影响。","id":"npcf_x_rc_9_3","base":true}],"optional":[{"name":"肉钩","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"","on_hit":"目标必须进行机体对抗检定。若刽子手胜，对方将被拉到刽子手邻近（或尽可能靠近）。若对方因此邻近刽子手，便立即被擒拿。","id":"npcf_x_rc_9_4","base":false},{"name":"内脏暴击","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[],"effect":"该武器只用于对付刽子手正在擒拿的角色。","on_hit":"目标受扰直到对方下一回合结束。","id":"npcf_x_rc_9_5","base":false},{"name":"如坠冰窖","type":"Trait","tags":[],"effect":"每当刽子手使敌方角色受到结构伤害时，视线内所有敌方角色必须进行系统豁免。失败则固定直到对方下一回合结束。","id":"npcf_x_rc_9_6","base":false},{"name":"斩立决","type":"System","tags":[{"id":"tg_shield"}],"effect":"擒拿时，刽子手获得对所有伤害的抗性。","id":"npcf_x_rc_9_7","base":false},{"name":"以神之名铸就","type":"System","tags":[],"effect":"处刑之刃造成的伤害等同目标最大 HP。","id":"npcf_x_rc_9_8","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_10","name":"要塞","role":"卫兵","role_en":"defender","page":64,"pages":[64],"flavor":"要塞是机械化作战、攻城作战和周边防御作战中相对较新的开发成功。这些巨像底盘配有硬化装甲板，在将巨大气动尖刺撞向地面前，它们会用退化的肢体将自己拖到合适的位置。一旦固定不动，堡垒将投射出先进的军用级硬光屏障，将周边环境转变为易于防御的固点。","tactics":"要塞可作为防御行动的核心，为其盟友提供硬性掩护，并为火炮提供方便的有利位置。","stats":{"hull":[4,4,4],"sys":[1,1,1],"agi":[-3,-3,-3],"eng":[1,1,1],"hp":[20,25,30],"armor":[0,0,0],"evasion":[6,6,6],"edef":[6,6,6],"speed":[2,2,2],"size":[3,3,3],"heatcap":[10,10,10],"save":[10,12,14],"sensor":[6,6,6],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"迫击炮阵列","type":"Weapon","tags":[{"id":"tg_arcing"},{"id":"tg_loading"},{"id":"tg_knockback","val":2}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":20},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[3,5,7]}],"effect":"邻近的盟友角色可用一个快速动作来重新装填该武器。","id":"npcf_x_rc_10_1","base":true},{"name":"部署","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"堡垒获得+2/3/4 装甲。它在场景结束前固定，对伏卧和非自主移动免疫。在射程 3 内自由空间任意位置部署 2 个线形 3 截面大小 1 不可摧毁的硬性掩护。它们持续到堡垒被摧毁。一旦部署，堡垒将在战场剩余时间内维持部署状态，无法再次执行该动作。","id":"npcf_x_rc_10_2","base":true},{"name":"城墙壁垒","type":"Trait","tags":[],"effect":"堡垒可容纳一个大小更小的盟友角色。邻近的盟军角色可用一个快速动作进入堡垒。一旦进入，它共享堡垒空间，并获益与硬性掩护以及对所有伤害的抗性，并对所有非自主移动免疫。它可用一个协定离开堡垒，将自己安置在一个邻近的自由空间。若堡垒被毁，它会被安置在残骸邻近。一个盟友角色可在堡垒内开始战斗场景。","id":"npcf_x_rc_10_3","base":true},{"name":"围攻装甲","type":"Trait","tags":[],"effect":"堡垒对射程 3 外的所有攻击伤害具有抗性。","id":"npcf_x_rc_10_4","base":true}],"optional":[{"name":"发射甲板","type":"System","tags":[{"id":"tg_protocol"}],"effect":"当一个角色以协定离开堡垒时，可飞行 6 空间。它必须在坚实表面上结束该移动否则开始坠落。","id":"npcf_x_rc_10_5","base":false},{"name":"大型防御工事","type":"Trait","tags":[],"effect":"部署时创造 4 个硬性掩护而非 2 个。","id":"npcf_x_rc_10_6","base":false},{"name":"定向阵列","type":"System","tags":[],"effect":"占领要塞的角色在攻击中+1 准度。","id":"npcf_x_rc_10_7","base":false},{"name":"内置自动装载机","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"一个邻近的盟军角色可重新装填所有武器。","id":"npcf_x_rc_10_8","base":false},{"name":"轨道陨落","type":"Trait","tags":[],"effect":"堡垒（以及里面的任意角色）不会部署在战场上。相反，在战场上任意位置标记一个溅射 3 区域，并为其分配一个数字。所有角色都知晓该区域和数字。在对应数字那轮结束时，区域中的所有地形都被摧毁，所有角色都被推出区域（即使对非自主移动免疫），角色也必须进行机体豁免否则受到 5/8/11爆炸伤害，成功则伤害减半。然后将堡垒放置在该区域中心。","id":"npcf_x_rc_10_9","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_11","name":"军团士兵","role":"突击","role_en":"striker","page":65,"pages":[65],"flavor":"军团级机甲是指挥官可使用最便宜的战斗骨架。配备最基本装备，操作这些机甲的驾驶员很快就学会了相互醒来而不是低于标准的装备。众所周知，军团士兵在紧密团结的部队中作战，偶尔会打出超越其体重级别的效果，干翻那些装备备更好价格更高的骨架。尽管有这些罕见的团队协作壮举，但部署军团士兵的指挥官这样做的原因很明显，那就是步步为营。","tactics":"军团士兵提供了种低等兵的替代品，为“填线”机甲提供了更连贯的感觉，而不会在伤害、热度或激活方面碾压玩家。一个军团士兵部队提供一个突击 NPC 的平均伤害，同时覆盖更大的战场面积。","stats":{"hull":[0,1,0],"sys":[0,1,0],"agi":[0,1,0],"eng":[0,1,0],"hp":[4,5,6],"armor":[0,0,0],"evasion":[7,9,11],"edef":[7,9,11],"speed":[4,4,4],"size":[1,1,1],"heatcap":[2,2,2],"save":[10,10,10],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"下挂刺刀卡宾枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10},{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[2,3,4]}],"effect":"该武器既可作为远程武器，也可用作近战武器。若作为近战武器，它将获得 AP。","id":"npcf_x_rc_11_1","base":true},{"name":"军团","type":"Trait","tags":[],"effect":"军团士兵通常 4 个一组的方式部署，称为部队。一个部队中的所有角色同时进行回合，同时开始和结束一个回合。部队中每个角色都必须在另一位军团士兵前完全结算自己的所有动作。每个军团士兵只能执行一次快速动作，且只能执行推进、交火和守望。军团士兵可能永远不会是低等兵、精英、指挥官、老兵或超体。","id":"npcf_x_rc_11_2","base":true},{"name":"内聚力","type":"Trait","tags":[],"effect":"在部队回合开始时，任何不在同一部队至少一名其他军团士兵感应内的军团士兵会受扰直到对方回合结束。若该部队仅包含一名军团士兵，则该规则不适用。","id":"npcf_x_rc_11_3","base":true}],"optional":[{"name":"高级军官","type":"Trait","tags":[],"effect":"当军团士兵在指挥官模板 NPC 感应内时，攻击、检定和豁免+1 准度。","id":"npcf_x_rc_11_4","base":false},{"name":"横队","type":"Trait","tags":[],"effect":"当与同一部队的角色邻近时，该角色对伤害具有抗性，其远程攻击忽略掩护。","id":"npcf_x_rc_11_5","base":false},{"name":"刺刀冲锋","type":"Trait","tags":[],"effect":"1/场景，你可在该部队开始时宣布其正在执行刺刀冲锋。单位中所有角色在此回合内只能进行推进。在完成推进后，它们可使用下挂刺刀卡宾枪对邻近角色进行近战攻击。","id":"npcf_x_rc_11_6","base":false},{"name":"支援武器","type":"Trait","tags":[],"effect":"部队中的一个角色携带支援武器。","id":"npcf_x_rc_11_7","base":false},{"name":"突击队","type":"Trait","tags":[],"effect":"军团士兵可执行锁定快速科技动作。1/场景，在部队回合开始时，部队中所有角色可隐形直到部队下一回合开始。","id":"npcf_x_rc_11_8","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_12","name":"辰星","role":"操纵","role_en":"controller","page":66,"pages":[66],"flavor":"辰星与其说是骨架产品，不如说是场绝望尖叫的赌博。辰星构型的机甲主要由叛乱团体使用并远程控制，通常不过是双腿上安装了个武器化反应堆。一旦被操纵就位，它们将开始不加区别地将核心热量排泄到地貌中。处理辰星非常危险，需要远程关闭反应堆，以免对其骨架造成过度损坏导致核连锁反应，摧毁大面积的任何存在。","tactics":"辰星是款体积庞大的机甲，最擅长吸引注意、区域拒止和冲击设防阵地。其极端坚固性和死亡时高伤性的威胁需协调一致的骇客攻击来关闭，或，进行极端高的远程攻击伤害来将其摧毁。一旦进入集群，辰星通常可向多个敌人释放热度和燃烧。在安置盟友时当心它的周围，辰星不分青红皂白。","stats":{"hull":[1,2,3],"sys":[0,0,0],"agi":[-2,-2,-2],"eng":[2,2,2],"hp":[10,15,20],"armor":[3,3,3],"evasion":[7,7,7],"edef":[8,10,12],"speed":[3,3,3],"size":[2,2,2],"heatcap":[6,6,6],"save":[12,15,18],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"围攻装甲","type":"Trait","tags":[],"effect":"辰星对射程 3 外的所有攻击伤害具有抗性。","id":"npcf_x_rc_12_1","base":true},{"name":"最终审判","type":"Trait","tags":[],"effect":"当辰星被摧毁时，若它没有暴露或没有被科技动作摧毁，它就会化为爆发 3 核火球。该区域内角色受到 15/20/25AP爆炸伤害，成功进行工程检定伤害减半。若最终审判触发，辰星不会留下残骸。","id":"npcf_x_rc_12_2","base":true},{"name":"故障通风口","type":"Trait","tags":[],"effect":"辰星永远无法清除暴露。","id":"npcf_x_rc_12_3","base":true},{"name":"根深蒂固","type":"Trait","tags":[],"effect":"辰星免疫来自敌方角色强迫的非自主移动。","id":"npcf_x_rc_12_4","base":true},{"name":"暴露核心","type":"System","tags":[{"id":"tg_full_action"}],"effect":"辰星打开反应堆防爆板。爆发 3 中的角色受到 4/6/8 燃烧和 2/4/6 热度，成功进行工程豁免伤害和热度减半。","id":"npcf_x_rc_12_5","base":true}],"optional":[{"name":"大红按钮","type":"System","tags":[{"id":"tg_protocol"}],"effect":"若没有暴露，辰星会在下一轮结束时自动引爆，如同最终审判。","id":"npcf_x_rc_12_6","base":false},{"name":"隔热","type":"Trait","tags":[],"effect":"辰星对燃烧免疫。","id":"npcf_x_rc_12_7","base":false},{"name":"无屏蔽反应堆","type":"Trait","tags":[],"effect":"角色开始回合中与辰星邻近，或在该回合中首次与辰星邻近，则受到 2/3/4 热度。","id":"npcf_x_rc_12_8","base":false},{"name":"一窥炉心","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"以一个快速动作，释放锥形 7 反应堆闪光。敌对角色必须进行系统豁免。受影响角色失败则视线只能绘制邻近空间直到对方下一回合结束。","id":"npcf_x_rc_12_9","base":false},{"name":"脏弹","type":"Trait","tags":[],"effect":"最终审判触发后，爆发区域持续到场景结束。该区域内角色将获得软性掩护。在轮内首次进入或在区域内开始回合的角色受到 3 燃烧。","id":"npcf_x_rc_12_10","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_13","name":"死灵法师","role":"突击","role_en":"striker","page":67,"pages":[67],"flavor":"死灵法师模式组（PG）是相对罕见具有最前沿纳米技术的 PG。在战场上，这些特殊纳米体犹如窒息恶臭般包围着死灵法师。被称为“拉撒路沼泽”的它们主要指令是将在战斗中倒下的机甲改装成简单思维体但有效的攻击无人机。死灵法师令人畏惧地扭曲腐化倒下盟友的金属和内在，使其化为能更好在战斗中为其服务的全新姿态。","tactics":"死灵法师擅长在中场游走，鉴于其能力，在那里它们相对安全。一旦战斗开始并制造出残骸，死灵法师就可以转变为一个更主动的角色。","stats":{"hull":[-1,-1,-1],"sys":[2,3,4],"agi":[1,2,3],"eng":[1,1,1],"hp":[12,14,16],"armor":[0,0,0],"evasion":[8,10,12],"edef":[10,13,16],"speed":[4,4,4],"size":[1,1,1],"heatcap":[5,5,5],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"拉撒路巢房","type":"Weapon","tags":[{"id":"tg_smart"},{"id":"tg_seeking"}],"weapon_size":"主武器","weapon_kind":"巢房","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":10}],"damage":[{"type":"Energy","val":[3,5,7]}],"effect":"当此攻击命中一个低于其最大 HP 一半的盟友角色时，对方将失去 1 结构。每当此次攻击摧毁了一个会留下残骸的角色时，对方就会留下与其大小相等的尸仆无人机。","id":"npcf_x_rc_13_1","base":true},{"name":"创造尸仆","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"尸仆无人机（大小 1/2，HP4/5/6，回避与电子防御 6/8/10，速度 3，标签：无人机）以感应内的一具残骸为目标。在邻近安置与残骸大小相同的尸仆无人机，然后移除残骸。（最少 1 尸仆）死灵法师每轮制造的尸仆永远不能超过 3 个，无论它使用哪种能力。在死灵法师回合结束时，它创造的尸仆按顺序进行回合。除非与之相邻，否则尸仆必须始终全速向最接近的敌方角色移动。每尸仆拥有一个快速动作，它必须使用该动作来推进或近战攻击，此次攻击威胁 1，命中+1/+2/+3，伤害 4/5/6 动能。此外，尸仆可进行守望，但无法执行其他动作，也无法留下残骸。每当死灵法师被摧毁时，它所创造的所有尸仆也会被摧毁。","id":"npcf_x_rc_13_2","base":true},{"name":"腐朽光环","type":"Trait","tags":[],"effect":"死灵法师射程 2 内的敌方角色离散。","id":"npcf_x_rc_13_3","base":true},{"name":"服从","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"死灵法师在盟友角色（包括尸仆无人机）射程 3 内受到远程或近战攻击。","effect":"盟友角色被攻击命中，受到所有伤害和效果。","id":"npcf_x_rc_13_4","base":true}],"optional":[{"name":"装甲束缚","type":"Trait","tags":[],"effect":"该死灵法师创造的尸仆具有 1 装甲。","id":"npcf_x_rc_13_5","base":false},{"name":"死亡之握","type":"Trait","tags":[],"effect":"每当尸仆攻击命中时，它会自动擒拿目标。","id":"npcf_x_rc_13_6","base":false},{"name":"永恒仆人","type":"Trait","tags":[],"effect":"每当一个角色因服从而被摧毁时，它们不会留下残骸，而是留下与其大小相等的尸仆。不会留下残骸的角色不会创造出尸仆。","id":"npcf_x_rc_13_7","base":false},{"name":"指挥尸群","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"死灵法师感应内的任意尸仆立即推进。","id":"npcf_x_rc_13_8","base":false},{"name":"大复活术","type":"System","tags":[{"id":"tg_full_action"}],"effect":"死灵法师可用一个完整动作使用创造尸仆，目标为最多 3个残骸而非一个。","id":"npcf_x_rc_13_9","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_14","name":"诺斯费拉图","role":"突击","role_en":"striker","page":68,"pages":[68],"flavor":"诺斯费拉图类别骨架是极度专业的机甲，以至于只有 3 家制造商生产。配备先进虚空核心反应堆，诺斯费拉图能量特征极其难以辨识，这使其成为秘密任务和渗透任务的理想选择。","tactics":"诺斯费拉图是种快速危险的突击机，擅长猎杀依赖大量热度积累的敌人。它们天生的隐形能力和抽搐机动特征使它们能够相对安全地拉近距离。一旦暴露，诺斯费拉图在进攻上变得更加危险，同时也会失去大部分防守潜力。","stats":{"hull":[-2,-2,-2],"sys":[-1,-1,-1],"agi":[2,3,4],"eng":[4,5,6],"hp":[10,10,10],"armor":[0,0,0],"evasion":[10,13,16],"edef":[8,8,8],"speed":[6,6,6],"size":[1,1,1],"heatcap":[10,10,10],"save":[10,12,14],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"獠牙","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[2,3,4]}],"effect":"","on_hit":"敌方角色清除所有热度，此次攻击造成的额外伤害等同清除的热度。诺斯费拉图获得同等数量的护盾和热度。","id":"npcf_x_rc_14_1","base":true},{"name":"过热利爪","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Energy","val":[10,12,14]}],"effect":"该武器只能在诺斯费拉图暴露下才能使用。","id":"npcf_x_rc_14_2","base":true},{"name":"渴血迷乱","type":"Trait","tags":[],"effect":"每当诺斯费拉图因失去压力而受损时，它可选择暴露。暴露时：• 诺斯费拉图所有攻击、豁免和检定+1 准度。• 若它拥有护盾，则对所有伤害具有抗性。• 无论何时移动都忽略交战和反应。","id":"npcf_x_rc_14_3","base":true},{"name":"耐心的捕食者","type":"Trait","tags":[],"effect":"未暴露时，诺斯费拉图隐形。","id":"npcf_x_rc_14_4","base":true},{"name":"抽搐机动","type":"Trait","tags":[],"effect":"每当诺斯费拉图被攻击失误时，它可立即移动 2 空间。此次移动忽略交战和反应。","id":"npcf_x_rc_14_5","base":true}],"optional":[{"name":"无屏蔽反应堆","type":"Trait","tags":[],"effect":"角色开始回合中与辰星邻近，或在该回合中首次与诺斯费拉图邻近，则受到 2/3/4 热度。","id":"npcf_x_rc_14_6","base":false},{"name":"蒸汽喷气发动机","type":"Trait","tags":[],"effect":"诺斯费拉图可在暴露时悬浮。","id":"npcf_x_rc_14_7","base":false},{"name":"诅咒","type":"System","tags":[{"id":"tg_limited","val":1}],"effect":"在用獠牙攻击敌方角色后消耗 1 充能。在场景结束前，角色若不处于超温危域便受扰。它可用一个完整动作通过工程检定来消除这种影响。","id":"npcf_x_rc_14_8","base":false},{"name":"尖啸","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":6}],"effect":"诺斯费拉图可在锥形 5 区域释放出可怕尖叫。该区域的角色必须进行系统豁免否则受扰直到下一回合结束。成功则对方受损代替。","id":"npcf_x_rc_14_9","base":false},{"name":"热源搜寻","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个敌方角色进入超温危域。","effect":"诺斯费拉图可立即向它们推进。","id":"npcf_x_rc_14_10","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_rc_15","name":"幻影","role":"炮击","role_en":"artillery","page":69,"pages":[69,70],"flavor":"幻影类别骨架利用强大的纳米反射虫群生成全息诱饵，用实时渲染的软光诱饵饱和指定区域。幻影的反对者，除非传感器拥有强大的处理能力支持，否则无法充分解决其目标定位解决方案，它们经常意识到自己的人数至少是五比一，难以理解其系统注册的目标数量。一直以来，幻影都在诱饵之间进进出出，使用强大的棱镜步枪在自己的军团中发起进攻。射击，寻找新的位置，射击，如此往复，幻影之名，当之无愧。","tactics":"尽管防御数据普普通通，但由于其全息诱饵能力，幻影很难被击败。其棱镜步枪是种强大的线形武器，再加上它们通过全息成像扩展棱镜步枪的能力，意味着它们可时刻保持警惕，以最大限度地增加目标数量。幻影是种几乎持续不断的威胁，它确保敌人始终踮着脚尖起舞。","stats":{"hull":[-2,-1,-2],"sys":[3,4,3],"agi":[3,4,3],"eng":[-1,0,-1],"hp":[10,12,14],"armor":[0,0,0],"evasion":[8,10,12],"edef":[10,13,16],"speed":[4,4,4],"size":[1,1,1],"heatcap":[6,6,6],"save":[12,14,16],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"生成诱饵","type":"System","tags":[{"id":"tg_full_action"}],"effect":"幻影在视线感应内的自由空间内创造 4 个大小 1 的全息投影。全息投影是 HP1 的物品，与制造它们的幻影具有相同回避和电子防御。全息投影可通过攻击或扫描来破坏。全息投影提供软性掩护。角色可占据与全息投影相同的空间。若幻影被摧毁，它所有的全息投影都被摧毁。幻影在战场上存在任意全息投影则它无法再执行该动作。重复数字特征，快速行动幻影在传感器和视线内创建全息图。","id":"npcf_x_rc_15_1","base":true},{"name":"补充数字","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"幻影在视线感应内创造一个全息投影。","id":"npcf_x_rc_15_2","base":true},{"name":"全息诱饵","type":"Trait","tags":[],"effect":"在攻击幻影前，角色必须先进行系统豁免。若成功，攻击正常执行。若失败，幻影会在其感应内（如果可能的话）瞬间移动代替全息投影之一。这以非自主移动结算。若如此行事，全息投影全部摧毁，攻击失误，幻影获得对该攻击所伤害和效果的免疫。","id":"npcf_x_rc_15_3","base":true},{"name":"折射光束","type":"System","tags":[],"effect":"每当棱镜步枪触及全息投影时，线形在那里停止。然后你可从全息投影的位置向任意方向画一条新的线形 10，继续攻击。根据该点确定覆盖范围。新线形可继续触及其他全息投影并以此法延伸自己。角色不能被攻击命中多次。全息投影无法被用来延长攻击多次。","id":"npcf_x_rc_15_4","base":true}],"optional":[{"name":"全息军团","type":"Trait","tags":[],"effect":"生成诱饵会生成 6 个全息投影而非 4 个。","id":"npcf_x_rc_15_5","base":false},{"name":"炙热光束","type":"Trait","tags":[],"effect":"棱镜步枪造成燃烧而非能量伤害。","id":"npcf_x_rc_15_6","base":false},{"name":"畸变场","type":"Trait","tags":[],"effect":"进入全息投影空间的敌方角色会摧毁全息投影。然后该角色必须进行系统豁免否则受扰直到对方下一回合结束。","id":"npcf_x_rc_15_7","base":false},{"name":"伪造目标","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":6}],"trigger":"一个全息投影射程 5 内一个角色，无论盟友还是敌人，成为攻击或动作的目标。","effect":"摧毁全息投影，角色获得对此次攻击或动作的所有伤害和效果的免疫。","id":"npcf_x_rc_15_8","base":false},{"name":"改变位置","type":"System","tags":[{"id":"tg_protocol"}],"effect":"幻影与全息投影瞬间移动交换位置。全息投影占据幻影位置，而幻影占据全息投影位置或尽可能靠近。这视为非自主移动。","id":"npcf_x_rc_15_9","base":false}],"pack":"强化战斗","source":14},{"id":"npcc_x_mi_1","name":"毒士","role":"炮击","role_en":"artillery","page":70,"pages":[70],"flavor":"可以说，毒士级原型机甲最具代表性的便是 GMS 哈勃 TBK 机甲。该机甲由海西尼亚及其他星球的第二委员会研发并部署，用于“软目标清除”。其现代化后继机型保留了许多相同特点——厚重装甲与绝缘外壳，以及为远程武器配备的支架，使得毒士级机甲的驾驶员永远不必过于靠近其生化武器所造成的毁灭性影响。使用毒士级常见气态和液态弹药的机甲底盘，无一例外都被视为不符合“乌托邦支柱”原则，这使得该类机甲成为分离主义团体、第二委员会的残党或复兴党派，以及那些很可能已招致联盟愤怒的暴虐僭主的标志。然而，它们的武器系统仍像遥远的历史那样凶残有效。","tactics":"毒士是极具威胁的生化武器机甲，惩罚那些试图维持静止或占据控制区的玩家，它会用特种弹药迫击炮瞄准特定区域，在战场上散布毒气云以封锁要道。然而，高机动近战机会意识毒士防突进手段欠缺，远程穿甲火炮也同样如此。","stats":{"hull":[1,2,3],"sys":[-1,-1,0],"agi":[-1,0,1],"eng":[3,4,4],"hp":[10,13,15],"armor":[2,3,3],"evasion":[8,8,8],"edef":[8,8,8],"speed":[3,3,3],"size":[1,1,1],"heatcap":[9,12,12],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"特种弹药迫击炮","type":"Weapon","tags":[{"id":"tg_ordnance"},{"id":"tg_arcing"},{"id":"tg_heat_self","val":3}],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15},{"type":"Blast","val":2}],"damage":[{"type":"Explosive","val":[1,1,1]},{"type":"Burn","val":[4,5,6]}],"effect":"未命中：造成 1/2/3 燃烧。","id":"npcf_x_mi_1_1","base":true},{"name":"隔热","type":"Trait","tags":[],"effect":"毒士免疫燃烧。","id":"npcf_x_mi_1_2","base":true},{"name":"毒气弹播种器","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":5}],"effect":"选择感应内一个自由空间；该空间出现一片毒气云。首个穿过或邻近该空间的敌方角色受到 2/3/4 燃烧，且毒气云随即消散。毒气云在场景结束时自行消散。","id":"npcf_x_mi_1_3","base":true},{"name":"预瞄信标","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":3}],"effect":"选择感应内一个自由空间；使用毒士的特种弹药迫击炮攻击该空间爆发 2 内目标时+1 准度。该空间只能同时存在一个；若选择新空间，旧空间将消失。","id":"npcf_x_mi_1_4","base":true}],"optional":[{"name":"菌株突变","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":5}],"trigger":"感应内的一个敌方角色进行燃烧检定。","effect":"对方必须掷两次该检定，并取最差的结果。","id":"npcf_x_mi_1_5","base":false},{"name":"腐蚀轰炸","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":5}],"effect":"选择感应内地表一个空间；所有角色都知悉该空间被选定。毒士发射大规模腐蚀弹轰炸，下一轮结束时命中产生爆发 2 洪流。受影响区域内角色必须通过工程豁免。失败则失去 1 装甲（最低降至 0）直到其下一回合结束，并承受 6/8/10 燃烧，检定成功则伤害减半。","id":"npcf_x_mi_1_6","base":false},{"name":"全环境适应性改造","type":"Trait","tags":[],"effect":"毒士忽略困难地形和危险地形。","id":"npcf_x_mi_1_7","base":false},{"name":"化学喷洒器","type":"Weapon","tags":[{"id":"tg_heat_self","val":3}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[0,1,2],"accuracy":[0,0,0],"range":[{"type":"Cone","val":3}],"damage":[{"type":"Burn","val":[2,3,4]}],"effect":"","id":"npcf_x_mi_1_8","base":false},{"name":"自复制载体","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":5}],"trigger":"感应内的一个敌方角色清除燃烧。","effect":"其爆发 1 内其他敌方角色承受该角色清除燃烧的一半燃烧。","id":"npcf_x_mi_1_9","base":false}],"pack":"午夜伊菲革涅亚","source":16},{"id":"npcc_x_mi_2","name":"霜灵","role":"操纵/突击","page":71,"pages":[71,72],"flavor":"“霜灵级”原型机甲最初源自第二委员会军规级工程与工业骨架：首批机甲冷核运转过热，而通常用于战舰工程堆栈维护的技术，被精心微型化，以便在战场进行反应堆维护。霜灵的绝缘密封部分也常被用于维护第二委员会的总生物杀伤“全生态杀伤武器中不稳定的系统，尤其是联盟的舰载核武库。革命爆发时，许多霜灵驾驶员（冲突双方都有）发现，他们用于照料机甲核心处“笼中恒星”的系统和硬件工具，同样可用于攻防：这一教训至今仍为许多现代化机甲的驾驶员所用。","tactics":"霜灵是一款控制型机甲，它不像怨恨者那样通过使对方过热来惩罚那些在配置中严重依赖热度转化的玩家，而是将对方易于获取热度的特征转化为武器。使用零点系统链接来防止玩家因核子游侠或其他超温危域增益而获得伤害，或诱使玩家使用高热度系统和超限来为霜灵供能：然后，利用对方队友的狂妄，来对低热度容量的玩家施加压力，或使用“烟囱桩”标枪和“莱瓦汀”脉冲镭射炮网络封锁一个区域。然而，霜灵在能够利用其吸取的热度之前，很容易受到高输出对手的伤害，尽管其机体庞大，但仍需在其中等感应范围内谨慎操作。","stats":{"hull":[0,1,1],"sys":[3,4,5],"agi":[-2,-2,-2],"eng":[3,4,5],"hp":[15,18,21],"armor":[2,2,2],"evasion":[8,8,8],"edef":[8,8,8],"speed":[4,4,4],"size":[1,1,1],"heatcap":[6,8,10],"save":[13,15,17],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"冷却剂喷管","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Line","val":5},{"type":"Cone","val":3}],"damage":[{"type":"Explosive","val":[3,5,7]}],"effect":"会心一击：目标缓慢直到下一回合结束。","on_hit":"目标必须通过工程豁免，否则其速度-2（最低为 0），直到对方下一回合结束。该效果不可叠加。","id":"npcf_x_mi_2_1","base":true},{"name":"隔热","type":"Trait","tags":[],"effect":"霜灵免疫燃烧。","id":"npcf_x_mi_2_2","base":true},{"name":"“烟囱桩”标枪","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_heat_self","val":2}],"effect":"选择感应内一个自由空间，霜灵发射一架“烟囱桩”标枪（大小 1，9/12/15HP，6/8/10HC，10 回避/ED，标签：可展开）。霜灵每获得 1 电容充能，标枪就获得1 热度；以一个快速动作，或若标枪超过其热度容量，它将对爆发 2 内所有敌方角色造成等同当前热度 AP 能量伤害。若标枪因其他原因被摧毁，则它不会产生效果。","id":"npcf_x_mi_2_3","base":true},{"name":"零点系统链接","type":"Tech","tags":[{"id":"tg_quick_tech"}],"tech_type":"Quick","effect":"选择视线感应内一个敌方角色；该角色必须通过系统豁免，否则受到 3/4/5 能量伤害，并与霜灵的辅助催化反应堆链接。当被链接角色从任何来源获得热度（减免前），他们不会获得热度；相反，霜灵将获得与被链角色本获得热度数量的电容充能（最高 8/10/12）。霜灵一次只能链接一个角色，且被链角色不能被其他 NPC链接。被链角色可用一个快速动作通过工程豁免中断链接，当霜灵晕眩或受扰时，链接会自然中断。霜灵可用一个快速动作，消耗 1 电容器充能来对位于感应内且未被链接的敌方角色造成等量的热度（系统豁免成功时减半），或消耗 4/5/6 电容充能来清除邻近的一个盟友角色的暴露状况。","id":"npcf_x_mi_2_4","base":true}],"optional":[{"name":"调解杆分流","type":"Tech","tags":[{"id":"tg_quick_tech"},{"id":"tg_recharge","val":4}],"attack_bonus":[1,3,5],"tech_type":"Quick","effect":"霜灵对视线感应内一个角色执行科技攻击。成功则目标受到 4/5/6 能量伤害，并获得一个反应堆泄漏直到对方下一回合结束。当位于感应内的盟友角色对该角色发动攻击时，可用自由动作消耗反应堆泄漏以造成等同该角色热度一半的额外伤害。","id":"npcf_x_mi_2_5","base":false},{"name":"“莱瓦汀”脉冲镭射炮","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"在霜灵射程 2 内一个自由空间部署一台“莱瓦汀”发射器（大小 1/2，8/10/12HP、10 闪避/ED，标签：可展开），并指定以发射器为起始的线形 10。在霜灵回合结束时，它可为一台发射器重新定向线形。1/轮，霜灵每获得电容充能，发射器可自动开火，对线形内所有敌方角色造成等同霜灵当前电容充能的能量伤害。战场上可同时部署多台发射器；所有发射器在触发时同时开火，但若一个角色在同一回合内受到多台发射器的伤害，则他们只会受到第一台发射器+2/3/4 伤害。","id":"npcf_x_mi_2_6","base":false},{"name":"能斯特逆变器","type":"Trait","tags":[],"effect":"1/轮，若一个被链角色将获得足量热度以使其进入超温危域时，霜灵可选择不获得任何电容充能，转而对被链角色造成等同获得热度的燃烧。","id":"npcf_x_mi_2_7","base":false},{"name":"反应堆技师","type":"Trait","tags":[],"effect":"当霜灵清除盟友角色的暴露时，它可优化其反应堆流程；该角色下次获得热度时，改为获得热度 0。","id":"npcf_x_mi_2_8","base":false},{"name":"喷射泵迫击炮","type":"Weapon","tags":[{"id":"tg_arcing"}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[1,2,3]}],"effect":"霜灵在使用该武器攻击时，可消耗任意数量的电容充能，造成等同消耗数量的 X 额外能量伤害。","id":"npcf_x_mi_2_9","base":false}],"pack":"午夜伊菲革涅亚","source":16},{"id":"npcc_x_lt_1","name":"执法者","role":"卫兵/操纵","page":20,"pages":[20],"flavor":"最初为政治和文化贵宾的安全而开发的 GMS“主教”级安全平台，是基于 R 型埃佛勒斯代码库构建而成。其低廉简单的构造以及先进的威胁/输出调节器网络防御装甲，使其在军事化警察部队、雇佣兵组织和富裕海盗单位中广受欢迎，用于保护物质资产和攻击较弱且未骑乘的对手。如今，在散居国太空中，执法者这个名号已臭名昭著，尽管主教级平台的代码库升级已中止，但无数衍生版本和后续产品仍在无数国家和自治区内得到使用和生产。","tactics":"执法者是种擅长在战斗中与敌人近身肉搏的战士。可以将执法者部署在重要目标附近以保卫它们，或尽可能接近敌对角色以利用其强大的防御特性。","stats":{"hull":[2,3,4],"sys":[0,0,0],"agi":[0,0,0],"eng":[2,2,2],"hp":[15,15,20],"armor":[1,2,2],"evasion":[8,10,12],"edef":[10,12,14],"speed":[2,2,2],"size":[1,1,1],"heatcap":[8,8,8],"save":[12,14,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"镇暴加农炮","type":"Weapon","tags":[{"id":"tg_knockback","val":1}],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Explosive","val":[3,4,5]}],"effect":"该武器可对同一角色或不同角色共进行两次攻击。","on_hit":"该武器对交战目标+1 击退。","id":"npcf_x_lt_1_1","base":true},{"name":"保镖","type":"Trait","tags":[],"effect":"邻近盟友角色可用执法者作为硬性掩护。","id":"npcf_x_lt_1_2","base":true},{"name":"强化","type":"Trait","tags":[],"effect":"当执法者开始其回合时，它会清除所有护盾，然后每邻近一个敌方角色获得 5 护盾。","id":"npcf_x_lt_1_3","base":true},{"name":"恐吓","type":"Trait","tags":[],"effect":"当执法者拥有任意数量护盾时，它会造成两倍的击退，并被视为大小 10 用于冲撞、擒拿、交战和施加非自主移动。","id":"npcf_x_lt_1_4","base":true},{"name":"侵略者威慑","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"射程 3 内一个敌方角色移动或执行敌对动作。","effect":"执法者可率先移动到该角色邻近自由空间。触发角色必须进行敏捷豁免否则伏卧，并进行机体豁免否则自动被擒拿。","id":"npcf_x_lt_1_5","base":true}],"optional":[{"name":"危险起来","type":"Trait","tags":[],"effect":"拥有护盾时，执法者忽略掩护和交战惩罚，检定豁免+1 准度，并所有远程近战攻击+1/+2/+3 额外伤害。","id":"npcf_x_lt_1_6","base":false},{"name":"警戒尖兵","type":"Trait","tags":[],"effect":"执法者在所有武器上+1 威胁，并且它在反应之前或之后可移动 1 空间，该移动忽略反应和交战。","id":"npcf_x_lt_1_7","base":false},{"name":"“宙斯”破障雷暴发生器","type":"Weapon","tags":[{"id":"tg_knockback","val":2},{"id":"tg_loading"}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Energy","val":[4,6,8]}],"effect":"","on_hit":"目标必须通过工程豁免否则受扰直到对方下一回合结束，并伏卧。","id":"npcf_x_lt_1_8","base":false},{"name":"区域拒止阵列","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_loading"}],"effect":"锥形 5 或爆发 2 内的所有角色必须通过系统豁免，否则缓慢并受损直到对方下一回合结束。邻近的地方角色自动在豁免上失败。","id":"npcf_x_lt_1_9","base":false},{"name":"统治之墙","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_deployable"},{"id":"tg_limited","val":1}],"effect":"统治哨所（大小 1，HP5，装甲 1/2/3，回避 8/10/12，ED12/14/16，标签：可展开）执法者在射程 5 内自由空间部署 5 统治哨所。只要执法者在哨所的视线射程 5 内，就被视为与哨所邻近的敌方角色邻近，并适用于射程内的守望，强化和侵略者威慑，以及哨所造成的交战。","id":"npcf_x_lt_1_10","base":false}],"pack":"天堂末班车","source":17},{"id":"npcc_x_lt_2","name":"警卫","role":"炮击/操纵","page":21,"pages":[21],"flavor":"“伊内拉吉塔”雷霆风暴空卫底盘通常被视为现代警卫模式底盘设计的起源，尽管冲突和大型星际制造商的侵略性战术几乎掩盖了这种原型最初的生产线。警卫模式底盘是侦察和安全细节工作的理想选择，其强大的远程传感器、灵活多变的机动套组和重型火力对常规攻击构成强有力威慑。","tactics":"警卫作为脆弱但灵敏的猎人，擅长在开阔地带为敌人带去痛苦。利用它的“蜻蜓”陀螺仪旋翼，将其放置在可俯瞰高优先级通道的最佳视野位置，并使用[警卫-激活]来惩罚那些没有掩护的敌人。","stats":{"hull":[-2,-2,-2],"sys":[1,2,3],"agi":[0,0,0],"eng":[1,1,1],"hp":[8,8,8],"armor":[0,0,0],"evasion":[12,14,15],"edef":[10,12,14],"speed":[6,6,6],"size":[0.5,0.5,0.5],"heatcap":[5,5,5],"save":[11,13,15],"sensor":[15,15,15],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"钢锯链枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":15}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"攻击时：若目标对警卫没有掩护，则攻击将获得智慧和可靠 3/4/5。","id":"npcf_x_lt_2_1","base":true},{"name":"“蜻蜓”陀螺仪旋翼","type":"System","tags":[],"effect":"警卫移动时可悬浮，但必须在地面上结束移动否则开始坠落。","id":"npcf_x_lt_2_2","base":true},{"name":"无休炮火","type":"Trait","tags":[],"effect":"当警卫用武器伤害一个没有掩护的角色时，目标必须通过一次机体豁免否则缓慢直到下一回合结束。","id":"npcf_x_lt_2_3","base":true},{"name":"[警卫-激活]","type":"System","tags":[{"id":"tg_protocol"}],"effect":"警卫在下一回合开始前固定，只要这些角色在视线射程内，且对警卫没有掩护，就用钢锯链枪攻击所有敌方角色。","id":"npcf_x_lt_2_4","base":true}],"optional":[{"name":"凝视引擎","type":"Trait","tags":[],"effect":"回合结束时，警卫在其视线射程 8 内无掩护的一个空间上放置溅射 3 伪造体直到自身下一回合结束。警卫以及处于其视线感应内的盟友角色，在攻击该区域内内的角色时可重新掷骰并选择最高结果。","id":"npcf_x_lt_2_5","base":false},{"name":"黄夹克发射器","type":"Weapon","tags":[{"id":"tg_loading"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Explosive","val":[8,10,12]}],"effect":"以一个协定，你可指定射程内对警卫没有掩护的一个敌方角色为优先目标。若对方仍然在射程内，且在你下一回合结束时仍然没有掩护，你可用该武器以一个自由动作对其发起攻击，获得+1 准度，+10 射程，命中后+8 额外伤害。","id":"npcf_x_lt_2_6","base":false},{"name":"克隆火力无人机","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_drone"},{"id":"tg_limited","val":1}],"effect":"克隆火力无人机（大小 1/2，HP5/10/15，回避 10，电子防御 10，标签：无人机）警卫将一架克隆火力无人机部署到视线射程 5 内的自由空间。当这架无人机被部署时，无人机爆发 3 内始终被视为在警卫钢锯链枪视线射程内，忽略障碍并且对警卫而言失去掩护。","id":"npcf_x_lt_2_7","base":false},{"name":"狩猎者","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"警卫视线感应内一敌方角色在掩护外结束移动。","effect":"警卫直线向触发角色移动双倍速度，即使它被自己特征、系统或能力所固定也可以移动。","id":"npcf_x_lt_2_8","base":false},{"name":"反火力套组","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"激活后，警卫将固定，但每当一个无掩护敌方角色攻击警卫时，它可率先以一个反应用钢锯链枪攻击对方，若成功攻击则无效化触发的攻击或移动。警卫可用协定停止该系统。","id":"npcf_x_lt_2_9","base":false}],"pack":"天堂末班车","source":17},{"id":"npcc_x_gf_1","name":"洪水","role":"炮击/卫兵","page":257,"pages":[257],"flavor":"洪水原型底盘是 N+1 火力理论的逻辑极端。一把昂贵的大枪可能威力很优秀，但几把稍小的枪也能以少得多达到同样效果。当你可以买一万颗子弹把整个区域冲洗干净，为什么要浪费大钱在那些可能被 ECM 击中的高级导弹上？毕竟，它们中总有个会命中。","tactics":"洪水的主要策略是通过设置区域来抑制机动性，让它自动破坏任何进入区域的东西。当它持续开火，它的伤害会随着热度提高而增加——这是个潜在弱点，它需要接近热度上限才能造成最大伤害。","stats":{"hull":[1,2,3],"sys":[0,1,1],"agi":[-2,-2,-2],"eng":[2,3,5],"hp":[12,14,18],"armor":[1,1,1],"evasion":[7,8,7],"edef":[10,12,14],"speed":[3,3,3],"size":[2,2,2],"heatcap":[8,8,8],"save":[10,12,14],"sensor":[10,10,10],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"四联突击加农炮","type":"Weapon","tags":[{"id":"tg_reliable","val":[2,3,4]},{"id":"tg_heat_self","val":2}],"weapon_size":"超重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Line","val":8}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"","id":"npcf_x_gf_1_1","base":true},{"name":"铅雨区","type":"Trait","tags":[],"effect":"用四联突击加农炮开火后，洪水可用自由动作在同一线形 10 中创造一个铅雨区。若洪水移动，被摧毁，晕眩或受扰，或者再次发射武器，该区域立即结束。当某角色在该区域开始其回合或在回合中第一次进入该区域，洪水会自动对他们造成四联突击加农炮的可靠伤害。","id":"npcf_x_gf_1_2","base":true},{"name":"反应性防御系统","type":"System","tags":[],"effect":"洪水和邻近盟友在产生铅雨区期间获得软性掩护。","id":"npcf_x_gf_1_3","base":true},{"name":"自旋向上","type":"Trait","tags":[],"effect":"当洪水处于超温危域时，其四联突击加农炮造成+2 额外伤害，可靠伤害+1。","id":"npcf_x_gf_1_4","base":true}],"optional":[{"name":"默图尔停点","type":"Trait","tags":[],"effect":"当洪水清除所有热度时，可以接受等于热度上限一半的热度，使其进入超温危域。","id":"npcf_x_gf_1_5","base":false},{"name":"点防模式","type":"System","tags":[{"id":"tg_recharge","val":4},{"id":"tg_full_action"}],"effect":"洪水重构其骨架，转变为点防模式。直到下一回合开始，洪水固定，无法采取正常动作，但它会在自己周围投射一个爆发 3 点防御区。这是个铅雨区，只伤害敌人，为洪水及其盟友角色提供软性掩护和远程攻击伤害的抗性。","id":"npcf_x_gf_1_6","base":false},{"name":"子弹量大管饱","type":"Trait","tags":[],"effect":"使用洪水的四联突击加农炮攻击会忽略隐形。","id":"npcf_x_gf_1_7","base":false},{"name":"喷射然后祈祷","type":"Trait","tags":[{"id":"tg_protocol"},{"id":"tg_recharge","val":4}],"effect":"直到下一回合开始，洪水的四联突击加农炮获得不准，但其攻击和产生的铅雨区变成锥形 7。","id":"npcf_x_gf_1_8","base":false},{"name":"毁灭雹击","type":"Trait","tags":[],"effect":"在洪水的铅雨区内的角色会受损，并且当他们留在区域内时无法通过任何方式清除此状态。","id":"npcf_x_gf_1_9","base":false}],"pack":"浴金焰","source":19},{"id":"npcc_x_gf_2","name":"高球手","role":"突击","role_en":"striker","page":258,"pages":[258],"flavor":"作为长环残酷务实战斗方式的活例，高球手只不过是个覆盖着压力板的民用装载机骨架，挥舞着再利用化的采矿炸药。它们是种廉价、高效的力量倍增器，对软目标或机械化底盘的近距离编队非常有效。","tactics":"高球手是种近距离战斗者，专门惩罚聚集在一起的目标。它拥有宽泛的可选系统，使其攻击更具战术灵活性。值得注意的是，它可对自己所能造成的所有伤害具有抗性，因此无需太担心自己被爆炸击中。若它有多个可选系统来改造其采矿炸药攻击，它可以同时使用其中的任何一种。","stats":{"hull":[0,1,2],"sys":[-1,-1,0],"agi":[1,2,3],"eng":[1,1,2],"hp":[12,14,16],"armor":[1,1,1],"evasion":[8,10,12],"edef":[8,10,12],"speed":[4,4,4],"size":[1,1,1],"heatcap":[6,6,8],"save":[12,15,18],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"采矿炸药","type":"Weapon","tags":[{"id":"tg_arcing"}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Blast","val":1}],"damage":[{"type":"Explosive","val":[4,6,8]}],"effect":"高球手可使用该武器作为弹幕两部分，但目标区域不能重叠。该两个区域的角色都只会受到一次攻击，但高球手可选择伤害来自哪个区域。","id":"npcf_x_gf_2_1","base":true},{"name":"爆破镀层","type":"Trait","tags":[],"effect":"高球手对爆炸和来自溅射攻击和系统的伤害拥有抗性。","id":"npcf_x_gf_2_2","base":true},{"name":"CQB 的有趣选择","type":"Trait","tags":[],"effect":"高球手的采矿炸药攻击将自己包含在溅射范围时，便不会因交战而受到难度。","id":"npcf_x_gf_2_3","base":true},{"name":"烹饪","type":"Trait","tags":[],"effect":"当高球手机甲被毁时，它会立即进行两次采矿炸药攻击。两次攻击都+1 准度，并且溅射范围必须将高球手包含在内；这并非弹幕，所以区域可能会重叠并瞄准一个角色两次。在该过程中，驾驶员可能会弹射，当然也应该这样做。","id":"npcf_x_gf_2_4","base":true}],"optional":[{"name":"突击发射器","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_free_action"}],"effect":"高球手使采矿炸药在本回合的射程变为 15。任意溅射范围维持不变。","id":"npcf_x_gf_2_5","base":false},{"name":"专家拆除主义者","type":"Trait","tags":[],"effect":"在高球手的采矿炸药对区域内物品，地形和可展开的攻击会自动命中并造成 5/8/10AP 爆炸伤害。","id":"npcf_x_gf_2_6","base":false},{"name":"燃烧装药","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_free_action"}],"effect":"高球手使采矿炸药在本回合造成 3/4/5 燃烧伤害而非其常规伤害。","id":"npcf_x_gf_2_7","base":false},{"name":"动能炸药","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_free_action"}],"effect":"高球手使采矿炸药在本回合获得击退 2。","id":"npcf_x_gf_2_8","base":false},{"name":"特大号装药","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_free_action"}],"effect":"高球手使采矿炸药在本回合范围变溅射 2。任意射程保持不变。","id":"npcf_x_gf_2_9","base":false},{"name":"震波装药","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_free_action"}],"effect":"高球手使采矿炸药在本回合对成功命中的敌人进行机体豁免否则伏卧。","id":"npcf_x_gf_2_10","base":false}],"pack":"浴金焰","source":19},{"id":"npcc_x_gf_3","name":"平行体","role":"突击","role_en":"striker","page":259,"pages":[259,260],"flavor":"编写：UIB-terminalculate 恢复：UIB-katatric 清除申请：庄严守夜我可以确认属于“平行”模式组的机甲与卡利俄珀事件中联系人首次观察到的特征相匹配（见报告：灾厄轴心）。我们还在寻找最初的开发者。目前直观的猜测是 SSC，兵工厂，地平线，甚至真一神教，但在我看来，不可能是其中任何一个。这项技术甚至比最庞大的企业国都领先几十年，更不用说一群在车库里的邪教分子了。","tactics":"平行体是种机动性很强的突击机，它可以通过同时出现在两个地方来控制战场大片区域。相位回声让他们放置一个可以交换位置，避免伤害或进行反应攻击的替身。平行体的主要弱点在于其脆弱性；它依赖于谨慎走位和明智地使用皈依来避免高伤害攻击。它无法承受集火伤害，而且移除回声会阻碍它移动。","stats":{"hull":[0,0,0],"sys":[2,2,3],"agi":[2,2,3],"eng":[0,1,1],"hp":[12,14,18],"armor":[0,0,0],"evasion":[8,10,12],"edef":[10,12,14],"speed":[5,5,5],"size":[1,1,1],"heatcap":[6,8,8],"save":[11,13,16],"sensor":[5,5,5],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"可能性之刃","type":"Weapon","tags":[{"id":"tg_reliable","val":[3,4,5]}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[6,8,10]}],"effect":"","id":"npcf_x_gf_3_1","base":true},{"name":"异常运动","type":"Trait","tags":[],"effect":"平行体进行标准移动时瞬间移动。","id":"npcf_x_gf_3_2","base":true},{"name":"相位回声","type":"Trait","tags":[],"effect":"每当平行体瞬间移动时，它都会在之前占据的空间中产生一个回声。回声是与平行体一样大小的障碍物，有回避 10，电子防御 10，若受到任何伤害或热度就会被摧毁，并投射出与平行体武器相同的威胁范围。平行体同一时间只能拥有一个回声；创建一个新的会破坏旧的回声。它还获得皈依和非时序响应反应。若它被缓慢或固定，它就无法使用这些反应。\n【皈依】（反应，1/轮）触发：对平行体发起攻击。\n效果：平行体打断触发的攻击，并传送到它一个回声的空间并摧毁它。现在攻击的目标是它留下的新回声。若同一攻击的一部分也瞄准了它此前的回声，那么它现在瞄准了平行体。\n【非时序响应】（反应，1/轮）触发：一个敌对角色在平行体回声的威胁中开始移动（包括推进和其他动作）。\n效果：平行体立即瞬间移动到回声的空间并摧毁它，然后在敌对角色移动前使用交火作为同一反应的一部分。在先前占用的平行体空间中创建一个新回声。","id":"npcf_x_gf_3_3","base":true}],"optional":[{"name":"破碎之镜","type":"Reaction","tags":[{"id":"tg_round","val":1},{"id":"tg_recharge","val":6}],"trigger":"对平行体或其回声进行近战或远程攻击。","effect":"攻击者必须进行系统豁免。失败则攻击不会发生，攻击者和目标交换位置如同同时进行瞬间移动。然后攻击者必须对自己重复攻击。","id":"npcf_x_gf_3_4","base":false},{"name":"死亡行者","type":"Trait","tags":[],"effect":"每次战斗中，平行体第一次被摧毁时，若其仍有回声则不时为被击败。平行体下回合开始时，瞬间移动至回声，摧毁它并恢复 1HP。若其最后一个回声在下回合前被摧毁，此特征失效，平行体将正常被摧毁。这与老兵模板假死特征不叠。","id":"npcf_x_gf_3_5","base":false},{"name":"多普勒","type":"System","tags":[{"id":"tg_protocol"}],"effect":"平行体将一个回声移动 5 空间。回声不是角色，因此该移动忽略交战，也不会引起反应。","id":"npcf_x_gf_3_6","base":false},{"name":"显化可能性","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"平行体在视线射程 10 内目标空间中创建一个回声。","id":"npcf_x_gf_3_7","base":false},{"name":"催破","type":"Trait","tags":[],"effect":"当一个回声被摧毁时，它在爆发 1 区域造成 3/6/9 动能伤害。","id":"npcf_x_gf_3_8","base":false},{"name":"不确定性","type":"System","tags":[],"effect":"平行体可同时激活两个回声，而非一个。若它创造第三个回声，它总是能决定摧毁之前哪个回声。若该系统被摧毁，平行体选择的回声也会被摧毁，即使它只剩下一个。","id":"npcf_x_gf_3_9","base":false},{"name":"幽灵射击","type":"Weapon","tags":[],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[1,1,1],"accuracy":[0,0,0],"range":[{"type":"Range","val":5},{"type":"Threat","val":3}],"damage":[{"type":"Energy","val":[2,2,2]}],"effect":"该武器每激活一个回声就会额外发动一次攻击。每次额外攻击都源于它的不同回声。","id":"npcf_x_gf_3_10","base":false}],"pack":"浴金焰","source":19},{"id":"npcc_x_gf_4","name":"投石手","role":"操纵","role_en":"controller","page":261,"pages":[261,262],"flavor":"投石手级机甲是更看重技术而非原始火力的驾驶员最爱。稳定、灵活、可靠，投石手骨架不需要军用级枪支或花哨技术；他们所需要的只是一个掌握控制权的人知道什么时候开枪结束战斗。与投石手进行战斗是一种伤脑筋的经历：一场下定决心的寂静决斗，每个战士都在寻找他们的完美时刻，那是将生与死分离的薄弱窗口。","tactics":"投石者是高效的区域封锁专家，大量交换他们的死亡印记机制。它会在会心一击时施加死亡印记，故而提供锁定的盟友更有帮助。它的攻击无视装甲，即使没有命中也会造成伤害，若它施加了大量死亡印记，它可以在回合开始时一次性释放多个死亡印记，威胁大范围内的多个敌人。投石手的主要弱点是无法远距打击目标，而且依赖死亡印记才能有效。造成伤害或使用掩体会使伤害更难造成。","stats":{"hull":[1,2,3],"sys":[-1,-1,-1],"agi":[2,3,4],"eng":[1,1,1],"hp":[16,20,20],"armor":[0,0,0],"evasion":[10,12,14],"edef":[8,10,12],"speed":[4,4,5],"size":[1,1,1],"heatcap":[7,7,7],"save":[11,13,16],"sensor":[8,8,8],"structure":[1,1,1],"stress":[1,1,1],"activations":[1,1,1]},"base":[{"name":"手炮","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_reliable","val":1}],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"","id":"npcf_x_gf_4_1","base":true},{"name":"冒失鬼","type":"Trait","tags":[],"effect":"投石手在交战中获得准度而非难度。","id":"npcf_x_gf_4_2","base":true},{"name":"死亡印记","type":"Trait","tags":[],"effect":"投石手造成会心一击时，他们的目标获得死亡印记。带有死亡印记的角色可用快速动作通过敏捷豁免来去除。","id":"npcf_x_gf_4_3","base":true},{"name":"午日当空","type":"Trait","tags":[{"id":"tg_recharge","val":5},{"id":"tg_quick_action"}],"effect":"在投石手视线射程 8 内选择任意数量的角色。他们都获得死亡印记。","id":"npcf_x_gf_4_4","base":true},{"name":"鸣钟","type":"Trait","tags":[{"id":"tg_protocol"}],"effect":"投石手对射程 8 内每个带有死亡印记的角色使用手炮攻击，然后清除这些角色的死亡印记。任意被次攻击命中的角色都会缓慢直到他们下一回合结束。造成会心一击的攻击可重新赋予死亡印记。","id":"npcf_x_gf_4_5","base":true}],"optional":[{"name":"另一手炮","type":"Weapon","tags":[{"id":"tg_ap"},{"id":"tg_reliable","val":1}],"weapon_size":"副武器","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[3,4,5]}],"effect":"当投石手使用其他武器进行守望攻击时，他们也可以使用该武器对被触发的角色进行攻击。这种武器被视为手炮，用于任何与之相关的特征或系统。","id":"npcf_x_gf_4_6","base":false},{"name":"暗风","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个角色用远程武器攻击投石手。","effect":"投石手对被触发角色使用手炮攻击。若该角色有死亡印记，清除它，然后投石手攻击先结算。若投石手攻击命中，目标将受损直至他下一回合结束。","id":"npcf_x_gf_4_7","base":false},{"name":"魔鬼之眼","type":"Trait","tags":[],"effect":"投石手者忽略任何有死亡印记角色的匿迹和隐形。","id":"npcf_x_gf_4_8","base":false},{"name":"抽牌！","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"带有死亡印记角色在投石手视线射程 8 内开始回合。","effect":"清除该角色死亡印记。直到他们回合结束，该角色在任何不针对投石手的攻击中+3 难度。","id":"npcf_x_gf_4_9","base":false},{"name":"扇锤","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"投石手准备发射铅弹雨。手炮下一次攻击变为锥形 5，但不会击中盟友角色。","id":"npcf_x_gf_4_10","base":false},{"name":"不可能跳弹","type":"Trait","tags":[],"effect":"投石手的手炮获得抛射。对抗带有死亡印记的角色时将获得引导。","id":"npcf_x_gf_4_11","base":false},{"name":"理当如此","type":"Reaction","tags":[],"keywords":["（1/2/3）/轮"],"trigger":"一个在投石手视线内的敌对角色攻击投石手一个盟友。","effect":"该角色获得死亡印记。T2 时，该反应每轮可进行两次。T3 时，每回合可进行三次。","id":"npcf_x_gf_4_12","base":false},{"name":"大地惊雷","type":"Trait","tags":[],"effect":"当带有死亡印记的角色攻击投石手时，投石手从该攻击中获得伤害，热度和燃烧的抗性。然后清除该角色的死亡印记。","id":"npcf_x_gf_4_13","base":false}],"pack":"浴金焰","source":19}],"templates":[{"id":"npct_cn_commander","name":"指挥官","page":318,"pages":[318],"description":"指挥官在大规模战役中运转，在天体和星际太空操控舰队和军队。他们可能不是最致命的士兵，但他们能激发出军队中最好的一面。","base":[{"name":"强化","type":"Trait","tags":[],"effect":"指挥官获得+1 结构和+1 压力。","id":"npcf_cn_commander_1","base":true,"bonus":{"structure":1,"stress":1}},{"name":"权威之声","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"一个盟友攻击，检定或豁免失败，并指挥官没有受扰。","effect":"盟友可以重掷此骰。","id":"npcf_cn_commander_2","base":true},{"name":"指挥官特征","type":"Trait","tags":[],"effect":"指挥官从指挥官特征表中选择其一。若指挥官受扰，则该特征不受用。","id":"npcf_cn_commander_3","base":true}],"optional":[{"name":"激励广播","type":"Trait","tags":[],"effect":"视线内所有盟友角色（指挥官除外）系统豁免+1准度，对其进行的科技攻击+1 难度。","id":"npcf_cn_commander_4","base":false},{"name":"强攻","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"某盟友角色受到目标的伤害。","effect":"指挥官可攻击目标，成功时造成一半伤害，热度或燃烧。","id":"npcf_cn_commander_5","base":false},{"name":"向前推进！","type":"Trait","tags":[{"id":"tg_recharge","val":4},{"id":"tg_quick_action"}],"effect":"指挥官清除当前视线内某盟友角色的晕眩或受扰状态。","id":"npcf_cn_commander_6","base":false},{"name":"齐步行进","type":"Trait","tags":[{"id":"tg_round","val":1},{"id":"tg_protocol"}],"effect":"指挥官可让视线内某盟军角色推进。","id":"npcf_cn_commander_7","base":false},{"name":"军纪","type":"Trait","tags":[],"effect":"邻近指挥官的盟友角色在所有攻击、豁免和检定上+1 准度。","id":"npcf_cn_commander_8","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_rpv","name":"RPV","page":318,"pages":[318],"description":"远程驾驶员媒介（RPV）是由 NHP、非现场驾驶员或伙伴/礼宾单元驾驶的任意机甲。它们以电子战的脆弱性换取个体单位的力量，并可以进行舱内有机单元限制之外的系统操作。","base":[{"name":"HP 加值","type":"Trait","tags":[],"effect":"RPV 获得+5 HP——它可以无视可能炸毁驾驶舱并致人死亡的伤害。","id":"npcf_cn_rpv_1","base":true,"bonus":{"hp":5}},{"name":"无人驾驶","type":"Trait","tags":[],"effect":"RPV 对任何直接影响驾驶员的系统或动作具有免疫；然而，它也会永久受损，且无法做出复杂的决定或道德判断。","id":"npcf_cn_rpv_2","base":true},{"name":"科技脆弱","type":"Trait","tags":[],"effect":"敌方对 RPV 的科技动作+1 准度。","id":"npcf_cn_rpv_3","base":true}],"optional":[],"pack":"核心规则书","source":1},{"id":"npct_cn_elite","name":"精英","page":318,"pages":[318],"description":"精英敌人比大多数敌人更强大——仅次于超体。他们可能是特别坚韧或经验丰富的驾驶员，特种部队，或使用比普通士兵更高水平技术或更好的装备的敌人。精英们可以在每轮行动几次并获得额外结构，这将高效地使他们的 HP 加倍，并允许他们像 PC 一样进行结构伤害检定。","base":[{"name":"强化","type":"Trait","tags":[],"effect":"精英获得+1 结构和+1 压力。","id":"npcf_cn_elite_1","base":true,"bonus":{"structure":1,"stress":1}},{"name":"蓄势待发","type":"Trait","tags":[],"effect":"精英每轮获得两个单独的回合。","id":"npcf_cn_elite_2","base":true,"bonus":{"activations":1}},{"name":"职业军人","type":"Trait","tags":[],"effect":"精英无法获得低等兵或超体模板","id":"npcf_cn_elite_3","base":true},{"name":"专业攻击","type":"Trait","tags":[],"effect":"精英从他们的职业中选择一个额外的可选系统。","id":"npcf_cn_elite_4","base":true}],"optional":[],"pack":"核心规则书","source":1},{"id":"npct_cn_exotic","name":"异种","page":319,"pages":[319],"description":"即使在这充满奇迹的银河系中，异种也是怪异而危险的敌人。一些具备独特技术，某些尚不适用于更宽泛的银河系，有些使用者更新至现代的古老武器样式，而另一些则携带着或采用着完全不符合联盟原则的装备或战术。","base":[{"name":"异种科技","type":"Trait","tags":[],"effect":"扫描不会显示任何关于异种系统的信息。","id":"npcf_cn_exotic_1","base":true},{"name":"固化目标","type":"Trait","tags":[],"effect":"异种获得系统豁免+1 准度，针对它们的科技攻击+1 难度。","id":"npcf_cn_exotic_2","base":true},{"name":"异种系统","type":"Trait","tags":[],"effect":"异种在异种系统和特征表中最多可以选择两项。","id":"npcf_cn_exotic_3","base":true}],"optional":[{"name":"活体底盘","type":"Trait","tags":[],"effect":"该特征只在异种是机甲情况下选择。异种化为生物。","id":"npcf_cn_exotic_4","base":false},{"name":"霎间割裂","type":"System","tags":[],"effect":"异种移动时瞬间移动。","id":"npcf_cn_exotic_5","base":false},{"name":"现世挤出物","type":"Trait","tags":[],"effect":"异种实际是某高维概念实体从非物质空间挤压而出的部分实体。异种获得所有伤害抗性；然而它们只造成一半伤害，其他角色可自由通过并结束回合在其空间，好似它们不存在。","id":"npcf_cn_exotic_6","base":false},{"name":"活体武器","type":"Trait","tags":[],"effect":"异种获得受扰免疫。此外其武器具有自然产生弹药的生物技术和半有机成分。异种重新装填武器时同样恢复 1d6HP。","id":"npcf_cn_exotic_7","base":false},{"name":"非因果律武器","type":"Trait","tags":[],"effect":"选择一件异种武器。它的伤害不以任何方式减少——装甲，抗性，免疫，或其他。","id":"npcf_cn_exotic_8","base":false},{"name":"计时环","type":"System","tags":[{"id":"tg_round","val":1}],"effect":"异种致使时间流的局部扭曲。它们可以重掷 1d20，或以反应迫使视线内另一个角色重掷 1d20。必须接受新的结果。","id":"npcf_cn_exotic_9","base":false},{"name":"再生器","type":"Trait","tags":[],"effect":"在异种回合结束时，恢复其总 HP 的 1/4。若它在同一回合中受到能量伤害，则不会恢复任何 HP。","id":"npcf_cn_exotic_10","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_grunt","name":"低等兵","page":319,"pages":[319],"description":"低等兵比炮灰高一级。他们通常以大批量生产或库存的机甲进入战场——通常以纪律而非卓越而训练。低等兵个体可能不会构成威胁，但在团队中，他们可能会成为压倒骆驼的最后一根稻草，甚至威胁到最强大的敌人。","base":[{"name":"无用之人","type":"Trait","tags":[],"effect":"低等兵只有 1HP 并无法获得更多 HP。与其他角色不同的是，他们在成功豁免时从不受到伤害——无论使用的是什么武器或系统——但在其他情况下，他们正常受到伤害。","id":"npcf_cn_grunt_1","base":true,"override":{"hp":1}},{"name":"贫弱","type":"Trait","tags":[],"effect":"低等兵决不会拥有超过 1 结构和 1 压力，当他们从除自己的系统和武器以外的任何来源受到热度时，他们会立即被摧毁。","id":"npcf_cn_grunt_2","base":true,"override":{"structure":1,"stress":1}},{"name":"普通军士","type":"Trait","tags":[],"effect":"低等兵无法与老兵，班组，精英，或超体模板混用。","id":"npcf_cn_grunt_3","base":true}],"optional":[],"pack":"核心规则书","source":1},{"id":"npct_cn_mercenary","name":"雇佣兵","page":320,"pages":[320],"description":"雇佣兵为出价最高者服务。他们可能会拥护某种信仰或旗帜，但说到做生意，他们只对出价最高者忠诚。","base":[{"name":"机会主义者","type":"Trait","tags":[],"effect":"雇佣兵对与盟友角色交战的目标攻击+1 准度。","id":"npcf_cn_mercenary_1","base":true},{"name":"雇佣兵系统和特征","type":"Trait","tags":[],"effect":"选择可选系统时，雇佣兵也可从雇佣兵系统和特征表中选择。","id":"npcf_cn_mercenary_2","base":true}],"optional":[{"name":"赏金猎人","type":"Trait","tags":[],"effect":"在战斗开始前，GM 选择一个 PC：他的脑袋会标上赏金。任何雇佣兵在战斗中对驾驶员和机甲的所有攻击、检定和豁免都+1 准度。","id":"npcf_cn_mercenary_3","base":false},{"name":"高效杀手","type":"Trait","tags":[],"effect":"佣兵攻击 2 结构或以下角色获得+1 准度和 AP。","id":"npcf_cn_mercenary_4","base":false},{"name":"人情债","type":"Trait","tags":[{"id":"tg_limited","val":1},{"id":"tg_quick_action"}],"effect":"雇佣兵请求帮助：轨道或炮火轰炸，目标是视线射程 30 内的溅射 2。受影响区域内的角色必须通过敏捷豁免否则受到 6/8/12 爆炸伤害并伏卧。成功则伤害减半不会伏卧。","id":"npcf_cn_mercenary_5","base":false},{"name":"侦察无人机","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_limited","val":1},{"id":"tg_quick_action"}],"effect":"侦查无人机（大小 1/2，HP10，回避 10，电子防御 10，标签：无人机）雇佣兵将无人机部署到感应内的自由空间。无人机构建一个爆发 2 的边界，在这个边界内，角色不能匿迹或隐形，若已拥有该状况则失去这些状况。雇佣兵攻击受影响区域内角色+1 准度。以一个协定，无人机可被部署到一个新地点。","id":"npcf_cn_mercenary_6","base":false},{"name":"最终宣言","type":"Reaction","tags":[{"id":"tg_limited","val":1}],"trigger":"雇佣兵降低到总 HP 一半以下。","effect":"爆发 1 内的角色必须通过敏捷豁免否则受到 2 动能伤害并受扰直到对方下一回合结束。随后雇佣兵向任意方向移动等同速度的空间。该移动忽略交战与反应。","id":"npcf_cn_mercenary_7","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_pirate","name":"海盗","page":320,"pages":[320,321],"description":"海盗生活在边界上——被占领的遗忘空间的避难所。他们活动范围很广，在霎闸、星际航线未定星球上活动。他们总能找到在任何地方存放或移动的资源，人们处于绝望之中，律法随之捉襟见肘。","base":[{"name":"致命","type":"Trait","tags":[],"effect":"海盗在会心一击时+1d6 额外伤害。","id":"npcf_cn_pirate_1","base":true},{"name":"海盗系统和特征","type":"Trait","tags":[],"effect":"选择可选系统时，海盗也可从海盗系统和特征表中选择。","id":"npcf_cn_pirate_2","base":true}],"optional":[{"name":"跳帮栓链","type":"Weapon","tags":[{"id":"tg_thrown","val":5}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"","on_hit":"目标必须通过机体豁免否则被拉向海盗并自动擒拿。","id":"npcf_cn_pirate_3","base":false},{"name":"分裂弹","type":"Trait","tags":[],"effect":"海盗在会心一击时+3 额外伤害。","id":"npcf_cn_pirate_4","base":false},{"name":"核虫火箭","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_full_action"}],"effect":"1d3 微型无人机附着在视线射程 10 内的一个角色身上，并开始钻进目标驾驶舱。在 1d3+2 轮，若有任何核虫仍附着，那么它们会抵达驾驶舱并狠揍一顿驾驶员，降低他们的 HP 到 0。目标知晓无人机需要工作多少轮，以及还有多少附着。目标和邻近盟友角色可以用一个快速动作在系统或工程检定成功下移除一架无人机。此外，若目标关机，核虫会陷入困惑，它们的轮次倒计时会暂停。","id":"npcf_cn_pirate_5","base":false},{"name":"撬爪","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_full_action"}],"effect":"海盗试图撬开邻近一个角色的驾驶舱。目标必须通过机体豁免否则驾驶员立即下马被迫踢出机甲。","id":"npcf_cn_pirate_6","base":false},{"name":"奴隶信号","type":"System","tags":[{"id":"tg_recharge","val":5},{"id":"tg_full_action"}],"effect":"射程 10 内一个有人驾驶的机甲或载具必须通过系统豁免。失败则目标内所有驾驶员和其他生物角色会被信号吞没而昏迷。除非其机甲或载具有 AI，否则机甲晕眩。若受影响角色（或其机甲或载具）受伤害，他们会被震醒而结束效果。与目标邻近的角色也可通过完整动作进行系统检定来消除信号从而结束效果。否则效果持续至海盗被摧毁。","id":"npcf_cn_pirate_7","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_ship","name":"飞船","page":321,"pages":[321],"description":"无论是民用还是军用，飞船都由其飞行能力定义，并为太空旅行而设计。虽然它们大多在大气外使用，但大多数在需要时可在近地位置运行。此模板可应用于任何机甲 NPC。用飞船取代机甲标签。","base":[{"name":"飞行物","type":"Trait","tags":[],"effect":"飞船在零重力环境中正常移动。它在大气中悬浮。它获得对固定、晕眩和伏卧的免疫。","id":"npcf_cn_ship_1","base":true},{"name":"巨物","type":"Trait","tags":[],"effect":"飞船大小 4。虽然它比大多数机甲更大，但就飞船标准而言它的规模很小；更大飞船的重型装甲无法被机甲规模的武器破坏。","id":"npcf_cn_ship_2","base":true,"override":{"size":4}},{"name":"船员","type":"Trait","tags":[],"effect":"飞船至少需要两名船员。","id":"npcf_cn_ship_3","base":true},{"name":"装甲船体","type":"Trait","tags":[],"effect":"飞船获得+5HP。","id":"npcf_cn_ship_4","base":true,"bonus":{"hp":5}},{"name":"无法交互","type":"Trait","tags":[],"effect":"飞船不能拾取物体，操纵物体或环境，或擒拿。","id":"npcf_cn_ship_5","base":true},{"name":"近战受限","type":"Trait","tags":[],"effect":"除冲撞外，飞船不能进行近战攻击。","id":"npcf_cn_ship_6","base":true},{"name":"运输","type":"Trait","tags":[],"effect":"飞船可运输一队班组或总大小小于自身的角色。","id":"npcf_cn_ship_7","base":true}],"optional":[],"pack":"核心规则书","source":1},{"id":"npct_cn_spacer","name":"太空民","page":321,"pages":[321],"description":"太空民是那些在无尽真空中诞生和成长的人。他们擅长在困难低重力的环境中和周围机动，这种环境只有在太空和低轨道中才会遇到——霎间跳跃站，空间站，小行星场以及军用和商用飞船之间的虚无。","base":[{"name":"高机动","type":"Trait","tags":[],"effect":"太空民在零重力环境下可以正常移动。","id":"npcf_cn_spacer_1","base":true},{"name":"太空民系统","type":"Trait","tags":[],"effect":"选择可选系统时太空民可从太空民系统表中选择。","id":"npcf_cn_spacer_2","base":true}],"optional":[{"name":"震荡枪","type":"Weapon","tags":[{"id":"tg_knockback","val":3}],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Cone","val":3}],"damage":[],"effect":"","id":"npcf_cn_spacer_3","base":false},{"name":"重力枪","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"步枪","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":10}],"damage":[],"effect":"","on_hit":"目标必须通过机体豁免否则以直线拉向太空民最多 10 空间或直到对方碰到障碍物。若与障碍物碰撞，对方伏卧。","id":"npcf_cn_spacer_4","base":false},{"name":"密封胶陷阱","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_mine"},{"id":"tg_quick_action"}],"effect":"当敌方角色移动到邻近地雷的位置，爆发 1 内角色会被一层厚厚的快干密封胶覆盖并固定。它们会一直粘着直到密封胶受到足够伤害而崩裂；它有 5/10/15HP和回避 5。","id":"npcf_cn_spacer_5","base":false},{"name":"震荡榴弹","type":"System","tags":[{"id":"tg_grenade"},{"id":"tg_limited","val":1},{"id":"tg_quick_action"}],"effect":"太空民花费 1 充能使用以下动作：震荡榴弹（榴弹，射程 5，溅射 1）：受影响区域角色必须通过行敏捷检定否则将被以远离爆炸中心的方式击退 3 空间。若与障碍物碰撞，对方伏卧。","id":"npcf_cn_spacer_6","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_ultra","name":"超体","page":322,"pages":[322,323],"description":"超体是枪骑兵在战场上可能遭遇的最危险的个体敌人——他们是英雄勇士、优越军士、神选战士和其他强大的战斗力量。超体可以指挥一小群随从或在前线领导一支军队，但他们不是伟大的战略家。他们的主要任务总是直接与敌人交战，守住或冲破防线，并通过英勇之举确保自己的一方赢得胜利。超体是种强大的敌人，能够同时对付多个机甲，如同电子游戏中的“boss”角色一样。如同精英，他们有额外结构，这意味着他们需要在结构伤害表上掷骰，比大多数 NPC 更有韧性。正因他们比普通 NPC 更强大（并且追踪他们更复杂），所以建议你在任何既定战斗中只使用一个超体。","base":[{"name":"精英中的精英","type":"Trait","tags":[],"effect":"超体无法使用精英或低等兵模板。","id":"npcf_cn_ultra_1","base":true},{"name":"震慑","type":"Trait","tags":[],"effect":"超体每轮有两个单独的回合。每回合它们都会重新获得花费的反应。若超体在战斗开始时面对 5 或更多的敌对角色，则每轮有三个回合。","id":"npcf_cn_ultra_2","base":true,"bonus":{"activations":1}},{"name":"致命","type":"Trait","tags":[],"effect":"超体在会心一击时+1d6 额外伤害。","id":"npcf_cn_ultra_3","base":true},{"name":"主宰","type":"Trait","tags":[],"effect":"超体回合开始时，它们清除一个状态。在回合结束时，会修复一件被摧毁的武器或系统。","id":"npcf_cn_ultra_4","base":true},{"name":"强化","type":"Trait","tags":[],"effect":"超体获得+3 结构和+3 压力。","id":"npcf_cn_ultra_5","base":true,"bonus":{"structure":3,"stress":3}},{"name":"传奇","type":"Trait","tags":[],"effect":"超体掷骰结构伤害和过热检定两次取任意结果。","id":"npcf_cn_ultra_6","base":true},{"name":"先进元件","type":"Trait","tags":[],"effect":"超体职业中选择 1~2 个额外可选系统。","id":"npcf_cn_ultra_7","base":true},{"name":"韧性","type":"Trait","tags":[],"effect":"超体获得+5HP。","id":"npcf_cn_ultra_8","base":true,"bonus":{"hp":5}},{"name":"本能反应","type":"Trait","tags":[],"effect":"超体每轮可以无限制次数守望。","id":"npcf_cn_ultra_9","base":true},{"name":"超体系统和特征","type":"Trait","tags":[],"effect":"超体从超体系统和特征表中选择 1~3 项。","id":"npcf_cn_ultra_10","base":true}],"optional":[{"name":"悬浮推进","type":"System","tags":[],"effect":"超体可在移动或推进时悬浮。","id":"npcf_cn_ultra_11","base":false},{"name":"斥力场","type":"System","tags":[],"effect":"敌方角色开始其回合时若邻近超体，或在轮内首次邻近超体时受到 2/4/6 能量伤害+2 热度，并且必须通过系统豁免否则受损直到对方下一回合结束。","id":"npcf_cn_ultra_12","base":false},{"name":"围攻盾","type":"System","tags":[],"effect":"超体对射程 3 外的所有攻击伤害具有抗性。","id":"npcf_cn_ultra_13","base":false},{"name":"裂片屏蔽","type":"System","tags":[],"effect":"该系统替换韧性。超体永久隐形。","id":"npcf_cn_ultra_14","base":false},{"name":"短循环光矛","type":"System","tags":[{"id":"tg_ordnance"},{"id":"tg_recharge","val":6},{"id":"tg_full_action"}],"effect":"绘制线形 30 路径，1 空间宽：受影响区域内角色必须通过敏捷豁免否则受到 1 结构伤害。成功则 HP 减少到 1。小于大小 5 的物品将被彻底消灭。","id":"npcf_cn_ultra_15","base":false},{"name":"齐射模块","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_protocol"}],"effect":"超体以稳定姿态准备一件武器。它们下一回合，以协定超体使用该武器攻击任意数量角色，只要在射程内，没有掩护或伏卧。所有角色都知悉该攻击，且可以选择在其回合中以一个自由动作伏卧来规避成为目标。作为该效果的一部分，超体可使用准备好的武器进行无限次的攻击，即使它有装填标签。","id":"npcf_cn_ultra_16","base":false},{"name":"狼猎导弹","type":"System","tags":[{"id":"tg_drone"},{"id":"tg_recharge","val":6},{"id":"tg_quick_action"}],"effect":"狼猎导弹（大小 1，HP10/15/20，回避 10，电子防御10，标签：无人机）超体邻近空间部署狼猎导弹，选择视线射程 30 内一个目标。超体开始回合时导弹向目标飞行 3 空间，若目标被锁定飞行 6 空间。它尽可能直线移动，若需要可绕过掩体和地形机动。当它与角色碰撞或到达目标时会产生爆发 1 爆炸。受影响区域内角色受到 14/20/28 能量伤害，若通过敏捷豁免则伤害减半。超体一次只能部署一枚狼猎导弹，且该系统只能在导弹引爆后再充能。","id":"npcf_cn_ultra_17","base":false},{"name":"阿耳戈斯装甲","type":"Trait","tags":[],"effect":"超体拥有 6 装甲。每次掷骰结构伤害或过热检定，它们失去 2 装甲，最低 0。","id":"npcf_cn_ultra_18","base":false,"override":{"armor":6}},{"name":"毁灭","type":"Trait","tags":[{"id":"tg_round","val":1}],"effect":"1/轮，超体发动一次成功的攻击时，视线内所有角色受到 2/4/6 动能，能量或爆炸伤害。","id":"npcf_cn_ultra_19","base":false},{"name":"规避","type":"Trait","tags":[],"effect":"超体获得+4 回避（最高 20）和-1 结构。","id":"npcf_cn_ultra_20","base":false,"bonus":{"evasion":4,"structure":-1}},{"name":"额外致命","type":"Trait","tags":[],"effect":"超体每回合首次会心一击在 T2 造成+2d6 伤害，或在 T3 造成+3d6 伤害。","id":"npcf_cn_ultra_21","base":false},{"name":"要塞","type":"Trait","tags":[],"effect":"超体系统豁免+3 准度，针对它们的科技攻击+3难度。","id":"npcf_cn_ultra_22","base":false},{"name":"带头冲锋","type":"Reaction","tags":[{"id":"tg_unlimited"}],"trigger":"一个敌人在视线内移动。","effect":"超体可推进。该反应在一轮中使用次数为任意。","id":"npcf_cn_ultra_23","base":false},{"name":"军团","type":"Trait","tags":[],"effect":"超体获得+4 电子防御（最高 20），所有科技攻击+1 准度。","id":"npcf_cn_ultra_24","base":false,"bonus":{"edef":4}},{"name":"无限","type":"Trait","tags":[],"effect":"超体可超限。它们总是受到 1d6 热度，代替标准代价。","id":"npcf_cn_ultra_25","base":false},{"name":"视域","type":"Trait","tags":[],"effect":"超体忽略隐形且感应内敌方角色无法躲藏。","id":"npcf_cn_ultra_26","base":false},{"name":"卓越结构","type":"Trait","tags":[],"effect":"该特征取代韧性。超体获得对一种伤害抗性——动能、能量或爆炸。它们不能获得对两种以上伤害类型的永久抗性，无论是来自该系统还是其他系统。","id":"npcf_cn_ultra_27","base":false},{"name":"卓越骨架","type":"Trait","tags":[],"effect":"超体获得对缓慢、离散和固定的免疫。","id":"npcf_cn_ultra_28","base":false},{"name":"卓越反应堆","type":"Trait","tags":[],"effect":"超体获得对晕眩和暴露的免疫。","id":"npcf_cn_ultra_29","base":false},{"name":"卓越索敌","type":"Trait","tags":[],"effect":"超体进行远程攻击时忽略掩体。","id":"npcf_cn_ultra_30","base":false},{"name":"至高维护","type":"Trait","tags":[{"id":"tg_quick_action"},{"id":"tg_free_action"}],"effect":"超体获得对受扰的免疫；此外，超体可在他们回合中以自由动作重新装填武器，并以快速动作修复被摧毁的武器或系统。","id":"npcf_cn_ultra_31","base":false},{"name":"至高近战","type":"Trait","tags":[{"id":"tg_free_action"}],"effect":"超体在所有近战攻击上+1 准度；此外，每他们的回合一次，超体可以用自由动作进行擒拿，冲撞或一次近战攻击。","id":"npcf_cn_ultra_32","base":false},{"name":"势不可挡","type":"Trait","tags":[],"effect":"超体免疫所有非自主移动，包括击退和伏卧。","id":"npcf_cn_ultra_33","base":false},{"name":"地狱火投射器","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"CQB","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Cone","val":5}],"damage":[{"type":"Energy","val":[3,3,3]},{"type":"Burn","val":[4,5,6]}],"effect":"该武器可进行两次攻击，但两次区域不可重叠。","id":"npcf_cn_ultra_34","base":false},{"name":"蹂躏者炮塔","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[1,1,1],"range":[{"type":"Range","val":10}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"该武器同时攻击视线射程内的所有敌方角色。","id":"npcf_cn_ultra_35","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_veteran","name":"老兵","page":324,"pages":[324],"description":"老兵是久经沙场、经验丰富的战士。这不是他们第一次登台演出，他们承受士气冲击的能力远远高于未经考验的新手。他们在战场上的价值在于他们为部署带来的经验以及他们在前线的稳定存在。使用老兵模板制作让人记忆犹新的角色。","base":[{"name":"强化","type":"Trait","tags":[],"effect":"老兵获得+1 结构和+1 压力。","id":"npcf_cn_veteran_1","base":true,"bonus":{"structure":1,"stress":1}},{"name":"老兵","type":"Trait","tags":[],"effect":"老板获得一项机甲技能（制造时选择）所有检定与豁免+1 准度：机体，敏捷，系统，工程。","id":"npcf_cn_veteran_2","base":true},{"name":"老兵特征","type":"Trait","tags":[],"effect":"老兵每层级获得一个老兵特征。","id":"npcf_cn_veteran_3","base":true}],"optional":[{"name":"杂技演员","type":"Trait","tags":[],"effect":"老兵移动或推进后可飞行 3 空间。该飞行无视交战和反应。","id":"npcf_cn_veteran_4","base":false},{"name":"致命","type":"Trait","tags":[],"effect":"老兵在会心一击时+1d6 额外伤害。","id":"npcf_cn_veteran_5","base":false},{"name":"假死","type":"Trait","tags":[],"effect":"老兵每场战斗中被摧毁时，他们实际在假死——他们看起来被摧毁了，但还剩 1HP。邻近老兵的角色可通过系统检定或驾驶员技能检定来揭示；否则老兵会一直被忽视直到对方移动或执行动作。","id":"npcf_cn_veteran_6","base":false},{"name":"骇客","type":"Trait","tags":[],"effect":"老兵成功的科技攻击造成+2 热度。","id":"npcf_cn_veteran_7","base":false},{"name":"固化目标","type":"Trait","tags":[],"effect":"老兵获得系统豁免+1 准度，针对它们的科技攻击+1 难度。","id":"npcf_cn_veteran_8","base":false},{"name":"暴头","type":"Trait","tags":[],"effect":"1/轮，会心一击时，老兵的目标必须通过机体豁免否则只能在对方下一回合结束前只能涉及邻近空间视线。","id":"npcf_cn_veteran_9","base":false},{"name":"隔热","type":"Trait","tags":[],"effect":"老兵对燃烧免疫。","id":"npcf_cn_veteran_10","base":false},{"name":"传奇","type":"Trait","tags":[],"effect":"老兵掷骰结构伤害和过热检定两次取任意结果。","id":"npcf_cn_veteran_11","base":false},{"name":"微弱信号","type":"Trait","tags":[],"effect":"老兵忽略射程 3 内角色隐形，射程 3 内敌方角色无法成功躲藏（若已躲藏则保持隐匿）。","id":"npcf_cn_veteran_12","base":false},{"name":"闪电反射","type":"Trait","tags":[],"effect":"当老兵被任意重武器或超重型武器攻击时，先掷1d6。结果为 5+时，攻击自动落空。","id":"npcf_cn_veteran_13","base":false},{"name":"无限","type":"Trait","tags":[],"effect":"老兵可超限。它们总是受到 1d6 热度，代替标准代价。","id":"npcf_cn_veteran_14","base":false},{"name":"NHP 副驾驶员","type":"Trait","tags":[],"effect":"老兵获得 AI 标签。其机甲或载具为自动驾驶，甚至可以在没有驾驶员情况下工作。NHP 会陷入层流，使用与 PC 的 AI 相同的规则。","id":"npcf_cn_veteran_15","base":false},{"name":"饯别之礼","type":"Trait","tags":[{"id":"tg_quick_action"}],"effect":"老兵可以自爆（见第三章机甲战斗）。","id":"npcf_cn_veteran_16","base":false},{"name":"竞技大师","type":"Trait","tags":[],"effect":"老兵可下马。步行时，老兵使用人类职业，并可以执行所有 PC 驾驶员可用的动作，包括骑乘。","id":"npcf_cn_veteran_17","base":false},{"name":"自我修复","type":"Trait","tags":[{"id":"tg_full_action"}],"effect":"1/场景，以完整动作，老兵恢复所有 HP 并清除所有状态。","id":"npcf_cn_veteran_18","base":false},{"name":"冲击装甲","type":"Trait","tags":[],"effect":"老兵对主武器的伤害获得抗性。","id":"npcf_cn_veteran_19","base":false},{"name":"狡猾","type":"Trait","tags":[],"effect":"老兵的标准移动忽略交战，不会引起反应。","id":"npcf_cn_veteran_20","base":false},{"name":"钢爪","type":"Trait","tags":[],"effect":"副武器无法对老兵造成超过 1 伤害。","id":"npcf_cn_veteran_21","base":false},{"name":"毒蛇之速","type":"Trait","tags":[],"effect":"老兵总是率先行动，甚至比 PC 玩家更早行动。无论在叙事扮演还是机甲战斗中，只要有谁先行动的问题，总是老兵。如果多个角色都有该特征，那么每次只有一个角色可以使用它。","id":"npcf_cn_veteran_22","base":false}],"pack":"核心规则书","source":1},{"id":"npct_cn_vehicle","name":"载具","page":325,"pages":[325],"description":"尽管机甲大肆盛行，但大多数装甲战斗、运输、侦察以及其他民用和军事任务都是由不起眼的履带式或轮式载具完成。由核聚变、内燃、电、氢，风，人，非因果律引擎，或更不寻常的能源提供动力，，载具可以载客、装载武器、穿披挂装甲，或以其他方式迅速完成设计它们的简单任务：将人员和物品以良好的状态快速地从 A 地运送到 B 地。此模板可应用于任何机甲 NPC。用载具取代机甲标签。","base":[{"name":"受限处理","type":"Trait","tags":[],"effect":"载具必须始终在直线上移动，尽管它可以在不同方向上移动和推进。此外，载具无法攀爬或游泳，并且只有在盟友角色邻近时才能清除伏卧。","id":"npcf_cn_vehicle_1","base":true},{"name":"乘员","type":"Trait","tags":[],"effect":"若载具大于大小 1/2，则它可能有一个乘员；若是如此，它的乘员至少是它的一半大小。","id":"npcf_cn_vehicle_2","base":true},{"name":"无法交互","type":"Trait","tags":[],"effect":"载具不能拾取物体，操纵物体或环境，或擒拿。","id":"npcf_cn_vehicle_3","base":true},{"name":"近战受限","type":"Trait","tags":[],"effect":"除冲撞外，载具不能进行近战攻击。","id":"npcf_cn_vehicle_4","base":true},{"name":"型号","type":"Trait","tags":[],"effect":"载具可从载具特征表中选择一或多项。","id":"npcf_cn_vehicle_5","base":true}],"optional":[{"name":"飞车","type":"Trait","tags":[],"effect":"当载具移动或推进时，它可以飞行。","id":"npcf_cn_vehicle_6","base":false},{"name":"运输","type":"Trait","tags":[],"effect":"载具可运输一队班组或总大小小于自身的角色。","id":"npcf_cn_vehicle_7","base":false},{"name":"步行或悬浮","type":"Trait","tags":[],"effect":"载具无视困难地形。","id":"npcf_cn_vehicle_8","base":false}],"pack":"核心规则书","source":1},{"id":"npct_horror","name":"恐怖体","pack":"尘墓","description":"超越人类理解的人造恐怖之物。从生物合成混种机甲、纳米虫群格式塔集群，到相位偏移的迅子幻影，恐怖体的形态千变万化，但被迫在战场上面对它们的人，总能认清其本质。","base":[{"id":"npcf_mutations_horror","name":"变异","type":"Trait","tags":[],"effect":"恐怖体可以从恐怖体变异列表中选择1个选项，并且每个等阶额外选择一个选项。","base":true}],"optional":[{"id":"npcf_abomination_horror","name":"憎恶之物","type":"Trait","tags":[],"effect":"扫描无法揭示恐怖体的任何信息，只能确认其为恐怖体。","base":false},{"id":"npcf_disruptor_whip_horror","name":"扰乱鞭","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[1,1,1],"range":[{"type":"Threat","val":3}],"damage":[],"effect":"","on_hit":"目标失去全部护盾。","base":false},{"id":"npcf_quadruped_horror","name":"四足形态","type":"Trait","tags":[],"effect":"恐怖体免疫伏卧，并可以用协定移动至多4格。","base":false},{"id":"npcf_superfluous_extremeties_horror","name":"多余肢体","type":"Trait","tags":[],"effect":"恐怖体进行擒拿时获得+1准度，并可以用快速动作进行权宜攻击。","base":false},{"id":"npcf_terrifying_horror","name":"恐怖威仪","type":"Trait","tags":[],"effect":"对恐怖体进行攻击时，如果攻击者对目标具有视线，该攻击受到+1难度。","base":false},{"id":"npcf_abhorrent_redundancies_horror","name":"可憎冗余","type":"Trait","tags":[],"effect":"每当恐怖体的HP降至0时，可以掷1d6。结果为5+时，其HP恢复至1，并获得{3/4/5}护盾。此特征首次触发后，只有结果为6+时才能再次触发。","base":false},{"id":"npcf_assimilaiton_maw_horror","name":"同化巨口","type":"Weapon","tags":[],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[8,10,12]}],"effect":"此外，如果恐怖体用此武器摧毁另一名角色，无论敌我，或命中一具残骸，则恢复{10/15/20} HP。此武器自动命中残骸和友军。被此武器命中的残骸自动被摧毁。","on_hit":"此次攻击结算后，如果目标的HP不超过一半，则必须通过机体豁免，否则HP降至0。","base":false},{"id":"npcf_phase_shift_generator_horror","name":"相位偏移发生器","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_recharge","val":4}],"effect":"恐怖体可以用协定变为无形，直到其下一回合开始；也可以改为清除无形。如果恐怖体在上一回合使用过此系统，则不能变为无形。","base":false},{"id":"npcf_artificial_horror","name":"人工构造","type":"Trait","tags":[],"effect":"此特征只能赋予具有生物标签的恐怖体。恐怖体失去生物标签，并获得6热度上限。","base":false}]},{"id":"npct_industrial_mech","name":"工业机甲","pack":"尘墓","description":"银河中为采矿和建筑而制造的民用机械，数量远超专为战斗设计的机器。尽管这些底盘的缺陷显而易见，别无选择的人仍常常驾驶它们投入战斗，将原本用于创造的工具化为毁灭的工具。","base":[{"id":"npcf_construction_tools_industrial_mech","name":"施工工具","type":"Trait","tags":[],"effect":"工业机甲可以从工业武器列表中选择一件武器。也可以选择第二件，但必须以其替换一件基础武器。","base":true},{"id":"npcf_civilian_machine_industrial_mech","name":"民用机械","type":"Trait","tags":[],"effect":"工业机甲的豁免和检定受到+1难度。针对工业机甲的科技攻击获得+1准度。","base":true},{"id":"npcf_bulky_construction_industrial_mech","name":"笨重构造","type":"Trait","tags":[],"effect":"工业机甲获得+1装甲，但推进由快速动作变为完整动作。","bonus":{"armor":1},"base":true}],"optional":[{"id":"npcf_rock_drill_industrial_mech","name":"凿岩钻","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[8,10,12]}],"effect":"此外，工业机甲可以用快速动作，对一块邻接地形自动造成50穿甲动能伤害。","on_hit":"目标被击倒伏卧。","base":false},{"id":"npcf_fusion_cutter_industrial_mech","name":"聚变切割器","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Energy","val":[3,4,5]},{"type":"Burn","val":[2,3,4]},{"type":"Heat","val":[2,3,4]}],"effect":"","base":false},{"id":"npcf_rivet_cannon_industrial_mech","name":"铆钉炮","type":"Weapon","tags":[{"id":"tg_knockback","val":1}],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":3},{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[3,3,3]}],"effect":"此攻击可以进行{1/2/3}次攻击。如果其中一次攻击将角色击退至使其停止移动的地形上，该角色陷入固定状态，直到其下一回合结束。","base":false},{"id":"npcf_buzzsaw_industrial_mech","name":"圆锯","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[1,1,1],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"会心一击时：此武器的基础伤害翻倍。","base":false},{"id":"npcf_wrecker_industrial_mech","name":"破拆锤","type":"Weapon","tags":[],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[-1,-1,-1],"range":[{"type":"Threat","val":3}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"每当使用此武器攻击时，都会攻击威胁范围内的所有角色。","base":false},{"id":"npcf_industrial_clamps_industrial_mech","name":"工业钳夹","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[5,7,9]}],"effect":"工业机甲进行擒拿时获得+1准度。此武器自动命中被擒拿的角色。","base":false}]},{"id":"npct_commando_spec_op","name":"特战队员","pack":"尘墓","description":"这些人员训练精湛、装备精良，通常以小队形式部署，进一步提升其致命的作战能力。任何与这种突击小队为敌的人，都应格外谨慎。","base":[{"id":"npcf_operatives_spec_op","name":"特战干员","type":"Trait","tags":[],"effect":"选择可选系统和特征时，特战队员也可以从特战队员系统与特征列表中选择。此外，特战队员不能采用杂兵、精英或究极模板。","base":true},{"id":"npcf_active_camo_spec_op","name":"主动迷彩","type":"System","tags":[{"id":"tg_protocol"},{"id":"tg_limited","val":1}],"effect":"特战队员可以用协定消耗一次充能，变为隐形，直到其下一回合结束。此效果持续期间，特战队员的下一次近战或远程攻击若命中，则视为会心一击。","base":true},{"id":"npcf_deadly_precision_spec_op","name":"致命精度","type":"Trait","tags":[],"effect":"特战队员在会心一击时造成+{2/3/3}额外伤害。","base":true},{"id":"npcf_coordinated_carnage_spec_op","name":"协同杀戮","type":"Trait","tags":[],"effect":"每轮中，所有特战队员角色都完成各自的回合后，一名特战队员角色可以按正常回合顺序额外进行一个回合。","base":true}],"optional":[{"id":"npcf_full_spectrum_sensor_suite_spec_op","name":"全频谱感应套组","type":"System","tags":[],"effect":"特战队员可以用协定进行锁定。每当射程10内的一名友方特战队员角色消耗任意锁定时，其攻击不受掩护影响。每场战斗只有一名特战队员可以携带此系统。","base":false},{"id":"npcf_automated_battlefield_awareness_node_spec_op","name":"自动战场感知节点","type":"System","tags":[],"effect":"特战队员获得战场感知反应，每轮可以使用任意次数。每场战斗只有一名特战队员可以携带此系统。<br><b>战场感知 </b><br><b>触发：</b>射程8内且在视线范围内的一名友方特战队员角色即将进行豁免掷骰。<br><b>效果：</b>在掷出任何骰子之前，该角色自动通过此次豁免。","base":false},{"id":"npcf_serrated_machete_spec_op","name":"锯齿砍刀","type":"Weapon","tags":[{"id":"tg_thrown","val":5}],"weapon_size":"主武器","weapon_kind":"近战","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[{"type":"Kinetic","val":[4,5,6]}],"effect":"会心一击时：目标陷入离散状态，直到其下一回合结束。","base":false},{"id":"npcf_special_munitions_spec_op","name":"特种弹药","type":"Trait","tags":[],"effect":"此角色的远程攻击获得“<b>会心一击时：</b>目标被击倒伏卧。”<br>此外，在进行造成动能、能量或爆炸伤害的远程攻击之前，特战队员可以将该伤害类型替换为另外两种类型之一。","base":false},{"id":"npcf_bulwark_mods_spec_op","name":"壁垒模块","type":"Trait","tags":[],"effect":"特战队员无视困难地形和危险地形。","base":false},{"id":"npcf_gyrojet_cannon_spec_op","name":"旋喷加农炮","type":"Weapon","tags":[{"id":"tg_loading"},{"id":"tg_knockback","val":2}],"weapon_size":"主武器","weapon_kind":"发射器","attack_bonus":[2,4,6],"accuracy":[0,0,0],"range":[{"type":"Range","val":8}],"damage":[{"type":"Explosive","val":[6,8,10]}],"effect":"","base":false},{"id":"npcf_burst_jets_spec_op","name":"跳跃背包","type":"System","tags":[],"effect":"特战队员每次推进时都可以飞行，但必须在坚实表面上结束此次移动，否则开始坠落。","base":false},{"id":"npcf_null_perception_coating_spec_op","name":"感知屏蔽涂层","type":"Trait","tags":[],"effect":"特战队员免疫锁定。","base":false}]},{"id":"npct_x_ws_1","name":"海军陆战队","page":62,"pages":[62],"description":"海军的登舰和反登舰行动是驾驶员可能进行的最危险的行动之一，它们往往发生在极其恶劣的环境中，双方的伤亡率都很高，尽管这是符合指挥官们预期的，也完全可以被他们接受。士兵们受命对船只和空间站进行攻击，或对那些试夺取它们的人进行反击。海军驾驶员知道，准备是生存的关键，他们相应地为底盘装备了额外的装甲、破门设备和近战武器，以便在船体切割器轰鸣作响、敌方破船而入时占据上风。","base":[{"name":"机动性","type":"Trait","tags":[],"effect":"海军陆战队可在零重力环境下正常移动。","id":"npcf_x_tws_1_1","base":true},{"name":"冲锋在前，撤退在后","type":"Trait","tags":[],"effect":"以反应对海军陆战队进行攻击时（如守望）获得+1难度。","id":"npcf_x_tws_1_2","base":true},{"name":"海军陆战队系统","type":"Trait","tags":[],"effect":"当选择可选系统时，海军陆战队可以从海军陆战队系统和特征中进行选择。","id":"npcf_x_tws_1_3","base":true}],"optional":[{"name":"尖兵镀层","type":"Trait","tags":[],"effect":"若海军陆战队没有护法特征，则邻近的盟友角色可视海军陆战队为硬性掩护。若已有护法特征，则该特征可为任何方向的所有邻近盟友角色提供软性掩护。","id":"npcf_x_tws_1_4","base":false},{"name":"破城槌","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"海军陆战队对一个邻近的地形，障碍物或可展开物品造成 10/20/30 AP 动能伤害。在使用该系统前或后，可移动 2 空间。","id":"npcf_x_tws_1_5","base":false},{"name":"便携式路障","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_limited","val":2}],"effect":"激活本系统时，海军陆战队每消耗 1 充能可在邻近的自由空间部署一块大小 1 路障。这些路障拥有 10HP，回避 5，且会在爆发 1 空间内形成仅对敌方角色有效的困难地形。","id":"npcf_x_tws_1_6","base":false},{"name":"甲板锚","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"海军陆战队被其他角色攻击或在被迫进行豁免中失败而强制移动。上述效果中不包括瞬间移动。","effect":"海军陆战队忽略该移动。","id":"npcf_x_tws_1_7","base":false},{"name":"捕俘刺","type":"System","tags":[{"id":"tg_full_action"}],"effect":"海军陆战队将强大的活塞尖刺捅进邻近一个敌方角色，强迫对方进行机体豁免。成功则对方将在下一回合结束前受损。失败则目标会被钉穿，自动被擒拿并直到擒拿结束前都会受损。海军陆战队在擒拿期间缓慢，但不论对方大小，海军陆战队总是视为较大方。要挣脱擒拿，被擒拿方必须以一个完整动作进行机体豁免代替原本的机体对抗检定。在目标被擒拿期间，任何对海军陆战队进行远程或近战攻击的其他角色必须先掷 1d6：结果为 4+，则该次攻击自动命中被擒拿角色（该效果不与隐形叠加），造成一半的伤害和热度。该效果持续到擒拿结束或海军陆战队再次进行该动作。","id":"npcf_x_tws_1_8","base":false}],"pack":"冬痕行动","source":5},{"id":"npct_x_cp_1","name":"火葬","page":88,"pages":[88],"description":"“火葬”是个笼统的术语，指那些好斗不理智的驾驶员——他们熊熊燃烧，内在躯体可能已经死亡。火葬的反应堆被推到临界点，以基本安全和结构完整性为代价，允许前所未有的输出。","base":[{"name":"无照改造","type":"Trait","tags":[],"effect":"火葬在工程检定和豁免中+1 准度，在压力检定双骰取高（若适用）。","id":"npcf_x_tcp_1_1","base":true},{"name":"烧灼","type":"Trait","tags":[],"effect":"1/轮，当火葬推进时，受到 1d6 热度并且移动同值的空间。","id":"npcf_x_tcp_1_2","base":true},{"name":"炉心管道","type":"Trait","tags":[],"effect":"火葬在超温危域时的第一次攻击+1d6 额外伤害或+2热度（由他们自己选择）。若暴露，这将增加到+2d6 额外哦伤害/4 热度。","id":"npcf_x_tcp_1_3","base":true},{"name":"火葬特征","type":"Trait","tags":[],"effect":"选择可选系统时，火葬也可从火葬系统和特征表中选择。","id":"npcf_x_tcp_1_4","base":true}],"optional":[{"name":"超频电池","type":"Trait","tags":[],"effect":"当火葬掷骰再充能时，它可以在看到结果后重新掷骰。它必须接受第二次结果，然后受到第二次结果等值的热度。","id":"npcf_x_tcp_1_5","base":false},{"name":"伽马轮转","type":"Trait","tags":[],"effect":"所有火葬的攻击获得+2 热度（自身），火葬造成的额外伤害总视为燃烧。多次攻击的武器只会让你承受一次热度。","id":"npcf_x_tcp_1_6","base":false},{"name":"冗余系统","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_quick_action"}],"effect":"火葬可激活该系统，以一个快速动作进行稳住阵脚。","id":"npcf_x_tcp_1_7","base":false},{"name":"不稳定系统","type":"Trait","tags":[],"effect":"火葬被毁时，其下一回合结束如同自爆般爆炸。","id":"npcf_x_tcp_1_8","base":false},{"name":"抛出燃料棒","type":"Weapon","tags":[{"id":"tg_limited","val":2}],"weapon_size":"主武器","weapon_kind":"CQB","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Energy","val":[4,6,8]},{"type":"Heat","val":[2,2,2]}],"effect":"攻击时：火葬清除 2/4/6 热度。","id":"npcf_x_tcp_1_9","base":false},{"name":"步行天灾","type":"Trait","tags":[],"effect":"火葬会释放爆发 3 环境场。该区域被视为以下环境危害之一（《枪骑兵》核心规则 272 页）：极端高温，极端日照，微粒风暴，闪电风暴，干扰风暴，毁灭风暴或熔热天体。火葬不受该环境影响。","id":"npcf_x_tcp_1_10","base":false},{"name":"衰退力场","type":"System","tags":[{"id":"tg_round","val":1}],"effect":"使用任意武器会心一击时，火葬会给目标注入瓦解光环。他们不能在任何攻击的最后一次掷骰中受益于准度，每获得 HP 时只能获得一半 HP，并且不能获得新的护盾（例如：若你在 4/10 HP 稳住阵脚，你本该获得+6HP，减半后+3，最终 HP 为 7）。他们可用完整动作通过工程豁免，或在火堆射程 3 内结束他们回合来结束该效果。若火葬被摧毁，该效果终止。","id":"npcf_x_tcp_1_11","base":false}],"pack":"卡斯特与帕勒克","source":11},{"id":"npct_x_sultan_1","name":"捍卫者","page":172,"pages":[172],"description":"无论是在分级的部队组织内部还是外部，都可以预期有一定比例的训练有素的驾驶员会在很大程度上超越他人。在更正式的军事指挥结构中，这些杰出人物常被建议接受高级训练，并可能被纳入特种部队，但即使在不那么规范的环境或那些非标准路运作环境中，这些模范战士也担任着各式从仪式性到名誉性突出的职责和地位，包括兄弟会成员、精英保镖、受人尊敬的竞技场斗士和神选战士。这些捍卫者通常采用同样非标准的负载和定制底盘，其中诸多底盘闻名天下或是臭名昭著——正如其驾驶员。","base":[{"name":"强化","type":"Trait","tags":[],"effect":"捍卫者获得+1 结构和+1 压力。","id":"npcf_x_tsultan_1_1","base":true,"bonus":{"structure":1,"stress":1}},{"name":"无双","type":"Trait","tags":[],"effect":"捍卫者无法使用低等兵模板，且任意场景只出现一个捍卫者。","id":"npcf_x_tsultan_1_2","base":true},{"name":"挑战者","type":"Trait","tags":[],"effect":"当捍卫者首次攻击射程 10 内的敌对角色时，无论命中与否，他都可用一个自由动作给予该角色捍卫者印记。捍卫者对该角色的所有近战和远程攻击+1 准度，但对任何其他目标的所有攻击+1 难度。当对印记目标会心一击时，他们可以消耗标记并获得 5/6/8 护盾。每次只能以该方式标记一个角色，并且在旧标记被消耗或捍卫者致使目标受到结构伤害（这会清除印记）之前，新标记无法放置。当一个标记激活时，捍卫者不能自主离开该角色。在战斗开始前，捍卫者可选择一个 PC：该角色在战斗开始时已携带捍卫者印记。","id":"npcf_x_tsultan_1_3","base":true},{"name":"捍卫者装饰物","type":"Trait","tags":[],"effect":"指挥官从不同职业额外选择一个基础武器或系统，然后从捍卫者系统和特征表中选择一个。","id":"npcf_x_tsultan_1_4","base":true}],"optional":[{"name":"复仇女神","type":"Trait","tags":[],"effect":"捍卫者对带有捍卫者印记角色的远程和近战攻击+1 准度。拥有捍卫者印记角色在对捍卫者的所有攻击中+1 准度。","id":"npcf_x_tsultan_1_5","base":false},{"name":"无懈可击","type":"Trait","tags":[],"effect":"1/轮，捍卫者可自动通过来自捍卫者印记角色的任意检定或豁免。","id":"npcf_x_tsultan_1_6","base":false},{"name":"荣耀守卫","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"射程 3 内盟友角色受到捍卫者印记角色攻击命中","effect":"捍卫者可消耗印记使盟友对该攻击所有伤害获得抗性。","id":"npcf_x_tsultan_1_7","base":false},{"name":"投身战场","type":"Reaction","tags":[{"id":"tg_round","val":1}],"trigger":"视线内带有捍卫者印记的角色移动","effect":"捍卫者或视线内的盟友角色可以直接向触发角色推进。","id":"npcf_x_tsultan_1_8","base":false},{"name":"破碎面容","type":"Trait","tags":[],"effect":"当捍卫者的结构在该场景第一次被降低到一半或以下时，它会立即刷新所有再充能，并获得以下反应：","id":"npcf_x_tsultan_1_9","base":false},{"name":"报应","type":"Reaction","tags":[{"id":"tg_limited","val":1}],"trigger":"捍卫者使用远程或近战攻击命中。","effect":"该命中会自动会心一击，且该伤害无法以任何方式减免。","id":"npcf_x_tsultan_1_10","base":false},{"name":"荣耀追求者","type":"Trait","tags":[],"effect":"当一个角色有捍卫者印记时，捍卫者无法从匿迹、隐形或掩护中获益，但是他们可对该角色造成所有伤害获得抗性。","id":"npcf_x_tsultan_1_11","base":false}],"pack":"苏丹","source":12},{"id":"npct_x_sultan_2","name":"铲土机","page":173,"pages":[173],"description":"铲土机又被称为垃圾车、技术车，更正式的说法是临时制作作战车辆，铲土机指定的底盘是有限资源和机械独创性的产物。资金充足的军队会部署标准化骨架，而游击队、土匪、恐怖分子和海盗通常会使用回收的军用或民用底盘，并通过额外武器和装甲来补充其力量。偶尔还能在一些由于不受控制地使用大规模毁灭性武器或与星际文明隔绝而导致社会和技术基础设施灾难性崩溃的国家中找到其他例子。在敌后长期被围困的善于发明的驾驶员也常知晓对他们的底盘进行非标准改造以争取生存。","base":[{"name":"个性化风格","type":"Trait","tags":[],"effect":"铲土机在任意豁免和检定（机体，敏捷，系统或工程）上+1准度，在另一个选择的类型上+1 难度。","id":"npcf_x_tsultan_2_1","base":true},{"name":"铲土机系统","type":"Trait","tags":[],"effect":"选择可选系统时，铲土机也可从铲土机系统和特征列表中选择。","id":"npcf_x_tsultan_2_2","base":true}],"optional":[{"name":"安装炮塔","type":"Weapon","tags":[],"weapon_size":"主武器","weapon_kind":"大炮","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Range","val":5}],"damage":[{"type":"Kinetic","val":[4,6,8]}],"effect":"该武器无法正常使用，但铲土机可在回合结束时将其为自由动作进行攻击。当远程或近战攻击会心一击击中铲土机时，该武器除正常攻击伤害和效果外，还会被摧毁而无法修复。","id":"npcf_x_tsultan_2_3","base":false},{"name":"重装机体","type":"Trait","tags":[],"effect":"铲土机获得+5HP，但他们无法再推进了","id":"npcf_x_tsultan_2_4","base":false,"bonus":{"hp":5}},{"name":"打桩机","type":"Weapon","tags":[{"id":"tg_knockback","val":5},{"id":"tg_recharge","val":5},{"id":"tg_inaccurate"}],"weapon_size":"重型","weapon_kind":"近战","attack_bonus":[1,2,3],"accuracy":[0,0,0],"range":[{"type":"Threat","val":2}],"damage":[{"type":"Kinetic","val":[6,9,12]}],"effect":"","on_hit":"铲土机失去 5HP，目标必须通过机体豁免否则伏卧，如果他们因击退而撞到足够大阻止他们移动的障碍物，则自动失败该豁免。","id":"npcf_x_tsultan_2_5","base":false},{"name":"不稳定核反应堆","type":"Trait","tags":[],"effect":"当铲土机被固定、受扰或晕眩时，掷 1 个 D6。1~4 则他们会忽略该种影响变成受损。5+则铲土机立即在爆发 2 区域爆炸。该区域内所有角色必须通过敏捷豁免，否则受到8/10/12 爆炸伤害，成功豁免则伤害减半。","id":"npcf_x_tsultan_2_6","base":false},{"name":"破碎 NHP","type":"System","tags":[],"effect":"铲土机获得 AI 标签，可在没有驾驶员情况下自主运行。回合开始时，铲土机掷 1 个 D6。1~3 则他们可能会移动 3 空间，忽略交战与反应。4~6 则他们在所有攻击上+1 准度直到下一回合开始。1/场景，当铲土机被入侵命中时，攻击者可能会迫使 NHP 进入层流而不是选择常规选项（攻击者在命中时会知晓该选项）。当 NHP 以这种方式层流时，铲土机下一回合中失去对机甲的控制，必须直接向最接近的盟友角色移动（若有多个盟友同样接近，则随机选择），并使用尽可能多的武器攻击他们，在下一回合结束时重新获得机甲控制。若他们不能在有效目标的范围内移动，或者没有其他盟友角色存在，则他们将改为晕眩直到下一回合结束。","id":"npcf_x_tsultan_2_7","base":false},{"name":"修补工具","type":"System","tags":[{"id":"tg_limited","val":1},{"id":"tg_full_action"},{"id":"tg_quick_action"}],"effect":"铲土车用快速动作恢复 1d6HP ，或者用完整动作恢复1d6+3HP。","id":"npcf_x_tsultan_2_8","base":false},{"name":"简易爆炸装置","type":"System","tags":[{"id":"tg_limited","val":1}],"effect":"战斗开始时，选择在任意敌方角色 5 空间外的区域部署简易爆炸装置。探测简易爆炸装置需要成功的系统检定，拆除它需要在邻近空间成功进行系统检定，否则它会立即引爆。铲土车可用快速动作引爆它，以简易爆炸装置为中心制造一个爆发 1区域。该区域内所有角色必须通过敏捷豁免否则受到2d6+4/6/8 爆炸伤害并被击倒伏卧，豁免成功伤害减半并且保持站立。。","id":"npcf_x_tsultan_2_9","base":false}],"pack":"苏丹","source":12},{"id":"npct_x_cca_1","name":"标志性超体：无畏级","page":44,"pages":[44],"description":"若武库拥有超体模板，它还可以获得以下基本系统，并可以选择无畏级可选系统之一。","base":[{"name":"重铁","type":"Trait","tags":[],"effect":"无畏级在拥有 3+结构时视为大小 3。每当无畏级上装置系统降级时，碎片会飞离庞大的骨架身躯，掷 1d6。由此产生的效果可放置在无畏级射程 3 的任何自由空间中。1. 创造一个大小 1 的硬性掩护（10HP）。2. 对物品或地形造成 10AP 动能伤害。若因此而破坏它，创造一个以它为中心爆发 1 的困难地形。3. 一个敌对角色必须通过机体豁免，否则就会因飞溅碎片冲击其机甲而缓慢和受损。4. 创造一个锯齿碎片线形 3 区域；进入该区域任意空间的角色受到 3AP 动能伤害。5. 1/2/3 个敌对角色必须通过敏捷豁免否则受到 5 动能伤害并伏卧。6. 创造一座废料炮塔（可展开，大小 1/2，8 回避/ED，5/10/15HP）。每当无畏级用火神卡宾枪开火时，所有废料炮塔均可向射程 5 内最近的敌方角色开火。其攻击为+1/+2/+3，命中时造成 3/5/7 动能伤害，未命中造成 1 动能伤害。每当无畏级上的装置系统降级，其总装置值降低时，它就会获得同等数量的废料。以一个协定，它可以创造一个钢铁炮组内置挂载点。它可消耗废料来添加以下效果。可多次选择同一选项：• （2 废料）添加 AP、精准、击退 2、可靠 2 或抛射标签。• （2 废料）提升基础伤害+2。• （2 废料）提升+1 命中/层级。该选项只能选择一次。• （2 废料）添加+1 受限充能。• （4 废料）将受限 1 标签替换为再充能 5+。• （4 废料）获得溅射 1 和 2 热度（自身）。战争铁匠协定，特征钢铁炮组主武器大炮，受限 1，+1/+2/+3[射程 8][3/4/5 动能伤害]被创造时，无畏级可将该武器装备给自己或邻近盟友。当一个角色弹幕并开火一把钢铁炮组时，他们可开火所有装备的钢铁炮组。","id":"npcf_x_tcca_1_1","base":true}],"optional":[{"name":"最终绝战","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":6}],"effect":"无畏级将其所有装备的武器开火。当以此法开火时，所有武器都会获得命中：该武器不会失去装填或失去受限充能，并且可立即再次开火。只要它继续命中目标，该效果便可无限重复。在单次使用该动作时，它无法用同一武器多次瞄准同一角色。","id":"npcf_x_tcca_1_2","base":false},{"name":"自行分裂","type":"Trait","tags":[],"effect":"每当重铁触发时，无畏级可掷骰 2d6 并且可选择任意一个结果。若两个骰子相同，则获得 1 废料。","id":"npcf_x_tcca_1_3","base":false},{"name":"废料回收机","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"无畏舰吞噬邻近盟友机甲残骸，并将其从战场上移除。它获得 2/3/4 废料，若对方是低等兵则获得 1 废料。","id":"npcf_x_tcca_1_4","base":false},{"name":"漫步烈火","type":"Trait","tags":[],"effect":"盟友角色可用一个快速动作攀登上邻近的无畏级。在骑乘时共享空间，并且获得从各方向的硬性掩护，与之一起移动，并可进行维稳动作。他们可用任意移动的一部分下马，若被除使用维稳之外的任何来源击退、伏卧或固定，则会坠落到邻近自由空间。","id":"npcf_x_tcca_1_5","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npct_x_cca_2","name":"标志性超体：流星","page":46,"pages":[46],"description":"若虹膜拥有超体模板，它还可以获得以下基本系统，并可以选择流星可选系统之一。","base":[{"name":"聚光灯","type":"Trait","tags":[],"effect":"在每轮开始时，流星选择一个敌对角色聚光直到本轮结束。它无法连续两轮选择相同角色。1/回合，当一个聚光角色从一个敌对角色成功攻击或失败豁免中受到 1 或更多伤害时，所有敌对角色受到 2 能量伤害。","id":"npcf_x_tcca_2_1","base":true},{"name":"星落指挥晶格","type":"Trait","tags":[],"effect":"在每轮结束时，若流星未被眩晕，则可以在地图上任何位置标记 3 个溅射 1 区域。这些区域不可彼此邻近。在下轮结束时，标记区域内的角色必须通过敏捷豁免否则受到 4/6/8爆炸伤害，成功则伤害减半。物品和地形受到 10 AP 爆炸伤害。在第 4 轮开始时，这些区域变为溅射 2。","id":"npcf_x_tcca_2_2","base":true}],"optional":[{"name":"中央舞台","type":"Trait","tags":[],"effect":"聚光目标无法从掩护中受益，也不能匿迹或隐形。","id":"npcf_x_tcca_2_3","base":false},{"name":"地狱之星飞天撞","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_limited","val":1}],"effect":"该系统只能在第 3 轮或更后面才能激活，且必须在一轮中流星的第一回合时激活。在下轮结束前，它一直处于固定。在下轮结束时，所有角色都会受到 20/30/40 能量伤害，机体豁免成功则伤害减半。角色可如同被攻击那般在该伤害中使用受身以获得抗性。流星及其射程 2 内角色对该伤害免疫。","id":"npcf_x_tcca_2_4","base":false},{"name":"离子炮","type":"System","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":6}],"effect":"在射程 5 内放置一个不与任何角色重叠的溅射 1 区域并选择一个方向。在流星每回合结束时，该区域会向所选方向移动 3 空间。在一轮中首次进入该区域或该区域移动经过的角色必须通过敏捷豁免否则受到 8/12/16 能量伤害，并在其目标标记上+1，成功豁免伤害减半。物品和地形自动受到 20 AP能量伤害。该效果一直持续到它离开地图或下一轮结束。流星可承受 2 热度让它继续坚持一轮。","id":"npcf_x_tcca_2_5","base":false},{"name":"轨道衰变","type":"Trait","tags":[],"effect":"任何移动都会将星落指挥晶格瞄准的区域视为困难地形，除了角色的标准移动，并且在这些区域结束回合的角色受到 3/4/5 动能伤害，以及如星落雨般坠击中被击倒伏卧。","id":"npcf_x_tcca_2_6","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npct_x_cca_3","name":"标志性超体：吸血鬼","page":48,"pages":[48,49],"description":"若蚊拥有超体模板，它还可以获得以下基本系统，并可以选择吸血鬼可选系统之一。","base":[{"name":"超储库领地","type":"Trait","tags":[],"effect":"在场景开始或吸血鬼进入场景时，在地图上创建一个超储库领地，一个受礼拜编码强化统治的溅射 3 区域。它始终存在直到吸血鬼被摧毁。吸血鬼在进场时必须携带该区域。在该区域内，吸血鬼可在移动时悬浮，作为任意移动的一部分，它可瞬间移动到领地内任意自由空间代替该移动。领地内 k 空间始终被视为吸血鬼感应内空间，它对至少部分位于该区域中的角色有以下影响：• 吸血鬼和盟友角色在受到射程 3 外的任意攻击时均被视为隐形。• 敌对角色视线无法超出射程 3。","id":"npcf_x_tcca_3_1","base":true},{"name":"搬家","type":"Trait","tags":[{"id":"tg_full_action"},{"id":"tg_recharge","val":5}],"effect":"吸血鬼将其超储库领地挪到感应内的任何地点。","id":"npcf_x_tcca_3_2","base":true},{"name":"“掘墓人”系统寄生物","type":"System","tags":[],"effect":"血奴无人机（8/10/12 回避/ED，1HP）每当非血奴盟军无人机或机甲角色被摧毁时，它就化为一架大小等同的血奴无人机，代替其留下残骸或从地图上移除。与血奴无人机邻近的空间被视为吸血鬼的超储库领地。血奴无人机每轮可在吸血鬼首个回合移动 2 空间。当血奴无人机被摧毁时，掷骰 1d6。若掷骰结果低于吸血鬼当前鲜血，则不会被摧毁，并返还 1HP。","id":"npcf_x_tcca_3_3","base":true}],"optional":[{"name":"超储库易位","type":"System","tags":[],"effect":"当吸血鬼搬家时，其超储库领地中所有角色都会被瞬间移动到目标区域内吸血鬼选择的自由空间。非自愿角色必须通过系统豁免避免该影响。","id":"npcf_x_tcca_3_4","base":false},{"name":"纳米广域迷雾","type":"System","tags":[],"effect":"吸血鬼可以在其超储库领地中以完整科技进行任意快速科技动作。若如此行事，那么该动作将转而针对领地内所有其选择的有效目标。","id":"npcf_x_tcca_3_5","base":false},{"name":"无宁之死","type":"Trait","tags":[],"effect":"血奴无人机邻近的空间对于敌对角色而言是困难地形，以及在血奴无人机邻近结束回合的角色受到每邻近无人机3/4/5 动能伤害。","id":"npcf_x_tcca_3_6","base":false},{"name":"电子通道獠牙","type":"Weapon","tags":[{"id":"tg_ap"}],"weapon_size":"超重型","weapon_kind":"近战","attack_bonus":[0,0,0],"accuracy":[0,0,0],"range":[{"type":"Threat","val":1}],"damage":[],"effect":"原文数值：超重型近战，AP，+X，[威胁 1][X 能量伤害]。\n（+X）\n目标每汲取该武器对其攻击+1 命中，并对其造成吸血鬼每鲜血的 3/3/4 能量伤害。","id":"npcf_x_tcca_3_7","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npct_x_cca_4","name":"标志性超体：暴风","page":52,"pages":[52,53],"description":"若地球化拥有超体模板，它还可以获得以下基本系统，并可以选择暴风可选系统之一。","base":[{"name":"压强","type":"Trait","tags":[],"effect":"在暴风工业中心超大杯的领域中的敌对角色必须在执行任何动作或完成标准移动外的任何移动后掷骰 1d6。结果为 1则他们的回合立即结束。","id":"npcf_x_tcca_4_1","base":true},{"name":"变电站","type":"Trait","tags":[],"effect":"暴风雨的大漩涡核心由变电站稳定。这些是 4 个大小 1的物品，对所有伤害和效果免疫，并放置在场景开始时的地图上。变电站必须与所有其他变电站保持至少 3 空间的距离，并且应放置均匀且易于接近。在每回合开始时，暴风为每个剩余变电站赋予 4/5/6 护盾。一个角色可在变电站附近用一个快速动作破坏它，摧毁变电站并成为风暴充能。风暴充电时，该角色离散并获得+2速度。在该角色每回合结束时会受到 2 热度+2/3/4 AP 能量伤害，然后获得 2/3/4 护盾。下次他们攻击一个角色命中时，会从目标身上移除所有护盾，并造成+1d6 额外能量伤害。然后不再风暴充能。","id":"npcf_x_tcca_4_2","base":true},{"name":"大漩涡核心","type":"Trait","tags":[],"effect":"战场笼罩在暴风增压核心的漩涡风暴中。它由变电站稳定。在每个级别风暴都会对整个战场产生影响，忽略障碍物或视线。每个级别都会赋予风暴一个能源动作，它只能在风暴该级别使用，且需要视线。仅这些动作的射程为整个战场而不是其领域。它以暴雨开始场景；每当变电站被摧毁时，风暴就会按顺序推进到下一个级别。4-暴雨：敌对角色远程攻击射程 8 外的角色具有软性掩护。进入战场的盟军角色在进入时可匿迹，即便没有足够掩护也可以维持匿迹直到下一回合开始（尽管玩家的搜索、采取敌对动作等仍可能显行）。• 倾盆（3 能源）：创造一个持续到场景结束的溅射1 水坑。水坑就敌对角色是个困难地形，在其中的敌对角色在敏捷和机体检定与豁免上+1 难度。3-疾风：对于飞行角色而言所有空间均为困难地形，并且敌对角色都会伏卧除非对方在回合结束时邻近与他们相同或更大的物品或角色。• 阵风（3 能源）：目标角色必须通过机体豁免，否则在任何方向上被推离 2/3/4 空间。2-台风：敌对角色所有移动减少 1，他们承受所有击退+1。每当一个敌对角色执行科技动作时，他们会受到 1/2/3 AP 能量伤害+1 热度，然后获得 1/2/3 护盾。• 冲刷（4 能源）：目标角色必须通过工程豁免否则失去所有护盾，清除所有燃烧并移除当前影响他们的所有科技动作效果。1-撕裂天堂：所有角色在每回合开始时都被直接拉向暴风 1 空间。在任意领域内结束回合的角色都会受损直到对方下一回合结束。• 雷霆之王（5 能源）：目标角色下一回合结束时会被闪电击中，在系统豁免失败时晕眩，成功则受扰。对于每个邻近的盟友角色，该效果会逐步减弱；从晕眩到受扰，再到受损，直到失去效果。0-临界过载：当最后一座变电站被摧毁时，暴风立即进入临界过载状态。在该状态下，它对所有伤害，热度和状态都免疫。风暴充能角色仍可对它造成伤害。它无法再执行任何动作，除了能源动作和推进，冲撞，擒拿，或权宜攻击。在下一轮结束时，它灾难性地熔毁了：所有角色必须通过敏捷豁免否则受到 20/25/30 爆炸伤害，成功则伤害减半。与暴风之间每隔 1 空间伤害降低 4/5/6。• 聚能（6 能源）：失去 1HP。增加爆炸基础伤害4/5/6。","id":"npcf_x_tcca_4_3","base":true}],"optional":[{"name":"黑刺纳米体","type":"Trait","tags":[],"effect":"暴风将感应内盟友机甲残骸化为黑刺花园。它和它爆发 1区域周围均为困难地形。角色可通过每移动 1 空间受到 1AP动能伤害来忽略该效果。在该区域伏卧或被击退至残骸的角色会受到 4/5/6 动能伤害。","id":"npcf_x_tcca_4_4","base":false},{"name":"雷进侵入","type":"Trait","tags":[],"effect":"每当暴风在能量骰上掷出 6 时，闪电击中战场上的一个角色，造成 2/3/4 AP 能量伤害或将其推离 2 空间，由对方选择。","id":"npcf_x_tcca_4_5","base":false},{"name":"重子冷凝器","type":"System","tags":[{"id":"tg_deployable"},{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"重子冷凝器（大小 1/2，5HP，8 回避/ED，标签：可展开，发电器）该系统可部署到感应内的自由空间。领域：在该领域内任何来自敌对角色的效果都无法以该区域外的任何事物作为目标。• 超巨质量（3 能源）：直到地球化下一回合结束，角色将领域边界视为障碍，除非通过机体豁免。• 现实空间洞穿（4 能源）：将领域内的所有从战场上移除。在他们下一回合开始时，他们再次出现在任何领域内暴风所选的空间。角色可尝试系统豁免来避免该效果，成功后立即瞬间移动 1d6 空间。","id":"npcf_x_tcca_4_6","base":false},{"name":"地质构造大剧变","type":"Trait","tags":[{"id":"tg_full_action"},{"id":"tg_limited","val":1}],"effect":"为本次遭遇战准备二阶段作战地图。它可以具有与主地图不同的地形、物品位置和环境危害。以一个完整动作，或以一个对变电站被摧毁的反应，暴风可激活该特征，使用该二阶段地图取代当前战场。该影响瞬间发生；若角色、地雷或可展开物品下的地形改变高度，它们会无害地移动到新位置，或者若当前空间成为了障碍，则会被推到最近的自由空间。当地面翻涌转换形状时，主地图上任何不受角色控制的结构都会被摧毁。这不会改变变电站射程 2内的任何事物。","id":"npcf_x_tcca_4_7","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npct_x_cca_5","name":"标志性超体：技术症候群","page":55,"pages":[55,56],"description":"若幻人拥有超体模板，它还可以获得以下基本系统，并可以选择技术症候群可选系统之一。","base":[{"name":"分型割断","type":"Trait","tags":[],"effect":"当技术症候群以一个盟友角色为科技动作目标时，它可以使用快速动作在邻近自由空间中创建一个分型。分区大小1/2，具有 1HP，回避和电子防御与技术症候群相同。它们不会阻碍移动或视线。分型邻近的空间被视为技术症候群感应内空间，它们为所有邻近盟友提供软性掩护。当技术症候群在回合开始时为召集效果充能检定时，它可在掷骰后将分型视为盟友角色，从而摧毁所有以此法使用的分型。","id":"npcf_x_tcca_5_1","base":true},{"name":"虚无降神","type":"Tech","tags":[{"id":"tg_full_tech"}],"keywords":["召集"],"tech_type":"Full","effect":"技术症候群在感应内选择了一个分型，使其成为一个由松散废料和线缆制成的机械怪物。它摧毁分型，用以下无人机取而代之。它可同时摧毁额外分型以增强创造的无人机能力，使其获得+2HP/分型，以及所列增益。所有以此法制造的无人机均为大小 1，并在技术症候群每轮最后一回合的任意时刻执行所列动作。• 本我粉碎（8 回避/ED，5HP）：该无人机以+1/+2/+3对射程 5 内的角色进行远程攻击，造成 5 动能伤害+2/额外分型（最大 15）。• 自我中继（8 回避/ED，5HP）：该无人机射程 3 内的盟军角色在所有检定和豁免中+1 准度。它指定射程 3内的盟友滑步 3+额外分型空间。• 超我枷锁（8 回避/ED，5HP）：该无人机迫使射程 5内的一个角色通过系统豁免否则获得 2 热度并受损。若额外摧毁 2+分型则加上缓慢，若摧毁 4+则受扰。","id":"npcf_x_tcca_5_2","base":true}],"optional":[{"name":"散列思维体","type":"Trait","tags":[],"effect":"当技术症候群被摧毁时，掷骰 1d6。若掷骰数小于或等于激活分型数量，它会瞬间移动到任意分型位置，重置为满HP 和 1 结构和 1 压力，并摧毁所有激活分型。","id":"npcf_x_tcca_5_3","base":false},{"name":"梦行者","type":"Trait","tags":[],"effect":"虚无降神制造的无人机速度 4，并每轮都可在技术症候群最后一回合移动。它们可选择推进、冲撞或擒拿而非其所列动作。","id":"npcf_x_tcca_5_4","base":false},{"name":"伊格林高利万物链接","type":"System","tags":[],"effect":"技术症候群感应内的盟友机甲角色获得清明梦协定。该角色会晕眩直到下一回合开始。技术症候群恢复4/5/6HP，并可用一个反应进行推进。若该角色在下一回合开始前被摧毁，则用分型代替其残骸。\n【清明梦 协定】","id":"npcf_x_tcca_5_5","base":false},{"name":"轮回定界符","type":"System","tags":[],"effect":"当技术症候群第 4 次对一个角色使用电镀时，对方会被递归增量能所充斥。该角色获得对所有伤害和热度的抗性，并获得+2 速度。在下一回合结束时，该角色释放出爆发 2 能量倾泻，对受影响区域内所有角色造成 6/8/10 能量伤害，成功进行敏捷豁免伤害减半。以分型代替其残骸。","id":"npcf_x_tcca_5_6","base":false}],"pack":"冷核圆形竞技场","source":13},{"id":"npct_x_legion_1","name":"傀儡师","page":73,"pages":[73],"description":"层流 NHP、致命副编码和模因武器出错都会强迫机器系统发挥远超其功能限制的效力。这些“提线木偶”感染并控制其他机械，即使是那些遭受了足以让人类驾驶的机甲无法行动的损坏。傀儡师是强大的敌人，这必须在它们用仆从大军淹没倒战斗之前压制它们。若战斗中有傀儡师，可考虑添加残骸作为地形。","base":[{"name":"固化目标","type":"Trait","tags":[],"effect":"傀儡师获得系统豁免+1 准度，针对他们的科技攻击+1 难度。","id":"npcf_x_tlegion_1_1","base":true},{"name":"苏生矩阵","type":"System","tags":[{"id":"tg_quick_action"}],"effect":"傀儡师在感应内选择一个残骸。它变为活体残骸，一个在 GM 控制下的机甲。活体残骸有被摧毁前相同的数据，但失去所有模板，获得低等兵模板，并永久受损。傀儡师一次最多可以拥有 1/2/3 个活体残骸，若傀儡师被摧毁，所有这些残骸都被摧毁。","id":"npcf_x_tlegion_1_2","base":true},{"name":"傀儡师系统和特征","type":"Trait","tags":[],"effect":"傀儡师可从傀儡师系统和特征表中选择一个选项。当选择可选系统时，傀儡师也可以从该列表中选择。","id":"npcf_x_tlegion_1_3","base":true}],"optional":[{"name":"怪物之母","type":"Trait","tags":[],"effect":"傀儡师可以超过活体残骸通常最大数量。对于每超过最大值的活体残骸，傀儡师获得另一种状况，以受损开始，然后是缓慢，固定，最后是晕眩。每个状况持续到活体残骸的数量再次降低，并以相反的顺序清除。否则它们无法被清除。","id":"npcf_x_tlegion_1_4","base":false},{"name":"夺命爪牙","type":"Trait","tags":[],"effect":"傀儡师的活体残骸不会受损。","id":"npcf_x_tlegion_1_5","base":false},{"name":"躯体成盾","type":"Trait","tags":[],"effect":"邻近傀儡师活体残骸的盟友角色可将其作为硬性掩护。","id":"npcf_x_tlegion_1_6","base":false},{"name":"牧群模式","type":"Trait","tags":[],"effect":"当傀儡师使用苏生矩阵时，最多可选择 2 个残骸进行活化。","id":"npcf_x_tlegion_1_7","base":false},{"name":"超自然生命","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":4}],"effect":"每个傀儡师的活体残骸获得 3/4/5 护盾。","id":"npcf_x_tlegion_1_8","base":false},{"name":"同类相喰纳米体","type":"System","tags":[{"id":"tg_quick_action"},{"id":"tg_recharge","val":6}],"effect":"傀儡师可消耗一个活体残骸来恢复 5/10/15HP。活体残骸被移出战场——它被彻底吞噬。","id":"npcf_x_tlegion_1_9","base":false}],"pack":"军团","source":20}]};
